async def safe_callback_answer(call=None, *args, **kwargs):
    """Безопасно отвечает на callback и не роняет бот из-за просроченного query.

    Поддерживает старые вызовы вида safe_callback_answer(),
    safe_callback_answer("Текст") и safe_callback_answer(call, "Текст").
    Если callback не передан явно, пытается взять его из локальных переменных
    вызывающего обработчика (call/query/callback).
    """
    # Старый код местами вызывал helper без аргумента или передавал первым
    # аргументом текст. Восстанавливаем callback из контекста обработчика.
    if call is None or not hasattr(call, "answer"):
        import inspect
        caller = inspect.currentframe().f_back if inspect.currentframe() else None
        locals_ = caller.f_locals if caller else {}

        # Если первым аргументом был текст/параметры ответа — сохраняем их.
        if call is not None and not hasattr(call, "answer"):
            if isinstance(call, str):
                args = (call, *args)
            elif call is not None:
                args = (call, *args)

        actual_call = None
        for name in ("call", "query", "callback", "cb"):
            candidate = locals_.get(name)
            if candidate is not None and hasattr(candidate, "answer"):
                actual_call = candidate
                break
        call = actual_call

    if call is None or not hasattr(call, "answer"):
        return None

    try:
        return await call.answer(*args, **kwargs)
    except TelegramBadRequest as exc:
        message = str(exc).lower()
        if ("query is too old" in message
                or "response timeout expired" in message
                or "query id is invalid" in message):
            return None
        raise


def utcnow_naive():
    """UTC time without tzinfo for compatibility with existing SQLite timestamps."""
    return datetime.now(timezone.utc).replace(tzinfo=None)



