def _fetch_live_fx_rates_sync():
    """Получает текущие курсы из публичного FX API.
    API нужен только как источник рыночной котировки; при недоступности
    используется последний успешный кэш.
    """
    urls = [
        "https://open.er-api.com/v6/latest/RUB",
        "https://api.frankfurter.app/latest?from=RUB",
    ]
    for url in urls:
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "AutoTraderBot/1.0"})
            with urllib.request.urlopen(req, timeout=5) as resp:
                data = json.loads(resp.read().decode("utf-8"))
            rates = data.get("rates") or {}
            if rates:
                result = {str(k).upper(): float(v) for k, v in rates.items() if isinstance(v, (int, float)) and float(v) > 0}
                result["RUB"] = 1.0
                return result
        except Exception:
            continue
    return {}


async def get_live_fx_rates():
    now = time.time()
    if FX_CACHE["rates"] and now - FX_CACHE["ts"] < FX_CACHE_TTL:
        return FX_CACHE["rates"]
    rates = await asyncio.to_thread(_fetch_live_fx_rates_sync)
    if rates:
        FX_CACHE["ts"] = now
        FX_CACHE["rates"] = rates
    return FX_CACHE["rates"]


async def rub_to_currency(rub: float, code: str) -> float | None:
    rates = await get_live_fx_rates()
    code = code.upper()
    if code not in rates:
        # Не возвращаем рублёвое значение под видом другой валюты.
        return None
    # API above дает units of currency per 1 RUB.
    return rub * rates[code]


def format_fx(value: float, code: str) -> str:
    symbols = {"USD": "$", "EUR": "€", "JPY": "¥", "GBP": "£", "CNY": "¥", "KRW": "₩", "AED": "د.إ", "CAD": "C$", "CHF": "CHF", "SEK": "kr", "AUD": "A$", "CZK": "Kč"}
    symbol = symbols.get(code.upper(), code.upper())
    if code.upper() in {"JPY", "KRW"}:
        return f"{symbol}{value:,.0f}".replace(",", " ")
    return f"{symbol}{value:,.2f}".replace(",", " ")


