def finding_cooldown_text(seconds_left):
    seconds_left = max(0, int(seconds_left))
    hours, rem = divmod(seconds_left, 3600)
    minutes, seconds = divmod(rem, 60)
    if hours:
        return f"{hours} ч. {minutes} мин."
    if minutes:
        return f"{minutes} мин. {seconds} сек."
    return f"{seconds} сек."


async def finding_state(user_id):
    async with aiosqlite.connect(DB) as db:
        await db.execute("""
            CREATE TABLE IF NOT EXISTS player_finding_cooldowns (
                user_id INTEGER PRIMARY KEY,
                last_started_at TEXT NOT NULL,
                active_seed INTEGER,
                inspected INTEGER NOT NULL DEFAULT 0
            )
        """)
        cur = await db.execute(
            "SELECT last_started_at, active_seed, inspected FROM player_finding_cooldowns WHERE user_id = ?",
            (user_id,),
        )
        return await cur.fetchone()


async def get_or_start_finding(user_id):
    """Одно новое место на игрока в час; незавершённое место можно открыть повторно."""
    now = datetime.now().replace(microsecond=0)
    async with aiosqlite.connect(DB) as db:
        await db.execute("""
            CREATE TABLE IF NOT EXISTS player_finding_cooldowns (
                user_id INTEGER PRIMARY KEY,
                last_started_at TEXT NOT NULL,
                active_seed INTEGER,
                inspected INTEGER NOT NULL DEFAULT 0
            )
        """)
        cur = await db.execute(
            "SELECT last_started_at, active_seed, inspected FROM player_finding_cooldowns WHERE user_id = ?",
            (user_id,),
        )
        row = await cur.fetchone()
        remaining = 0
        if row and row[0]:
            try:
                elapsed = (now - datetime.fromisoformat(str(row[0]))).total_seconds()
                remaining = max(0, int(FINDING_COOLDOWN_SECONDS - elapsed))
            except (TypeError, ValueError):
                remaining = 0

        if row and remaining > 0:
            if row[1] is not None and not int(row[2] or 0):
                return int(row[1]), 0
            return None, remaining

        seed = random.randint(100_000, 999_999_999)
        await db.execute(
            """INSERT INTO player_finding_cooldowns(user_id, last_started_at, active_seed, inspected)
               VALUES(?,?,?,0)
               ON CONFLICT(user_id) DO UPDATE SET last_started_at=excluded.last_started_at,
                   active_seed=excluded.active_seed, inspected=0""",
            (user_id, now.isoformat(timespec="seconds"), seed),
        )
        await db.commit()
        return seed, 0


