PLATE_LETTERS = "АВЕКМНОРСТУХ"
PLATE_REGIONS = ["77", "99", "97", "177", "197", "777", "799", "50", "90", "150"]
PLATE_GOVERNMENT_SERIES = ["АМР", "ЕКХ", "АОО", "ВОО", "МОО", "СОО", "АМО", "КОО", "МММ", "ООО", "ССС"]
PLATE_SPECIAL_REGIONS = ["77", "97", "99", "177", "197", "199"]
PLATE_LETTER_PAIRS = ["АБ", "ВК", "ЕК", "МН", "ОР", "СТ", "УХ", "ХА"]


def generate_plate_number(plate_type):
    """Генерирует игровую уникальную комбинацию в формате выпавшей серии.

    Специальные названия и форматы — игровые категории коллекции, а не
    подтверждение реального ведомственного статуса или разрешения на использование.
    """
    rng = random.Random(f"plate:{plate_type}:{random.randint(1, 10**9)}")
    region = rng.choice(PLATE_REGIONS)
    special_region = rng.choice(PLATE_SPECIAL_REGIONS)
    a, b, c = rng.choices(PLATE_LETTERS, k=3)

    if plate_type == "exclusive":
        return f"EX {rng.randint(100000, 999999)}"
    if plate_type == "government":
        series = rng.choice(PLATE_GOVERNMENT_SERIES)
        digits = rng.choice([f"{n:03d}" for n in (1, 7, 10, 111, 222, 333, 555, 777, 888, 999)])
        return f"{series} {digits} {special_region}"
    if plate_type == "military":
        return f"{rng.randint(0, 9999):04d} {rng.choice(PLATE_LETTER_PAIRS)} {region}"
    if plate_type == "police":
        return f"ПОЛ {rng.randint(0, 999):03d} {special_region}"
    if plate_type == "taxi":
        return f"ТХ {rng.randint(0, 999):03d} {region}"
    if plate_type == "diplomatic":
        return f"{rng.randint(100, 999)} CD {special_region}"
    if plate_type == "trailer":
        return f"{rng.choice(PLATE_LETTER_PAIRS)} {rng.randint(0, 9999):04d} {region}"
    if plate_type == "transit":
        return f"ТР {rng.randint(0, 9999):04d} {region}"
    if plate_type == "motorcycle":
        return f"МОТО {rng.randint(0, 9999):04d} {rng.choice(PLATE_LETTER_PAIRS)} {region}"
    if plate_type == "electric":
        return f"ЭКО {rng.randint(0, 999):03d} {region}"

    if plate_type == "mirror":
        digits = rng.choice(["101", "202", "303", "404", "505", "707", "808", "909"])
    elif plate_type == "lucky":
        digits = rng.choice(["007", "111", "333", "555", "777", "888"])
    elif plate_type == "triple":
        digit = rng.choice("123456789")
        digits = digit * 3
    elif plate_type == "gold":
        digits = rng.choice(["001", "007", "010", "111", "777", "888", "999"])
    elif plate_type == "letters":
        letter = rng.choice(PLATE_LETTERS)
        a = b = c = letter
        digits = "".join(rng.choice("0123456789") for _ in range(3))
    elif plate_type == "classic":
        region = rng.choice(["77", "99", "97", "50", "90"])
        digits = "".join(rng.choice("0123456789") for _ in range(3))
    else:
        digits = "".join(rng.choice("0123456789") for _ in range(3))
    return f"{a}{digits}{b}{c} {region}"


def plate_display(plate):
    if not plate:
        return "Без номера"
    return plate.get("number", "Без номера")


# Единая стоимость одного прокрута. Редкость выбирается случайно по весам PLATE_TYPES.
PLATE_ROLL_COST = 75_000


def normalize_plate_number(number):
    """Единый формат номера для проверки уникальности."""
    return " ".join(str(number or "").upper().split())


def plate_effect_text(plate_type):
    """Человеко-понятное описание редкости и бонуса номера."""
    data = PLATE_TYPES.get(plate_type, PLATE_TYPES["region"])
    multiplier = float(data.get("multiplier", 1.0))
    bonus_pct = round((multiplier - 1.0) * 100)
    bonus_label = f"+{bonus_pct}%" if bonus_pct > 0 else "без бонуса"
    return (
        f"✨ <b>Особенность:</b> {data.get('feature', 'Коллекционный номер')}\n"
        f"📈 <b>Коэффициент к расчётной цене автомобиля:</b> ×{multiplier:.2f} ({bonus_label})\n"
        f"🎯 <b>Эффект:</b> {data.get('effect', 'Влияет на расчётную цену автомобиля.')}"
    )


async def claim_unique_plate_number(db, plate_type, user_id, preferred_number=None):
    """Навсегда регистрирует свободную комбинацию в реестре номеров.

    Используется для номеров, выдаваемых напрямую (например, при регистрации
    машины или при покупке заброшенного автосалона). Номер из реестра не
    освобождается даже после продажи или удаления соответствующей записи.
    Вызывается внутри текущей DB-транзакции.
    """
    await db.execute("""
        CREATE TABLE IF NOT EXISTS plate_number_registry (
            number TEXT PRIMARY KEY,
            status TEXT NOT NULL DEFAULT 'owned',
            reserved_by INTEGER,
            expires_at TEXT,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        )
    """)
    await db.execute(
        "DELETE FROM plate_number_registry WHERE status = 'reserved' AND expires_at <= ?",
        (datetime.now().replace(microsecond=0).isoformat(timespec="seconds"),),
    )
    candidates = []
    if preferred_number:
        candidates.append(normalize_plate_number(preferred_number))
    for _ in range(500):
        candidates.append(normalize_plate_number(generate_plate_number(plate_type)))

    for number in candidates:
        if not number:
            continue
        cursor = await db.execute(
            "SELECT 1 FROM plates WHERE UPPER(TRIM(number)) = ? LIMIT 1",
            (number,),
        )
        if await cursor.fetchone():
            continue
        cursor = await db.execute(
            "INSERT OR IGNORE INTO plate_number_registry(number, status, reserved_by, expires_at) "
            "VALUES(?, 'owned', NULL, NULL)",
            (number,),
        )
        if cursor.rowcount == 1:
            return number
    return None


