def sto_share_percent(invested: int, total_invested: int) -> float:
    if total_invested <= 0:
        return 0.0
    return invested / total_invested * 100


async def get_sto_investment(user_id):
    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute(
            "SELECT invested, total_income, name FROM sto_investments WHERE user_id = ?",
            (user_id,)
        )
        return await cursor.fetchone()


async def get_sto_total_invested():
    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute("SELECT COALESCE(SUM(invested), 0) FROM sto_investments")
        row = await cursor.fetchone()
        return int(row[0] or 0)


async def invest_sto(user_id, amount):
    if amount <= 0 or amount % 100_000 != 0:
        return False, "Сумма должна быть кратна 100 000 ₽."

    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute("SELECT balance FROM players WHERE user_id = ?", (user_id,))
        row = await cursor.fetchone()
        balance = int(row[0] or 0) if row else 0

        cursor = await db.execute("SELECT invested FROM sto_investments WHERE user_id = ?", (user_id,))
        own = await cursor.fetchone()
        current = int(own[0] or 0) if own else 0

        if current + amount > STO_MAX_INVESTMENT:
            return False, f"Максимальная инвестиция в СТО — {STO_MAX_INVESTMENT:,} ₽."
        if balance < amount:
            return False, "❌ Недостаточно денег."

        await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (amount, user_id))
        await db.execute(
            """
            INSERT INTO sto_investments (user_id, invested) VALUES (?, ?)
            ON CONFLICT(user_id) DO UPDATE SET invested = invested + excluded.invested
            """,
            (user_id, amount)
        )
        await db.commit()

    return True, f"✅ Ты инвестировал {amount:,} ₽ в СТО."


async def distribute_sto_income(repair_amount: int, payer_user_id: int):
    if repair_amount <= 0:
        return 0

    pool = int(repair_amount * STO_REVENUE_POOL)
    if pool <= 0:
        return 0

    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute(
            "SELECT user_id, invested FROM sto_investments WHERE invested > 0 ORDER BY invested DESC"
        )
        investors = await cursor.fetchall()
        eligible = [(int(uid), int(inv)) for uid, inv in investors if int(uid) != int(payer_user_id)]
        total = sum(inv for _, inv in eligible)
        if total <= 0:
            return 0

        paid_total = 0
        for investor_id, invested in eligible:
            payout = int(pool * invested / total)
            if payout <= 0:
                continue
            await db.execute(
                "UPDATE players SET balance = balance + ? WHERE user_id = ?",
                (payout, investor_id)
            )
            await db.execute(
                "UPDATE sto_investments SET total_income = total_income + ? WHERE user_id = ?",
                (payout, investor_id)
            )
            paid_total += payout

        await db.commit()
        return paid_total


