async def get_workshop(user_id):
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM workshops WHERE owner_id = ?", (user_id,))
        return await cur.fetchone()

async def ensure_workshop_job(user_id, workshop):
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            "SELECT * FROM workshop_jobs WHERE owner_id = ? AND status IN ('offered','active') ORDER BY id DESC LIMIT 1",
            (user_id,),
        )
        row = await cur.fetchone()
        if row:
            return row
        level = int(workshop["level"])
        car_name, car_rank = random.choice(WORKSHOP_CARS)
        allowed = [k for k, v in WORKSHOP_JOB_TYPES.items() if 1 + int(v[1] * 2) <= level + 4]
        job_type = random.choice(allowed or ["repair"])
        type_name, mult, payout_mult = WORKSHOP_JOB_TYPES[job_type]
        difficulty = max(1, min(5, car_rank + random.randint(0, 1)))
        base = random.randint(65_000, 170_000) * difficulty
        payout = int(base * payout_mult * (1 + 0.12 * (level - 1)))
        cost = int(payout * 0.25)
        quality_required = min(95, 45 + difficulty * 8)
        await db.execute(
            "INSERT INTO workshop_jobs(owner_id,customer_name,car_name,job_type,difficulty,cost,payout,quality_required) VALUES(?,?,?,?,?,?,?,?)",
            (user_id, random.choice(WORKSHOP_CUSTOMERS), car_name, job_type, difficulty, cost, payout, quality_required),
        )
        await db.commit()
        cur = await db.execute("SELECT * FROM workshop_jobs WHERE owner_id = ? ORDER BY id DESC LIMIT 1", (user_id,))
        return await cur.fetchone()

