@dp.callback_query(F.data == "workshop_open")
async def workshop_open(call):
    cost = 3_000_000
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT 1 FROM workshops WHERE owner_id = ?", (call.from_user.id,))
        if await cur.fetchone():
            await safe_callback_answer("Мастерская уже открыта.", show_alert=True)
            return
        cur = await db.execute("SELECT balance FROM players WHERE user_id = ?", (call.from_user.id,))
        row = await cur.fetchone(); balance = int(row[0] or 0) if row else 0
        if balance < cost:
            await safe_callback_answer(f"❌ Нужно {cost:,} ₽.", show_alert=True); return
        await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (cost, call.from_user.id))
        await db.execute("INSERT INTO workshops(owner_id) VALUES(?)", (call.from_user.id,))
        await db.commit()
    workshop = await get_workshop(call.from_user.id)
    job = await ensure_workshop_job(call.from_user.id, workshop)
    await edit_text_safe(call, await build_workshop_text(call.from_user.id), parse_mode="HTML", reply_markup=workshop_keyboard(workshop, job))
    await safe_callback_answer("🛠 Мастерская открыта!")

