@dp.callback_query(F.data.startswith("workshop_accept:"))
async def workshop_accept(call):
    job_id = int(call.data.split(":",1)[1]); workshop = await get_workshop(call.from_user.id)
    if not workshop: await safe_callback_answer("Мастерская не открыта.", show_alert=True); return
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM workshop_jobs WHERE id = ? AND owner_id = ? AND status = 'offered'", (job_id, call.from_user.id)); job = await cur.fetchone()
        if not job: await safe_callback_answer("Заказ уже недоступен.", show_alert=True); return
        duration_min = max(2, int(job["difficulty"]) * 5 - int(workshop["equipment"]) * 2)
        finish = datetime.now() + timedelta(minutes=duration_min)
        await db.execute("UPDATE workshop_jobs SET status='active', accepted_at=?, finish_at=? WHERE id=?", (datetime.now().isoformat(timespec="seconds"), finish.isoformat(timespec="seconds"), job_id)); await db.commit()
    workshop = await get_workshop(call.from_user.id); job = await ensure_workshop_job(call.from_user.id, workshop)
    await edit_text_safe(call, await build_workshop_text(call.from_user.id), parse_mode="HTML", reply_markup=workshop_keyboard(workshop, job))
    await safe_callback_answer("🔧 Заказ принят в работу!")

@dp.callback_query(F.data.startswith("workshop_finish:"))
async def workshop_finish(call):
    job_id = int(call.data.split(":",1)[1]); workshop = await get_workshop(call.from_user.id)
    if not workshop: await safe_callback_answer("Мастерская не открыта.", show_alert=True); return
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM workshop_jobs WHERE id=? AND owner_id=? AND status='active'", (job_id, call.from_user.id)); job=await cur.fetchone()
        if not job: await safe_callback_answer("Заказ не найден.", show_alert=True); return
        try: ready = datetime.now() >= datetime.fromisoformat(job["finish_at"])
        except Exception: ready = True
        if not ready:
            left = max(1, int((datetime.fromisoformat(job["finish_at"]) - datetime.now()).total_seconds() // 60))
            await safe_callback_answer(f"⏳ Ещё примерно {left} мин.", show_alert=True); return
        quality = min(99, 45 + int(workshop["level"])*7 + int(workshop["equipment"])*6 + int(workshop["reputation"])//12 + random.randint(-8,8))
        success = quality >= int(job["quality_required"])
        payout = int(job["payout"]) if success else int(job["payout"] * 0.35)
        rep_delta = 2 if success else -3
        await db.execute("UPDATE players SET balance = balance + ? WHERE user_id = ?", (payout, call.from_user.id))
        await db.execute("UPDATE workshops SET jobs_done=jobs_done+1, total_income=total_income+?, reputation=MAX(0, MIN(100, reputation+?)), failed_jobs=failed_jobs+? WHERE owner_id=?", (payout, rep_delta, 0 if success else 1, call.from_user.id))
        await db.execute("UPDATE workshop_jobs SET status='completed', completed_at=? WHERE id=?", (datetime.now().isoformat(timespec="seconds"), job_id))
        await db.execute("INSERT INTO workshop_history(owner_id,job_id,car_name,job_type,quality,payout) VALUES(?,?,?,?,?,?)", (call.from_user.id, job_id, job["car_name"], job["job_type"], quality, payout))
        await db.commit()
    workshop=await get_workshop(call.from_user.id); next_job=await ensure_workshop_job(call.from_user.id, workshop)
    result = "✅ Заказ выполнен качественно!" if success else "⚠️ Клиент недоволен качеством. Получена только часть оплаты."
    await edit_text_safe(call, await build_workshop_text(call.from_user.id) + f"\n\n{result}\n🎯 Качество: <b>{quality}%</b>\n💰 Выплата: <b>{payout:,} ₽</b>", parse_mode="HTML", reply_markup=workshop_keyboard(workshop, next_job))
    await safe_callback_answer()

