@dp.message(BusinessRenameForm.waiting_name)
async def business_rename_enter(message: Message, state: FSMContext):
    name = (message.text or "").strip()
    if len(name) < 2 or len(name) > 40:
        await message.answer("❌ Название должно содержать от 2 до 40 символов.")
        return
    if "\n" in name or "\r" in name:
        await message.answer("❌ Название должно быть в одну строку.")
        return
    data = await state.get_data()
    target = data.get("rename_target")
    uid = message.from_user.id
    changed = False
    result_text = ""
    back_callback = "businesses"
    async with aiosqlite.connect(DB) as db:
        if target == "dealer":
            cur = await db.execute("SELECT 1 FROM dealerships WHERE owner_id=?", (uid,))
            if await cur.fetchone():
                await db.execute("UPDATE dealerships SET name=? WHERE owner_id=?", (name, uid))
                changed = True
                result_text = f"✅ Автосалон теперь называется <b>{html.escape(name)}</b>."
                back_callback = "business_dealer"
        elif target == "sto":
            cur = await db.execute("SELECT 1 FROM sto_investments WHERE user_id=?", (uid,))
            if await cur.fetchone():
                await db.execute("UPDATE sto_investments SET name=? WHERE user_id=?", (name, uid))
                changed = True
                result_text = f"✅ СТО теперь называется <b>{html.escape(name)}</b>."
                back_callback = "business_sto"
        elif target == "workshop":
            cur = await db.execute("SELECT 1 FROM workshops WHERE owner_id=?", (uid,))
            if await cur.fetchone():
                await db.execute("UPDATE workshops SET name=? WHERE owner_id=?", (name, uid))
                changed = True
                result_text = f"✅ Мастерская теперь называется <b>{html.escape(name)}</b>."
                back_callback = "business_workshop"
        elif target == "property":
            key = data.get("business_key")
            cur = await db.execute("SELECT 1 FROM player_business_properties WHERE owner_id=? AND business_key=?", (uid, key))
            if await cur.fetchone():
                await db.execute("UPDATE player_business_properties SET name=? WHERE owner_id=? AND business_key=?", (name, uid, key))
                changed = True
                result_text = f"✅ Бизнес теперь называется <b>{html.escape(name)}</b>."
                back_callback = f"service_business:{key}" if key in SERVICE_INFO else "business_property_mine"
        await db.commit()
    await state.clear()
    if not changed:
        await message.answer("❌ Бизнес не найден или он тебе не принадлежит.")
        return
    kb = InlineKeyboardBuilder()
    kb.button(text="✅ Открыть бизнес", callback_data=back_callback)
    kb.button(text="💼 Бизнесы", callback_data="businesses")
    kb.adjust(1)
    await message.answer(result_text, parse_mode="HTML", reply_markup=kb.as_markup())


# =========================================================
# 🏎️ ТЕСТОВЫЙ ПОЛИГОН
# =========================================================

TEST_TRACK_COST = 5_000_000
TEST_TRACK_UPGRADES = {1: 3_000_000, 2: 6_000_000, 3: 12_000_000, 4: 25_000_000}
INSPECTION_COSTS = {1: 15_000, 2: 25_000, 3: 40_000, 4: 60_000, 5: 100_000}

NURBURGRING_PRIZE = 5_000_000

def nurburgring_month_key(dt=None):
    dt = dt or datetime.now()
    return f"{dt.year:04d}-{dt.month:02d}"

def previous_nurburgring_month(dt=None):
    dt = dt or datetime.now()
    first = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    prev = first - timedelta(days=1)
    return nurburgring_month_key(prev)

def format_nurburgring_time(seconds):
    seconds = float(seconds)
    minutes = int(seconds // 60)
    sec = seconds - minutes * 60
    return f"{minutes}:{sec:05.2f}"

async def settle_previous_nurburgring_month():
    previous_month = previous_nurburgring_month()
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT 1 FROM nurburgring_month_awards WHERE month_key=?", (previous_month,))
        if await cur.fetchone():
            return None
        cur = await db.execute(
            """SELECT r.owner_id, r.car_name, r.lap_time, COALESCE(p.username, 'Игрок') AS username
               FROM nurburgring_runs r
               LEFT JOIN players p ON p.user_id=r.owner_id
               WHERE r.month_key=?
               ORDER BY r.lap_time ASC, r.id ASC LIMIT 1""",
            (previous_month,)
        )
        winner = await cur.fetchone()
        if not winner:
            return None
        prize = int(NURBURGRING_PRIZE)
        await db.execute("UPDATE players SET balance=balance+?, xp=xp+500 WHERE user_id=?", (prize, int(winner["owner_id"])))
        await db.execute(
            "INSERT INTO nurburgring_month_awards(month_key,winner_id,winner_name,lap_time,prize) VALUES(?,?,?,?,?)",
            (previous_month, int(winner["owner_id"]), str(winner["username"]), float(winner["lap_time"]), prize)
        )
        await db.commit()
        return {"month": previous_month, "winner": winner, "prize": prize}

async def get_test_track(user_id):
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM test_tracks WHERE owner_id = ?", (user_id,))
        return await cur.fetchone()


def test_track_keyboard(track):
    kb = InlineKeyboardBuilder()
    if not track:
        kb.button(text=f"🏎️ Открыть полигон — {TEST_TRACK_COST:,} ₽", callback_data="test_track_open")
    else:
        kb.button(text="🚗 Выбрать автомобиль", callback_data="test_track_cars")
        if int(track["level"]) < 5:
            cost = TEST_TRACK_UPGRADES.get(int(track["level"]))
            kb.button(text=f"⬆️ Улучшить до {int(track['level'])+1} ур. — {cost:,} ₽", callback_data="test_track_upgrade")
        kb.button(text="🏆 Рекорды", callback_data="test_track_records")
        kb.button(text="🏁 Нюрбургринг", callback_data="nurburgring")
    kb.button(text="🔙 Бизнесы", callback_data="businesses")
    kb.adjust(1)
    return kb.as_markup()


