@dp.callback_query(F.data.startswith("test_run:"))
async def test_run(call):
    uid = call.from_user.id; car_id = int(call.data.split(":",1)[1])
    track = await get_test_track(uid)
    if not track: return await safe_callback_answer(call, "Полигон не открыт.", show_alert=True)
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT id, car_name, buy_price, repair_cost, repaired, repair_count, originality_score, mileage, condition, engine_condition, gearbox_condition, suspension_condition, brakes_condition, tires_condition, fluids_condition FROM garage WHERE id = ? AND user_id = ?", (car_id, uid))
        car = await cur.fetchone()
        if not car: return await safe_callback_answer(call, "Машина не найдена.", show_alert=True)
        template = get_car_template(car["car_name"], car["buy_price"], car["repair_cost"]) or {}
        base = max(40, int(car["buy_price"] or 0) // 10000)
        level = int(track["level"])
        condition = clamp_percent(car["condition"]) + min(10, int(car["originality_score"] or 0)//10) - min(25, int(car["repair_count"] or 0)*2)
        engine_hint = max(40, min(100, base + random.randint(-15,15)))
        zero = max(2.8, round(10.5 - engine_hint/15 + random.uniform(-0.35,0.35) - level*0.12, 2))
        brake = max(24.0, round(43.0 - level*1.2 - random.uniform(0,3) + (condition-80)*0.05, 2))
        vmax = max(90.0, round(130 + engine_hint*2.2 + level*8 + random.uniform(-15,15), 1))
        lap = max(35.0, round(150 - engine_hint*0.35 - level*2 + random.uniform(-5,5), 2))
        consumption = max(4.0, round(8.5 + engine_hint/45 + random.uniform(-0.7,0.7), 1))
        reliability = int(max(20, min(100, condition + level*3 + random.randint(-6,6))))
        await db.execute("INSERT INTO test_runs(owner_id,car_id,car_name,zero_to_100,braking,top_speed,lap_time,consumption,reliability) VALUES(?,?,?,?,?,?,?,?,?)", (uid, car_id, car["car_name"], zero, brake, vmax, lap, consumption, reliability))
        km=random.randint(30,90); wear=mileage_wear(km,True)
        parts={"engine_condition":max(0,clamp_percent(car["engine_condition"])-wear["engine"]),"gearbox_condition":max(0,clamp_percent(car["gearbox_condition"])-wear["gearbox"]),"suspension_condition":max(0,clamp_percent(car["suspension_condition"])-wear["suspension"]),"brakes_condition":max(0,clamp_percent(car["brakes_condition"])-wear["brakes"]),"tires_condition":max(0,clamp_percent(car["tires_condition"])-wear["tires"]),"fluids_condition":max(0,clamp_percent(car["fluids_condition"])-wear["fluids"])}
        new_condition=clamp_percent(sum(parts.values())/6)
        await db.execute("UPDATE garage SET mileage=COALESCE(mileage,0)+?,condition=?,engine_condition=?,gearbox_condition=?,suspension_condition=?,brakes_condition=?,tires_condition=?,fluids_condition=?,last_drive_at=? WHERE id=? AND user_id=?",(km,new_condition,parts["engine_condition"],parts["gearbox_condition"],parts["suspension_condition"],parts["brakes_condition"],parts["tires_condition"],parts["fluids_condition"],datetime.now().isoformat(timespec="seconds"),car_id,uid))
        await db.execute("INSERT INTO maintenance_history(user_id,car_id,car_name,service_type,amount,mileage,condition_before,condition_after) VALUES(?,?,?,?,?,?,?,?)",(uid,car_id,car["car_name"],"Тестовый полигон",0,int(car["mileage"] or 0)+km,int(car["condition"] or 0),new_condition))
        await db.execute("UPDATE test_tracks SET attempts=attempts+1,total_tests=total_tests+1 WHERE owner_id=?", (uid,))
        await db.commit()
    text = (f"🏁 <b>РЕЗУЛЬТАТ ИСПЫТАНИЯ</b>\n\n🚗 <b>{html.escape(car['car_name'])}</b>\n\n" f"⚡ 0–100: <b>{zero} сек.</b>\n🛑 Торможение: <b>{brake} м</b>\n💨 Макс. скорость: <b>{vmax} км/ч</b>\n🏎️ Круг: <b>{lap} сек.</b>\n⛽ Расход: <b>{consumption} л/100 км</b>\n🛡 Надёжность: <b>{reliability}%</b>\n\nРезультат сохранён в таблицу рекордов.")
    kb=InlineKeyboardBuilder(); kb.button(text="🏆 Рекорды",callback_data="test_track_records"); kb.button(text="🚗 Другой автомобиль",callback_data="test_track_cars"); kb.button(text="🔙 Полигон",callback_data="business_test_track"); kb.adjust(1)
    await edit_text_safe(call,text,parse_mode="HTML",reply_markup=kb.as_markup()); await safe_callback_answer(call)


