@dp.callback_query(F.data.startswith("nring_run:"))
async def nurburgring_run(call):
    uid = call.from_user.id
    car_id = int(call.data.split(":",1)[1])
    month = nurburgring_month_key()
    await settle_previous_nurburgring_month()
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            """SELECT id, car_name, buy_price, repaired, condition, engine_condition, gearbox_condition,
                      suspension_condition, brakes_condition, tires_condition, fluids_condition, build_turbo
               FROM garage WHERE id=? AND user_id=?""", (car_id, uid)
        )
        car = await cur.fetchone()
        if not car:
            return await safe_callback_answer(call, "Машина не найдена.", show_alert=True)
        parts = [clamp_percent(car[k]) for k in ("engine_condition","gearbox_condition","suspension_condition","brakes_condition","tires_condition","fluids_condition")]
        condition = clamp_percent(sum(parts)/6)
        if not int(car["repaired"] or 0):
            condition = min(condition, 70)
        price_score = min(100.0, 20.0 + (float(car["buy_price"] or 0) / 7_500_000.0) * 80.0)
        turbo_bonus = 5.0 if int(car["build_turbo"] or 0) else 0.0
        performance = max(15.0, min(105.0, price_score * 0.55 + condition * 0.45 + turbo_bonus))
        variance = random.uniform(-6.0, 6.0)
        lap = max(395.0, 760.0 - performance * 2.9 + variance)
        cur = await db.execute(
            "SELECT MIN(lap_time) FROM nurburgring_runs WHERE owner_id=? AND month_key=?", (uid, month)
        )
        previous_best = (await cur.fetchone())[0]
        await db.execute(
            "INSERT INTO nurburgring_runs(owner_id,car_id,car_name,lap_time,month_key) VALUES(?,?,?,?,?)",
            (uid, car_id, car["car_name"], lap, month)
        )
        km = random.randint(21, 25)
        wear = mileage_wear(km, True)
        new_parts = {k:max(0,clamp_percent(car[k])-wear[key]) for k,key in [("engine_condition","engine"),("gearbox_condition","gearbox"),("suspension_condition","suspension"),("brakes_condition","brakes"),("tires_condition","tires"),("fluids_condition","fluids")]}
        new_condition = clamp_percent(sum(new_parts.values())/6)
        await db.execute(
            """UPDATE garage SET mileage=COALESCE(mileage,0)+?, condition=?, engine_condition=?, gearbox_condition=?,
                      suspension_condition=?, brakes_condition=?, tires_condition=?, fluids_condition=?, last_drive_at=?
               WHERE id=? AND user_id=?""",
            (km,new_condition,new_parts["engine_condition"],new_parts["gearbox_condition"],new_parts["suspension_condition"],new_parts["brakes_condition"],new_parts["tires_condition"],new_parts["fluids_condition"],datetime.now().isoformat(timespec="seconds"),car_id,uid)
        )
        await db.execute(
            "INSERT INTO maintenance_history(user_id,car_id,car_name,service_type,amount,mileage,condition_before,condition_after) VALUES(?,?,?,?,?,?,?,?)",
            (uid,car_id,car["car_name"],"Нюрбургринг",0,km,int(condition),int(new_condition))
        )
        await db.commit()
    improved = previous_best is None or lap < float(previous_best)
    text = (
        "🏁 <b>ЗАЕЗД НА НЮРБУРГРИНГ</b>\n\n"
        f"🚗 <b>{html.escape(str(car['car_name']))}</b>\n"
        f"⏱ <b>{format_nurburgring_time(lap)}</b>\n"
        f"📊 Состояние перед стартом: <b>{condition}%</b>\n"
        f"📏 Пробег за заезд: <b>+{km} км</b>\n"
    )
    text += "🔥 <b>Новый личный лучший результат!</b>\n" if improved else "📌 Личный рекорд месяца не побит.\n"
    text += f"\n🏆 Приз лидеру месяца: <b>{NURBURGRING_PRIZE:,} ₽ + 500 XP</b>"
    kb=InlineKeyboardBuilder(); kb.button(text="🏆 Результаты месяца",callback_data="nurburgring"); kb.button(text="🚗 Ещё заезд",callback_data="nurburgring_cars"); kb.button(text="🔙 Полигон",callback_data="business_test_track"); kb.adjust(1)
    await edit_text_safe(call,text,parse_mode="HTML",reply_markup=kb.as_markup())
    await safe_callback_answer(call, "🏁 Результат записан!")


