SEASON_MONTH_NAMES = {
    1: "январь", 2: "февраль", 3: "март", 4: "апрель",
    5: "май", 6: "июнь", 7: "июль", 8: "август",
    9: "сентябрь", 10: "октябрь", 11: "ноябрь", 12: "декабрь",
}


def current_season_key():
    return datetime.now().strftime("%Y-%m")


def current_season_title():
    now = datetime.now()
    return f"{SEASON_MONTH_NAMES[now.month].capitalize()} {now.year}"


async def seasonal_add_stat(user_id: int, metric: str, amount: int):
    """Безопасно увеличивает один показатель игрока в текущем месячном сезоне."""
    cfg = SEASONAL_METRICS.get(metric)
    if not cfg or not amount:
        return
    column = cfg["column"]  # только whitelist выше; поле не берётся из callback.
    season_key = current_season_key()
    try:
        async with aiosqlite.connect(DB) as db:
            await db.execute(
                "INSERT OR IGNORE INTO seasonal_player_stats(season_key, user_id) VALUES(?, ?)",
                (season_key, int(user_id)),
            )
            await db.execute(
                f"UPDATE seasonal_player_stats SET {column} = {column} + ?, updated_at=CURRENT_TIMESTAMP "
                "WHERE season_key=? AND user_id=?",
                (int(amount), season_key, int(user_id)),
            )
            await db.commit()
    except Exception:
        # Не позволяем необязательной таблице рейтингов сорвать игровую операцию.
        return


def seasonal_rating_keyboard(selected="profit"):
    kb = InlineKeyboardBuilder()
    for key, cfg in SEASONAL_METRICS.items():
        prefix = "✅ " if key == selected else ""
        kb.button(text=prefix + cfg["title"], callback_data=f"seasonal_rank:{key}")
    kb.button(text="🔄 Обновить", callback_data=f"seasonal_rank:{selected}")
    kb.button(text="🔙 Forbes", callback_data="forbes")
    kb.adjust(2, 2, 1, 1)
    return kb.as_markup()


async def build_seasonal_rating_text(metric="profit"):
    cfg = SEASONAL_METRICS.get(metric, SEASONAL_METRICS["profit"])
    column = cfg["column"]
    season_key = current_season_key()
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            f"""SELECT s.user_id, COALESCE(p.username, '') AS username, s.{column} AS score
                FROM seasonal_player_stats s
                LEFT JOIN players p ON p.user_id=s.user_id
                WHERE s.season_key=? AND s.{column} != 0
                ORDER BY s.{column} DESC, s.updated_at ASC, s.user_id ASC LIMIT 10""",
            (season_key,),
        )
        rows = await cur.fetchall()
    medals = ["🥇", "🥈", "🥉"]
    text = (
        f"🏆 <b>СЕЗОННЫЕ РЕЙТИНГИ</b>\n"
        f"📅 Сезон: <b>{html.escape(current_season_title())}</b>\n\n"
        f"{cfg['title']}\n"
        f"<i>{cfg['description']}</i>\n\n"
    )
    if rows:
        for i, row in enumerate(rows, 1):
            label = f"@{row['username']}" if row['username'] else "Игрок без username"
            medal = medals[i - 1] if i <= 3 else f"{i}."
            score = int(row["score"] or 0)
            formatted = f"{score:+,} ₽" if metric == "profit" else f"{score:,} {cfg['unit']}"
            text += f"{medal} <b>{html.escape(label)}</b> — <b>{formatted}</b>\n"
    else:
        text += "Пока в этой категории нет результатов.\n"
    text += "\nСезон автоматически обновляется первого числа каждого месяца. В текущей таблице учитываются только результаты этого месяца."
    return text


