@dp.callback_query(F.data.startswith("special_auction_bid_start:"))
async def special_auction_bid_start(call, state: FSMContext):
    try:
        aid = int(call.data.split(':', 1)[1])
    except ValueError:
        return await safe_callback_answer(call, '❌ Некорректный лот.', show_alert=True)

    await ensure_special_auctions()
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM special_auctions WHERE id=? AND status='active'", (aid,))
        auction = await cur.fetchone()
    if not auction or auction['auction_type'] != 'closed':
        return await safe_callback_answer(call, '❌ Закрытый аукцион недоступен.', show_alert=True)

    if datetime.fromisoformat(auction['ends_at']) <= datetime.now():
        return await safe_callback_answer(call, '❌ Время аукциона вышло.', show_alert=True)

    await state.set_state(SpecialAuctionBidForm.waiting_bid)
    await state.update_data(auction_id=aid)
    kb = InlineKeyboardBuilder()
