async def ensure_garage_auctions():
    now = datetime.now()
    async with aiosqlite.connect(DB) as db:
        await db.execute("UPDATE garage_auctions SET status='finished', winner_id=highest_bidder_id WHERE status='active' AND ends_at<=?", (now.isoformat(timespec='seconds'),))
        cur = await db.execute("SELECT COUNT(*) FROM garage_auctions WHERE status='active'")
        active = int((await cur.fetchone())[0] or 0)
        used = set()
        if active:
            cur = await db.execute("SELECT garage_name FROM garage_auctions WHERE status='active'")
            used = {r[0] for r in await cur.fetchall()}
        while active < 3:
            choices = [x for x in GARAGE_AUCTION_POOL if x[0] not in used] or GARAGE_AUCTION_POOL
            name, loc, start, hint, cars = random.choice(choices)
            ends = now + timedelta(hours=random.randint(2, 6), minutes=random.randint(0, 45))
            hidden_value = random.randint(int(start*0.45), int(start*2.8))
            await db.execute(
                "INSERT INTO garage_auctions(garage_name,location,start_price,current_bid,contents_hint,hidden_cars,hidden_value,ends_at) VALUES(?,?,?,?,?,?,?,?)",
                (name, loc, start, start, hint, cars, hidden_value, ends.isoformat(timespec='seconds'))
            )
            used.add(name); active += 1
        await db.commit()

