def make_gov_auction_details(car_name, start_price):
    types = [x[0] for x in GOV_AUCTION_HIDDEN_PROFILES]
    weights = [x[3] for x in GOV_AUCTION_HIDDEN_PROFILES]
    history_type = random.choices(types, weights=weights, k=1)[0]
    profile = next(x for x in GOV_AUCTION_HIDDEN_PROFILES if x[0] == history_type)
    _, history_multiplier, feature, _ = profile
    template = get_car_template(car_name, start_price, 0) or {}
    low = int(template.get("min", max(1, int(start_price * 0.8))) or max(1, int(start_price * 0.8)))
    high = int(template.get("max", max(low, int(start_price * 1.6))) or max(low, int(start_price * 1.6)))
    base_value = max(start_price, (low + high) // 2)
    estimated_value = max(1, int(base_value * history_multiplier * random.uniform(0.92, 1.10)))
    base_repair = int(template.get("repair", max(20_000, int(start_price * 0.07))) or max(20_000, int(start_price * 0.07)))
    if history_type == "accident":
        repair_cost = int(base_repair * random.uniform(2.0, 3.8))
    else:
        repair_cost = int(base_repair * random.uniform(0.65, 1.75))
    return history_type, float(history_multiplier), feature, estimated_value, max(5_000, repair_cost)


async def _ensure_gov_auctions_unlocked():
    now = datetime.now()
    now_text = now.isoformat(timespec="seconds")
    settled_winners = []
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        # Старые лоты получают скрытую историю один раз при первом открытии новой версии.
        cur = await db.execute(
            "SELECT * FROM government_auctions WHERE status='active' AND (hidden_feature='' OR estimated_value<=0)"
        )
        for old in await cur.fetchall():
            hist_type, hist_mult, feature, estimate, repair_cost = make_gov_auction_details(old["car_name"], int(old["start_price"]))
            await db.execute(
                "UPDATE government_auctions SET hidden_feature=?, hidden_history_type=?, hidden_multiplier=?, estimated_value=?, repair_cost=? WHERE id=?",
                (feature, hist_type, hist_mult, estimate, repair_cost, int(old["id"])),
            )

        # Закрываем истёкшие торги и выдаём машину победителю только один раз.
        cur = await db.execute(
            "SELECT * FROM government_auctions WHERE status='active' AND ends_at<=? ORDER BY id",
            (now_text,),
        )
        expired = await cur.fetchall()
        for auction in expired:
            auction_id = int(auction["id"])
            winner_id = int(auction["highest_bidder_id"]) if auction["highest_bidder_id"] else None
            cur = await db.execute(
                "UPDATE government_auctions SET status='finished', winner_id=? WHERE id=? AND status='active'",
                (winner_id, auction_id),
            )
            if cur.rowcount != 1 or not winner_id:
                continue
            # Ставка уже списана при торгах; после закрытия лота автомобиль зачисляется в гараж.
            condition_text = str(auction["condition"] or "Хорошее")
            if "лёгкого ремонта" in condition_text.lower():
                condition_score, engine_score = 58, 52
            elif "консервации" in condition_text.lower():
                condition_score, engine_score = 70, 68
            elif "очень хорошее" in condition_text.lower():
                condition_score, engine_score = 91, 90
            else:
                condition_score, engine_score = 80, 78
            cur = await db.execute(
                """INSERT INTO garage
                   (user_id, car_name, buy_price, repair_cost, repaired, history_type, history_multiplier,
                    origin_country, current_country, current_city, purchased_at, original_buy_price,
                    original_purchased_at, owner_count, maintenance_initialized, condition, engine_condition,
                    gearbox_condition, suspension_condition, brakes_condition, tires_condition, fluids_condition)
                   VALUES(?,?,?,?,0,? ,?,'Россия','Россия','Большой автоаукцион',?,?,?,1,1,?,?,?,?,?,?,?)""",
                (
                    winner_id, auction["car_name"], int(auction["current_bid"]), int(auction["repair_cost"] or 0),
                    auction["hidden_history_type"] or "normal", float(auction["hidden_multiplier"] or 1.0),
                    now_text, int(auction["current_bid"]), now_text,
                    condition_score, engine_score, max(35, engine_score - 2), max(30, condition_score - 8),
                    max(30, condition_score - 4), max(25, condition_score - 12), max(30, condition_score - 6),
                ),
            )
            car_id = int(cur.lastrowid)
            feature = str(auction["hidden_feature"] or "Особых сведений нет")
            await db.execute(
                "INSERT INTO vehicle_history(car_id,owner_id,event_type,event_at,amount,details) VALUES(?,?,?,?,?,?)",
                (car_id, winner_id, "auction_purchase", now_text, int(auction["current_bid"]),
                 f"Победа в большом автомобильном аукционе. История лота: {feature}"),
            )
            settled_winners.append((winner_id, auction["car_name"], int(auction["current_bid"]), car_id))

        cur = await db.execute("SELECT car_name FROM government_auctions WHERE status='active'")
        active_names = {str(row[0]) for row in await cur.fetchall()}
        active = len(active_names)
        while active < 4:
            choices = [lot for lot in GOV_AUCTION_POOL if lot[0] not in active_names] or GOV_AUCTION_POOL
            name, start_price, history = random.choice(choices)
            active_names.add(name)
            ends = (now + timedelta(hours=GOV_HOURS, minutes=random.randint(0, 45))).isoformat(timespec="seconds")
            condition = random.choice(["Требует лёгкого ремонта", "Хорошее", "Очень хорошее", "После консервации"])
            hist_type, hist_mult, feature, estimate, repair_cost = make_gov_auction_details(name, start_price)
            await db.execute(
                """INSERT INTO government_auctions
                   (car_name,start_price,current_bid,history,condition,ends_at,hidden_feature,hidden_history_type,hidden_multiplier,estimated_value,repair_cost)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                (name, start_price, start_price, history, condition, ends, feature, hist_type, hist_mult, estimate, repair_cost),
            )
            active += 1
        await db.commit()

    # Статистика и уведомления выполняются после коммита аукциона.
    for winner_id, car_name, final_bid, car_id in settled_winners:
        await seasonal_add_stat(winner_id, "collection", 1)
        if bot is not None:
            try:
                await bot.send_message(
                    winner_id,
                    "🏆 <b>ТЫ ВЫИГРАЛ БОЛЬШОЙ АВТОАУКЦИОН!</b>\n\n"
                    f"🚗 <b>{html.escape(str(car_name))}</b>\n"
                    f"💰 Ставка: <b>{final_bid:,} ₽</b>\n"
                    "🏠 Автомобиль уже добавлен в гараж. Его скрытая история и состояние сохранены.",
                    parse_mode="HTML",
                )
            except Exception:
                pass


GOV_AUCTION_LOCK = asyncio.Lock()


async def ensure_gov_auctions():
    """Serializes background settlement with calls triggered by the UI."""
    async with GOV_AUCTION_LOCK:
        await _ensure_gov_auctions_unlocked()


async def gov_auction_settlement_loop():
    """Автоматически закрывает истёкшие большие автоаукционы во время работы бота."""
    while True:
        try:
            await ensure_gov_auctions()
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            print(f"⚠️ Ошибка автоматического закрытия автоаукционов: {exc}")
        await asyncio.sleep(30)


