@dp.callback_query(F.data.startswith("gov_auction_view:"))
async def gov_auction_view(call, auction_id=None):
    # CallbackQuery frozen: после ставки передаём auction_id напрямую.
    if auction_id is None:
        parts = call.data.split(":")
        auction_id = int(parts[1])
    aid = int(auction_id)
    uid = call.from_user.id
    await ensure_gov_auctions()
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM government_auctions WHERE id=?", (aid,))
        a = await cur.fetchone()
        cur = await db.execute(
            "SELECT 1 FROM government_auction_inspections WHERE auction_id=? AND user_id=?",
            (aid, uid),
        )
        inspected = bool(await cur.fetchone())
    if not a:
        return await safe_callback_answer(call, "Лот не найден.", show_alert=True)
    if a["status"] != "active" or datetime.fromisoformat(a["ends_at"]) <= datetime.now():
        return await safe_callback_answer(call, "Аукцион уже завершён.", show_alert=True)

    step = max(10_000, int(a["current_bid"] * 0.05))
    minimum_bid = int(a["current_bid"]) + step
    kb = InlineKeyboardBuilder()
    for mult in (1, 1.10, 1.20, 1.35):
        raw_bid = int(minimum_bid * mult)
        bid = ((raw_bid + 9_999) // 10_000) * 10_000
        kb.button(text=f"💰 Ставка {bid:,} ₽", callback_data=f"gov_bid:{aid}:{bid}")
    if not inspected:
        kb.button(text=f"🔎 Проверить историю — {GOV_AUCTION_INSPECTION_COST:,} ₽", callback_data=f"gov_auction_inspect:{aid}")
    kb.button(text="🔙 Большой автоаукцион", callback_data="business_gov_auction_hub")
    kb.adjust(1)

    left = max(0, int((datetime.fromisoformat(a["ends_at"]) - datetime.now()).total_seconds()))
    text = (
        f"🚘 <b>АУКЦИОННЫЙ ЛОТ #{aid}</b>\n\n"
        f"🚗 <b>{html.escape(str(a['car_name']))}</b>\n"
        f"💰 Стартовая цена: <b>{int(a['start_price']):,} ₽</b>\n"
        f"🔥 Текущая ставка: <b>{int(a['current_bid']):,} ₽</b>\n"
        f"📜 История владельцев: {html.escape(str(a['history']))}\n"
        f"🔧 Внешнее состояние: <b>{html.escape(str(a['condition']))}</b>\n"
        f"⏳ До конца: <b>{left // 3600} ч {(left % 3600) // 60} мин</b>\n\n"
    )
    if inspected:
        text += (
            "🔎 <b>ОТЧЁТ ПРОВЕРКИ</b>\n"
            f"🧩 Особенность: {html.escape(str(a['hidden_feature'] or 'Не выявлена'))}\n"
            f"📈 Ориентировочная стоимость: <b>{int(a['estimated_value'] or 0):,} ₽</b>\n"
            f"🛠 Ожидаемые расходы на восстановление: <b>{int(a['repair_cost'] or 0):,} ₽</b>\n\n"
            "Отчёт доступен тебе; другим игрокам скрытая информация не раскрывается.\n\n"
        )
    else:
        text += (
            "🕵️ В лоте есть скрытая история: комплектация, оригинальность агрегатов или возможные повреждения.\n"
            f"Проверка стоит <b>{GOV_AUCTION_INSPECTION_COST:,} ₽</b> и раскрывает отчёт только тебе.\n\n"
        )
    text += "Ставка списывается с баланса. Если тебя перебьют, предыдущая ставка возвращается. После завершения победитель получит автомобиль в гараж."
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer(call)


@dp.callback_query(F.data.startswith("gov_auction_inspect:"))
async def gov_auction_inspect(call):
    aid = int(call.data.split(":", 1)[1])
    uid = call.from_user.id
    now = datetime.now()
    async with aiosqlite.connect(DB) as db:
        await db.execute("BEGIN IMMEDIATE")
        cur = await db.execute("SELECT status, ends_at FROM government_auctions WHERE id=?", (aid,))
        auction = await cur.fetchone()
        if not auction or auction[0] != "active" or datetime.fromisoformat(auction[1]) <= now:
            await db.rollback()
            return await safe_callback_answer(call, "❌ Этот лот уже недоступен.", show_alert=True)
        cur = await db.execute(
            "SELECT 1 FROM government_auction_inspections WHERE auction_id=? AND user_id=?",
            (aid, uid),
        )
        if await cur.fetchone():
            await db.rollback()
            return await gov_auction_view(call, auction_id=aid)
        cur = await db.execute(
            "UPDATE players SET balance=balance-? WHERE user_id=? AND balance>=?",
            (GOV_AUCTION_INSPECTION_COST, uid, GOV_AUCTION_INSPECTION_COST),
        )
        if cur.rowcount != 1:
            await db.rollback()
            return await safe_callback_answer(call, f"❌ Для проверки нужно {GOV_AUCTION_INSPECTION_COST:,} ₽.", show_alert=True)
        await db.execute(
            "INSERT INTO government_auction_inspections(auction_id,user_id) VALUES(?,?)",
            (aid, uid),
        )
        await db.commit()
    await gov_auction_view(call, auction_id=aid)


@dp.callback_query(F.data.startswith("gov_bid:"))
async def gov_bid(call):
    _, aid_s, bid_s = call.data.split(":")
    aid, bid, uid = int(aid_s), int(bid_s), call.from_user.id
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        await db.execute("BEGIN IMMEDIATE")
        cur = await db.execute("SELECT * FROM government_auctions WHERE id=?", (aid,))
        auction = await cur.fetchone()
        if not auction or auction["status"] != "active":
            await db.rollback()
            return await safe_callback_answer(call, "Лот уже закрыт.", show_alert=True)
        if datetime.fromisoformat(auction["ends_at"]) <= datetime.now():
            await db.rollback()
            return await safe_callback_answer(call, "Время вышло.", show_alert=True)

        current_bid = int(auction["current_bid"] or 0)
        old_bidder = int(auction["highest_bidder_id"]) if auction["highest_bidder_id"] else None
        min_bid = current_bid + max(10_000, int(current_bid * 0.05))
        if bid < min_bid:
            await db.rollback()
            return await safe_callback_answer(call, f"Минимальная ставка {min_bid:,} ₽", show_alert=True)

        # Если лидер повышает собственную ставку, списываем только разницу.
        charge = bid - current_bid if old_bidder == uid else bid
        cur = await db.execute(
            "UPDATE players SET balance=balance-? WHERE user_id=? AND balance>=?",
            (charge, uid, charge),
        )
        if cur.rowcount != 1:
            await db.rollback()
            return await safe_callback_answer(call, "❌ Недостаточно денег.", show_alert=True)

        # Возвращаем депозит прежнему лидеру, если это другой игрок.
        if old_bidder and old_bidder != uid:
            await db.execute(
                "UPDATE players SET balance=balance+? WHERE user_id=?",
                (current_bid, old_bidder),
            )
        await db.execute(
            "UPDATE government_auctions SET current_bid=?, highest_bidder_id=? WHERE id=?",
            (bid, uid, aid),
        )
        await db.execute(
            "INSERT INTO government_auction_bids(auction_id,bidder_id,amount) VALUES(?,?,?)",
            (aid, uid, bid),
        )
        await db.commit()

    # Повторно открываем лот: сообщение покажет принятую ставку и актуальную сумму.
    await gov_auction_view(call, auction_id=aid)

