async def get_business_workers(user_id):
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            "SELECT * FROM business_workers WHERE user_id = ? ORDER BY id",
            (user_id,),
        )
        return await cur.fetchall()


def worker_upgrade_cost(worker_type, current_level):
    data = WORKER_TYPES[worker_type]
    return int(data["upgrade"] * current_level)


def worker_salary(worker_type, level):
    return int(WORKER_TYPES[worker_type]["salary"] * (1 + 0.20 * max(0, level - 1)))


async def get_worker_level(user_id, worker_type):
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute(
            "SELECT level FROM business_workers WHERE user_id = ? AND worker_type = ?",
            (user_id, worker_type),
        )
        row = await cur.fetchone()
    return int(row[0] or 0) if row else 0

async def collect_worker_salary(user_id):
    """Списывает зарплату работников не чаще одного раза в сутки."""
    now = datetime.now()
    paid = 0
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT balance FROM players WHERE user_id = ?", (user_id,))
        balance_row = await cur.fetchone()
        balance = int(balance_row["balance"] or 0) if balance_row else 0
        cur = await db.execute("SELECT * FROM business_workers WHERE user_id = ?", (user_id,))
        workers = await cur.fetchall()
        for worker in workers:
            due = True
            if worker["last_paid"]:
                try:
                    due = now - datetime.fromisoformat(str(worker["last_paid"])) >= timedelta(days=1)
                except Exception:
                    due = True
            if not due:
                continue
            salary = worker_salary(worker["worker_type"], int(worker["level"] or 1))
            if balance < salary:
                continue
            balance -= salary
            paid += salary
            await db.execute(
                "UPDATE business_workers SET salary_paid = salary_paid + ?, last_paid = ? WHERE id = ?",
                (salary, now.isoformat(timespec="seconds"), worker["id"]),
            )
        if paid:
            await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (paid, user_id))
        await db.commit()
    return paid


