async def build_business_workers_text(user_id):
    dealership = await get_dealership(user_id)
    if not dealership:
        return (
            "👨‍🔧 <b>РАБОТНИКИ</b>\n\n"
            "Чтобы нанимать сотрудников, сначала открой автосалон за <b>5 000 000 ₽</b>."
        )

    await collect_worker_salary(user_id)
    workers = await get_business_workers(user_id)
    text = "👨‍🔧 <b>КОМАНДА АВТОБИЗНЕСА</b>\n\n"
    text += "Работники влияют на ремонт, оценку, продажи и доставку автомобилей.\n\n"
    if not workers:
        text += "У тебя пока нет сотрудников.\n\n"
    else:
        for w in workers:
            key = w["worker_type"]
            data = WORKER_TYPES[key]
            level = int(w["level"] or 1)
            salary = worker_salary(key, level)
            bonus = int(data["bonus_per_level"] * level * 100)
            text += (
                f"{data['name']}\n"
                f"⭐ Уровень: <b>{level}/5</b>\n"
                f"💰 Зарплата: <b>{salary:,} ₽/день</b>\n"
                f"📈 Бонус: <b>+{bonus}%</b>\n"
                f"🛠 Работ выполнено: <b>{int(w['jobs_done'] or 0)}</b>\n\n"
            )
    text += (
        "💡 Работника можно улучшать до 5 уровня.\n"
        "Если на балансе не хватает денег, зарплата автоматически не списывается до следующей проверки."
    )
    return text


