@dp.callback_query(F.data.startswith("worker_appraise:"))
async def worker_appraise(call):
    car_id = int(call.data.split(":", 1)[1])
    level = await get_worker_level(call.from_user.id, "appraiser")
    if not level:
        await safe_callback_answer("❌ Оценщик не нанят.", show_alert=True)
        return
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT car_name, buy_price, repair_cost, repaired, history_multiplier FROM garage WHERE id = ? AND user_id = ?", (car_id, call.from_user.id))
        car = await cur.fetchone()
    if not car:
        await safe_callback_answer("❌ Машина не найдена.", show_alert=True)
        return
    template = get_car_template(car["car_name"], car["buy_price"], car["repair_cost"])
    if not template:
        await safe_callback_answer("❌ Для этой машины нет рыночных данных.", show_alert=True)
        return
    market_mid = (int(template.get("min", 0)) + int(template.get("max", 0))) // 2
    mult = float(car["history_multiplier"] or 1.0)
    market_mid = int(market_mid * mult)
    accuracy = min(0.12, max(0.03, 0.12 - level * 0.018))
    low = int(market_mid * (1 - accuracy))
    high = int(market_mid * (1 + accuracy))
    certainty = min(99, 55 + level * 9)
    text = (
        "🔍 <b>ОЦЕНКА ОЦЕНЩИКА</b>\n\n"
        f"🚗 <b>{car['car_name']}</b>\n"
        f"⭐ Уровень оценщика: <b>{level}/5</b>\n"
        f"📊 Оценочная стоимость: <b>{low:,} — {high:,} ₽</b>\n"
        f"🎯 Точность оценки: <b>~{certainty}%</b>\n\n"
        "Чем выше уровень оценщика, тем уже диапазон и точнее результат."
    )
    kb = InlineKeyboardBuilder()
    kb.button(text="🔍 Оценить ещё", callback_data="worker_appraise_choose")
    kb.button(text="🔙 Работники", callback_data="business_workers")
    kb.adjust(1)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer("✅ Автомобиль оценён.")


