async def create_player(user_id, username=None):
    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute("SELECT user_id FROM players WHERE user_id = ?", (user_id,))
        player = await cursor.fetchone()

        if not player:
            await db.execute(
                """
                INSERT INTO players
                    (user_id, username, balance, xp, level, registered_at)
                VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
                """,
                (user_id, username, 500000, 0, 1),
            )
        else:
            # Дату регистрации не меняем. Для старых игроков, у которых этого поля не было,
            # ставим дату первого запуска после миграции.
            await db.execute(
                """
                UPDATE players
                SET username = ?,
                    registered_at = COALESCE(registered_at, CURRENT_TIMESTAMP)
                WHERE user_id = ?
                """,
                (username, user_id),
            )

        await db.commit()


async def get_player_username_label(user_id, fallback="Игрок без username"):
    """Получает публичное имя игрока для интерфейса; числовой ID не раскрывает."""
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT username FROM players WHERE user_id = ?", (int(user_id),))
        row = await cur.fetchone()
    if row and row[0]:
        return "@" + str(row[0])
    return fallback


async def get_player(user_id):
    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute(
            "SELECT balance, xp, level FROM players WHERE user_id = ?",
            (user_id,),
        )
        row = await cursor.fetchone()
        if not row:
            return None

        balance, xp, stored_level = row
        actual_level = max(1, int(xp or 0) // 1000 + 1)
        if int(stored_level or 1) != actual_level:
            await db.execute(
                "UPDATE players SET level = ? WHERE user_id = ?",
                (actual_level, user_id),
            )
            await db.commit()
        return (balance, int(xp or 0), actual_level)

