async def show_market(call, city, seed, index, replace=False):

    index %= 12

    ad = get_market_ad(city, seed, index)

    photo_path = find_car_photo(ad["car"])

    caption = market_caption(
        city,
        seed,
        index
    )

    markup = market_keyboard(
        city,
        seed,
        index
    )

    if not photo_path or not photo_path.exists():

        await edit_text_safe(
            call,
            caption +
            "\n\n⚠️ Фото не найдено: "
            "<code>" + str(photo_path) + "</code>",
            parse_mode="HTML",
            reply_markup=markup
        )

        await safe_callback_answer()
        return

    photo = FSInputFile(str(photo_path))

    if replace:

        await call.message.delete()

        await bot.send_photo(
            call.message.chat.id,
            photo=photo,
            caption=caption,
            parse_mode="HTML",
            reply_markup=markup
        )

    else:

        try:

            await call.message.edit_media(
                media=InputMediaPhoto(
                    media=photo,
                    caption=caption,
                    parse_mode="HTML"
                ),
                reply_markup=markup
            )

        except TelegramBadRequest:

            await call.message.delete()

            await bot.send_photo(
                call.message.chat.id,
                photo=FSInputFile(str(photo_path)),
                caption=caption,
                parse_mode="HTML",
                reply_markup=markup
            )


