@dp.callback_query(F.data.startswith("exhibition_cat:"))
async def exhibition_category(call):
    category = call.data.split(":", 1)[1]
    if category not in EXHIBITION_CATEGORIES:
        await safe_callback_answer("❌ Категория не найдена.", show_alert=True)
        return
    text, rows, mine, voted = await build_exhibition_category(call.from_user.id, category)
    can_vote = voted
