# 🏛 МУЗЕИ ИГРОКОВ
# =========================================================

MUSEUM_CREATE_COST = 2_000_000
MUSEUM_DEFAULT_FEE = 5_000
MUSEUM_MAX_CARS = 20
MUSEUM_VISITOR_XP = 20


def museum_day():
    return datetime.now().strftime("%Y-%m-%d")


async def get_museum(owner_id):
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute(
            "SELECT owner_id, name, level, entrance_fee, reputation FROM museums WHERE owner_id = ?",
            (owner_id,)
        )
        return await cursor.fetchone()


async def get_museum_cars(owner_id):
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute(
            "SELECT id, source_car_id, car_name, history_type FROM museum_cars WHERE museum_owner_id = ? ORDER BY id DESC",
            (owner_id,)
        )
        return await cursor.fetchall()


def museum_car_is_eligible(car):
    name = (car.get("name") or "").lower()
    history = car.get("history_type") or "normal"
    rare_marks = ("supra", "skyline", "silvia", "porsche", "maserati", "delta", "wrx", "gta", "mark ii", "boxster")
    return history in ("collector", "rare") or any(x in name for x in rare_marks) or int(car.get("max") or 0) >= 1_000_000


def museum_keyboard(museum, own=False):
    kb = InlineKeyboardBuilder()
    if own:
        kb.button(text="🚗 Добавить экспонат", callback_data="museum_add")
        kb.button(text="🎟 Цена входа", callback_data="museum_fee")
        kb.button(text="📊 Статистика", callback_data="museum_stats")
    else:
        kb.button(text="🎟 Посетить музей", callback_data=f"museum_visit:{museum['owner_id']}")
    kb.button(text="🏛 Все музеи", callback_data="museum_list")
    kb.button(text="🔙 Меню", callback_data="menu")
    kb.adjust(1)
    return kb.as_markup()


def museum_list_keyboard(museums):
    kb = InlineKeyboardBuilder()
    for m in museums:
        kb.button(text=f"🏛 {m['name']} · {m['cars']} авто · {m['entrance_fee']:,} ₽", callback_data=f"museum_open:{m['owner_id']}")
    kb.button(text="🔙 Меню", callback_data="menu")
    kb.adjust(1)
    return kb.as_markup()


async def build_museum_text(owner_id, viewer_id=None):
    viewer_id = owner_id if viewer_id is None else viewer_id
    museum = await get_museum(owner_id)
    if not museum:
        return None, None
    cars = await get_museum_cars(owner_id)
    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute("SELECT username FROM players WHERE user_id = ?", (owner_id,))
        row = await cursor.fetchone()
    username = row[0] if row and row[0] else "без_ника"
    text = (
        f"🏛 <b>{museum['name']}</b>\n"
        f"👤 Владелец: <b>@{username}</b>\n\n"
        f"⭐ Уровень: <b>{museum['level']}</b>\n"
        f"🎟 Билет: <b>{museum['entrance_fee']:,} ₽</b>\n"
        f"❤️ Репутация: <b>{museum['reputation']}</b>\n"
        f"🚗 Экспонатов: <b>{len(cars)}/{MUSEUM_MAX_CARS}</b>\n\n"
    )
    if cars:
        text += "📚 <b>КОЛЛЕКЦИЯ</b>\n"
        for i, car in enumerate(cars[:12], 1):
            mark = " 💎" if car['history_type'] in ("collector", "rare") else ""
            text += f"{i}. 🚘 {car['car_name']}{mark}\n"
        if len(cars) > 12:
            text += f"… ещё {len(cars)-12}\n"
    else:
        text += "📭 Пока нет экспонатов.\n"
    if int(owner_id) == int(viewer_id):
        text += "\n💡 Редкие и дорогие машины можно передать из гаража в музей."
    else:
        text += "\n💡 Оплата билета идёт владельцу музея."
    return text, museum


async def create_museum(user_id):
    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute("SELECT 1 FROM museums WHERE owner_id = ?", (user_id,))
        if await cursor.fetchone():
            return False, "❌ У тебя уже есть музей."
        cursor = await db.execute("SELECT balance FROM players WHERE user_id = ?", (user_id,))
        row = await cursor.fetchone()
        balance = int(row[0] or 0) if row else 0
        if balance < MUSEUM_CREATE_COST:
            return False, f"❌ Нужно {MUSEUM_CREATE_COST:,} ₽."
        await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (MUSEUM_CREATE_COST, user_id))
        await db.execute("INSERT INTO museums (owner_id, name, entrance_fee) VALUES (?, 'Автомузей', ?)", (user_id, MUSEUM_DEFAULT_FEE))
        await db.commit()
    return True, "🏛 Музей открыт!"


@dp.message(F.text == "🏛 Музей")
async def museum_message(message: Message):
    await create_player(message.from_user.id, message.from_user.username)
    museum = await get_museum(message.from_user.id)
    if not museum:
        kb = InlineKeyboardBuilder()
        kb.button(text=f"🏛 Открыть за {MUSEUM_CREATE_COST:,} ₽", callback_data="museum_create")
        kb.button(text="🏛 Посмотреть музеи", callback_data="museum_list")
        kb.button(text="🔙 Меню", callback_data="menu")
        kb.adjust(1)
        await message.answer(
            "🏛 <b>АВТОМУЗЕЙ</b>\n\n"
            "Собирай редкие машины и получай деньги с посетителей.\n\n"
            f"💰 Открытие: <b>{MUSEUM_CREATE_COST:,} ₽</b>\n"
            f"🎟 Базовый билет: <b>{MUSEUM_DEFAULT_FEE:,} ₽</b>",
            parse_mode="HTML", reply_markup=kb.as_markup()
        )
        return
    text, museum = await build_museum_text(message.from_user.id)
    await message.answer(text, parse_mode="HTML", reply_markup=museum_keyboard(museum, own=True))


