@dp.callback_query(F.data == "museum_list")
async def museum_list(call):
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute(
            """SELECT m.owner_id, m.name, m.level, m.entrance_fee, m.reputation, COUNT(mc.id) AS cars
               FROM museums m LEFT JOIN museum_cars mc ON mc.museum_owner_id = m.owner_id
               GROUP BY m.owner_id ORDER BY m.reputation DESC, cars DESC LIMIT 20"""
        )
        museums = await cursor.fetchall()
