@dp.callback_query(F.data == "museum_add")
async def museum_add(call):
    owner_id = call.from_user.id
    museum = await get_museum(owner_id)
    if not museum:
        await safe_callback_answer("❌ Сначала открой музей.", show_alert=True)
        return
    museum_cars = await get_museum_cars(owner_id)
    if len(museum_cars) >= MUSEUM_MAX_CARS:
        await safe_callback_answer("❌ Все места заняты.", show_alert=True)
        return
    rows = await get_garage_rows(owner_id)
    eligible = []
    for row in rows:
        car = build_garage_car(row)
        if car and museum_car_is_eligible(car):
            eligible.append(car)
    if not eligible:
        await safe_callback_answer("❌ Нет подходящих редких автомобилей.", show_alert=True)
        return
    kb = InlineKeyboardBuilder()
    for car in eligible[:20]:
        kb.button(text=f"🏆 {car['name']}", callback_data=f"museum_exhibit:{car['id']}")
    kb.button(text="🔙 Музей", callback_data="museum")
    kb.adjust(1)
    await edit_text_safe(call, "🚗 <b>ВЫБЕРИ ЭКСПОНАТ</b>\n\nМожно выставить редкую, историческую или дорогую машину.", parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer()


@dp.callback_query(F.data.startswith("museum_exhibit:"))
async def museum_exhibit(call):
    owner_id = call.from_user.id
    car_id = int(call.data.split(":", 1)[1])
    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute("SELECT car_name, history_type FROM garage WHERE id = ? AND user_id = ?", (car_id, owner_id))
        car = await cursor.fetchone()
        if not car:
            await safe_callback_answer("❌ Машина не найдена.", show_alert=True)
            return
        cursor = await db.execute("SELECT COUNT(*) FROM museum_cars WHERE museum_owner_id = ?", (owner_id,))
        if int((await cursor.fetchone())[0] or 0) >= MUSEUM_MAX_CARS:
            await safe_callback_answer("❌ Все места заняты.", show_alert=True)
            return
        cursor = await db.execute("SELECT 1 FROM museum_cars WHERE source_car_id = ?", (car_id,))
        if await cursor.fetchone():
            await safe_callback_answer("❌ Машина уже в музее.", show_alert=True)
            return
        await db.execute("INSERT INTO museum_cars (museum_owner_id, source_car_id, car_name, history_type) VALUES (?, ?, ?, ?)", (owner_id, car_id, car[0], car[1] or "normal"))
        await db.execute("DELETE FROM garage WHERE id = ? AND user_id = ?", (car_id, owner_id))
        await db.execute("UPDATE museums SET reputation = reputation + 5 WHERE owner_id = ?", (owner_id,))
        await db.commit()
    text, museum = await build_museum_text(owner_id)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=museum_keyboard(museum, own=True))
    await safe_callback_answer("🏆 Экспонат добавлен!")


@dp.callback_query(F.data.startswith("museum_visit:"))
async def museum_visit(call):
    owner_id = int(call.data.split(":", 1)[1])
    visitor_id = call.from_user.id
    if owner_id == visitor_id:
        await safe_callback_answer("🏛 Это твой музей.")
        return
    museum = await get_museum(owner_id)
    if not museum:
        await safe_callback_answer("❌ Музей не найден.", show_alert=True)
        return
    day = museum_day()
    fee = int(museum["entrance_fee"])
    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute("SELECT 1 FROM museum_visits WHERE museum_owner_id = ? AND visitor_id = ? AND day = ?", (owner_id, visitor_id, day))
        if await cursor.fetchone():
            await safe_callback_answer("✅ Сегодня ты уже посещал этот музей.", show_alert=True)
            return
        cursor = await db.execute("SELECT balance FROM players WHERE user_id = ?", (visitor_id,))
        row = await cursor.fetchone()
        balance = int(row[0] or 0) if row else 0
        if balance < fee:
            await safe_callback_answer(f"❌ Не хватает {fee - balance:,} ₽.", show_alert=True)
            return
        await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (fee, visitor_id))
        await db.execute("UPDATE players SET balance = balance + ? WHERE user_id = ?", (fee, owner_id))
        await db.execute("UPDATE museums SET reputation = reputation + 1 WHERE owner_id = ?", (owner_id,))
        await db.execute("UPDATE players SET xp = xp + ? WHERE user_id = ?", (MUSEUM_VISITOR_XP, visitor_id))
        await db.execute("INSERT INTO museum_visits (museum_owner_id, visitor_id, day, paid) VALUES (?, ?, ?, 1)", (owner_id, visitor_id, day))
        await db.commit()
    await safe_callback_answer(f"🎟 Билет куплен за {fee:,} ₽")


@dp.callback_query(F.data == "museum_fee")
async def museum_fee(call):
    museum = await get_museum(call.from_user.id)
    if not museum:
        await safe_callback_answer("❌ Музей не найден.", show_alert=True)
        return
    kb = InlineKeyboardBuilder()
    for fee in (1000, 5000, 10000, 25000, 50000):
        kb.button(text=f"🎟 {fee:,} ₽", callback_data=f"museum_setfee:{fee}")
    kb.button(text="🔙 Музей", callback_data="museum")
    kb.adjust(1)
    await edit_text_safe(call, "🎟 <b>ЦЕНА БИЛЕТА</b>\n\nВыбери стоимость входа в свой музей.", parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer()


@dp.callback_query(F.data.startswith("museum_setfee:"))
async def museum_setfee(call):
    fee = int(call.data.split(":", 1)[1])
    async with aiosqlite.connect(DB) as db:
        await db.execute("UPDATE museums SET entrance_fee = ? WHERE owner_id = ?", (fee, call.from_user.id))
        await db.commit()
    text, museum = await build_museum_text(call.from_user.id)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=museum_keyboard(museum, own=True))
    await safe_callback_answer(f"🎟 Цена входа: {fee:,} ₽")


@dp.callback_query(F.data == "museum_stats")
async def museum_stats(call):
    museum = await get_museum(call.from_user.id)
    if not museum:
        await safe_callback_answer("❌ Музей не найден.", show_alert=True)
        return
    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute("SELECT COUNT(*), COALESCE(SUM(paid), 0) FROM museum_visits WHERE museum_owner_id = ?", (call.from_user.id,))
        visits, income = await cursor.fetchone()
        cursor = await db.execute("SELECT COUNT(*) FROM museum_visits WHERE museum_owner_id = ? AND day = ?", (call.from_user.id, museum_day()))
        today = int((await cursor.fetchone())[0] or 0)
    text = (
        "📊 <b>СТАТИСТИКА МУЗЕЯ</b>\n\n"
        f"🎟 Сегодня посетителей: <b>{today}</b>\n"
        f"👥 Всего посещений: <b>{visits}</b>\n"
        f"💰 Всего дохода: <b>{income:,} ₽</b>\n"
        f"❤️ Репутация: <b>{museum['reputation']}</b>"
    )
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=museum_keyboard(museum, own=True))
    await safe_callback_answer()


