async def crime_text(user_id: int) -> str:
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute(
            "SELECT operations, successful, failed, earned, fines, notoriety, last_action_at FROM crime_stats WHERE user_id = ?",
            (user_id,)
        )
        row = await cur.fetchone()

    if row:
        operations, successful, failed, earned, fines, notoriety, last_action_at = row
    else:
        operations = successful = failed = earned = fines = notoriety = 0
        last_action_at = None

    text = (
        "🚨 <b>КРИМИНАЛ</b>\n\n"
        f"🔒 Доступ с <b>{CRIME_REQUIRED_LEVEL} уровня</b>.\n\n"
        "Опасный раздел рынка перекупщиков. Здесь всё происходит только в рамках игры: "
        "можно заработать крупную сумму, но есть шанс получить штраф и повысить свою известность.\n\n"
        f"💰 Успешных операций: <b>{successful}</b>\n"
        f"❌ Провалов: <b>{failed}</b>\n"
        f"📦 Всего операций: <b>{operations}</b>\n"
        f"💵 Заработано: <b>{earned:,} ₽</b>\n"
        f"💸 Штрафов: <b>{fines:,} ₽</b>\n"
        f"🔥 Известность: <b>{notoriety}</b>\n\n"
        "Выбери операцию ниже. После действия действует общий кулдаун."
    )
    return text


