@dp.callback_query(F.data.startswith("crime:"))
async def crime_action_callback(call):
    key = call.data.split(":", 1)[1]
    cfg = CRIME_ACTIONS.get(key)
    if not cfg:
        await safe_callback_answer(call, "❌ Операция недоступна.", show_alert=True)
        return

    uid = call.from_user.id
    now = datetime.now()
    player = await get_player(uid)
    player_level = int(player[2] or 1) if player else 1
    if player_level < CRIME_REQUIRED_LEVEL:
        await safe_callback_answer(
            f"🔒 Криминал открывается с {CRIME_REQUIRED_LEVEL} уровня. Твой уровень: {player_level}.",
            show_alert=True,
        )
        return

    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT balance FROM players WHERE user_id = ?", (uid,))
        player = await cur.fetchone()
        if not player:
            await create_player(uid)
            balance = 0
        else:
            balance = int(player[0] or 0)

        cur = await db.execute("SELECT last_action_at FROM crime_stats WHERE user_id = ?", (uid,))
        row = await cur.fetchone()
        last_action = row[0] if row else None

        if last_action:
            try:
                last_dt = datetime.fromisoformat(last_action)
                remaining = (last_dt + timedelta(minutes=CRIME_COOLDOWN_MINUTES) - now).total_seconds()
                if remaining > 0:
                    mins = int(remaining // 60)
                    secs = int(remaining % 60)
                    await safe_callback_answer(call, f"⏳ Следующая операция через {mins} мин. {secs} сек.", show_alert=True)
                    return
            except ValueError:
                pass

        cost = int(cfg["cost"])
        if balance < cost:
            await safe_callback_answer(call, f"❌ Нужно {cost:,} ₽ для начала операции.", show_alert=True)
            return

        success = random.random() < float(cfg["success_chance"])
        await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (cost, uid))

        if success:
            reward = random.randint(*cfg["success"])
            await db.execute("UPDATE players SET balance = balance + ? WHERE user_id = ?", (reward, uid))
            await db.execute("""
                INSERT INTO crime_stats(user_id, operations, successful, failed, earned, fines, notoriety, last_action_at)
                VALUES(?, 1, 1, 0, ?, 0, ?, ?)
                ON CONFLICT(user_id) DO UPDATE SET
                    operations = operations + 1,
                    successful = successful + 1,
                    earned = earned + excluded.earned,
                    notoriety = notoriety + excluded.notoriety,
                    last_action_at = excluded.last_action_at
            """, (uid, reward, int(cfg["notoriety"]), now.isoformat(timespec="seconds")))
            text = (
                f"✅ <b>{cfg['name']}</b>\n\n"
                f"{cfg['success_text']}\n\n"
                f"💸 Вход: <b>{cost:,} ₽</b>\n"
                f"💰 Доход: <b>+{reward:,} ₽</b>\n"
                f"🔥 Известность: <b>+{cfg['notoriety']}</b>"
            )
        else:
            fine = random.randint(*cfg["fail_fine"])
            total_loss = cost + fine
            await db.execute("UPDATE players SET balance = MAX(0, balance - ?) WHERE user_id = ?", (fine, uid))
            await db.execute("""
                INSERT INTO crime_stats(user_id, operations, successful, failed, earned, fines, notoriety, last_action_at)
                VALUES(?, 1, 0, 1, 0, ?, ?, ?)
                ON CONFLICT(user_id) DO UPDATE SET
                    operations = operations + 1,
                    failed = failed + 1,
                    fines = fines + excluded.fines,
                    notoriety = notoriety + excluded.notoriety,
                    last_action_at = excluded.last_action_at
            """, (uid, fine, max(1, int(cfg["notoriety"] // 2)), now.isoformat(timespec="seconds")))
            text = (
                f"❌ <b>{cfg['name']}</b>\n\n"
                f"{cfg['fail_text']}\n\n"
                f"💸 Расход: <b>{cost:,} ₽</b>\n"
                f"🚔 Штраф: <b>{fine:,} ₽</b>\n"
                f"🔥 Известность: <b>+{max(1, int(cfg['notoriety'] // 2))}</b>"
            )

        await db.commit()

    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=crime_keyboard())
    await safe_callback_answer(call)


