@dp.message(PhoneAlertForm.waiting_model_and_price)
async def phone_alert_add_message(message: Message, state: FSMContext):
    raw = " ".join(str(message.text or "").split()).strip()
    parts = raw.rsplit(" ", 1)
    if len(parts) != 2:
        await message.answer("❌ Формат: <b>BMW E36 600000</b>", parse_mode="HTML")
        return
    car_name, price_text = parts
    try:
        target = int(price_text.replace(",", "").replace(" ", "").replace("₽", ""))
    except ValueError:
        await message.answer("❌ Последним значением укажи цену числом.", parse_mode="HTML")
        return
    if not car_name or target <= 0:
        await message.answer("❌ Неверная модель или цена.")
        return
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute(
            "SELECT asking_price FROM player_market_listings l JOIN garage g ON g.id=l.car_id WHERE g.car_name=? AND l.status='active' ORDER BY l.asking_price ASC LIMIT 1",
            (car_name,)
        )
        row = await cur.fetchone()
        current = int(row[0]) if row else 0
        await db.execute(
            "INSERT INTO phone_price_alerts(user_id, car_name, target_price, last_seen_price, active) VALUES(?,?,?,?,1)",
            (message.from_user.id, car_name, target, current),
        )
        await db.commit()
    await state.clear()
    await message.answer(
        f"✅ Уведомление создано.\n\n🚗 {html.escape(car_name)}\n🔔 Сообщить, когда цена будет ≤ <b>{target:,} ₽</b>.",
        parse_mode="HTML", reply_markup=phone_center_keyboard()
    )


