async def phone_price_alert_loop():
    while True:
        try:
            async with aiosqlite.connect(DB) as db:
                db.row_factory = aiosqlite.Row
                alerts_cur = await db.execute(
                    "SELECT id, user_id, car_name, target_price, last_seen_price FROM phone_price_alerts WHERE active=1"
                )
                alerts = await alerts_cur.fetchall()
                for alert in alerts:
                    cur = await db.execute(
                        """SELECT MIN(l.asking_price) FROM player_market_listings l
                           JOIN garage g ON g.id=l.car_id AND g.user_id=l.seller_id
                           WHERE g.car_name=? AND l.status='active'""",
                        (alert["car_name"],)
                    )
                    row = await cur.fetchone()
                    current = int(row[0] or 0) if row and row[0] is not None else 0
                    if current <= 0:
                        continue
                    previous = int(alert["last_seen_price"] or 0)
                    target = int(alert["target_price"])
                    notify = current <= target and (previous == 0 or current < previous)
                    await db.execute("UPDATE phone_price_alerts SET last_seen_price=? WHERE id=?", (current, alert["id"]))
                    if notify:
                        await db.execute(
                            "UPDATE phone_price_alerts SET last_notified_at=CURRENT_TIMESTAMP WHERE id=?",
                            (alert["id"],)
                        )
                        await db.execute(
                            "INSERT INTO phone_messages(user_id,sender_name,subject,message,data,is_read) VALUES(?,?,?,?,?,0)",
                            (
                                alert["user_id"], "Рынок", "Снижение цены",
                                f"Цена на {alert['car_name']} упала до {current:,} ₽. Твоя цель: {target:,} ₽.",
                                "price_alert",
                            )
                        )
                await db.commit()
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            print(f"PHONE ALERT LOOP ERROR: {exc}")
        await asyncio.sleep(60)


