@dp.message(NPCDealForm.waiting_price)
async def npc_offer_enter(message: Message, state: FSMContext):
    try:
        offer_price = int(
            str(message.text).replace(" ", "").replace("₽", "").replace(",", "")
        )
    except (TypeError, ValueError):
        await message.answer("❌ Введи цену только числом, например <b>650000</b>.", parse_mode="HTML")
        return

    if offer_price <= 0:
        await message.answer("❌ Цена должна быть больше нуля.")
        return

    data = await state.get_data()
    deal_id = int(data.get("deal_id", 0))
    deal = await get_npc_deal(message.from_user.id, deal_id)

    if not deal or deal["status"] != "active":
        await state.clear()
        await message.answer("❌ Переговоры уже завершены.")
        return

    current = int(deal["current_price"])
    minimum = int(deal["min_price"])
    rounds = int(deal["rounds"])

    if offer_price >= current:
        ok, result = await npc_purchase(message.from_user.id, deal_id, current)
        await state.clear()
        await message.answer(result, parse_mode="HTML")
        return

    if rounds >= 3:
        await state.clear()
        await message.answer(
            f"❌ Продавец закончил торг. Его последняя цена: <b>{current:,} ₽</b>.",
            parse_mode="HTML",
        )
        return

    if offer_price < minimum:
        if random.random() < 0.55:
            async with aiosqlite.connect(DB) as db:
                await db.execute(
                    "UPDATE phone_npc_deals SET status='declined', rounds=rounds+1, updated_at=CURRENT_TIMESTAMP WHERE id=?",
                    (deal_id,)
                )
                await db.execute(
                    "INSERT INTO phone_messages(user_id,sender_name,subject,message,data,is_read) VALUES(?,?,?,?,?,0)",
                    (
                        message.from_user.id,
                        deal["sender_name"],
                        "Торг закончен",
                        "Слишком низкая цена. Продавец отказался.",
                        f"npc_deal:{deal_id}:closed",
                    )
                )
                await db.commit()
            await state.clear()
            await message.answer("❌ Продавец отказался торговаться. Предложение закрыто.")
            return
        counter = max(minimum, int((current + minimum) / 2))
    else:
        ratio = (offer_price - minimum) / max(1, current - minimum)
        chance = min(0.92, max(0.30, 0.30 + ratio * 0.55 - rounds * 0.08))

        if random.random() <= chance:
            ok, result = await npc_purchase(
                message.from_user.id, deal_id, offer_price
            )
            await state.clear()
            await message.answer(result, parse_mode="HTML")
            return

        counter = max(minimum, int((current + offer_price) / 2))

    async with aiosqlite.connect(DB) as db:
        await db.execute(
            "UPDATE phone_npc_deals SET current_price=?, rounds=rounds+1, updated_at=CURRENT_TIMESTAMP WHERE id=?",
            (counter, deal_id)
        )
        await db.execute(
            "INSERT INTO phone_messages(user_id,sender_name,subject,message,data,is_read) VALUES(?,?,?,?,?,0)",
            (
                message.from_user.id,
                deal["sender_name"],
                "Встречная цена",
                f"Могу уступить до {counter:,} ₽. Как тебе такая цена?",
                f"npc_deal:{deal_id}",
            )
        )
        await db.execute(
            "INSERT INTO phone_outgoing(user_id,recipient_name,subject,message) VALUES(?,?,?,?)",
            (
                message.from_user.id,
                deal["sender_name"],
                "Моё предложение",
                f"Предлагаю {offer_price:,} ₽ за {deal['car_name']}.",
            )
        )
        await db.commit()

    await state.clear()

    kb = InlineKeyboardBuilder()
    kb.button(text="✅ Согласиться", callback_data=f"npc_accept:{deal_id}")
    kb.button(text="💬 Торговаться ещё", callback_data=f"npc_offer:{deal_id}")
    kb.button(text="❌ Отказаться", callback_data=f"npc_decline:{deal_id}")
    kb.adjust(1)

    await message.answer(
        f"💬 <b>ПРОДАВЕЦ ОТВЕТИЛ</b>\n\n"
        f"👤 {html.escape(str(deal['sender_name']))}\n"
        f"🚗 {html.escape(str(deal['car_name']))}\n"
        f"💰 Встречная цена: <b>{counter:,} ₽</b>\n\n"
        "Попробуй ещё раз поторговаться.",
        parse_mode="HTML",
        reply_markup=kb.as_markup(),
    )


