@dp.callback_query(F.data == "phone_achievements")
async def phone_achievements_callback(call):
    uid = call.from_user.id
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT balance, xp, level FROM players WHERE user_id = ?", (uid,))
        player = await cur.fetchone()
        cur = await db.execute("SELECT COUNT(*) FROM garage WHERE user_id = ?", (uid,))
        cars = int((await cur.fetchone())[0] or 0)
        cur = await db.execute("SELECT COUNT(*) FROM player_deals WHERE seller_id = ? OR buyer_id = ?", (uid, uid))
        deals = int((await cur.fetchone())[0] or 0)
        cur = await db.execute("SELECT COUNT(*) FROM exhibition_entries WHERE user_id = ?", (uid,))
        exhibits = int((await cur.fetchone())[0] or 0)
    balance, xp, level = (player if player else (0, 0, 1))
    achievements = [
        ("🔑 Первый гараж", cars >= 1),
        ("💰 Первый миллион", int(balance or 0) >= 1_000_000),
        ("🚗 Коллекционер", cars >= 10),
        ("🤝 Торговец", deals >= 5),
        ("🏆 Выставочник", exhibits >= 3),
        ("👑 Уровень 10", int(level or 1) >= 10),
    ]
    text = "🏆 <b>ДОСТИЖЕНИЯ</b>\n\n"
    for name, done in achievements:
        text += f"{'✅' if done else '🔒'} {name}\n"
    text += f"\n⭐ XP: <b>{int(xp or 0)}</b>\n🏅 Уровень: <b>{int(level or 1)}</b>"
    kb = InlineKeyboardBuilder(); kb.button(text="📱 Телефон", callback_data="phone"); kb.button(text="🔙 Меню", callback_data="menu"); kb.adjust(1)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer(call)


