def phone_media_level(subscribers: int) -> int:
    if subscribers >= 100_000:
        return 10
    if subscribers >= 50_000:
        return 9
    if subscribers >= 25_000:
        return 8
    if subscribers >= 10_000:
        return 7
    if subscribers >= 5_000:
        return 6
    if subscribers >= 2_500:
        return 5
    if subscribers >= 1_000:
        return 4
    if subscribers >= 500:
        return 3
    if subscribers >= 100:
        return 2
    return 1


def phone_media_sponsor_name(level: int) -> str:
    sponsors = {
        1: "AutoParts",
        2: "GazFuel",
        3: "Ozon Drive",
        4: "PetroMax",
        5: "Porsche Center",
    }
    return sponsors.get(level, "ENOT Premium")


async def phone_media_text(user_id: int) -> str:
    await ensure_phone_media(user_id)
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM phone_media WHERE user_id = ?", (user_id,))
        row = await cur.fetchone()
    subs = int(row["subscribers"] or 0)
    views = int(row["views"] or 0)
    videos = int(row["videos"] or 0)
    income = int(row["media_income"] or 0)
    rep = int(row["reputation"] or 0)
    equipment = int(row["equipment"] or 1)
    energy = int(row["energy"] or 100)
    engagement = float(row["engagement"] or 1.0)
    channel_level = int(row["channel_level"] or phone_media_level(subs))
    streak = int(row["streak"] or 0)
    niche = str(row["niche"] or "Автообзоры")
    trust = float(row["trust"] or 35.0)
    audience_fit = float(row["audience_fit"] or 1.0)
    burnout = float(row["burnout"] or 0.0)
    content_quality = float(row["content_quality"] or 50.0)
    level = phone_media_level(subs)
    sponsor = phone_media_sponsor_name(level) if subs >= 500 else "Пока нет спонсора"
    next_subs = next((x for x in [100, 500, 1000, 2500, 5000, 10000, 25000, 50000, 100000] if x > subs), None)
    progress = f"До следующего уровня: {max(0, next_subs - subs):,} подписчиков" if next_subs else "Максимальный уровень канала"
    return (
        "📺 <b>АВТОКАНАЛ</b>\n\n"
        f"📡 Канал: <b>{html.escape(row['channel_name'])}</b>\n"
        f"👥 Подписчики: <b>{subs:,}</b>\n"
        f"👁 Просмотры: <b>{views:,}</b>\n"
        f"🎬 Выпуски: <b>{videos}</b>\n"
        f"⭐ Репутация: <b>{rep}</b>\n"
        f"💰 Доход канала: <b>{income:,} ₽</b>\n"
        f"🏅 Уровень: <b>{level}/10</b>\n"
        f"🎯 Ниша: <b>{html.escape(niche)}</b>\n"
        f"🎥 Оборудование: <b>{equipment}/5</b>\n"
        f"⚡ Энергия: <b>{energy}/100</b>\n"
        f"❤️ Вовлечённость: <b>{engagement:.1f}x</b>\n"
        f"🧠 Доверие аудитории: <b>{trust:.0f}/100</b>\n"
        f"🎯 Попадание в аудиторию: <b>{audience_fit:.2f}x</b>\n"
        f"🎬 Среднее качество: <b>{content_quality:.0f}/100</b>\n"
        f"😵 Выгорание: <b>{burnout:.0f}/100</b>\n"
        f"🔥 Серия выпусков: <b>{streak}</b>\n"
        f"🤝 Спонсор: <b>{sponsor}</b>\n\n"
        f"📈 {progress}"
    )


