@dp.message(MediaForm.waiting_name)
async def media_rename_enter(message: Message, state: FSMContext):
    name = (message.text or "").strip()
    if not 3 <= len(name) <= 24:
        await message.answer("❌ Название должно быть длиной от 3 до 24 символов.")
        return
    banned = ["http://", "https://", "t.me/", "@everyone"]
    if any(x in name.lower() for x in banned):
        await message.answer("❌ Такое название использовать нельзя.")
        return
    uid = message.from_user.id
    await ensure_phone_media(uid)
    async with aiosqlite.connect(DB) as db:
        await db.execute("UPDATE phone_media SET channel_name = ? WHERE user_id = ?", (name, uid))
        await db.commit()
    await state.clear()
    await message.answer("✅ Название канала изменено!\n\n" + await phone_media_text(uid), parse_mode="HTML", reply_markup=phone_media_keyboard())


