@dp.callback_query(F.data.startswith("media_upgrade_buy:"))
async def media_upgrade_buy_callback(call):
    uid = call.from_user.id
    try:
        current = int(call.data.split(":", 1)[1])
    except (ValueError, IndexError):
        await safe_callback_answer(call, "❌ Некорректный уровень улучшения.", show_alert=True)
        return

    costs = {1: 50_000, 2: 150_000, 3: 400_000, 4: 1_000_000}
    cost = costs.get(current)
    if cost is None:
        await safe_callback_answer(call, "❌ Недоступно.", show_alert=True)
        return

    await ensure_phone_media(uid)
    async with aiosqlite.connect(DB) as db:
        # Резервируем средства только при достаточном балансе.
        debit = await db.execute(
            "UPDATE players SET balance = balance - ? WHERE user_id = ? AND balance >= ?",
            (cost, uid, cost),
        )
        if debit.rowcount != 1:
            await db.rollback()
            await safe_callback_answer(call, "❌ Недостаточно денег.", show_alert=True)
            return

        # Защита от повторного нажатия устаревшей кнопки.
        upgrade = await db.execute(
            "UPDATE phone_media SET equipment = equipment + 1 "
            "WHERE user_id = ? AND equipment = ?",
            (uid, current),
        )
        if upgrade.rowcount != 1:
            await db.rollback()
            await safe_callback_answer(
                call,
                "⚠️ Уровень студии уже изменился. Открой раздел развития заново.",
                show_alert=True,
            )
            return
        await db.commit()

    await edit_text_safe(
        call,
        "✅ <b>Студия улучшена!</b>\n\n" + await phone_media_text(uid),
        parse_mode="HTML",
        reply_markup=phone_media_keyboard(),
    )
    await safe_callback_answer(call, "🎥 Качество контента выросло!")


@dp.callback_query(F.data.startswith("media_action:"))
async def media_action_callback(call):
    uid = call.from_user.id
    action = call.data.split(":", 1)[1]
    data = MEDIA_ACTIONS.get(action)
    if not data:
        await safe_callback_answer(call, "❌ Неизвестное действие.", show_alert=True)
        return
    await ensure_phone_media(uid)
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM phone_media WHERE user_id = ?", (uid,))
        row = await cur.fetchone()
        cur = await db.execute("SELECT balance FROM players WHERE user_id = ?", (uid,))
        player = await cur.fetchone()
        balance = int(player[0] or 0) if player else 0
        if balance < data["cost"]:
            await safe_callback_answer(call, f"❌ Нужно {data['cost']:,} ₽.", show_alert=True)
            return
        equipment = int(row["equipment"] or 1)
        subs = int(row["subscribers"] or 0)
        energy = int(row["energy"] or 100)
        engagement = float(row["engagement"] or 1.0)
        streak = int(row["streak"] or 0)
        niche = str(row["niche"] or "Автообзоры")
        energy_cost = {"review": 15, "test": 22, "rare": 30}.get(action, 18)
        if energy < energy_cost:
            await safe_callback_answer(call, f"⚡ Недостаточно энергии. Нужно {energy_cost}, доступно {energy}.", show_alert=True)
            return
        last_action_raw = row["last_action_at"]
        if last_action_raw and int(row["videos"] or 0) > 0:
            try:
                last_dt = datetime.fromisoformat(str(last_action_raw).replace("Z", ""))
                if datetime.now() - last_dt < timedelta(hours=4):
                    wait_h = 4 - (datetime.now() - last_dt).total_seconds() / 3600
                    await safe_callback_answer(call, f"⏳ Аудитория устала от частых публикаций. Следующий выпуск через ~{max(1, int(wait_h))} ч.", show_alert=True)
                    return
            except Exception:
                pass
        trust = float(row["trust"] or 35.0)
        burnout = float(row["burnout"] or 0.0)
        audience_fit = float(row["audience_fit"] or 1.0)
        avg_quality = float(row["content_quality"] or 50.0)
        # Меньше гарантированных подписок: важны качество, доверие, удержание,
        # совпадение с нишей и удача. Плохой ролик способен увести подписчиков.
        quality = min(100, random.randint(35, 70) + equipment * 5 + min(12, streak) * 2 - int(burnout / 12))
        retention = max(0.25, min(1.45, 0.45 + quality / 110 + engagement / 5))
        ctr = max(0.25, min(1.30, 0.45 + equipment * 0.06 + random.uniform(-0.08, 0.12)))
        viral_chance = max(0.0, min(0.35, (quality - 82) / 50))
        viral = 1.0 + (random.uniform(1.0, 3.5) if random.random() < viral_chance else 0.0)
        viral *= max(0.7, min(1.25, audience_fit))
        views_gain = max(40, int(random.randint(*data["views"]) * retention * ctr * viral * (0.65 + equipment * 0.07)))
        # Подписка привязана к просмотрам; высокий trust повышает конверсию.
        follow_rate = max(0.0008, min(0.014, 0.001 + quality / 14000 + trust / 12000))
        subs_gain = int(views_gain * follow_rate * random.uniform(0.65, 1.25))
        if quality < 45 and random.random() < 0.55:
            subs_gain = -max(1, int(subs * random.uniform(0.0002, 0.0012)))
        income = max(0, int(views_gain * random.uniform(4, 13) * (1 + equipment * 0.06)))
        rep_gain = max(0, int((quality - 45) / 12))
        new_engagement = max(0.55, min(2.0, engagement + (0.05 if quality >= 82 else -0.04 if quality < 50 else 0.01)))
        new_trust = max(0.0, min(100.0, trust + (0.6 if quality >= 80 else -0.8 if quality < 48 else 0.1) - burnout * 0.01))
        new_burnout = max(0.0, min(100.0, burnout + 7.0 - (2.0 if quality >= 80 else 0.0)))
        new_avg = max(0.0, min(100.0, avg_quality * 0.82 + quality * 0.18))
        new_streak = streak + 1 if quality >= 55 else max(0, streak - 1)
        debit = await db.execute(
            "UPDATE players SET balance = balance - ? WHERE user_id = ? AND balance >= ?",
            (data["cost"], uid, data["cost"]),
        )
        if debit.rowcount != 1:
            await db.rollback()
            await safe_callback_answer(call, "❌ Баланс изменился. Проверь деньги и попробуй снова.", show_alert=True)
            return

        media_update = await db.execute(
            "UPDATE phone_media SET subscribers = MAX(0, subscribers + ?), views = views + ?, videos = videos + 1, media_income = media_income + ?, reputation = MIN(100, reputation + ?), energy = energy - ?, engagement = ?, streak = ?, trust = ?, burnout = ?, content_quality = ?, last_topic = ?, last_action_at = CURRENT_TIMESTAMP WHERE user_id = ? AND energy >= ?",
            (subs_gain, views_gain, income, rep_gain, energy_cost, new_engagement, new_streak, new_trust, new_burnout, new_avg, data["title"], uid, energy_cost),
        )
        if media_update.rowcount != 1:
            await db.rollback()
            await safe_callback_answer(call, "⚡ Энергия изменилась. Обнови автоканал и попробуй снова.", show_alert=True)
            return

        await db.execute(
            "INSERT INTO phone_media_posts(user_id, post_type, title, quality, subscribers_gain, views_gain, income_gain) VALUES(?,?,?,?,?,?,?)",
            (uid, action, data["title"], quality, subs_gain, views_gain, income),
        )
        await db.commit()
    await edit_text_safe(
        call,
        await phone_media_text(uid) + f"\n\n✅ <b>{data['title']}</b> опубликован!\n👥 +{subs_gain:,} подписчиков\n👁 +{views_gain:,} просмотров\n💰 +{income:,} ₽ дохода",
        parse_mode="HTML", reply_markup=phone_media_keyboard()
    )
    await safe_callback_answer(call, "📺 Выпуск опубликован!")


