async def seed_phone_news():
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT COUNT(*) FROM phone_news")
        count = int((await cur.fetchone())[0] or 0)
        if count == 0:
            rows = [
                ("Рынок оживает", "На рынке стало больше предложений от частников и перекупов."),
                ("Редкие находки", "На заброшенных парковках снова замечают автомобили 90-х."),
                ("Импорт", "В порт поступила новая партия автомобилей из-за границы."),
            ]
            await db.executemany("INSERT INTO phone_news(title, body) VALUES(?, ?)", rows)
            await db.commit()


async def phone_npc_loop():
    await seed_phone_news()
    while True:
        try:
            async with aiosqlite.connect(DB) as db:
                cur = await db.execute("SELECT user_id FROM players")
                users = [int(r[0]) for r in await cur.fetchall()]
            now = utcnow_naive()
            for uid in users:
                async with aiosqlite.connect(DB) as db:
                    cur = await db.execute("SELECT last_sent_at FROM phone_npc_cooldown WHERE user_id = ?", (uid,))
                    row = await cur.fetchone()
                    due = True
                    if row and row[0]:
                        try:
                            due = (now - datetime.fromisoformat(str(row[0]))).total_seconds() >= 1800
                        except Exception:
                            due = True
                    if not due:
                        continue
                    offer = dict(random.choice(PHONE_NPC_OFFERS))
                    limited_key = maybe_roll_limited_spawn_key()
                    if limited_key:
                        limited_car = LIMITED_CARS_BY_KEY[limited_key]
                        offer.update({
                            "sender": "Коллекционер, срочная продажа",
                            "subject": "Эксклюзивный лимитированный экземпляр",
                            "car_name": limited_car["name"],
                            "ask_price": int(limited_car["price"]),
                            "min_price": int(limited_car["price"]),
                            "repair_cost": 0,
                            "condition": "Лимитированный экземпляр с подтверждённой серией. Цена фиксированная, торг не предусмотрен.",
                            "message": f"Есть редкий {limited_car['name']}. Экземпляр лимитированного тиража, при покупке выдаётся уникальный EX-номер. Цена {int(limited_car['price']):,} ₽ без торга.",
                        })
                    cur = await db.execute(
                        """INSERT INTO phone_npc_deals(
                            user_id, sender_name, car_name, asking_price, current_price,
                            min_price, repair_cost, condition_text, limited_car_key
                        ) VALUES(?,?,?,?,?,?,?,?,?)""",
                        (
                            uid,
                            offer["sender"],
                            offer["car_name"],
                            offer["ask_price"],
                            offer["ask_price"],
                            offer["min_price"],
                            offer["repair_cost"],
                            offer["condition"],
                            limited_key,
                        ),
                    )
                    deal_id = cur.lastrowid
                    await db.execute(
                        "INSERT INTO phone_messages(user_id, sender_name, subject, message, data, is_read) VALUES(?, ?, ?, ?, ?, 0)",
                        (
                            uid,
                            offer["sender"],
                            offer["subject"],
                            offer["message"],
                            f"npc_deal:{deal_id}",
                        ),
                    )
                    await db.execute(
                        "INSERT OR REPLACE INTO phone_npc_cooldown(user_id, last_sent_at) VALUES(?, CURRENT_TIMESTAMP)",
                        (uid,),
                    )
                    await db.execute(
                        "INSERT INTO phone_calls(user_id, caller_name, call_type, note) VALUES(?, ?, 'incoming', ?)",
                        (uid, random.choice(PHONE_NPC_CALLS)[0], random.choice(PHONE_NPC_CALLS)[1]),
                    )
                    await db.commit()
                try:
                    await bot.send_message(uid, f"📩 <b>Новое сообщение</b>\n\n👤 <b>{html.escape(offer['sender'])}</b>\n📌 {html.escape(offer['subject'])}\n\n{html.escape(offer['message'])}", parse_mode="HTML")
                except Exception:
                    pass
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            print(f"PHONE LOOP ERROR: {exc}")
        await asyncio.sleep(60)


