@dp.callback_query(F.data.startswith("court_lawyer:"))
async def court_lawyer_callback(call):
    _, raw_case_id, lawyer_key = call.data.split(":")
    case_id = int(raw_case_id)
    lawyer = COURT_LAWYERS.get(lawyer_key)
    if not lawyer:
        await safe_callback_answer(call, "❌ Адвокат не найден.", show_alert=True)
        return

    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            "SELECT * FROM court_cases WHERE id=? AND user_id=? AND status='pending'",
            (case_id, call.from_user.id),
        )
        case = await cur.fetchone()
        if not case:
            await safe_callback_answer(call, "❌ Дело уже завершено или не найдено.", show_alert=True)
            return

        fee = int(lawyer["price"])
        if fee:
            cur = await db.execute("SELECT balance FROM players WHERE user_id=?", (call.from_user.id,))
            player = await cur.fetchone()
            balance = int(player[0] or 0) if player else 0
            if balance < fee:
                await safe_callback_answer(call, f"❌ Не хватает {fee - balance:,} ₽", show_alert=True)
                return
            await db.execute("UPDATE players SET balance=balance-? WHERE user_id=?", (fee, call.from_user.id))

        chance = int(lawyer["chance"])
        won = random.randint(1, 100) <= chance
        status = "won" if won else "lost"
        await db.execute(
            "UPDATE court_cases SET status=?, lawyer=?, resolved_at=CURRENT_TIMESTAMP WHERE id=?",
            (status, lawyer_key, case_id),
        )

        if won:
            cursor = await db.execute(
                """INSERT INTO garage
                (user_id, car_name, buy_price, repair_cost, repaired, history_type, history_multiplier,
                 paparazzi_multiplier, paparazzi_until, registered, original_buy_price, original_purchased_at,
                 purchased_at, owner_count, origin_country, current_country, current_city)
                VALUES (?, ?, ?, ?, 0, 'grey_market_court', ?, 1.0, NULL, 0, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 1, ?, ?, ?)""",
                (
                    call.from_user.id, case["car_name"], int(case["purchase_price"]), int(case["repair_cost"]),
                    1.12 if int(case["market_price"]) > int(case["purchase_price"]) else 1.0,
                    int(case["market_price"]), "Серый рынок", "Россия", "Москва",
                ),
            )
            car_id = cursor.lastrowid
            text = (
                "✅ <b>СУД ВЫИГРАН!</b>\n\n"
                f"🚗 <b>{html.escape(str(case['car_name']))}</b> теперь в твоём гараже.\n"
                f"👨‍⚖️ Адвокат: <b>{lawyer['name']}</b>\n"
                f"💸 Гонорар: <b>{fee:,} ₽</b>\n"
                "⚠️ Автомобиль всё ещё требует легализации/оформления.\n"
                f"🆔 ID автомобиля: <code>{car_id}</code>"
            )
        else:
            text = (
                "❌ <b>СУД ПРОИГРАН!</b>\n\n"
                f"🚔 <b>{html.escape(str(case['car_name']))}</b> конфискован.\n"
                f"👨‍⚖️ Адвокат: <b>{lawyer['name']}</b>\n"
                f"💸 Гонорар: <b>{fee:,} ₽</b>\n\n"
                "Автомобиль потерян, компенсации нет."
            )
        await db.commit()

    kb = InlineKeyboardBuilder()
    kb.button(text="⚖️ Суд", callback_data="court_list")
    kb.button(text="🚗 Гараж", callback_data="garage")
    kb.button(text="🌑 Серый рынок", callback_data="grey_market_new")
    kb.adjust(1)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer(call)


