@dp.callback_query(F.data == "fx_rates")
async def fx_rates_callback(call):
    rates = await get_live_fx_rates()
    now_text = datetime.now().strftime("%d.%m.%Y %H:%M")
    rows = [("USD", "🇺🇸 Доллар", rates.get("USD")), ("EUR", "🇪🇺 Евро", rates.get("EUR")),
            ("JPY", "🇯🇵 Иена", rates.get("JPY")), ("GBP", "🇬🇧 Фунт", rates.get("GBP")),
            ("CNY", "🇨🇳 Юань", rates.get("CNY")), ("KRW", "🇰🇷 Вона", rates.get("KRW")),
            ("AED", "🇦🇪 Дирхам", rates.get("AED")), ("CAD", "🇨🇦 Канадский доллар", rates.get("CAD"))]
    text = "💱 <b>КУРСЫ ВАЛЮТ</b>\n\n"
    if not rates:
        text += "⚠️ Источник временно недоступен. Используются сохранённые курсы, если они есть.\n"
    else:
        text += "Котировки обновляются автоматически перед операциями импорта.\n\n"
        # API rates are currency units for 1 RUB; invert for привычный формат ₽ за 1 единицу.
        for code, name, rub_per_currency in rows:
            if rub_per_currency and rub_per_currency > 0:
                text += f"{name}: <b>{1/rub_per_currency:.4f} ₽</b> за 1 {code}\n"
    text += f"\n🕒 Проверено: <b>{now_text}</b>\n"
    text += "ℹ️ Рыночные котировки могут отличаться от банковских/платёжных курсов."
    kb = InlineKeyboardBuilder()
    kb.button(text="🔄 Обновить", callback_data="fx_rates")
    kb.button(text="🌐 Страны", callback_data="import_countries")
    kb.button(text="🔙 Меню", callback_data="back")
    kb.adjust(1)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer(call)


