@dp.callback_query(F.data.startswith("import_buy:"))
async def import_buy(call):
    _, country, seed, index = call.data.split(":")
    if country not in IMPORT_COUNTRIES:
        await safe_callback_answer("❌ Страна не найдена!", show_alert=True)
        return

    seed = int(seed)
    index = int(index)
    car, total_price = import_total_price(country, seed, index)
    user_id = call.from_user.id
    balance, xp, level = await get_player(user_id)

    if balance < total_price:
        await safe_callback_answer(
            f"❌ Не хватает денег! Нужно {total_price:,} ₽.",
            show_alert=True
        )
        return

    data = IMPORT_COUNTRIES[country]
    history_type = "normal"
    history_multiplier = 1.0
    roll = random.randint(1, 100)

    # Страновые особенности влияют на шанс особой истории.
    if country == "usa" and roll <= 22:
        history_type = "accident"
        history_multiplier = 0.75
        repair = car["repair"] * 3
    elif country == "italy" and roll <= 22:
        history_type = "rare"
        history_multiplier = 1.45
        repair = car["repair"]
    elif country == "japan" and roll <= 22:
        history_type = "collector"
        history_multiplier = 1.25
        repair = car["repair"]
    elif roll <= 10:
        history_type = "profit"
        history_multiplier = 1.35
        repair = car["repair"]
    else:
        repair = car["repair"]

    async with aiosqlite.connect(DB) as db:
        await db.execute(
            "UPDATE players SET balance = balance - ? WHERE user_id = ?",
            (total_price, user_id)
        )
        cur = await db.execute(
            """
            INSERT INTO garage
            (user_id, car_name, buy_price, repair_cost, repaired, history_type, history_multiplier, paparazzi_multiplier, paparazzi_until, origin_country, current_country, current_city, repair_count, repaint_count, restoration_stage, originality_score)
            VALUES (?, ?, ?, ?, 0, ?, ?, ?, ?, ?, ?, ?, 0, 0, 0, 0)
            """,
            (
                user_id,
                car["name"],
                total_price,
                repair,
                history_type,
                history_multiplier,
                1.0,
                None,
                data["name"],
                "Россия",
                "Москва",
            )
        )
        car_id = cur.lastrowid
        now = datetime.now().isoformat(timespec="seconds")
        await db.execute(
            "INSERT INTO vehicle_locations(car_id, country, city, event_at, event_type) VALUES(?,?,?,?,?)",
            (car_id, data["name"], "Импорт", now, "import")
        )
        await db.execute(
            "INSERT INTO vehicle_history(car_id, owner_id, event_type, event_at, amount, details) VALUES(?,?,?,?,?,?)",
            (car_id, user_id, "import", now, total_price, f"Импорт из {data['name']}")
        )
        await db.commit()

    await seasonal_add_stat(user_id, "collection", 1)
    special_text = ""
    if history_type != "normal":
        special_text = "\n🔥 Внимание: автомобиль получил скрытую историю — проверь её в гараже!"

    await edit_text_safe(
        call,
        "✅ <b>ИМПОРТ ЗАВЕРШЁН!</b>\n\n"
        f"{data['emoji']} Страна: <b>{data['name']}</b>\n"
        f"🚗 Автомобиль: <b>{car['name']}</b>\n"
        f"💰 Потрачено: <b>{total_price:,} ₽</b>\n"
        f"🔧 Ремонт: <b>{repair:,} ₽</b>"
        f"{special_text}\n\n"
        "🏠 Машина уже находится в твоём гараже.",
        parse_mode="HTML",
        reply_markup=menu()
    )
    await safe_callback_answer("🎉 Автомобиль импортирован!")


