async def send_garage_card(chat_id, rows, index=0):
    if not rows:
        await bot.send_message(
            chat_id,
            "🏠 <b>Гараж пуст</b>\n\n"
            "У тебя пока нет автомобилей.\n\n"
            "Открой 🚗 Рынок и купи первую машину!",
            parse_mode="HTML",
            reply_markup=menu()
        )
        return

    total = len(rows)
    index %= total
    car = build_garage_car(rows[index])

    if car is None:
        await bot.send_message(
            chat_id,
            "❌ Не удалось загрузить автомобиль из гаража.",
            reply_markup=menu()
        )
        return

    caption = build_garage_caption(car, index, total)
    markup = build_garage_keyboard(car, index, total)
    photo_path = BASE_DIR / car["photo"] if car["photo"] else None

    if photo_path and photo_path.exists():
        await bot.send_photo(
            chat_id,
            photo=FSInputFile(str(photo_path)),
            caption=caption,
            parse_mode="HTML",
            reply_markup=markup
        )
    else:
        await bot.send_message(
            chat_id,
            caption + "\n\n⚠️ Фото автомобиля не найдено.",
            parse_mode="HTML",
            reply_markup=markup
        )


