async def get_service_stats(user_id):
    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute(
            "SELECT last_job, total_income, jobs_count FROM vehicle_services WHERE user_id = ?",
            (user_id,),
        )
        return await cursor.fetchone()


def service_remaining_seconds(last_job):
    if not last_job:
        return 0
    try:
        elapsed = (utcnow_naive() - datetime.fromisoformat(last_job)).total_seconds()
    except (ValueError, TypeError):
        return 0
    return max(0, SERVICE_COOLDOWN_MINUTES * 60 - int(elapsed))


def format_seconds(seconds):
    minutes, sec = divmod(max(0, int(seconds)), 60)
    return f"{minutes} мин. {sec:02d} сек."


def work_keyboard(car_id, cooldown=0, level=1):
    kb = InlineKeyboardBuilder()
    if cooldown <= 0:
        for key, config in SERVICE_CONFIG.items():
            required = JOB_LEVEL_REQUIREMENTS.get(key, 1)
            if level >= required:
                kb.button(text=config["name"], callback_data=f"work_run:{car_id}:{key}")
            else:
                kb.button(text=f"🔒 {config['name']} — с {required} ур.", callback_data=f"work_locked:{required}")
    else:
        kb.button(text=f"⏳ Следующая работа через {format_seconds(cooldown)}", callback_data="work_wait")
    kb.button(text="🔙 Выбрать другую машину", callback_data="work_cars")
    kb.button(text="🏠 Меню", callback_data="menu")
    kb.adjust(1)
    return kb.as_markup()


async def show_work_menu(call, car_id):
    user_id = call.from_user.id
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute(
            "SELECT id, car_name, buy_price, repair_cost, repaired FROM garage WHERE id = ? AND user_id = ?",
            (car_id, user_id),
        )
        car = await cursor.fetchone()

    if not car:
        await safe_callback_answer("❌ Автомобиль не найден.", show_alert=True)
        return

    stats = await get_service_stats(user_id)
    player = await get_player(user_id)
    player_level = int(player[2] or 1) if player else 1
    cooldown = service_remaining_seconds(stats[0] if stats else None)
    total_income = int(stats[1]) if stats else 0
    jobs_count = int(stats[2]) if stats else 0

    status = (
        "✅ Машина исправна."
        if car["repaired"]
        else "⚠️ Машина требует ремонта — заработок снижен на 30%."
    )
    text = (
        "💼 <b>РАБОТА</b>\n\n"
        f"🚗 Машина: <b>{car['car_name']}</b>\n"
        f"{status}\n\n"
        "Выбери работу:\n"
        f"🚕 Яндекс Такси — с {JOB_LEVEL_REQUIREMENTS['yandex_taxi']} уровня\n"
        f"🍔 Яндекс Еда — с {JOB_LEVEL_REQUIREMENTS['yandex_eats']} уровня\n"
        f"📦 Ozon Fresh — с {JOB_LEVEL_REQUIREMENTS['ozon_fresh']} уровня\n"
        f"🛒 Магнит — с {JOB_LEVEL_REQUIREMENTS['magnit']} уровня\n"
        f"\n🏅 Твой уровень: <b>{player_level}</b>\n\n"
        f"💰 Заработано: <b>{total_income:,} ₽</b>\n"
        f"📊 Выполнено заказов: <b>{jobs_count}</b>"
    )
    if cooldown:
        text += f"\n\n⏳ До следующего заказа: <b>{format_seconds(cooldown)}</b>"

    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=work_keyboard(car_id, cooldown, player_level))


