@dp.callback_query(F.data.startswith("work_run:"))
async def work_run_callback(call):
    _, car_id_text, job_key = call.data.split(":", 2)
    car_id = int(car_id_text)
    user_id = call.from_user.id
    config = SERVICE_CONFIG.get(job_key)
    if not config:
        await safe_callback_answer("❌ Такая работа недоступна.", show_alert=True)
        return

    player = await get_player(user_id)
    player_level = int(player[2] or 1) if player else 1
    required_level = JOB_LEVEL_REQUIREMENTS.get(job_key, 1)
    if player_level < required_level:
        await safe_callback_answer(
            f"🔒 Нужно {required_level} уровень. Твой уровень: {player_level}.",
            show_alert=True,
        )
        return

    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute(
            "SELECT id, car_name, buy_price, repair_cost, repaired, mileage, condition FROM garage WHERE id = ? AND user_id = ?",
            (car_id, user_id),
        )
        car = await cursor.fetchone()
        if not car:
            await safe_callback_answer("❌ Автомобиль не найден.", show_alert=True)
            return
        cursor = await db.execute("SELECT registered FROM garage WHERE id = ? AND user_id = ?", (car_id, user_id))
        reg = await cursor.fetchone()
        if not reg or not reg[0]:
            await safe_callback_answer("🪪 Сначала зарегистрируй автомобиль за 25 000 ₽.", show_alert=True)
            return

        cursor = await db.execute(
            "SELECT 1 FROM player_market_listings WHERE car_id = ? AND seller_id = ? AND status = 'active'",
            (car_id, user_id),
        )
        if await cursor.fetchone():
            await safe_callback_answer("❌ Машина уже выставлена на рынке игроков.", show_alert=True)
            return

        cursor = await db.execute(
            "SELECT last_job, total_income, jobs_count FROM vehicle_services WHERE user_id = ?",
            (user_id,),
        )
        stats = await cursor.fetchone()
        cooldown = service_remaining_seconds(stats[0] if stats else None)
        if cooldown > 0:
            await safe_callback_answer(f"⏳ Ещё {format_seconds(cooldown)}.", show_alert=True)
            return

        template = get_car_template(car["car_name"], car["buy_price"], car["repair_cost"])
        if template:
            market_mid = (int(template.get("min", car["buy_price"] or 0)) + int(template.get("max", car["buy_price"] or 0))) // 2
        else:
            market_mid = int(car["buy_price"] or 0)

        payout = min(
            config["cap"],
            config["base"] + int(max(50_000, market_mid) * config["multiplier"]),
        )
        if not car["repaired"]:
            payout = int(payout * 0.70)
        payout = int(payout * random.uniform(0.90, 1.15))

        tip = 0
        if random.random() < config["chance_tip"]:
            tip = random.randint(*config["bonus_tip"])
            payout += tip

        old_income = int(stats[1]) if stats else 0
        old_jobs = int(stats[2]) if stats else 0
        now = utcnow_naive().isoformat(timespec="seconds")

        await db.execute(
            "UPDATE players SET balance = balance + ?, xp = xp + ? WHERE user_id = ?",
            (payout, config["xp"], user_id),
        )
        km=random.randint(45,160); wear=mileage_wear(km,job_key in {"yandex_taxi","yandex_eats"})
        fresh_cur=await db.execute("SELECT * FROM garage WHERE id=? AND user_id=?",(car_id,user_id)); fresh=await fresh_cur.fetchone()
        condition_after=int(car["condition"] or 0)
        if fresh:
            parts={"engine_condition":max(0,clamp_percent(fresh["engine_condition"])-wear["engine"]),"gearbox_condition":max(0,clamp_percent(fresh["gearbox_condition"])-wear["gearbox"]),"suspension_condition":max(0,clamp_percent(fresh["suspension_condition"])-wear["suspension"]),"brakes_condition":max(0,clamp_percent(fresh["brakes_condition"])-wear["brakes"]),"tires_condition":max(0,clamp_percent(fresh["tires_condition"])-wear["tires"]),"fluids_condition":max(0,clamp_percent(fresh["fluids_condition"])-wear["fluids"])}
            condition_after=clamp_percent(sum(parts.values())/6)
            await db.execute("UPDATE garage SET mileage=COALESCE(mileage,0)+?,condition=?,engine_condition=?,gearbox_condition=?,suspension_condition=?,brakes_condition=?,tires_condition=?,fluids_condition=?,last_drive_at=? WHERE id=? AND user_id=?",(km,condition_after,parts["engine_condition"],parts["gearbox_condition"],parts["suspension_condition"],parts["brakes_condition"],parts["tires_condition"],parts["fluids_condition"],now,car_id,user_id))
            await db.execute("INSERT INTO maintenance_history(user_id,car_id,car_name,service_type,amount,mileage,condition_before,condition_after) VALUES(?,?,?,?,?,?,?,?)",(user_id,car_id,car["car_name"],config["name"],0,int(fresh["mileage"] or 0)+km,int(fresh["condition"] or 0),condition_after))

        await db.execute(
            """INSERT INTO vehicle_services(user_id, last_job, total_income, jobs_count)
               VALUES (?, ?, ?, ?)
               ON CONFLICT(user_id) DO UPDATE SET
                   last_job = excluded.last_job,
                   total_income = excluded.total_income,
                   jobs_count = excluded.jobs_count""",
            (user_id, now, old_income + payout, old_jobs + 1),
        )
        await db.commit()

    updated_player = await get_player(user_id)
    player_level = int(updated_player[2] or 1) if updated_player else player_level

    tip_text = f"\n🎁 Чаевые: <b>+{tip:,} ₽</b>" if tip else ""
    result_text = (
        "✅ <b>ЗАКАЗ ВЫПОЛНЕН!</b>\n\n"
        f"{config['name']}\n"
        f"🚗 Машина: <b>{car['car_name']}</b>\n"
        f"💰 Заработок: <b>+{payout:,} ₽</b>\n"
        f"⭐ Опыт: <b>+{config['xp']} XP</b>"
        f"{tip_text}\n\n"
        f"⏳ Следующий заказ через {SERVICE_COOLDOWN_MINUTES} минут."
    )
    await edit_text_safe(
        call,
        result_text,
        parse_mode="HTML",
        reply_markup=work_keyboard(car_id, SERVICE_COOLDOWN_MINUTES * 60, player_level),
    )
    await safe_callback_answer(f"💰 +{payout:,} ₽")


