async def ensure_social(car_id):
    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute("SELECT car_id, followers, views, likes, posts, last_post FROM vehicle_social WHERE car_id = ?", (car_id,))
        row = await cursor.fetchone()
        if row:
            return row
        await db.execute("INSERT INTO vehicle_social (car_id) VALUES (?)", (car_id,))
        await db.commit()
        return (car_id, 0, 0, 0, 0, None)


def social_kb(car_id):
    kb = InlineKeyboardBuilder()
    kb.button(text="📢 Опубликовать пост", callback_data=f"social_post:{car_id}")
    kb.button(text="🔄 Обновить", callback_data=f"social:{car_id}")
    kb.button(text="🔙 К автомобилю", callback_data=f"car:{car_id}")
    kb.button(text="🏠 Гараж", callback_data="garage")
    kb.adjust(1)
    return kb.as_markup()


@dp.callback_query(F.data.regexp(r"^social:\d+$"))
async def social_open(call):
    car_id = int(call.data.split(":", 1)[1])
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute(
            """
            SELECT g.*,
                   p.number AS plate_number,
                   p.plate_type AS plate_type,
                   p.buy_price AS plate_buy_price
            FROM garage g
            LEFT JOIN plates p ON p.id = g.plate_id
            WHERE g.id = ? AND g.user_id = ?
            """,
            (car_id, call.from_user.id)
        )
        row = await cursor.fetchone()
    if not row:
        await safe_callback_answer("❌ Машина не найдена.", show_alert=True)
        return
    social = await ensure_social(car_id)
    car = build_garage_car(row)
    text = (
        "📱 <b>СОЦСЕТИ АВТОМОБИЛЯ</b>\n\n"
        f"🚗 <b>{car['name']}</b>\n\n"
        f"👥 Подписчики: <b>{social[1]:,}</b>\n"
        f"👀 Просмотры: <b>{social[2]:,}</b>\n"
        f"❤️ Лайки: <b>{social[3]:,}</b>\n"
        f"📢 Постов: <b>{social[4]:,}</b>\n\n"
        "Публикуй посты и развивай популярность своего проекта."
    )
    photo = find_car_photo(car)
    if photo and photo.exists():
        try:
            await call.message.edit_media(InputMediaPhoto(media=FSInputFile(str(photo)), caption=text, parse_mode="HTML"), reply_markup=social_kb(car_id))
        except TelegramBadRequest:
            try: await call.message.delete()
            except Exception: pass
            await bot.send_photo(call.message.chat.id, FSInputFile(str(photo)), caption=text, parse_mode="HTML", reply_markup=social_kb(car_id))
    else:
        await edit_text_safe(call, text, parse_mode="HTML", reply_markup=social_kb(car_id))
    await safe_callback_answer()


SOCIAL_COOLDOWN_MINUTES = 60


@dp.callback_query(F.data.startswith("social_post:"))
async def social_post(call):
    try:
        car_id = int(call.data.split(":", 1)[1])
    except (ValueError, IndexError):
        await safe_callback_answer(call, "❌ Некорректный автомобиль.", show_alert=True)
        return
    user_id = call.from_user.id
    now = utcnow_naive()
    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute("SELECT car_name, buy_price, repaired, history_multiplier, paparazzi_multiplier, paparazzi_until FROM garage WHERE id = ? AND user_id = ?", (car_id, user_id))
        car = await cursor.fetchone()
        if not car:
            await safe_callback_answer(call, "❌ Машина не найдена.", show_alert=True); return
        cursor = await db.execute("SELECT followers, views, likes, posts, last_post FROM vehicle_social WHERE car_id = ?", (car_id,))
        social = await cursor.fetchone()
        if not social:
            await db.execute("INSERT INTO vehicle_social (car_id) VALUES (?)", (car_id,))
            followers = views = likes = posts = 0; last_post = None
        else:
            followers, views, likes, posts, last_post = social
        if last_post:
            try:
                remaining = timedelta(minutes=SOCIAL_COOLDOWN_MINUTES) - (now - datetime.fromisoformat(last_post))
                if remaining.total_seconds() > 0:
                    await safe_callback_answer(call, f"⏳ Новый пост через {int(remaining.total_seconds()//60)+1} мин.", show_alert=True); return
            except ValueError:
                pass
        base = max(1, int(car[1] or 1))
        mult = (1.35 if car[2] else 1.0) * float(car[3] or 1.0)
        if car[4] and paparazzi_is_active(car[5]): mult *= float(car[4] or 1.0)
        rng = random.Random(f"social:{user_id}:{car_id}:{posts}:{now.date()}")
        add_views = max(100, int(base / 1000 * rng.uniform(2.0, 4.0) * mult))
        add_followers = max(1, int(add_views * rng.uniform(0.03, 0.08)))
        add_likes = max(1, int(add_views * rng.uniform(0.06, 0.15)))
        await db.execute("UPDATE vehicle_social SET followers=followers+?, views=views+?, likes=likes+?, posts=posts+1, last_post=? WHERE car_id=?", (add_followers, add_views, add_likes, now.isoformat(timespec="seconds"), car_id))
        await db.commit()
    await social_open(call)
    await safe_callback_answer(call, f"📢 Пост опубликован! +{add_followers:,} подписчиков")


