# 🏆 ЗАЛ СЛАВЫ
# =========================================================

async def build_hall_of_fame_text():
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT username, user_id, balance FROM players ORDER BY balance DESC LIMIT 1")
        richest = await cur.fetchone()
        cur = await db.execute("SELECT g.car_name, g.buy_price, g.repaired, g.history_multiplier FROM garage g ORDER BY (g.buy_price * COALESCE(g.history_multiplier,1.0) * CASE WHEN g.repaired=1 THEN 1.1 ELSE 1 END) DESC LIMIT 1")
        expensive = await cur.fetchone()
        cur = await db.execute("SELECT g.car_name, g.buy_price, g.repaired, g.history_multiplier FROM garage g WHERE g.repaired=1 ORDER BY (g.buy_price * COALESCE(g.history_multiplier,1.0)) DESC LIMIT 1")
        tuning = await cur.fetchone()
        cur = await db.execute("""
            SELECT p.username, p.user_id, COUNT(*) AS wins
            FROM exhibition_entries e JOIN players p ON p.user_id=e.user_id
            WHERE e.votes > 0 AND e.votes = (SELECT MAX(e2.votes) FROM exhibition_entries e2 WHERE e2.day=e.day AND e2.category=e.category)
            GROUP BY e.user_id ORDER BY wins DESC LIMIT 1
        """)
        wins = await cur.fetchone()
        cur = await db.execute("SELECT p.username, p.user_id, COUNT(g.id) AS cars FROM players p LEFT JOIN garage g ON g.user_id=p.user_id GROUP BY p.user_id ORDER BY cars DESC, p.balance DESC LIMIT 1")
        collection = await cur.fetchone()
        cur = await db.execute("SELECT p.username, p.user_id, COUNT(v.id) AS visits FROM museums m JOIN players p ON p.user_id=m.owner_id LEFT JOIN museum_visits v ON v.museum_owner_id=m.owner_id GROUP BY m.owner_id ORDER BY visits DESC, m.reputation DESC LIMIT 1")
        museum = await cur.fetchone()

    def who(row):
        if not row: return "нет данных"
        return f"@{row['username']}" if row['username'] else "Игрок без username"

    text="🏆 <b>ЗАЛ СЛАВЫ</b>\n\n"
    text += f"👑 <b>Самый богатый игрок</b> — {who(richest)}\n💰 {richest['balance']:,} ₽\n\n" if richest else "👑 <b>Самый богатый игрок</b> — нет данных\n\n"
    if expensive:
        val=int(float(expensive['buy_price'] or 0)*float(expensive['history_multiplier'] or 1)*(1.1 if expensive['repaired'] else 1)); text += f"🚗 <b>Самая дорогая машина</b> — {expensive['car_name']}\n💰 {val:,} ₽\n\n"
    else: text += "🚗 <b>Самая дорогая машина</b> — нет данных\n\n"
    if tuning:
        score=int(float(tuning['buy_price'] or 0)*float(tuning['history_multiplier'] or 1)); text += f"🔥 <b>Лучший тюнинг</b> — {tuning['car_name']}\n📊 Оценка проекта: {score:,} ₽\n\n"
    else: text += "🔥 <b>Лучший тюнинг</b> — нет данных\n\n"
    text += f"🏁 <b>Больше всего побед</b> — {who(wins)}\n🏆 Побед: {wins['wins']}\n\n" if wins else "🏁 <b>Больше всего побед</b> — пока нет побед\n\n"
    text += f"🚘 <b>Самая большая коллекция</b> — {who(collection)}\n🚗 Машин: {collection['cars']}\n\n" if collection else "🚘 <b>Самая большая коллекция</b> — нет данных\n\n"
    text += f"🏛 <b>Самый посещаемый музей</b> — {who(museum)}\n👥 Посещений: {museum['visits']}\n\n" if museum else "🏛 <b>Самый посещаемый музей</b> — пока нет посещений\n\n"
    text += "📱 Популярность автомобилей развивается через их социальные профили."
    return text


@dp.message(F.text == "🏆 Зал славы")
async def hall_of_fame_message(message: Message):
    await message.answer(await build_hall_of_fame_text(), parse_mode="HTML", reply_markup=forbes_back_keyboard())


