async def plate_market_listings():
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("""
            SELECT l.id, l.seller_id, l.plate_id, l.asking_price, p.number,
                   p.plate_type, p.buy_price, COALESCE(u.username, '') AS username
            FROM plate_market_listings l
            JOIN plates p ON p.id = l.plate_id
            LEFT JOIN players u ON u.user_id = l.seller_id
            WHERE l.status = 'active'
            ORDER BY l.id DESC LIMIT 30
        """)
        return await cur.fetchall()


