@dp.callback_query(F.data == "plate_market_sell")
async def plate_market_sell(call):
    rows = await get_user_plates(call.from_user.id)
    free = [r for r in rows if r[4] is None]
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT plate_id FROM plate_market_listings WHERE seller_id = ? AND status = 'active'", (call.from_user.id,))
        listed = {int(r[0]) for r in await cur.fetchall()}
    kb = InlineKeyboardBuilder()
    text = "🏷 <b>ПРОДАЖА НОМЕРА</b>\n\n"
    count = 0
    for pid, number, ptype, buy_price, _, _ in free:
        if pid in listed:
            continue
        pdata = PLATE_TYPES.get(ptype, PLATE_TYPES['region'])
        suggested = max(1, int(buy_price * float(pdata.get('multiplier', 1.0))))
        kb.button(text=f"{number} · ~{suggested:,} ₽", callback_data=f"plate_market_price:{pid}")
        count += 1
    if count == 0:
        text += "Нет свободных номеров, доступных для выставления."
    else:
        text += "Выбери номер, который хочешь выставить:\n"
    kb.button(text="🔙 Рынок номеров", callback_data="plate_market")
    kb.adjust(1)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer()


