@dp.callback_query(F.data.startswith("plate_market_buy:"))
async def plate_market_buy(call):
    listing_id = int(call.data.split(":", 1)[1])
    buyer_id = call.from_user.id
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        await db.execute("BEGIN IMMEDIATE")
        cur = await db.execute("""
            SELECT l.seller_id, l.plate_id, l.asking_price, p.number
            FROM plate_market_listings l JOIN plates p ON p.id = l.plate_id
            WHERE l.id = ? AND l.status = 'active'
        """, (listing_id,))
        row = await cur.fetchone()
        if not row:
            await db.rollback(); await safe_callback_answer("❌ Номер уже продан.", show_alert=True); return
        if int(row['seller_id']) == buyer_id:
            await db.rollback(); await safe_callback_answer("❌ Нельзя купить свой номер.", show_alert=True); return
        cur = await db.execute("SELECT balance FROM players WHERE user_id = ?", (buyer_id,))
        buyer = await cur.fetchone()
        price = int(row['asking_price'])
        if not buyer or int(buyer[0] or 0) < price:
            await db.rollback(); await safe_callback_answer("❌ Недостаточно денег.", show_alert=True); return
        cur = await db.execute("SELECT 1 FROM garage WHERE plate_id = ?", (row['plate_id'],))
        if await cur.fetchone():
            await db.rollback(); await safe_callback_answer("❌ Номер уже установлен.", show_alert=True); return
        await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (price, buyer_id))
        await db.execute("UPDATE players SET balance = balance + ? WHERE user_id = ?", (price, row['seller_id']))
        await db.execute("UPDATE plates SET user_id = ? WHERE id = ?", (buyer_id, row['plate_id']))
        await db.execute("UPDATE plate_market_listings SET status = 'sold' WHERE id = ?", (listing_id,))
        await db.commit()
    await safe_callback_answer(f"✅ {row['number']} куплен за {price:,} ₽")
    await show_plate_market(call)


