def current_market_event():
    day = utcnow_naive().strftime("%Y-%m-%d")
    rng = random.Random(f"community-market-event:{day}")
    return MARKET_EVENTS[rng.randrange(len(MARKET_EVENTS))]


def market_event_multiplier(car_name, repaired=True, condition=100):
    event = current_market_event()
    normalized = str(car_name or "").casefold()
    if event.get("condition_event"):
        return (1.06 if int(condition or 0) >= 85 else 0.88) if repaired else 0.82
    if event.get("global_event"):
        return float(event.get("multiplier", 1.0))
    # Ключевые слова сверяются по границам строки насколько возможно; для коротких
    # обозначений вроде M/RS используем проверку отдельного токена.
    for keyword in event.get("keywords", ()):
        if len(keyword) <= 2:
            if keyword in normalized.replace("-", " ").split():
                return float(event.get("multiplier", 1.0))
        elif keyword in normalized:
            return float(event.get("multiplier", 1.0))
    return 1.0


