def parse_market_range(raw):
    cleaned = str(raw or "").lower().replace("от", "").replace("до", "-").replace("км", "").replace("₽", "")
    cleaned = cleaned.replace(" ", "").replace(",", "").replace("_", "")
    for separator in ("-", "–", "—", ":"):
        if separator in cleaned:
            bits = cleaned.split(separator, 1)
            def as_int(value):
                return int(value) if value.isdigit() else 0
            low, high = as_int(bits[0]), as_int(bits[1])
            if low and high and low > high:
                low, high = high, low
            return low, high
    if cleaned.isdigit():
        value = int(cleaned)
        return value, value
    raise ValueError("Укажи число или диапазон через дефис.")


