def pmarket_market_price(
    name, buy_price, repair_cost, repaired, history_multiplier=1.0,
    build_engine=None, build_gearbox=None, build_turbo=0,
    mileage=0, condition=100, build_body=None,
    build_suspension=0, build_interior=0, build_paint=0, supply_count=1,
):
    """Стабильная дневная оценка с учётом состояния, тюнинга, события и предложения рынка."""
    template = get_car_template(name, buy_price, repair_cost)
    if not template:
        return max(1, int(buy_price or 1))
    day = utcnow_naive().strftime("%Y-%m-%d")
    seed_text = f"community-price:{day}:{str(name).casefold()}"
    rng = random.Random(seed_text)
    low = max(1, int(template.get("min", buy_price or 1)))
    high = max(low, int(template.get("max", buy_price or low)))
    price = rng.randint(low, high)
    price = int(price * max(0.5, float(history_multiplier or 1.0)))
    price = int(price * (1.0 if repaired else 0.84))

    cond = max(0, min(100, int(condition or 0)))
    price = int(price * (0.65 + cond * 0.0035))
    odo = max(0, int(mileage or 0))
    price = int(price * max(0.70, 1.0 - min(300_000, odo) / 1_000_000))

    # Модификаторы установленных запчастей. Значение не равно полной розничной
    # цене детали: вложения увеличивают оценку проекта, но не возвращаются целиком.
    engines = globals().get("CONSTRUCTOR_ENGINES", {})
    gearboxes = globals().get("CONSTRUCTOR_GEARBOXES", {})
    turbo_cfg = globals().get("CONSTRUCTOR_TURBO", {"multiplier": 1.0})
    engine = engines.get(build_engine or "stock", engines.get("stock", {"multiplier": 1.0}))
    gearbox = gearboxes.get(build_gearbox or "stock", gearboxes.get("stock", {"multiplier": 1.0}))
    tuning_mult = (float(engine.get("multiplier", 1.0)) ** 0.38) * (float(gearbox.get("multiplier", 1.0)) ** 0.45)
    if build_turbo:
        tuning_mult *= float(turbo_cfg.get("multiplier", 1.0)) ** 0.45
    extras = globals().get("CONSTRUCTOR_EXTRAS", {})
    for key, installed in (("body", bool(build_body)), ("suspension", bool(build_suspension)), ("interior", bool(build_interior)), ("paint", bool(build_paint))):
        if installed and key in extras:
            tuning_mult *= float(extras[key].get("multiplier", 1.0))
    price = int(price * max(0.75, min(2.2, tuning_mult)))
    price = int(price * market_event_multiplier(name, bool(repaired), cond))

    # Избыток одинаковых моделей на рынке давит на цену, редкие предложения
    # получают небольшой бонус. Это рыночная оценка, а не гарантия продажи.
    supply = max(0, int(supply_count or 0))
    supply_mult = 1.06 if supply <= 1 else (1.02 if supply <= 3 else (0.97 if supply <= 6 else 0.90))
    price = int(price * supply_mult)
    return max(1, price)


