async def pmarket_listings(user_id=None):
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute("""
            SELECT l.id, l.seller_id, l.car_id, l.asking_price, l.created_at,
                   g.car_name, g.repair_cost, g.repaired, g.buy_price,
                   g.history_type, g.history_multiplier, COALESCE(g.mileage,0) AS mileage,
                   COALESCE(g.condition,100) AS car_condition,
                   g.build_engine, g.build_gearbox, g.build_turbo, g.build_body,
                   COALESCE(g.build_suspension,0) AS build_suspension,
                   COALESCE(g.build_interior,0) AS build_interior,
                   COALESCE(g.build_paint,0) AS build_paint,
                   (SELECT COUNT(*) FROM player_market_listings l2 JOIN garage g2 ON g2.id=l2.car_id AND g2.user_id=l2.seller_id
                    WHERE l2.status='active' AND lower(g2.car_name)=lower(g.car_name)) AS model_supply,
                   COALESCE(p.username, '') AS username,
                   COALESCE((SELECT AVG(r.rating) FROM seller_reviews r WHERE r.seller_id = l.seller_id), 0) AS seller_rating,
                   (SELECT COUNT(*) FROM seller_reviews r WHERE r.seller_id = l.seller_id) AS seller_reviews
            FROM player_market_listings l
            JOIN garage g ON g.id = l.car_id AND g.user_id = l.seller_id
            LEFT JOIN players p ON p.user_id = l.seller_id
            WHERE l.status = 'active'
            ORDER BY l.id DESC
        """)
        rows = await cursor.fetchall()
    if user_id is None:
        return rows[:20]
    filters = await player_market_filters_for(user_id)
    result = []
    for row in rows:
        if filters["make"] and str(filters["make"]).casefold() not in str(row["car_name"] or "").casefold():
            continue
        price = int(row["asking_price"] or 0)
        if int(filters["min_price"] or 0) and price < int(filters["min_price"]):
            continue
        if int(filters["max_price"] or 0) and price > int(filters["max_price"]):
            continue
        template = get_car_template(row["car_name"], row["buy_price"], row["repair_cost"])
        year_value = template.get("year") if template else None
        try:
            year_value = int(year_value)
        except (TypeError, ValueError):
            year_value = None
        if int(filters["min_year"] or 0) and (year_value is None or year_value < int(filters["min_year"])):
            continue
        if int(filters["max_year"] or 0) and (year_value is None or year_value > int(filters["max_year"])):
            continue
        mileage = int(row["mileage"] or 0)
        if int(filters["min_mileage"] or 0) and mileage < int(filters["min_mileage"]):
            continue
        if int(filters["max_mileage"] or 0) and mileage > int(filters["max_mileage"]):
            continue
        state_filter = str(filters.get("condition") or "any")
        if state_filter == "repaired" and not int(row["repaired"] or 0):
            continue
        if state_filter == "needs_repair" and int(row["repaired"] or 0):
            continue
        if state_filter == "good" and int(row["car_condition"] or 0) < 85:
            continue
        result.append(row)
        if len(result) >= 20:
            break
    return result


