@dp.message(PlayerMarketFilterForm.waiting_value)
async def pmarket_filter_value_message(message: Message, state: FSMContext):
    data = await state.get_data()
    key = str(data.get("filter_key", ""))
    raw = " ".join(str(message.text or "").split()).strip()
    if not raw:
        await message.answer("❌ Значение не должно быть пустым. Напиши «сброс», чтобы очистить поле.")
        return
    filters = await player_market_filters_for(message.from_user.id)
    clear = raw.casefold() in {"сброс", "сбросить", "любое", "любой"}
    try:
        if key == "make":
            filters["make"] = "" if clear else raw[:40]
        elif key in {"price", "year", "mileage"}:
            low, high = (0, 0) if clear else parse_market_range(raw)
            prefix = {"price": "price", "year": "year", "mileage": "mileage"}[key]
            filters[f"min_{prefix}"] = low
            filters[f"max_{prefix}"] = high
            if key == "year" and any(v and not 1880 <= v <= datetime.now().year + 2 for v in (low, high)):
                raise ValueError("Год должен быть в разумном диапазоне (1880–текущий год+2).")
            if key == "mileage" and max(low, high) > 2_000_000:
                raise ValueError("Пробег не должен превышать 2 000 000 км.")
            if key == "price" and max(low, high) > 10_000_000_000:
                raise ValueError("Цена слишком велика.")
        elif key == "condition":
            norm = raw.casefold()
            mapping = {
                "любое": "any", "сброс": "any", "сбросить": "any", "любой": "any",
                "отремонтирована": "repaired", "отремонтирован": "repaired", "ремонт готов": "repaired",
                "требует ремонта": "needs_repair", "не отремонтирована": "needs_repair",
                "хорошее состояние": "good", "хорошее": "good", "85%": "good",
            }
            if norm not in mapping:
                raise ValueError("Не понял состояние. Выбери: любое, отремонтирована, требует ремонта или хорошее состояние.")
            filters["condition"] = mapping[norm]
        else:
            raise ValueError("Неизвестный фильтр. Открой фильтры рынка ещё раз.")
    except ValueError as exc:
        await message.answer("❌ " + html.escape(str(exc)), parse_mode="HTML")
        return

    async with aiosqlite.connect(DB) as db:
        await db.execute("""
            INSERT INTO player_market_filters
                (user_id, make, min_price, max_price, min_year, max_year, min_mileage, max_mileage, condition, updated_at)
            VALUES(?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP)
            ON CONFLICT(user_id) DO UPDATE SET
                make=excluded.make, min_price=excluded.min_price, max_price=excluded.max_price,
                min_year=excluded.min_year, max_year=excluded.max_year,
                min_mileage=excluded.min_mileage, max_mileage=excluded.max_mileage,
                condition=excluded.condition, updated_at=CURRENT_TIMESTAMP
        """, (
            int(message.from_user.id), str(filters.get("make") or ""),
            int(filters.get("min_price") or 0), int(filters.get("max_price") or 0),
            int(filters.get("min_year") or 0), int(filters.get("max_year") or 0),
            int(filters.get("min_mileage") or 0), int(filters.get("max_mileage") or 0),
            str(filters.get("condition") or "any"),
        ))
        await db.commit()
    await state.clear()
    filters = await player_market_filters_for(message.from_user.id)
    await message.answer(
        "✅ Фильтр сохранён.\n\n" + player_market_filter_summary(filters),
        parse_mode="HTML", reply_markup=player_market_filters_keyboard(),
    )


