@dp.callback_query(F.data.startswith("pmarket_view:"))
async def pmarket_view(call):
    listing_id = int(call.data.split(":")[1])
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute("""
            SELECT l.id, l.seller_id, l.car_id, l.asking_price,
                   g.car_name, g.buy_price, g.repair_cost, g.repaired,
                   g.history_type, g.history_multiplier, COALESCE(g.mileage,0) AS mileage,
                   COALESCE(g.condition,100) AS car_condition,
                   g.build_engine, g.build_gearbox, g.build_turbo, g.build_body,
                   COALESCE(g.build_suspension,0) AS build_suspension,
                   COALESCE(g.build_interior,0) AS build_interior,
                   COALESCE(g.build_paint,0) AS build_paint,
                   (SELECT COUNT(*) FROM player_market_listings l2 JOIN garage g2 ON g2.id=l2.car_id AND g2.user_id=l2.seller_id
                    WHERE l2.status='active' AND lower(g2.car_name)=lower(g.car_name)) AS model_supply,
                   p.username,
                   COALESCE((SELECT AVG(r.rating) FROM seller_reviews r WHERE r.seller_id = l.seller_id), 0) AS seller_rating,
                   (SELECT COUNT(*) FROM seller_reviews r WHERE r.seller_id = l.seller_id) AS seller_reviews
            FROM player_market_listings l
            JOIN garage g ON g.id = l.car_id AND g.user_id = l.seller_id
            LEFT JOIN players p ON p.user_id = l.seller_id
            WHERE l.id = ? AND l.status = 'active'
        """, (listing_id,))
        row = await cursor.fetchone()

    if not row:
        await safe_callback_answer("❌ Объявление уже снято или продано.", show_alert=True)
        return

    market = pmarket_market_price(
        row['car_name'], row['buy_price'], row['repair_cost'], row['repaired'], row['history_multiplier'],
        row['build_engine'], row['build_gearbox'], row['build_turbo'], row['mileage'], row['car_condition'],
        row['build_body'], row['build_suspension'], row['build_interior'], row['build_paint'], row['model_supply'],
    )
    seller = f"@{row['username']}" if row['username'] else "Продавец без username"
    status = "✅ отремонтирована" if row['repaired'] else "🔧 требует ремонта"
    text = (
        "📣 <b>ОБЪЯВЛЕНИЕ ИГРОКА</b>\n\n"
        f"🚗 <b>{row['car_name']}</b>\n"
        f"👤 Продавец: <b>{seller}</b>\n"
        f"{seller_rating_text(float(row['seller_rating'] or 0), int(row['seller_reviews'] or 0))}\n"
        f"💰 Цена продавца: <b>{row['asking_price']:,} ₽</b>\n"
        f"📊 Ориентир рынка: <b>{market:,} ₽</b>\n"
        f"🛣 Пробег: <b>{int(row['mileage'] or 0):,} км</b>\n"
        f"❤️ Состояние кузова/узлов: <b>{int(row['car_condition'] or 0)}%</b>\n"
        f"🔧 Состояние: <b>{status}</b>\n\n"
        "Покупатель может предложить свою цену, продавец выберет лучшее предложение."
    )
    markup = await pmarket_keyboard_for_listing(listing_id, row['asking_price'], row['seller_id'], call.from_user.id)
    kb_extra = InlineKeyboardBuilder()
    kb_extra.button(text="👤 Профиль продавца", callback_data=f"social_player:{row['seller_id']}")
    for button_row in getattr(markup, "inline_keyboard", []):
        for button in button_row:
            kb_extra.button(text=button.text, callback_data=button.callback_data)
    kb_extra.adjust(1)
    markup = kb_extra.as_markup()
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=markup)
    await safe_callback_answer()


