@dp.callback_query(F.data.startswith("ptrade_start:"))
async def ptrade_start(call):
    listing_id = int(call.data.split(":")[1])
    user_id = call.from_user.id
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute("""
            SELECT l.id, l.seller_id, l.car_id, l.asking_price, g.car_name
            FROM player_market_listings l
            JOIN garage g ON g.id = l.car_id AND g.user_id = l.seller_id
            WHERE l.id = ? AND l.status = 'active'
        """, (listing_id,))
        listing = await cursor.fetchone()
        if not listing:
            await safe_callback_answer("❌ Объявление уже закрыто.", show_alert=True)
            return
        if int(listing['seller_id']) == user_id:
            await safe_callback_answer("❌ Нельзя предложить обмен своей машине.", show_alert=True)
            return
        cursor = await db.execute("""
            SELECT id, car_name, buy_price, repair_cost, repaired, history_multiplier
            FROM garage
            WHERE user_id = ?
            ORDER BY id DESC
            LIMIT 30
        """, (user_id,))
        cars = await cursor.fetchall()
        active_ids = await db.execute_fetchall("SELECT car_id FROM player_market_listings WHERE seller_id = ? AND status = 'active'", (user_id,))
        active_ids = {int(x[0]) for x in active_ids}

    cars = [car for car in cars if int(car['id']) not in active_ids and int(car['id']) != int(listing['car_id'])]
    kb = InlineKeyboardBuilder()
    for car in cars:
        market = pmarket_market_price(car['car_name'], car['buy_price'], car['repair_cost'], car['repaired'], car['history_multiplier'])
        kb.button(text=f"🚗 {car['car_name']} · ~{market:,} ₽", callback_data=f"ptrade_car:{listing_id}:{car['id']}")
    kb.button(text="🔙 К автомобилю", callback_data=f"pmarket_view:{listing_id}")
    kb.adjust(1)
    text = (
        "🤝 <b>ПРЕДЛОЖИТЬ ОБМЕН</b>\n\n"
        f"🚗 Хочешь получить: <b>{listing['car_name']}</b>\n\n"
        "Выбери автомобиль из своего гаража. Затем можно добавить денежную доплату."
    )
    if not cars:
        text += "\n\n❌ В гараже нет подходящих машин для обмена."
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer()


@dp.callback_query(F.data.startswith("ptrade_car:"))
async def ptrade_car(call):
    _, listing_text, car_text = call.data.split(":")
    listing_id, car_id = int(listing_text), int(car_text)
    user_id = call.from_user.id
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute("""
            SELECT l.id, l.seller_id, l.car_id, l.asking_price, g.car_name, g.buy_price,
                   g.repair_cost, g.repaired, g.history_multiplier, g.build_engine, g.build_gearbox, g.build_turbo,
                   g.build_body, COALESCE(g.mileage,0) AS mileage, COALESCE(g.condition,100) AS car_condition,
                   COALESCE(g.build_suspension,0) AS build_suspension, COALESCE(g.build_interior,0) AS build_interior,
                   COALESCE(g.build_paint,0) AS build_paint,
                   (SELECT COUNT(*) FROM player_market_listings l2 JOIN garage g2 ON g2.id=l2.car_id AND g2.user_id=l2.seller_id
                    WHERE l2.status='active' AND lower(g2.car_name)=lower(g.car_name)) AS model_supply
            FROM player_market_listings l
            JOIN garage g ON g.id = l.car_id AND g.user_id = l.seller_id
            WHERE l.id = ? AND l.status = 'active'
        """, (listing_id,))
        listing = await cursor.fetchone()
        cursor = await db.execute("""
            SELECT id, car_name, buy_price, repair_cost, repaired, history_multiplier,
                   build_engine, build_gearbox, build_turbo, build_body,
                   COALESCE(mileage,0) AS mileage, COALESCE(condition,100) AS car_condition,
                   COALESCE(build_suspension,0) AS build_suspension, COALESCE(build_interior,0) AS build_interior,
                   COALESCE(build_paint,0) AS build_paint,
                   (SELECT COUNT(*) FROM player_market_listings l2 JOIN garage g2 ON g2.id=l2.car_id AND g2.user_id=l2.seller_id
                    WHERE l2.status='active' AND lower(g2.car_name)=lower(garage.car_name)) AS model_supply
            FROM garage WHERE id = ? AND user_id = ?
        """, (car_id, user_id))
        offered = await cursor.fetchone()
        if not listing or not offered or int(listing['seller_id']) == user_id:
            await safe_callback_answer("❌ Машина или объявление больше недоступны.", show_alert=True)
            return

    target_value = pmarket_market_price(
        listing['car_name'], listing['buy_price'], listing['repair_cost'], listing['repaired'], listing['history_multiplier'],
        listing['build_engine'], listing['build_gearbox'], listing['build_turbo'], listing['mileage'], listing['car_condition'],
        listing['build_body'], listing['build_suspension'], listing['build_interior'], listing['build_paint'], listing['model_supply'],
    )
    offer_value = pmarket_market_price(
        offered['car_name'], offered['buy_price'], offered['repair_cost'], offered['repaired'], offered['history_multiplier'],
        offered['build_engine'], offered['build_gearbox'], offered['build_turbo'], offered['mileage'], offered['car_condition'],
        offered['build_body'], offered['build_suspension'], offered['build_interior'], offered['build_paint'], offered['model_supply'],
    )
    diff = max(0, target_value - offer_value)
    suggestions = sorted({0, int(diff * 0.5), diff, int(diff * 1.25)})
    kb = InlineKeyboardBuilder()
    for money in suggestions:
        label = "🤝 Без доплаты" if money == 0 else f"💵 +{money:,} ₽"
        kb.button(text=label, callback_data=f"ptrade_send:{listing_id}:{car_id}:{money}")
    kb.button(text="🔙 Выбрать другую машину", callback_data=f"ptrade_start:{listing_id}")
    kb.adjust(1)
    await edit_text_safe(
        call,
        "🤝 <b>УСЛОВИЯ ОБМЕНА</b>\n\n"
        f"🚗 Ты отдаёшь: <b>{offered['car_name']}</b>\n"
        f"🚘 Получаешь: <b>{listing['car_name']}</b>\n\n"
        f"📊 Ориентир твоего авто: ~{offer_value:,} ₽\n"
        f"📊 Ориентир встречного авто: ~{target_value:,} ₽\n\n"
        "Выбери размер доплаты. Её платит покупатель при завершении сделки.",
        parse_mode="HTML", reply_markup=kb.as_markup()
    )
    await safe_callback_answer()


@dp.callback_query(F.data.startswith("ptrade_send:"))
async def ptrade_send(call):
    _, listing_text, car_text, money_text = call.data.split(":")
    listing_id, from_car_id, money = int(listing_text), int(car_text), int(money_text)
    buyer_id = call.from_user.id
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute("""
            SELECT l.id, l.seller_id, l.car_id, l.asking_price, g.car_name
            FROM player_market_listings l
            JOIN garage g ON g.id = l.car_id AND g.user_id = l.seller_id
            WHERE l.id = ? AND l.status = 'active'
        """, (listing_id,))
        listing = await cursor.fetchone()
        cursor = await db.execute("SELECT car_name FROM garage WHERE id = ? AND user_id = ?", (from_car_id, buyer_id))
        offered = await cursor.fetchone()
        if not listing or not offered or int(listing['seller_id']) == buyer_id:
            await safe_callback_answer("❌ Сделка больше недоступна.", show_alert=True)
            return
        if money < 0:
            await safe_callback_answer("❌ Некорректная доплата.", show_alert=True)
            return
        if money:
            cursor = await db.execute("SELECT balance FROM players WHERE user_id = ?", (buyer_id,))
            bal = await cursor.fetchone()
            if not bal or int(bal[0] or 0) < money:
                await safe_callback_answer("❌ Недостаточно денег для доплаты.", show_alert=True)
                return
        cursor = await db.execute("SELECT 1 FROM player_market_listings WHERE car_id = ? AND status = 'active'", (from_car_id,))
        if await cursor.fetchone():
            await safe_callback_answer("❌ Твоя машина уже выставлена на рынке.", show_alert=True)
            return
        cursor = await db.execute(
            "INSERT INTO trades (from_user_id, to_user_id, from_car_id, to_car_id, money_from, status, from_confirmed, to_confirmed) VALUES (?, ?, ?, ?, ?, 'pending', 0, 0)",
            (buyer_id, listing['seller_id'], from_car_id, listing['car_id'], money),
        )
        trade_id = cursor.lastrowid
        await db.commit()

    try:
        kb = InlineKeyboardBuilder()
        kb.button(text="✅ Принять обмен", callback_data=f"ptrade_accept:{trade_id}")
        kb.button(text="❌ Отклонить", callback_data=f"ptrade_reject:{trade_id}")
        kb.adjust(1)
        extra = f"\n💵 Доплата: <b>{money:,} ₽</b>" if money else "\n💵 Без доплаты"
        await bot.send_message(
            listing['seller_id'],
            "🤝 <b>НОВОЕ ПРЕДЛОЖЕНИЕ ОБМЕНА</b>\n\n"
            f"🚗 Ты отдаёшь: <b>{listing['car_name']}</b>\n"
            f"🚘 Тебе предлагают: <b>{offered['car_name']}</b>{extra}\n\n"
            "Ты можешь принять или отклонить обмен.",
            parse_mode="HTML", reply_markup=kb.as_markup()
        )
    except Exception:
        pass
    await safe_callback_answer("🤝 Предложение обмена отправлено!")


async def finalize_player_trade(trade_id: int):
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        await db.execute("BEGIN IMMEDIATE")
        cur = await db.execute("""
            SELECT t.id,t.from_user_id,t.to_user_id,t.from_car_id,t.to_car_id,t.money_from,
                   g1.car_name AS from_car_name,g2.car_name AS to_car_name,
                   p1.username AS from_username,p2.username AS to_username
            FROM trades t
            JOIN garage g1 ON g1.id=t.from_car_id AND g1.user_id=t.from_user_id
            JOIN garage g2 ON g2.id=t.to_car_id AND g2.user_id=t.to_user_id
            LEFT JOIN players p1 ON p1.user_id=t.from_user_id
            LEFT JOIN players p2 ON p2.user_id=t.to_user_id
            WHERE t.id=? AND t.status='pending' AND t.from_confirmed=1 AND t.to_confirmed=1
        """, (trade_id,))
        trade=await cur.fetchone()
        if not trade:
            await db.rollback(); return False, "❌ Сделка уже закрыта или активы больше недоступны.", None
        cur=await db.execute("SELECT balance FROM players WHERE user_id=?", (trade['from_user_id'],))
        bal=await cur.fetchone()
        money=int(trade['money_from'] or 0)
        if money and (not bal or int(bal[0] or 0)<money):
            await db.rollback(); return False, "❌ У отправителя недостаточно денег для доплаты.", None
        now=datetime.now().isoformat(timespec='seconds')
        if money:
            await db.execute("UPDATE players SET balance=balance-? WHERE user_id=?", (money,trade['from_user_id']))
            await db.execute("UPDATE players SET balance=balance+? WHERE user_id=?", (money,trade['to_user_id']))
        await db.execute("UPDATE garage SET user_id=?, owner_count=COALESCE(owner_count,1)+1, purchased_at=? WHERE id=? AND user_id=?", (trade['from_user_id'],now,trade['to_car_id'],trade['to_user_id']))
        await db.execute("UPDATE garage SET user_id=?, owner_count=COALESCE(owner_count,1)+1, purchased_at=? WHERE id=? AND user_id=?", (trade['to_user_id'],now,trade['from_car_id'],trade['from_user_id']))
        await db.execute("UPDATE player_market_listings SET status='traded' WHERE car_id=? AND status='active'", (trade['to_car_id'],))
        await db.execute("UPDATE player_market_offers SET status='rejected' WHERE listing_id IN (SELECT id FROM player_market_listings WHERE car_id=?) AND status='pending'", (trade['to_car_id'],))
        await db.execute("UPDATE trades SET status='accepted' WHERE id=?", (trade_id,))
        cur=await db.execute("INSERT INTO player_deals(seller_id,buyer_id,car_id,amount,deal_type) VALUES(?,?,?,?, 'trade')", (trade['to_user_id'],trade['from_user_id'],trade['to_car_id'],money))
        deal_id=cur.lastrowid
        from_name = "@" + str(trade["from_username"]) if trade["from_username"] else "игроком без username"
        to_name = "@" + str(trade["to_username"]) if trade["to_username"] else "игроком без username"
        await db.execute("INSERT INTO vehicle_history(car_id,owner_id,event_type,event_at,amount,details) VALUES(?,?,?,?,?,?)", (trade['to_car_id'],trade['from_user_id'],'trade',now,money,f"Обмен с {to_name}"))
        await db.execute("INSERT INTO vehicle_history(car_id,owner_id,event_type,event_at,amount,details) VALUES(?,?,?,?,?,?)", (trade['from_car_id'],trade['to_user_id'],'trade',now,money,f"Обмен с {from_name}"))
        await db.commit()
    return True, None, deal_id


def trade_contract_text(trade):
    return (
        "📜 <b>ДОГОВОР СДЕЛКИ</b>\n\n"
        f"🤝 Сделка №<b>{int(trade['id'])}</b>\n"
        f"👤 Отправитель: <b>{html.escape('@' + str(trade['from_username']) if trade['from_username'] else 'Без username')}</b>\n"
        f"👤 Получатель: <b>{html.escape('@' + str(trade['to_username']) if trade['to_username'] else 'Без username')}</b>\n\n"
        f"🚗 Отправляется: <b>{html.escape(str(trade['from_car_name']))}</b>\n"
        f"🚘 Получается: <b>{html.escape(str(trade['to_car_name']))}</b>\n"
        f"💰 Доплата: <b>{int(trade['money_from'] or 0):,} ₽</b>\n\n"
        "🛡 Передача произойдёт только после подтверждения обеих сторон."
    )

@dp.callback_query(F.data.startswith("ptrade_accept:"))
async def ptrade_accept(call):
    trade_id=int(call.data.split(":")[1]); uid=call.from_user.id
    async with aiosqlite.connect(DB) as db:
        db.row_factory=aiosqlite.Row
        cur=await db.execute("""SELECT t.*,g1.car_name AS from_car_name,g2.car_name AS to_car_name FROM trades t JOIN garage g1 ON g1.id=t.from_car_id JOIN garage g2 ON g2.id=t.to_car_id WHERE t.id=? AND t.status='pending'""",(trade_id,)); trade=await cur.fetchone()
        if not trade or int(trade['to_user_id'])!=uid:
            await safe_callback_answer(call,"❌ Сделка недоступна.",show_alert=True); return
        await db.execute("UPDATE trades SET to_confirmed=1 WHERE id=?",(trade_id,)); await db.commit()
    kb=InlineKeyboardBuilder(); kb.button(text="🔒 Подтвердить сделку",callback_data=f"ptrade_confirm:{trade_id}"); kb.button(text="📜 Договор",callback_data=f"ptrade_contract:{trade_id}"); kb.button(text="💬 Чат сделки",callback_data=f"ptrade_chat:{trade_id}"); kb.button(text="❌ Отклонить",callback_data=f"ptrade_reject:{trade_id}"); kb.adjust(1)
    await edit_text_safe(call, trade_contract_text(trade), parse_mode="HTML", reply_markup=kb.as_markup())
    try: await bot.send_message(trade['from_user_id'], "🤝 <b>Игрок согласился с условиями.</b>\nТеперь нажми «🔒 Подтвердить сделку», чтобы завершить обмен.",parse_mode="HTML",reply_markup=kb.as_markup())
    except Exception: pass
    await safe_callback_answer(call,"✅ Условия приняты")

@dp.callback_query(F.data.startswith("ptrade_confirm:"))
async def ptrade_confirm(call):
    trade_id=int(call.data.split(":")[1]); uid=call.from_user.id
    async with aiosqlite.connect(DB) as db:
        db.row_factory=aiosqlite.Row
        cur=await db.execute("SELECT * FROM trades WHERE id=? AND status='pending'",(trade_id,)); trade=await cur.fetchone()
        if not trade or uid not in (int(trade['from_user_id']),int(trade['to_user_id'])):
            await safe_callback_answer(call,"❌ Сделка недоступна.",show_alert=True); return
        col="from_confirmed" if uid==int(trade['from_user_id']) else "to_confirmed"
        await db.execute(f"UPDATE trades SET {col}=1 WHERE id=?",(trade_id,)); await db.commit()
        cur=await db.execute("SELECT from_confirmed,to_confirmed FROM trades WHERE id=?",(trade_id,)); flags=await cur.fetchone()
    if not flags or not int(flags[0]) or not int(flags[1]):
        await edit_text_safe(call,"🔒 <b>ТВОЁ ПОДТВЕРЖДЕНИЕ ПОЛУЧЕНО</b>\n\nОжидаем подтверждение второй стороны.\n🛡 Активы пока не передаются.",parse_mode="HTML",reply_markup=community_keyboard())
        other=int(trade['to_user_id']) if uid==int(trade['from_user_id']) else int(trade['from_user_id'])
        try: await bot.send_message(other,"🔒 Вторая сторона подтвердила сделку. Осталось твоё подтверждение — после него обмен завершится.",parse_mode="HTML",reply_markup=InlineKeyboardBuilder().as_markup())
        except Exception: pass
        await safe_callback_answer(call,"🔒 Подтверждено")
        return
    ok,msg,deal_id=await finalize_player_trade(trade_id)
    if not ok:
        await safe_callback_answer(call,msg,show_alert=True); return
    review=InlineKeyboardBuilder(); review.button(text="⭐ Оценить партнёра",callback_data=f"review_prompt:{deal_id}"); review.button(text="👥 Сообщество",callback_data="community"); review.adjust(1)
    result=("✅ <b>СДЕЛКА ЗАВЕРШЕНА</b>\n\n"
            f"🚗 Получено: <b>{html.escape(str(trade['to_car_name']))}</b>\n"
            f"🚘 Передано: <b>{html.escape(str(trade['from_car_name']))}</b>\n"
            f"💰 Доплата: <b>{int(trade['money_from'] or 0):,} ₽</b>\n\n"
            "🛡 Гарант: обе стороны подтвердили передачу.")
    await edit_text_safe(call,result,parse_mode="HTML",reply_markup=review.as_markup())
    other=int(trade['to_user_id']) if uid==int(trade['from_user_id']) else int(trade['from_user_id'])
    try: await bot.send_message(other,result,parse_mode="HTML",reply_markup=review.as_markup())
    except Exception: pass
    await safe_callback_answer(call,"🤝 Обмен завершён")

@dp.callback_query(F.data.startswith("ptrade_contract:"))
async def ptrade_contract(call):
    tid=int(call.data.split(":")[1])
    async with aiosqlite.connect(DB) as db:
        db.row_factory=aiosqlite.Row
        cur=await db.execute("SELECT t.*,g1.car_name AS from_car_name,g2.car_name AS to_car_name FROM trades t JOIN garage g1 ON g1.id=t.from_car_id JOIN garage g2 ON g2.id=t.to_car_id WHERE t.id=?",(tid,)); trade=await cur.fetchone()
    if not trade: await safe_callback_answer(call,"❌ Договор не найден.",show_alert=True); return
