@dp.callback_query(F.data.startswith("review_prompt:"))
async def review_prompt(call):
    deal_id = int(call.data.split(":")[1])
    user_id = call.from_user.id
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute("SELECT id, seller_id, buyer_id FROM player_deals WHERE id = ?", (deal_id,))
        deal = await cursor.fetchone()
        cursor = await db.execute("SELECT 1 FROM seller_reviews WHERE deal_id = ?", (deal_id,))
        existing = await cursor.fetchone()
    if not deal or int(deal['buyer_id']) != user_id:
        await safe_callback_answer("❌ Отзыв недоступен.", show_alert=True)
        return
    if existing:
        await safe_callback_answer("✅ Ты уже оценил эту сделку.", show_alert=True)
        return
    kb = InlineKeyboardBuilder()
    for rating in range(5, 0, -1):
        kb.button(text="⭐" * rating, callback_data=f"review:{deal_id}:{rating}")
    kb.button(text="🔙 Назад", callback_data="pmarket")
    kb.adjust(1)
    await edit_text_safe(call, "⭐ <b>ОЦЕНИ ПРОДАВЦА</b>\n\nКак прошла сделка? Выбери оценку от 1 до 5 звёзд.", parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer()


@dp.callback_query(F.data.startswith("review:"))
async def review_submit(call):
    _, deal_text, rating_text = call.data.split(":")
    deal_id, rating = int(deal_text), int(rating_text)
    reviewer_id = call.from_user.id
    if rating < 1 or rating > 5:
        await safe_callback_answer("❌ Некорректная оценка.", show_alert=True)
        return
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute("SELECT seller_id, buyer_id FROM player_deals WHERE id = ?", (deal_id,))
        deal = await cursor.fetchone()
        if not deal or int(deal['buyer_id']) != reviewer_id:
            await safe_callback_answer("❌ Отзыв недоступен.", show_alert=True)
            return
        try:
            await db.execute(
                "INSERT INTO seller_reviews (deal_id, reviewer_id, seller_id, rating, comment) VALUES (?, ?, ?, ?, '')",
                (deal_id, reviewer_id, deal['seller_id'], rating),
            )
            await db.commit()
        except aiosqlite.IntegrityError:
            await safe_callback_answer("✅ Ты уже оставил отзыв.", show_alert=True)
            return
        cursor = await db.execute("SELECT AVG(rating), COUNT(*) FROM seller_reviews WHERE seller_id = ?", (deal['seller_id'],))
        avg_rating, reviews = await cursor.fetchone()
    await edit_text_safe(
        call,
        "✅ <b>ОТЗЫВ СОХРАНЁН!</b>\n\n"
        f"⭐ Твоя оценка: <b>{rating}/5</b>\n"
        f"📣 Репутация продавца: <b>{float(avg_rating or 0):.1f}/5</b>\n"
        f"📝 Отзывов: <b>{int(reviews or 0)}</b>",
        parse_mode="HTML", reply_markup=menu()
    )
    try:
        await bot.send_message(deal['seller_id'], f"⭐ Тебе оставили отзыв: <b>{rating}/5</b>\n📣 Текущая репутация: <b>{float(avg_rating or 0):.1f}/5</b>", parse_mode="HTML")
    except Exception:
        pass
    await safe_callback_answer("⭐ Спасибо за отзыв!")


