@dp.callback_query(F.data.startswith("pmarket_offer:"))
async def pmarket_offer(call):
    _, listing_id_text, price_text = call.data.split(":")
    listing_id, offer_price = int(listing_id_text), int(price_text)
    buyer_id = call.from_user.id
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute("SELECT seller_id, car_id, asking_price FROM player_market_listings WHERE id = ? AND status = 'active'", (listing_id,))
        listing = await cursor.fetchone()
        if not listing:
            await safe_callback_answer("❌ Объявление уже закрыто.", show_alert=True)
            return
        if int(listing['seller_id']) == buyer_id:
            await safe_callback_answer("Нельзя торговаться за собственную машину.", show_alert=True)
            return
        cursor = await db.execute("SELECT balance FROM players WHERE user_id = ?", (buyer_id,))
        bal_row = await cursor.fetchone()
        balance = int(bal_row[0] or 0) if bal_row else 0
        if balance < offer_price:
            await safe_callback_answer("❌ Недостаточно денег для такого предложения.", show_alert=True)
            return
        cursor = await db.execute("SELECT id FROM player_market_offers WHERE listing_id = ? AND buyer_id = ? AND status = 'pending'", (listing_id, buyer_id))
        existing = await cursor.fetchone()
        if existing:
            await db.execute("UPDATE player_market_offers SET offer_price = ?, created_at = CURRENT_TIMESTAMP WHERE id = ?", (offer_price, existing[0]))
        else:
            await db.execute("INSERT INTO player_market_offers (listing_id, buyer_id, offer_price) VALUES (?, ?, ?)", (listing_id, buyer_id, offer_price))
        cur = await db.execute("SELECT seller_id FROM player_market_listings WHERE id = ?", (listing_id,))
        seller_row = await cur.fetchone()
        seller_name = "Продавец без username" if seller_row else "Продавец"
        if seller_row:
            cur = await db.execute("SELECT username FROM players WHERE user_id = ?", (seller_row[0],))
            urow = await cur.fetchone()
            if urow and urow[0]:
                seller_name = f"@{urow[0]}"
        await db.execute(
            "INSERT INTO phone_outgoing(user_id,recipient_name,subject,message) VALUES(?,?,?,?)",
            (buyer_id, seller_name, "Предложение по автомобилю", f"Предлагаю {offer_price:,} ₽ за автомобиль на рынке игроков."),
        )
        await db.commit()
    await safe_callback_answer(f"💬 Предложение {offer_price:,} ₽ отправлено продавцу!")
    try:
        await bot.send_message(
            listing['seller_id'],
            f"📣 <b>НОВОЕ ПРЕДЛОЖЕНИЕ</b>\n\n🚗 Машина в твоём объявлении\n💰 Предложили: <b>{offer_price:,} ₽</b>\n\nОткрой 📣 Рынок игроков → Мои объявления → Предложения.",
            parse_mode="HTML"
        )
    except Exception:
        pass


