@dp.callback_query(F.data.startswith("pmarket_accept:"))
async def pmarket_accept(call):
    offer_id = int(call.data.split(":")[1])
    seller_id = call.from_user.id
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        await db.execute("BEGIN IMMEDIATE")
        cursor = await db.execute("""
            SELECT o.id, o.listing_id, o.buyer_id, o.offer_price,
                   l.seller_id, l.car_id, g.car_name, g.buy_price, g.repair_cost, g.repaired,
                   g.history_type, g.history_multiplier, g.build_engine, g.build_gearbox, g.build_turbo,
                   g.build_body, COALESCE(g.mileage,0) AS mileage, COALESCE(g.condition,100) AS car_condition,
                   COALESCE(g.build_suspension,0) AS build_suspension, COALESCE(g.build_interior,0) AS build_interior,
                   COALESCE(g.build_paint,0) AS build_paint,
                   (SELECT COUNT(*) FROM player_market_listings l2 JOIN garage g2 ON g2.id=l2.car_id AND g2.user_id=l2.seller_id
                    WHERE l2.status='active' AND lower(g2.car_name)=lower(g.car_name)) AS model_supply
            FROM player_market_offers o
            JOIN player_market_listings l ON l.id = o.listing_id
            JOIN garage g ON g.id = l.car_id AND g.user_id = l.seller_id
            WHERE o.id = ? AND o.status = 'pending' AND l.status = 'active'
        """, (offer_id,))
        offer = await cursor.fetchone()
        if not offer or int(offer['seller_id']) != seller_id:
            await db.rollback()
            await safe_callback_answer("❌ Предложение уже недоступно.", show_alert=True)
            return
        cursor = await db.execute("SELECT balance FROM players WHERE user_id = ?", (offer['buyer_id'],))
        buyer_row = await cursor.fetchone()
        buyer_balance = int(buyer_row[0] or 0) if buyer_row else 0
        if buyer_balance < offer['offer_price']:
            await db.rollback()
            await safe_callback_answer("❌ У покупателя уже недостаточно денег.", show_alert=True)
            return

        await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (offer['offer_price'], offer['buyer_id']))
        await db.execute("UPDATE players SET balance = balance + ? WHERE user_id = ?", (offer['offer_price'], seller_id))
        await db.execute("""
            INSERT INTO garage
            (user_id, car_name, buy_price, repair_cost, repaired, history_type, history_multiplier, paparazzi_multiplier, paparazzi_until, plate_id,
             purchased_at, original_buy_price, original_purchased_at, owner_count, vin, registered, registered_at,
             build_engine, build_gearbox, build_turbo, build_body, build_suspension, build_interior, build_paint,
             mileage, condition, engine_condition, gearbox_condition, suspension_condition,
             brakes_condition, tires_condition, fluids_condition, last_drive_at, last_maintenance_at, maintenance_spend, maintenance_initialized)
            SELECT ?, car_name, ?, repair_cost, repaired, history_type, history_multiplier, paparazzi_multiplier, paparazzi_until, plate_id,
                   ?, original_buy_price, original_purchased_at, COALESCE(owner_count,1)+1, vin, registered, registered_at,
                   build_engine, build_gearbox, build_turbo, build_body, build_suspension, build_interior, build_paint,
                   mileage, condition, engine_condition, gearbox_condition, suspension_condition,
                   brakes_condition, tires_condition, fluids_condition, last_drive_at, last_maintenance_at, maintenance_spend, maintenance_initialized
            FROM garage WHERE id = ? AND user_id = ?
        """, (offer['buyer_id'], offer['offer_price'], datetime.now().isoformat(timespec='seconds'), offer['car_id'], seller_id))
        await db.execute("DELETE FROM garage WHERE id = ? AND user_id = ?", (offer['car_id'], seller_id))
        await db.execute("UPDATE player_market_listings SET status = 'sold' WHERE id = ?", (offer['listing_id'],))
        await db.execute("UPDATE player_market_offers SET status = 'accepted' WHERE id = ?", (offer_id,))
        await db.execute("UPDATE player_market_offers SET status = 'rejected' WHERE listing_id = ? AND id != ? AND status = 'pending'", (offer['listing_id'], offer_id))
        deal_cur = await db.execute(
            "INSERT INTO player_deals (seller_id, buyer_id, car_id, amount, deal_type) VALUES (?, ?, ?, ?, 'sale')",
            (seller_id, offer['buyer_id'], offer['car_id'], offer['offer_price'])
        )
        deal_id = deal_cur.lastrowid
        await db.commit()

    sale_profit = offer['offer_price'] - offer['buy_price'] - (offer['repair_cost'] if offer['repaired'] else 0)
    await seasonal_add_stat(seller_id, "profit", sale_profit)
    await seasonal_add_stat(int(offer['buyer_id']), "collection", 1)
    if sale_profit > 0:
        await player_daily_progress(seller_id, "profitable_sale")
    buyer_market_value = pmarket_market_price(
        offer['car_name'], offer['buy_price'], offer['repair_cost'], offer['repaired'], offer['history_multiplier'],
        offer['build_engine'], offer['build_gearbox'], offer['build_turbo'], offer['mileage'], offer['car_condition'],
        offer['build_body'], offer['build_suspension'], offer['build_interior'], offer['build_paint'], offer['model_supply'],
    )
    if int(offer['offer_price']) < int(buyer_market_value):
        await player_daily_progress(int(offer['buyer_id']), "buy_below_market")
    await edit_text_safe(
        call,
        "✅ <b>СДЕЛКА СОСТОЯЛАСЬ!</b>\n\n"
        f"🚗 {offer['car_name']}\n"
        f"💰 Цена продажи: <b>{offer['offer_price']:,} ₽</b>\n"
        f"📈 Твой результат: <b>{sale_profit:+,} ₽</b>\n\n"
        "🏠 Машина отправлена покупателю.",
        parse_mode="HTML", reply_markup=menu()
    )
    try:
        review_kb = InlineKeyboardBuilder()
        review_kb.button(text="⭐ Оценить продавца", callback_data=f"review_prompt:{deal_id}")
        review_kb.adjust(1)
        await bot.send_message(
            offer['buyer_id'],
            f"🎉 <b>ПОКУПКА НА РЫНКЕ ИГРОКОВ!</b>\n\n🚗 {offer['car_name']}\n💰 Цена: <b>{offer['offer_price']:,} ₽</b>\n🏠 Машина уже в твоём гараже.\n\nОцени продавца после сделки.",
            parse_mode="HTML",
            reply_markup=review_kb.as_markup(),
        )
    except Exception:
        pass
    await safe_callback_answer("💰 Сделка завершена!")


