async def get_user_plates(user_id, installed_only=False):
    async with aiosqlite.connect(DB) as db:
        query = """
            SELECT p.id, p.number, p.plate_type, p.buy_price,
                   g.id AS car_id, g.car_name
            FROM plates p
            LEFT JOIN garage g ON g.plate_id = p.id
            WHERE p.user_id = ?
        """
        params = [user_id]
        if installed_only:
            query += " AND g.id IS NOT NULL"
        query += " ORDER BY p.id DESC"
        cursor = await db.execute(query, params)
        return await cursor.fetchall()


