async def execute_plate_roll(call):
    """Списывает фиксированную цену и сразу выдаёт случайный уникальный номер."""
    user_id = call.from_user.id
    keys = list(PLATE_TYPES.keys())
    weights = [int(PLATE_TYPES[key].get("weight", 1)) for key in keys]
    total_weight = sum(weights)
    plate_type = random.choices(keys, weights=weights, k=1)[0]
    data = PLATE_TYPES[plate_type]

    try:
        async with aiosqlite.connect(DB) as db:
            await db.execute("BEGIN IMMEDIATE")
            cur = await db.execute(
                "SELECT balance FROM players WHERE user_id = ?", (user_id,)
            )
            player = await cur.fetchone()
            balance = int(player[0] or 0) if player else 0
            if not player or balance < PLATE_ROLL_COST:
                await db.rollback()
                await safe_callback_answer(
                    call,
                    f"❌ Один прокрут стоит {PLATE_ROLL_COST:,} ₽. Не хватает денег.",
                    show_alert=True,
                )
                return

            # Регистрируем комбинацию в той же транзакции, что и списание денег.
            # Так номер не может одновременно достаться двум игрокам.
            number = await claim_unique_plate_number(db, plate_type, user_id)
            if not number:
                await db.rollback()
                await safe_callback_answer(
                    call, "❌ Не удалось найти свободную комбинацию. Попробуй ещё раз.",
                    show_alert=True,
                )
                return

            cur = await db.execute(
                "UPDATE players SET balance = balance - ? WHERE user_id = ? AND balance >= ?",
                (PLATE_ROLL_COST, user_id, PLATE_ROLL_COST),
            )
            if cur.rowcount != 1:
                await db.rollback()
                await safe_callback_answer(
                    call, "❌ Недостаточно денег. Попробуй ещё раз.", show_alert=True
                )
                return

            # buy_price остаётся оценкой типа номера для существующих рынков/продажи;
            # purchase_cost хранит реально списанную фиксированную цену прокрута.
            await db.execute(
                "INSERT INTO plates (user_id, number, plate_type, buy_price, purchase_cost) "
                "VALUES (?, ?, ?, ?, ?)",
                (user_id, number, plate_type, int(data["price"]), PLATE_ROLL_COST),
            )
            await db.commit()
    except aiosqlite.IntegrityError:
        await safe_callback_answer(
            call, "❌ Комбинация только что занята. Прокрути ещё раз.", show_alert=True
        )
        return
    except Exception:
        await safe_callback_answer(
            call, "❌ Не удалось выполнить прокрут. Деньги не должны быть списаны.",
            show_alert=True,
        )
        return

    plate_score = {
        "region": 1, "mirror": 3, "lucky": 5, "triple": 12, "gold": 30,
        "government": 15, "military": 4, "police": 5, "taxi": 2,
        "diplomatic": 20, "trailer": 1, "transit": 1, "motorcycle": 1,
        "classic": 6, "letters": 10, "electric": 2,
    }.get(plate_type, 1)
    await seasonal_add_stat(user_id, "rare_plates", plate_score)
    chance = weights[keys.index(plate_type)] / total_weight * 100 if total_weight else 0
    await edit_text_safe(
        call,
        "🎉 <b>НОМЕР ВЫПАЛ!</b>\n\n"
        f"🏷 <b>{number}</b>\n"
        f"{data['name']}\n"
        f"🎯 Шанс этой редкости: <b>{chance:g}%</b>\n"
        f"💸 Стоимость прокрута: <b>{PLATE_ROLL_COST:,} ₽</b>\n\n"
        f"{plate_effect_text(plate_type)}\n\n"
        "🔒 Номер сразу сохранён в «Мои номера» и навсегда занесён в реестр.\n"
        "Тип и формат выбираются случайно — купить конкретную серию отдельно нельзя.",
        parse_mode="HTML",
        reply_markup=plate_roll_result_keyboard(),
    )
    await safe_callback_answer(call, "✅ Номер выпал и добавлен в коллекцию!")


