async def show_plates_inventory(call, page=0):
    """Показывает инвентарь номерных знаков постранично, не превышая лимит Telegram."""
    rows = await get_user_plates(call.from_user.id)
    page_size = 5
    total_pages = max(1, (len(rows) + page_size - 1) // page_size)
    page = max(0, min(int(page or 0), total_pages - 1))
    page_rows = rows[page * page_size:(page + 1) * page_size]

    kb = InlineKeyboardBuilder()
    text = "🏷 <b>МОИ НОМЕРА</b>\n\n"
    if not rows:
        text += "У тебя пока нет номерных знаков."
    else:
        text += f"📄 Страница <b>{page + 1}/{total_pages}</b> · Всего номеров: <b>{len(rows)}</b>\n\n"
        for pid, number, ptype, buy_price, car_id, car_name in page_rows:
            pdata = PLATE_TYPES.get(ptype, PLATE_TYPES["region"])
            state = f"🚗 {html.escape(str(car_name or ''))}" if car_id else "📦 свободен"
            bonus_pct = round((float(pdata.get("multiplier", 1.0)) - 1.0) * 100)
            bonus_label = f"+{bonus_pct}%" if bonus_pct > 0 else "0%"
            safe_number = html.escape(str(number or "Без номера"))
            text += (
                f"{html.escape(str(pdata['name']))} — <b>{safe_number}</b>\n"
                f"{html.escape(str(pdata.get('feature', 'Коллекционный номер')))}\n"
                f"📈 Коэффициент: <b>×{pdata.get('multiplier', 1.0):.2f} ({bonus_label})</b>\n"
                f"🎯 {html.escape(str(pdata.get('effect', 'Влияет на расчётную цену автомобиля.')))}\n"
                f"{state}\n\n"
            )
            if ptype == "exclusive":
                kb.button(text=f"💎 EX закреплён · {number}", callback_data=f"limited_catalog")
            elif car_id is None:
                sell_price = max(1, int(buy_price * pdata['multiplier'] * 0.75))
                kb.button(text=f"💰 Продать {number} — {sell_price:,} ₽", callback_data=f"plate_sell:{pid}")
            else:
                kb.button(text=f"🔓 Снять {number}", callback_data=f"plate_uninstall:{pid}")

        if total_pages > 1:
            if page > 0:
                kb.button(text="⬅️ Назад", callback_data=f"plates_inventory_page:{page - 1}")
            kb.button(text=f"📄 {page + 1}/{total_pages}", callback_data=f"plates_inventory_page:{page}")
            if page < total_pages - 1:
                kb.button(text="Вперёд ➡️", callback_data=f"plates_inventory_page:{page + 1}")

    kb.button(text="🎲 Прокрутить номер", callback_data="plates_shop")
    kb.button(text="🔙 Меню", callback_data="menu")
    kb.adjust(1)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())


