@dp.callback_query(F.data.startswith("plate_install:"))
async def plate_install(call):
    _, car_id, plate_id = call.data.split(":")
    car_id = int(car_id); plate_id = int(plate_id)
    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute("SELECT id FROM garage WHERE id = ? AND user_id = ?", (car_id, call.from_user.id))
        if not await cursor.fetchone():
            await safe_callback_answer(call, "❌ Машина не найдена.", show_alert=True); return
        cursor = await db.execute("SELECT id FROM plates WHERE id = ? AND user_id = ?", (plate_id, call.from_user.id))
        if not await cursor.fetchone():
            await safe_callback_answer("❌ Номер не найден.", show_alert=True); return
        cursor = await db.execute("SELECT plate_id FROM garage WHERE id = ?", (car_id,))
        current = await cursor.fetchone()
        if current and current[0]:
            await safe_callback_answer("❌ Сначала сними старый номер.", show_alert=True); return
        cursor = await db.execute("SELECT 1 FROM garage WHERE plate_id = ?", (plate_id,))
        if await cursor.fetchone():
            await safe_callback_answer("❌ Этот номер уже установлен.", show_alert=True); return
        await db.execute("UPDATE garage SET plate_id = ? WHERE id = ? AND user_id = ?", (plate_id, car_id, call.from_user.id))
        await db.commit()
    await safe_callback_answer("🏷 Номер установлен!")
    await show_garage_for_call(call, 0)


@dp.callback_query(F.data.startswith("plate_uninstall:"))
async def plate_uninstall(call):
    plate_id = int(call.data.split(":")[1])
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT plate_type FROM plates WHERE id=? AND user_id=?", (plate_id, call.from_user.id))
        plate_row = await cur.fetchone()
        if plate_row and plate_row[0] == "exclusive":
            await safe_callback_answer(call, "💎 EX-номер нельзя снять: он является частью лимитированного экземпляра.", show_alert=True)
            return
        await db.execute("UPDATE garage SET plate_id = NULL WHERE plate_id = ? AND user_id = ?", (plate_id, call.from_user.id))
        await db.commit()
    await safe_callback_answer("🔓 Номер снят. Теперь его можно продать отдельно.")
    await plates_inventory(call)


@dp.callback_query(F.data.startswith("plate_sell:"))
async def plate_sell(call):
    plate_id = int(call.data.split(":")[1])
    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute("SELECT number, plate_type, buy_price FROM plates WHERE id = ? AND user_id = ?", (plate_id, call.from_user.id))
        row = await cursor.fetchone()
        if not row:
            await safe_callback_answer("❌ Номер не найден.", show_alert=True); return
        cursor = await db.execute("SELECT 1 FROM garage WHERE plate_id = ?", (plate_id,))
        if await cursor.fetchone():
            await safe_callback_answer("❌ Сначала сними номер с машины.", show_alert=True); return
        number, ptype, buy_price = row
        if ptype == "exclusive":
            await safe_callback_answer(call, "💎 EX-номер навсегда привязан к лимитированному автомобилю и не продаётся отдельно.", show_alert=True)
            return
        pdata = PLATE_TYPES.get(ptype, PLATE_TYPES["region"])
        sell_price = max(1, int(buy_price * pdata["multiplier"] * 0.75))
        await db.execute("UPDATE players SET balance = balance + ? WHERE user_id = ?", (sell_price, call.from_user.id))
        await db.execute("DELETE FROM plates WHERE id = ? AND user_id = ?", (plate_id, call.from_user.id))
        await db.commit()
    await safe_callback_answer(f"💰 Номер продан за {sell_price:,} ₽")
    await plates_inventory(call)



async def build_profile_text(user_id: int) -> str:
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            "SELECT username, balance, xp, level, registered_at, coins FROM players WHERE user_id = ?",
            (user_id,),
        )
        player = await cur.fetchone()
        if not player:
            return "❌ Профиль не найден."

        cur = await db.execute(
            "SELECT COUNT(*), COALESCE(SUM(COALESCE(buy_price,0)),0) FROM garage WHERE user_id = ?",
            (user_id,),
        )
        cars_count, cars_value = await cur.fetchone()

        cur = await db.execute(
            "SELECT COUNT(*), COALESCE(SUM(COALESCE(buy_price,0)),0) FROM plates WHERE user_id = ?",
            (user_id,),
        )
        plates_count, plates_value = await cur.fetchone()

        cur = await db.execute(
            "SELECT COUNT(*), COALESCE(SUM(COALESCE(price,0)),0) FROM player_properties WHERE owner_id = ?",
            (user_id,),
        )
        properties_count, properties_value = await cur.fetchone()

        cur = await db.execute(
            "SELECT COALESCE(SUM(invested),0) FROM sto_investments WHERE user_id = ?",
            (user_id,),
        )
        sto_value = int((await cur.fetchone())[0] or 0)

        cur = await db.execute(
            "SELECT COUNT(*), COALESCE(SUM(price),0) FROM player_business_properties WHERE owner_id = ?",
            (user_id,),
        )
        business_properties_count, business_properties_value = await cur.fetchone()
        business_properties_count = int(business_properties_count or 0)
        business_properties_value = int(business_properties_value or 0)

        cur = await db.execute(
            "SELECT COUNT(*) FROM dealerships WHERE owner_id = ?",
            (user_id,),
        )
        dealerships_count = int((await cur.fetchone())[0] or 0)

        balance = int(player["balance"] or 0)
        xp = int(player["xp"] or 0)
        level = max(1, xp // 1000 + 1)
        next_xp = level * 1000
        total_assets = balance + int(cars_value or 0) + int(plates_value or 0) + int(properties_value or 0) + sto_value + business_properties_value
        registered_at = format_datetime_ru(player["registered_at"])
        username = f"@{html.escape(player['username'])}" if player["username"] else "Без username"

        text = (
            "👤 <b>ПРОФИЛЬ ИГРОКА</b>\n\n"
            f"👤 Игрок: <b>{username}</b>\n"
            f"📅 Зарегистрирован: <b>{registered_at}</b>\n\n"
            f"💰 Деньги: <b>{balance:,} ₽</b>\n"
            f"🪙 Коины: <b>{int(player['coins'] or 0):,}</b>\n"
            f"⭐ Уровень: <b>{level}</b>\n"
            f"✨ Опыт: <b>{xp}/{next_xp}</b> XP\n\n"
            "🏠 <b>ИМУЩЕСТВО</b>\n"
            f"🚗 Автомобилей: <b>{int(cars_count or 0)}</b> · {int(cars_value or 0):,} ₽\n"
            f"🏷 Номеров: <b>{int(plates_count or 0)}</b> · {int(plates_value or 0):,} ₽\n"
            f"🏡 Недвижимость: <b>{int(properties_count or 0)}</b> · {int(properties_value or 0):,} ₽\n"
            f"🏢 Бизнес-объектов: <b>{business_properties_count}</b> · {business_properties_value:,} ₽\n"
            f"🔧 Вложено в СТО: <b>{sto_value:,} ₽</b>\n"
            f"🏢 Автосалонов: <b>{dealerships_count}</b>\n\n"
            f"💎 <b>Общая оценка имущества: {total_assets:,} ₽</b>"
        )
        return text


