async def build_top_text():
    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute(
            """
            SELECT username, user_id, balance, level
            FROM players
            ORDER BY balance DESC
            LIMIT 10
            """
        )
        players = await cursor.fetchall()

    text = "🏆 <b>ТОП ПЕРЕКУПОВ</b>\n\n"
    medals = ["🥇", "🥈", "🥉"]

    for i, (username, user_id, balance, level) in enumerate(players):
        medal = medals[i] if i < 3 else f"{i + 1}."
        display_name = f"@{username}" if username else "Игрок без username"
        text += f"{medal} <b>{display_name}</b> — {balance:,} ₽ (ур. {level})\n"

    if not players:
        text += "Пока игроков нет."

    return text


