@dp.callback_query(F.data.startswith("mt:"))
async def trade_result(call):
    try:
        _, city, seed, index, discount = call.data.split(":")
        seed = int(seed)
        index = int(index)
        discount = int(discount)
        ad = get_market_ad(city, seed, index)
    except (ValueError, KeyError):
        await safe_callback_answer(call, "❌ Объявление устарело.", show_alert=True)
        return

    if ad.get("limited_car_key"):
        await safe_callback_answer(call, "💎 За лимитированные экземпляры торг не предусмотрен.", show_alert=True)
        return

    car_name = ad["car"]["name"]
    original_price = int(ad["price"])
    repair = int(ad["repair"])
    history_type = ad.get("history_type", "normal")
    seller_type = seller_personality_for_ad(seed, city, index)
    seller = SELLER_PERSONALITIES.get(seller_type, SELLER_PERSONALITIES["calm"])

    base_chances = {5: 90, 10: 75, 15: 55, 20: 35, 25: 15}
    chance = max(5, min(95, base_chances.get(discount, 50) + seller["bonus"]))
    roll = random.randint(1, 100)

    if roll <= chance:
        new_price = int(original_price * (1 - discount / 100))
        saved = original_price - new_price
        kb = InlineKeyboardBuilder()
        kb.button(text=f"🛒 Купить за {new_price:,} ₽", callback_data=f"mb:{city}:{seed}:{index}")
        kb.button(text="🤝 Торговаться ещё раз", callback_data=f"mn:{city}:{seed}:{index}")
        kb.button(text="🔄 Отказаться", callback_data="market")
        kb.adjust(1)
        text = (
            "🔥 <b>ТОРГ УДАЛСЯ!</b>\n\n"
            f"🚗 {car_name}\n"
            f"👤 Продавец: <b>{seller['name']}</b>\n\n"
            f"💵 Было: <s>{original_price:,} ₽</s>\n"
            f"🏷️ Скидка: <b>−{discount}%</b>\n"
            f"💰 Новая цена: <b>{new_price:,} ₽</b>\n\n"
            f"🎉 Ты сэкономил: <b>{saved:,} ₽</b>\n\n"
            f"🎭 {seller['success']}"
        )
    else:
        kb = InlineKeyboardBuilder()
        kb.button(text="🤝 Попробовать снова", callback_data=f"mn:{city}:{seed}:{index}")
        kb.button(text=f"💵 Купить за {original_price:,} ₽", callback_data=f"mb:{city}:{seed}:{index}")
        kb.button(text="🔄 Другая машина", callback_data="market")
        kb.adjust(1)
        text = (
            "❌ <b>ПРОДАВЕЦ ОТКАЗАЛСЯ!</b>\n\n"
            f"🚗 {car_name}\n"
            f"👤 Характер: <b>{seller['name']}</b>\n\n"
            f"💵 Цена продавца: <b>{original_price:,} ₽</b>\n"
            f"🗣️ Ты просил скидку: <b>−{discount}%</b>\n\n"
            f"🎭 {seller['text']}\n\n"
            "😐 «Эту цену я не приму. Попробуй предложить что-нибудь разумнее.»"
        )

    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer()


