@dp.callback_query(F.data.startswith("market_inspect:"))
async def market_inspect(call):
    _, city, seed, index = call.data.split(":")
    index = int(index); seed = int(seed)
    ad = get_market_ad(city, seed, index)
    car = ad["car"]
    rng = random.Random(f"preview-docs:{city}:{seed}:{index}")
    docs_total = 5
    docs_have = sum(1 for _ in range(docs_total) if rng.random() > 0.25)
    trust = min(100, 35 + docs_have * 13 + (10 if ad["history_type"] in {"collector", "rare", "profit"} else 0))
    panel_states = []
    for name in ("Капот", "Левая дверь", "Правая дверь", "Крыло", "Крыша"):
        roll = rng.random()
        status = "✅ оригинал" if roll < 0.68 else ("🎨 крашеная" if roll < 0.88 else "⚠️ ремонт")
        panel_states.append((name, status))
    text = (
        "🔍 <b>ПРЕДПРОДАЖНЫЙ ОСМОТР</b>\n\n"
        f"🚗 <b>{html.escape(car['name'])}</b>\n"
        f"🛣 Пробег: <b>{int(ad.get('mileage', 0)):,} км</b>\n"
        f"💰 Цена: <b>{ad['price']:,} ₽</b>\n\n"
        "📜 <b>Документы</b>\n"
        f"Комплект: <b>{docs_have}/{docs_total}</b>\n"
        f"⭐ Доверие: <b>{trust}/100</b>\n\n"
        "🚗 <b>Кузов</b>\n"
        + "\n".join(f"{name} — {status}" for name, status in panel_states) +
        "\n\n⚠️ Осмотр рынка показывает только общую картину. После покупки полная история автомобиля сохраняется в гараже."
    )
    kb=InlineKeyboardBuilder()
    kb.button(text=f"🛒 Купить за {ad['price']:,} ₽", callback_data=f"mb:{city}:{seed}:{index}")
    kb.button(text="🔙 К объявлению", callback_data=f"market:{city}:{seed}:{index}")
    kb.adjust(1)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer(call)


async def buy_limited_from_market(call, ad, city):
    user_id = int(call.from_user.id)
    price = int(ad["price"])
    car_key = str(ad.get("limited_car_key") or "")
    if car_key not in LIMITED_CARS_BY_KEY:
        await safe_callback_answer(call, "❌ Лимитированное объявление устарело.", show_alert=True)
        return

    await create_player(user_id, call.from_user.username)
    async with aiosqlite.connect(DB) as db:
        await db.execute("BEGIN IMMEDIATE")
        cur = await db.execute("SELECT balance FROM players WHERE user_id=?", (user_id,))
        player = await cur.fetchone()
        balance = int(player[0] or 0) if player else 0
        if balance < price:
            await db.rollback()
            await safe_callback_answer(call, f"❌ Не хватает {price - balance:,} ₽.", show_alert=True)
            return
        cur = await db.execute(
            "UPDATE players SET balance=balance-? WHERE user_id=? AND balance>=?",
            (price, user_id, price),
        )
        if cur.rowcount != 1:
            await db.rollback()
            await safe_callback_answer(call, "❌ Баланс изменился. Обнови объявление.", show_alert=True)
            return
        award = await issue_limited_vehicle_in_transaction(
            db, user_id, car_key, source="npc_market", paid_price=price
        )
        if not award:
            await db.rollback()
            await refresh_limited_stock_cache()
            await safe_callback_answer(call, "❌ Этот лимитированный экземпляр уже забрали. Тираж не бесконечный.", show_alert=True)
            return
        await db.commit()

    await refresh_limited_stock_cache()
    await seasonal_add_stat(user_id, "collection", 1)
    kb = InlineKeyboardBuilder()
    kb.button(text="🏠 Мой гараж", callback_data="garage")
    kb.button(text="🔎 Ещё объявления", callback_data="market_cities")
    kb.button(text="💎 Реестр лимитированных авто", callback_data="limited_catalog")
    kb.adjust(1)
    await edit_text_safe(
        call,
        "✅ <b>ТЕБЕ ПОПАЛСЯ ЛИМИТИРОВАННЫЙ ЛОТ!</b>\n\n"
        f"🏙 Город: <b>{html.escape(MARKET_CITIES.get(city, {}).get('name', city))}</b>\n"
        f"💸 Оплачено NPC: <b>{price:,} ₽</b>\n\n"
        + limited_award_text(award, "💎 <b>ЭКСКЛЮЗИВНЫЙ АВТОМОБИЛЬ КУПЛЕН!</b>"),
        parse_mode="HTML", reply_markup=kb.as_markup(),
    )
    await safe_callback_answer(call, "💎 Тираж обновлён!")


@dp.callback_query(F.data.startswith("mb:"))
async def buy_car(call):

    try:
        _, city, seed, index = call.data.split(":")
        seed = int(seed)
        index = int(index)
        ad = get_market_ad(city, seed, index)
    except (ValueError, KeyError):
        await safe_callback_answer(call, "❌ Объявление устарело.", show_alert=True)
        return

    if ad.get("limited_car_key"):
        await buy_limited_from_market(call, ad, city)
        return

    car_name = ad["car"]["name"]
    price = int(ad["price"])
    repair = int(ad["repair"])
    history_type = ad.get("history_type", "normal")

    history_multipliers = {
        "collector": 1.25,
        "accident": 0.75,
        "rare": 1.45,
        "profit": 1.35,
        "normal": 1.0,
    }
    history_multiplier = history_multipliers.get(history_type, 1.0)

    user_id = call.from_user.id
    paparazzi = paparazzi_roll(car_name, history_type, user_id)

    async with aiosqlite.connect(DB) as db:
        debit = await db.execute(
            """
            UPDATE players
            SET balance = balance - ?
            WHERE user_id = ? AND balance >= ?
            """,
            (price, user_id, price),
        )
        if debit.rowcount != 1:
            await db.rollback()
            await safe_callback_answer(call, "❌ Недостаточно денег!", show_alert=True)
            return

        cursor = await db.execute(
            """
            INSERT INTO garage
            (user_id, car_name, buy_price, repair_cost, repaired, history_type, history_multiplier, paparazzi_multiplier, paparazzi_until, mileage)
            VALUES (?, ?, ?, ?, 0, ?, ?, ?, ?, ?)
            """,
            (
                user_id,
                car_name,
                price,
                repair,
                history_type,
                history_multiplier,
                paparazzi["multiplier"] if paparazzi else 1.0,
                paparazzi["until"] if paparazzi else None,
                int(ad.get("mileage", 0)),
            )
        )
        new_car_id = cursor.lastrowid
        await db.commit()

    await seasonal_add_stat(user_id, "collection", 1)
    await ensure_vehicle_metadata(new_car_id, user_id)

    paparazzi_text = ""
    if paparazzi:
        paparazzi_text = (
            f"\n\n📸 <b>ПАПАРАЦЦИ!</b>\n"
            f"{paparazzi['label']}\n"
            f"📈 Ожидаемый интерес рынка: <b>×{paparazzi['multiplier']:.2f}</b>\n"
            f"⏳ Бонус действует около {PAPARAZZI_CONFIG[history_type]['days']} дн.\n"
            "👥 Другие игроки уже обсуждают эту машину!"
        )

    await edit_text_safe(call,
        "✅ <b>МАШИНА КУПЛЕНА!</b>\n\n"
        f"🚗 {car_name}\n"
        f"🛣 Пробег: {int(ad.get('mileage', 0)):,} км\n"
        f"💵 Покупка: {price:,} ₽\n"
        f"🔧 Ремонт: {repair:,} ₽\n\n"
        + ("🔥 Это была машина с историей! Загляни в гараж и раскрой её тайну." if history_type != "normal" else "Теперь зайди в гараж и реши, что делать дальше.")
        + paparazzi_text,
        parse_mode="HTML",
        reply_markup=menu()
    )

    await safe_callback_answer()



