@dp.callback_query(F.data.startswith("body_check:"))
async def body_check_callback(call):
    car_id = int(call.data.split(":", 1)[1])
    await ensure_vehicle_metadata(car_id, call.from_user.id)
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT car_name FROM garage WHERE id=? AND user_id=?", (car_id, call.from_user.id))
        car = await cur.fetchone()
        if not car:
            await safe_callback_answer(call, "❌ Автомобиль не найден.", show_alert=True); return
        cur = await db.execute("SELECT * FROM vehicle_body_panels WHERE car_id=? ORDER BY id", (car_id,))
        panels = await cur.fetchall()
    text = f"🔍 <b>ОСМОТР КУЗОВА</b>\n\n🚗 <b>{html.escape(car['car_name'])}</b>\n\n"
    hidden_count = 0
    for panel in panels:
        if int(panel['hidden']) and not int(panel['revealed']):
            text += f"{panel['panel_name']} — ❓ скрытый дефект\n"
            hidden_count += 1
        else:
            status = {"original":"✅ оригинал","painted":"🎨 крашеная","repaired":"⚠️ ремонт"}.get(panel['status'], "❓ неизвестно")
            text += f"{panel['panel_name']} — {status}\n"
    text += "\n"
    if hidden_count:
        text += f"⚠️ Скрытых элементов: <b>{hidden_count}</b>\n"
        text += "💡 Полная диагностика раскроет все повреждения."
    else:
        text += "✅ Скрытых повреждений не обнаружено."
    kb=InlineKeyboardBuilder()
    if hidden_count:
        kb.button(text="🧪 Полная диагностика — 75 000 ₽", callback_data=f"body_full:{car_id}")
    kb.button(text="📚 Документы", callback_data=f"docs:{car_id}")
    kb.button(text="🔙 К автомобилю", callback_data=f"car:{car_id}")
    kb.adjust(1)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer(call)


@dp.callback_query(F.data.startswith("body_full:"))
async def body_full_diagnostics(call):
    car_id = int(call.data.split(":", 1)[1]); uid = call.from_user.id; cost = 75_000
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT car_name FROM garage WHERE id=? AND user_id=?", (car_id, uid))
        car = await cur.fetchone()
        if not car:
            await safe_callback_answer(call, "❌ Автомобиль не найден.", show_alert=True); return
        cur = await db.execute("SELECT balance FROM players WHERE user_id=?", (uid,)); player=await cur.fetchone()
        balance=int(player[0] or 0) if player else 0
        if balance < cost:
            await safe_callback_answer(call, f"❌ Нужно ещё {cost-balance:,} ₽.", show_alert=True); return
        await db.execute("UPDATE players SET balance=balance-? WHERE user_id=?", (cost,uid))
        await db.execute("UPDATE vehicle_body_panels SET revealed=1 WHERE car_id=?", (car_id,))
        await db.commit()
    await safe_callback_answer(call, "✅ Полная диагностика завершена!")
    await body_check_callback(call)


