# =========================================================
# 🛠 РЫНОК ЗАПЧАСТЕЙ + РЕСТАВРАЦИЯ / ДОНОР / ГЕОГРАФИЯ
# =========================================================

PART_MARKET_CATALOG = {
    "body": {"name": "🚗 Кузовной комплект", "price": 180_000, "description": "Оригинальные кузовные элементы для восстановления."},
    "engine": {"name": "⚙️ Двигатель", "price": 350_000, "description": "Оригинальный агрегат для восстановления силовой установки."},
    "interior": {"name": "🪑 Салон", "price": 150_000, "description": "Оригинальный комплект салона."},
    "paint": {"name": "🎨 Заводская краска", "price": 120_000, "description": "Оригинальная заводская окраска."},
}

RESTORATION_PART_ORDER = ["body", "engine", "interior", "paint"]


def restoration_part_for_stage(stage):
    if 1 <= int(stage or 0) <= len(RESTORATION_PART_ORDER):
        return RESTORATION_PART_ORDER[int(stage) - 1]
    return None


def restoration_part_name(part_key):
    data = PART_MARKET_CATALOG.get(part_key)
    return data["name"] if data else str(part_key)


async def get_part_inventory(user_id):
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT part_key, part_name, quantity FROM player_parts WHERE user_id = ? ORDER BY part_key", (user_id,))
        rows = await cur.fetchall()
    return {row["part_key"]: int(row["quantity"] or 0) for row in rows}


def parts_market_keyboard(car_id=None):
    kb = InlineKeyboardBuilder()
    for key, data in PART_MARKET_CATALOG.items():
        suffix = f":{car_id}" if car_id else ""
        kb.button(text=f"{data['name']} — {data['price']:,} ₽", callback_data=f"parts_buy:{key}{suffix}")
    if car_id:
        kb.button(text="🛠 Реставрация", callback_data=f"restoration:{car_id}")
    else:
        kb.button(text="🔧 Мои запчасти", callback_data="parts_inventory")
    kb.button(text="🔙 Рынок", callback_data="market_cities")
    kb.adjust(1)
    return kb.as_markup()


def parts_market_text(inventory, car_id=None):
    text = "🔩 <b>РЫНОК ЗАПЧАСТЕЙ</b>\n\n"
    text += "Покупай оригинальные детали и используй их для восстановления автомобилей поэтапно.\n\n"
    if car_id:
        text += f"🚗 Детали нужны для проекта <b>#{car_id}</b>.\n\n"
    for key, data in PART_MARKET_CATALOG.items():
        qty = inventory.get(key, 0)
        text += f"{data['name']}\n💵 {data['price']:,} ₽ · 📦 У тебя: <b>{qty} шт.</b>\n{data['description']}\n\n"
    return text


def restoration_keyboard(car_id, stage):
    kb = InlineKeyboardBuilder()
    if stage < 4:
        labels = {1: "🚗 Кузов", 2: "⚙️ Двигатель", 3: "🪑 Салон", 4: "🎨 Покраска"}
        next_stage = stage + 1
        kb.button(text=f"🔧 Восстановить: {labels[next_stage]}", callback_data=f"restore_step:{car_id}:{next_stage}")
        kb.button(text="🔩 Оригинальные детали", callback_data=f"original_parts:{car_id}")
        kb.button(text="💎 Найти редкую деталь", callback_data=f"rare_part:{car_id}")
        kb.button(text="🏭 Разобрать донора", callback_data=f"donor:{car_id}")
    else:
        kb.button(text="🏭 Разобрать донора", callback_data=f"donor:{car_id}")
        kb.button(text="🔩 Оригинальные детали", callback_data=f"original_parts:{car_id}")
        kb.button(text="💎 Найти редкую деталь", callback_data=f"rare_part:{car_id}")
        kb.button(text="🧾 Сертификат реставрации", callback_data=f"certificate:{car_id}")
    kb.button(text="📍 География", callback_data=f"locations:{car_id}")
    kb.button(text="🔙 К автомобилю", callback_data=f"car:{car_id}")
    kb.adjust(1)
    return kb.as_markup()


@dp.callback_query(F.data.startswith("restoration:"))
async def restoration_menu(call):
    # Поддерживаем restoration:<car_id> и защищаемся от случайных дополнительных частей.
    parts = call.data.split(":")
    if len(parts) != 2 or not parts[1].isdigit():
        await safe_callback_answer("❌ Некорректный ID автомобиля.", show_alert=True)
        return
    car_id = int(parts[1])
    row = await get_car_pts(car_id, call.from_user.id)
    if not row:
        await safe_callback_answer("❌ Автомобиль не найден.", show_alert=True)
        return
    template = get_car_template(row["car_name"], row["buy_price"], row["repair_cost"]) or {}
    year = template.get("year", "—")
    try:
        eligible = int(year) <= 2000
    except (TypeError, ValueError):
        eligible = False
    stage = int(row["restoration_stage"] or 0)
    text = (
        "🛠 <b>РЕСТАВРАЦИОННЫЙ ПРОЕКТ</b>\n\n"
        f"🚗 <b>{row['car_name']}</b>\n"
        f"📅 Год: <b>{year}</b>\n"
        f"📊 Прогресс: <b>{stage}/4</b> — {restoration_stage_name(stage)}\n"
        f"⭐ Оригинальность: <b>{int(row['originality_score'] or 0)}%</b>\n\n"
    )
    if not eligible:
        text += "❌ Для реставрации нужны классические автомобили 2000 года или старше."
    elif stage >= 4:
        text += "🏆 Проект полностью восстановлен. Оригинальные детали повышают коллекционную ценность."
    else:
        next_stage = stage + 1
        part_key = restoration_part_for_stage(next_stage)
        part = PART_MARKET_CATALOG.get(part_key, {})
        inventory = await get_part_inventory(call.from_user.id)
        qty = inventory.get(part_key, 0)
        cost = restoration_stage_cost(next_stage, row["repair_cost"])
        text += (
            f"🔩 Нужна деталь: <b>{part.get('name', 'Деталь')}</b> — <b>1 шт.</b>\n"
            f"📦 В гараже деталей: <b>{qty} шт.</b>\n"
            f"🔧 Работа мастера: <b>{cost:,} ₽</b>\n\n"
            "Купи запчасть на рынке или разбери подходящего донора."
        )
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=restoration_keyboard(car_id, stage))
    await safe_callback_answer()


@dp.callback_query(F.data.startswith("restore_step:"))
async def restore_step(call):
    _, car_id_s, stage_s = call.data.split(":")
    car_id, stage = int(car_id_s), int(stage_s)
    row = await get_car_pts(car_id, call.from_user.id)
    if not row:
        await safe_callback_answer("❌ Автомобиль не найден.", show_alert=True)
        return
    template = get_car_template(row["car_name"], row["buy_price"], row["repair_cost"]) or {}
    try:
        year = int(template.get("year"))
    except (TypeError, ValueError):
        year = 9999
    if year > 2000:
        await safe_callback_answer("❌ Это не классический автомобиль.", show_alert=True)
        return
    current = int(row["restoration_stage"] or 0)
    if stage != current + 1:
        await safe_callback_answer("❌ Сначала закончи предыдущий этап.", show_alert=True)
        return

    part_key = restoration_part_for_stage(stage)
    part = PART_MARKET_CATALOG.get(part_key)
    if not part:
        await safe_callback_answer("❌ Деталь не найдена.", show_alert=True)
        return
    cost = restoration_stage_cost(stage, row["repair_cost"])

    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT balance FROM players WHERE user_id = ?", (call.from_user.id,))
        player = await cur.fetchone()
        cur = await db.execute("SELECT quantity FROM player_parts WHERE user_id = ? AND part_key = ?", (call.from_user.id, part_key))
        inv = await cur.fetchone()
        quantity = int(inv["quantity"] or 0) if inv else 0

        if quantity < 1:
            await safe_callback_answer(f"❌ Нужна запчасть: {part['name']}. Купи её на рынке.", show_alert=True)
            return
        if not player or int(player["balance"] or 0) < cost:
            await safe_callback_answer(f"❌ Нужно {cost:,} ₽ на работу мастера.", show_alert=True)
            return

        now = datetime.now().isoformat(timespec="seconds")
        await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (cost, call.from_user.id))
        await db.execute("UPDATE player_parts SET quantity = quantity - 1, updated_at = ? WHERE user_id = ? AND part_key = ?", (now, call.from_user.id, part_key))
        await db.execute("""
            INSERT INTO restoration_parts(car_id, part_key, part_name, purchased, is_original, price)
            VALUES(?,?,?,?,?,?)
            ON CONFLICT(car_id, part_key) DO UPDATE SET purchased=1, is_original=1, price=excluded.price
        """, (car_id, part_key, part["name"], 1, 1, int(part["price"])))
        await db.execute("UPDATE garage SET restoration_stage = ?, repaired = 1, repair_count = repair_count + 1, originality_score = MIN(100, originality_score + 25) WHERE id = ?", (stage, car_id))
        await db.execute("INSERT INTO vehicle_history(car_id, owner_id, event_type, event_at, amount, details) VALUES(?,?,?,?,?,?)", (car_id, call.from_user.id, "restoration_part", now, cost + int(part["price"]), f"Установлена оригинальная деталь: {part['name']}; работа {cost:,} ₽"))
        await db.commit()

    await seasonal_add_stat(call.from_user.id, "restoration", 20 + stage * 10)
    await restoration_menu(call)
    await safe_callback_answer(f"✅ {part['name']} установлена. Этап завершён!")


@dp.callback_query(F.data.startswith("original_parts:"))
async def original_parts(call):
    car_id = int(call.data.split(":", 1)[1])
    row = await get_car_pts(car_id, call.from_user.id)
