@dp.callback_query(F.data.startswith("donor:"))
async def donor_menu(call):
    car_id = int(call.data.split(":", 1)[1])
    rows = await get_garage_rows(call.from_user.id)
    donors = [r for r in rows if int(r["id"]) != car_id]
    text = "🏭 <b>АВТОМОБИЛЬ-ДОНОР</b>\n\nВыбери машину, которую разберём на детали для проекта.\n\n"
    kb = InlineKeyboardBuilder()
    if not donors:
        text += "❌ Нужен ещё один автомобиль в гараже."
    else:
        for r in donors[:20]:
            kb.button(text=f"🚗 {r['car_name']}", callback_data=f"donor_use:{car_id}:{r['id']}")
    kb.button(text="🔙 Реставрация", callback_data=f"restoration:{car_id}")
    kb.adjust(1)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer()


@dp.callback_query(F.data.startswith("donor_use:"))
async def donor_use(call):
    _, target_s, donor_s = call.data.split(":")
    target_id, donor_id = int(target_s), int(donor_s)
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM garage WHERE id = ? AND user_id = ?", (target_id, call.from_user.id))
        target = await cur.fetchone()
        cur = await db.execute("SELECT * FROM garage WHERE id = ? AND user_id = ?", (donor_id, call.from_user.id))
        donor = await cur.fetchone()
        if not target or not donor:
            await safe_callback_answer("❌ Автомобиль не найден.", show_alert=True)
            return
        target_template = get_car_template(target["car_name"], target["buy_price"], target["repair_cost"]) or {}
        donor_template = get_car_template(donor["car_name"], donor["buy_price"], donor["repair_cost"]) or {}
        if str(target_template.get("year")) != str(donor_template.get("year")) and target["car_name"] != donor["car_name"]:
            await safe_callback_answer("⚠️ Лучше использовать донора той же модели.", show_alert=True)
            return
        stage = int(target["restoration_stage"] or 0)
        extracted = max(1, 4 - stage)
        now = datetime.now().isoformat(timespec="seconds")
        for part_key in RESTORATION_PART_ORDER[stage:]:
            pdata = PART_MARKET_CATALOG[part_key]
            await db.execute(
                "INSERT INTO player_parts(user_id, part_key, part_name, quantity, updated_at) VALUES(?,?,?,?,?) ON CONFLICT(user_id, part_key) DO UPDATE SET quantity = quantity + 1, updated_at = excluded.updated_at",
                (call.from_user.id, part_key, pdata["name"], 1, now),
            )
        await db.execute("UPDATE garage SET originality_score = MIN(100, originality_score + ?), repair_cost = MAX(0, repair_cost - ?) WHERE id = ?", (min(20, extracted * 5), extracted * 20_000, target_id))
        await db.execute("DELETE FROM garage WHERE id = ?", (donor_id,))
        await db.execute("INSERT INTO vehicle_history(car_id, owner_id, event_type, event_at, amount, details) VALUES(?,?,?,?,?,?)", (target_id, call.from_user.id, "donor", datetime.now().isoformat(timespec="seconds"), 0, f"Донор: {donor['car_name']}"))
        await db.commit()
    await restoration_menu(call)
    await safe_callback_answer("🏭 Донор разобран, детали перенесены!")


