@dp.callback_query(F.data.startswith("move_car:"))
async def move_car(call):
    _, car_id_s, country, city = call.data.split(":")
    car_id = int(car_id_s)
    row = await get_car_pts(car_id, call.from_user.id)
    if not row:
        await safe_callback_answer("❌ Автомобиль не найден.", show_alert=True)
        return
    cost = 25_000 if city == "Москва" else 35_000
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT balance FROM players WHERE user_id = ?", (call.from_user.id,))
        player = await cur.fetchone()
        if not player or int(player[0]) < cost:
            await safe_callback_answer(f"❌ Доставка стоит {cost:,} ₽.", show_alert=True)
            return
        await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (cost, call.from_user.id))
        await db.execute("UPDATE garage SET current_country = ?, current_city = ? WHERE id = ?", (country, city, car_id))
        await db.execute("INSERT INTO vehicle_locations(car_id, country, city, event_at, event_type) VALUES(?,?,?,?,?)", (car_id, country, city, datetime.now().isoformat(timespec="seconds"), "delivery"))
        await db.commit()
    await locations_history(call)
    await safe_callback_answer(f"🚚 Автомобиль доставлен в {city}!")


