@dp.callback_query(F.data.startswith("car:"))
async def car_info(call):

    car_id = int(
        call.data.split(":")[1]
    )

    user_id = call.from_user.id

    async with aiosqlite.connect(DB) as db:

        cursor = await db.execute(
            """
            SELECT g.car_name,
                   g.buy_price,
                   g.repair_cost,
                   g.repaired,
                   g.history_type,
                   p.number AS plate_number
            FROM garage g
            LEFT JOIN plates p ON p.id = g.plate_id
            WHERE g.id = ?
            AND g.user_id = ?
            """,
            (car_id, user_id)
        )

        car = await cursor.fetchone()

    if not car:

        await safe_callback_answer(
            "Машина не найдена",
            show_alert=True
        )

        return

    name, buy, repair, repaired, history_type, plate_number = car

    template = get_car_template(name, buy, repair)

    if template is None:
        await safe_callback_answer(
            "❌ Не удалось загрузить характеристики автомобиля.",
            show_alert=True
        )
        return

    year = template.get("year", "—")
    market_min = template.get("min", 0)
    market_max = template.get("max", 0)

    kb = build_car_details_keyboard(car_id, repaired=bool(repaired))

    status = (
        "✅ Готова к продаже"
        if repaired
        else "🔧 Требует ремонта"
    )

    await edit_text_safe(call,
        "🚗 <b>ПОДРОБНОСТИ АВТОМОБИЛЯ</b>\n\n"
        f"🔥 <b>{name}</b>\n"
        f"📅 Год: {year}\n"
        f"💵 Цена покупки: {buy:,} ₽\n"
        f"📊 Рынок: {market_min:,} — {market_max:,} ₽\n"
        f"🔧 Ремонт: {repair:,} ₽\n"
        f"📋 Статус: {status}\n"
        f"🏷 Номер: <b>{plate_number or 'нет'}</b>\n\n"
        "Здесь собраны дополнительные действия, которые не нужны в основном меню.",
        parse_mode="HTML",
        reply_markup=kb
    )

    await safe_callback_answer()


