@dp.callback_query(F.data.startswith("history:"))
async def car_history(call):
    car_id = int(call.data.split(":", 1)[1])
    user_id = call.from_user.id

    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("""
            SELECT g.*, p.number AS plate_number
            FROM garage g
            LEFT JOIN plates p ON p.id = g.plate_id
            WHERE g.id = ? AND g.user_id = ?
        """, (car_id, user_id))
        car = await cur.fetchone()
        if not car:
            await safe_callback_answer(call, "❌ Автомобиль не найден!", show_alert=True)
            return

        cur = await db.execute("""
            SELECT event_type, event_at, amount, details
            FROM vehicle_history
            WHERE car_id = ?
            ORDER BY event_at ASC, id ASC
            LIMIT 30
        """, (car_id,))
        events = await cur.fetchall()

        cur = await db.execute("""
            SELECT accident_type, severity, description, fine, insurance_payout,
                   insurance_status, fraud_suspected, created_at
            FROM car_accidents
            WHERE car_id = ?
            ORDER BY created_at ASC
            LIMIT 20
        """, (car_id,))
        accidents = await cur.fetchall()

        cur = await db.execute("SELECT * FROM car_designs WHERE car_id = ?", (car_id,))
        design = await cur.fetchone()

    def date_short(value):
        if not value:
            return "—"
        try:
            return datetime.fromisoformat(str(value)).strftime("%d.%m.%Y")
        except Exception:
            return str(value)[:10]

    timeline = []
    if car["original_purchased_at"] or car["purchased_at"]:
        origin = car["origin_country"] or "Россия"
        city = car["current_city"] or "Москва"
        timeline.append(
            f"{date_short(car['original_purchased_at'] or car['purchased_at'])} — куплена / зарегистрирована в истории\n"
            f"   📍 {html.escape(str(origin))} → {html.escape(str(city))}"
        )

    for event in events:
        details = html.escape(str(event["details"] or ""))
        amount = int(event["amount"] or 0)
        amount_text = f" · 💰 {amount:,} ₽" if amount else ""
        line = f"{date_short(event['event_at'])} — {html.escape(str(event['event_type']))}{amount_text}"
        if details:
            line += f"\n   {details}"
        timeline.append(line)

    for accident in accidents:
        timeline.append(
            f"{date_short(accident['created_at'])} — 🚨 ДТП: {html.escape(str(accident['accident_type']))}\n"
            f"   {html.escape(str(accident['description']))}"
        )

    text = (
        "📜 <b>БИОГРАФИЯ АВТОМОБИЛЯ</b>\n\n"
        f"🚗 <b>{html.escape(str(car['car_name']))}</b>\n"
        f"🔑 VIN: <b>{html.escape(str(car['vin'] or 'нет'))}</b>\n"
        f"👤 Владельцев: <b>{int(car['owner_count'] or 1)}</b>\n"
        f"🛣 Пробег: <b>{int(car['mileage'] or 0):,} км</b>\n"
        f"❤️ Состояние: <b>{clamp_percent(car['condition'])}%</b>\n"
        f"🔧 Ремонтов: <b>{int(car['repair_count'] or 0)}</b>\n"
        f"🎨 Перекрасок: <b>{int(car['repaint_count'] or 0)}</b>\n"
        f"💥 ДТП: <b>{len(accidents)}</b>\n"
        f"🏁 Последний город: <b>{html.escape(str(car['current_city'] or '—'))}</b>\n"
        f"🏷 Номер: <b>{html.escape(str(car['plate_number'] or 'нет'))}</b>\n"
        f"🌍 Страна: <b>{html.escape(str(car['current_country'] or 'Россия'))}</b>\n"
    )

    if design:
        text += (
            "\n🎨 <b>Текущий дизайн</b>\n"
            f"• Цвет: {html.escape(str(design['paint']))}\n"
            f"• Винил: {html.escape(str(design['vinyl']))}\n"
            f"• Диски: {html.escape(str(design['wheels']))}\n"
            f"• Салон: {html.escape(str(design['interior']))}\n"
            f"• Карбон: {html.escape(str(design['carbon']))}\n"
            f"• Обвес: {html.escape(str(design['aero']))}\n"
            f"• Фары: {html.escape(str(design['headlights']))}\n"
            f"• Выхлоп: {html.escape(str(design['exhaust']))}\n"
            f"💎 Ценность дизайна: +{int(design['design_value'] or 0):,} ₽\n"
        )

    text += "\n🕰 <b>Хронология</b>\n"
    if timeline:
        text += "\n".join(timeline[:16])
    else:
        text += "История пока пустая. Новые события будут записываться автоматически."

    kb = InlineKeyboardBuilder()
    kb.button(text="🛡 Страховка", callback_data=f"insurance:{car_id}")
    kb.button(text="🎨 Дизайн", callback_data=f"design:{car_id}")
    kb.button(text="🔙 К автомобилю", callback_data=f"car:{car_id}")
    kb.button(text="🏠 Гараж", callback_data="garage")
    kb.adjust(2, 1, 1)

    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer(call, "📜 Биография обновлена")


