def maintenance_keyboard(car):
    kb=InlineKeyboardBuilder(); kb.button(text=f"🔧 Полное ТО — {maintenance_cost(dict(car)):,} ₽",callback_data=f"maintenance_full:{car['id']}")
    for key,(_,name,_) in MAINTENANCE_COMPONENTS.items():
        if clamp_percent(dict(car).get(MAINTENANCE_COMPONENTS[key][0],100))<98:
            kb.button(text=f"{name} — {maintenance_cost(dict(car),key):,} ₽",callback_data=f"maintenance_part:{car['id']}:{key}")
    kb.button(text="🚘 Проехать",callback_data=f"drive:{car['id']}"); kb.button(text="🔙 К машине",callback_data=f"car:{car['id']}"); kb.adjust(1); return kb.as_markup()

@dp.callback_query(F.data.startswith("maintenance:"))
async def maintenance_view(call):
    car_id=int(call.data.split(":",1)[1]); uid=call.from_user.id; car=await ensure_car_lifecycle(car_id,uid)
    if not car: return await safe_callback_answer("❌ Автомобиль не найден.",show_alert=True)
    text=(f"🔧 <b>ТО И СОСТОЯНИЕ</b>\n\n🚗 <b>{html.escape(str(car['car_name']))}</b>\n" f"🛣 Пробег: <b>{int(car['mileage'] or 0):,} км</b> · {mileage_label(car['mileage'])}\n" f"❤️ Общее состояние: <b>{clamp_percent(car['condition'])}%</b> · {condition_label(car['condition'])}\n\n" f"{maintenance_text(car)}\n\n💸 На ТО потрачено: <b>{int(car['maintenance_spend'] or 0):,} ₽</b>\n" "Регулярное обслуживание поддерживает ресурс и цену автомобиля.")
    await edit_text_safe(call,text,parse_mode="HTML",reply_markup=maintenance_keyboard(car)); await safe_callback_answer(call)

async def perform_maintenance(call,car_id,component=None):
    uid=call.from_user.id; car=await ensure_car_lifecycle(car_id,uid)
    if not car: return await safe_callback_answer("❌ Автомобиль не найден.",show_alert=True)
    if not int(car["repaired"] or 0): return await safe_callback_answer("🔧 Сначала нужен основной ремонт автомобиля.",show_alert=True)
    cost=maintenance_cost(dict(car),component); before=maintenance_overall(car); now=datetime.now().isoformat(timespec="seconds")
    async with aiosqlite.connect(DB) as db:
        db.row_factory=aiosqlite.Row
        cur=await db.execute("SELECT balance FROM players WHERE user_id=?",(uid,)); br=await cur.fetchone(); balance=int(br["balance"] or 0) if br else 0
        if balance<cost: return await safe_callback_answer(f"❌ Для ТО нужно {cost:,} ₽.",show_alert=True)
        if component:
            col=MAINTENANCE_COMPONENTS[component][0]; service=MAINTENANCE_COMPONENTS[component][1]
            await db.execute(f"UPDATE garage SET {col}=100,last_maintenance_at=?,maintenance_spend=COALESCE(maintenance_spend,0)+? WHERE id=? AND user_id=?",(now,cost,car_id,uid))
            await db.execute("UPDATE garage SET condition=(engine_condition+gearbox_condition+suspension_condition+brakes_condition+tires_condition+fluids_condition)/6 WHERE id=? AND user_id=?",(car_id,uid))
        else:
            service="Полное ТО"
            await db.execute("UPDATE garage SET condition=100,engine_condition=100,gearbox_condition=100,suspension_condition=100,brakes_condition=100,tires_condition=100,fluids_condition=100,last_maintenance_at=?,maintenance_spend=COALESCE(maintenance_spend,0)+? WHERE id=? AND user_id=?",(now,cost,car_id,uid))
        await db.execute("UPDATE players SET balance=balance-? WHERE user_id=?",(cost,uid))
        cur=await db.execute("SELECT condition,mileage FROM garage WHERE id=? AND user_id=?",(car_id,uid)); ar=await cur.fetchone(); after=int(ar["condition"] or before); mileage=int(ar["mileage"] or 0)
        await db.execute("INSERT INTO maintenance_history(user_id,car_id,car_name,service_type,amount,mileage,condition_before,condition_after) VALUES(?,?,?,?,?,?,?,?)",(uid,car_id,car["car_name"],service,cost,mileage,before,after)); await db.commit()
    await safe_callback_answer(f"✅ {service}: -{cost:,} ₽"); await maintenance_view(call)

@dp.callback_query(F.data.startswith("maintenance_full:"))
async def maintenance_full(call): await perform_maintenance(call,int(call.data.split(":",1)[1]),None)

@dp.callback_query(F.data.startswith("maintenance_part:"))
async def maintenance_part(call):
    _,cid,key=call.data.split(":",2)
    if key not in MAINTENANCE_COMPONENTS: return await safe_callback_answer("❌ Неизвестный узел.",show_alert=True)
    await perform_maintenance(call,int(cid),key)

@dp.callback_query(F.data.startswith("drive:"))
async def drive_car(call):
    car_id = int(call.data.split(":", 1)[1])
    uid = call.from_user.id
    car = await ensure_car_lifecycle(car_id, uid)
    if not car:
        return await safe_callback_answer(call, "❌ Автомобиль не найден.", show_alert=True)
    if not int(car["repaired"] or 0):
        return await safe_callback_answer(call, "🔧 Сначала отремонтируй машину.", show_alert=True)

    last = car["last_drive_at"]
    if last:
        try:
            elapsed = (datetime.now() - datetime.fromisoformat(str(last))).total_seconds()
        except (ValueError, TypeError):
            elapsed = DRIVE_COOLDOWN_SECONDS
        if elapsed < DRIVE_COOLDOWN_SECONDS:
            return await safe_callback_answer(
                call,
                f"⏳ Следующая поездка через {max(1, int(DRIVE_COOLDOWN_SECONDS - elapsed))} сек.",
                show_alert=True,
            )

    km = random.randint(25, 180)
    used = await apply_car_usage(car_id, uid, km, False, "Поездка")

    # Вероятность события небольшая, чтобы поездки не превращались в спам авариями.
    event_roll = random.random()
    accident = None
    if event_roll < 0.10:
        accident = random.choice([
            ("Мелкое ДТП", "minor", "Не успел вовремя затормозить перед потоком.", 8, 5, 14, (5_000, 25_000)),
            ("Серьёзное ДТП", "major", "Жёсткое столкновение на перекрёстке.", 20, 22, 42, (40_000, 150_000)),
            ("Наезд на препятствие", "obstacle", "Зацепил препятствие на дороге.", 3, 10, 20, (0, 15_000)),
            ("Повреждение на парковке", "parking", "Кто-то задел автомобиль и уехал.", 2, 3, 17, (0, 10_000)),
            ("Угон / попытка угона", "theft", "Автомобиль пытались угнать во время стоянки.", 0, 0, 8, (0, 0)),
        ])

    if not accident:
        text = (
            f"🚘 <b>ПОЕЗДКА ЗАВЕРШЕНА</b>\n\n"
            f"🚗 {html.escape(str(car['car_name']))}\n"
            f"🛣 Пройдено: <b>+{km} км</b>\n"
            f"❤️ Состояние: <b>{used['condition_before']}% → {used['condition_after']}%</b>\n"
            f"📏 Теперь пробег: <b>{int(car['mileage'] or 0) + km:,} км</b>\n\n"
            "✅ На дороге всё прошло спокойно."
        )
    else:
        acc_type, severity, description, engine_dmg, suspension_dmg, body_dmg, fine_range = accident
        fine = random.randint(*fine_range) if fine_range[1] else 0
        at_fault = random.random() < 0.75 if severity != "parking" else False
        if severity == "theft":
            at_fault = False
            engine_dmg = suspension_dmg = body_dmg = 0

        async with aiosqlite.connect(DB) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute("SELECT * FROM garage WHERE id=? AND user_id=?", (car_id, uid))
            current = await cur.fetchone()
            if not current:
                return await safe_callback_answer(call, "❌ Автомобиль исчез из гаража.", show_alert=True)

            # Состояние автомобиля после ДТП.
            old_engine = int(current["engine_condition"] or 100)
            old_susp = int(current["suspension_condition"] or 100)
            old_body = int(current["condition"] or 100)
            new_engine = max(0, old_engine - engine_dmg)
            new_susp = max(0, old_susp - suspension_dmg)
            new_body = max(0, old_body - body_dmg)
            new_condition = max(0, int((new_body + new_engine + new_susp + int(current["gearbox_condition"] or 100) + int(current["brakes_condition"] or 100) + int(current["tires_condition"] or 100) + int(current["fluids_condition"] or 100)) / 7))

            if severity == "major" and random.random() < 0.12:
                repair_flag = 0
            else:
                repair_flag = int(current["repaired"] or 0)

            insurance = await db.execute("SELECT * FROM car_insurance WHERE car_id=? AND user_id=? AND active=1", (car_id, uid))
            policy = await insurance.fetchone()
            payout = 0
            insurance_status = "none"
            fraud_suspected = 0

            if policy:
                expires = str(policy["expires_at"] or "")
                if expires and expires < datetime.now().isoformat():
                    await db.execute("UPDATE car_insurance SET active=0 WHERE car_id=?", (car_id,))
                    policy = None

            if policy:
                claim_count = int(policy["claim_count"] or 0)
                fraud_score = int(policy["fraud_score"] or 0)
                if claim_count >= 3 or fraud_score >= 2:
                    fraud_suspected = 1
                    fraud_score += 1
                    payout_factor = 0.40
                    insurance_status = "fraud_review"
                else:
                    payout_factor = 0.85 if severity == "major" else 0.65
                    insurance_status = "paid"
                estimated_damage = max(15_000, int((body_dmg * 25_000 + engine_dmg * 45_000 + suspension_dmg * 30_000)))
                payout = min(int(policy["coverage"] or 0), int(estimated_damage * payout_factor))
                await db.execute("""
                    UPDATE car_insurance
                    SET claim_count=claim_count+1,
                        fraud_score=?
                    WHERE car_id=? AND user_id=?
                """, (fraud_score, car_id, uid))

            await db.execute("""
                UPDATE garage
                SET accident_count=COALESCE(accident_count,0)+1,
                    repair_count=repair_count,
                    condition=?,
                    engine_condition=?,
                    suspension_condition=?,
                    repaired=?,
                    repair_cost=CASE WHEN ?=0 THEN MAX(repair_cost, 25000) ELSE repair_cost END,
                    last_drive_at=?
                WHERE id=? AND user_id=?
            """, (
                new_condition, new_engine, new_susp, repair_flag, repair_flag,
                datetime.now().isoformat(timespec="seconds"), car_id, uid,
            ))

            if fine > 0 and at_fault:
                cur = await db.execute("UPDATE players SET balance=balance-? WHERE user_id=? AND balance>=?", (fine, uid, fine))
                if cur.rowcount != 1:
                    fine = 0

            if payout > 0:
                await db.execute("UPDATE players SET balance=balance+? WHERE user_id=?", (payout, uid))

            accident_details = (
                f"{description} Ущерб: двигатель -{engine_dmg}%, подвеска -{suspension_dmg}%, кузов -{body_dmg}%."
            )
            await db.execute("""
                INSERT INTO car_accidents(
                    user_id, car_id, accident_type, severity, description,
                    engine_damage, suspension_damage, body_damage, fine, at_fault,
                    insurance_payout, insurance_status, fraud_suspected, created_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            """, (
                uid, car_id, acc_type, severity, accident_details,
                engine_dmg, suspension_dmg, body_dmg, fine, int(at_fault),
                payout, insurance_status, fraud_suspected,
                datetime.now().isoformat(timespec="seconds"),
            ))
            await db.execute("""
                INSERT INTO vehicle_history(car_id, owner_id, event_type, event_at, amount, details)
                VALUES(?,?,?,?,?,?)
            """, (
                car_id, uid, "ДТП", datetime.now().isoformat(timespec="seconds"), payout,
                accident_details,
            ))
            await db.commit()

        result_lines = [
            f"🚨 <b>{html.escape(acc_type.upper())}</b>",
            "",
            f"🚗 {html.escape(str(car['car_name']))}",
            f"📝 {html.escape(description)}",
            "",
            f"🔧 Двигатель: -{engine_dmg}%",
            f"🛞 Подвеска: -{suspension_dmg}%",
            f"🚪 Кузов: -{body_dmg}%",
        ]
        if fine and at_fault:
            result_lines.append(f"💸 Штраф: <b>{fine:,} ₽</b>")
        else:
            result_lines.append("⚖️ Ты не признан виновником.")
        if payout:
            result_lines.append(f"🛡 Страховая выплата: <b>+{payout:,} ₽</b>")
        elif policy:
            result_lines.append("🛡 Страховая не выплатила компенсацию по этому случаю.")
        if fraud_suspected:
            result_lines.append("⚠️ Страховая поставила отметку о подозрении на мошенничество.")
        if severity == "theft":
            result_lines.append("🔐 Автомобиль удалось вернуть, но инцидент занесён в историю.")

        text = "\n".join(result_lines)

    kb = InlineKeyboardBuilder()
    kb.button(text="📜 Биография", callback_data=f"history:{car_id}")
    kb.button(text="🛡 Страховка", callback_data=f"insurance:{car_id}")
    kb.button(text="🔧 ТО и состояние", callback_data=f"maintenance:{car_id}")
    kb.button(text="🔙 К машине", callback_data=f"car:{car_id}")
    kb.adjust(2, 1, 1)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer(call, "🚘 Поездка обработана")


