# РЕМОНТ
# =========================================================

@dp.callback_query(F.data.startswith("repair:"))
async def repair_car(call):

    car_id = int(
        call.data.split(":")[1]
    )

    user_id = call.from_user.id

    async with aiosqlite.connect(DB) as db:

        cursor = await db.execute(
            """
            SELECT repair_cost, repaired
            FROM garage g
            WHERE g.id = ?
            AND g.user_id = ?
            """,
            (car_id, user_id)
        )

        car = await cursor.fetchone()

        if not car:
            await safe_callback_answer("Авто не найдено")
            return

        repair, repaired = car

        mechanic_level = await get_worker_level(user_id, "mechanic")
        original_repair = int(repair or 0)
        if mechanic_level:
            repair = max(5_000, int(original_repair * (1 - 0.04 * mechanic_level)))

        if repaired:
            await safe_callback_answer(
                "Машина уже отремонтирована!"
            )
            return

        cursor = await db.execute(
            """
            SELECT balance
            FROM players
            WHERE user_id = ?
            """,
            (user_id,)
        )

        balance = (await cursor.fetchone())[0]

        if balance < repair:

            await safe_callback_answer(
                "❌ Не хватает денег на ремонт!",
                show_alert=True
            )

            return

        await db.execute(
            """
            UPDATE players
            SET balance = balance - ?
            WHERE user_id = ?
            """,
            (repair, user_id)
        )

        await db.execute(
            """
            UPDATE garage
            SET repaired = 1, repair_count = repair_count + 1,
                condition = MAX(condition,82), engine_condition = MAX(engine_condition,88), gearbox_condition = MAX(gearbox_condition,86),
                suspension_condition = MAX(suspension_condition,82), brakes_condition = MAX(brakes_condition,84),
                tires_condition = MAX(tires_condition,76), fluids_condition = MAX(fluids_condition,80), maintenance_initialized = 1
            WHERE id = ?
            """,
            (car_id,)
        )

        await db.commit()

    sto_income = await distribute_sto_income(repair, user_id)

    success_text = "🔧 Машина отремонтирована!"
    if mechanic_level:
        saved = max(0, original_repair - repair)
        success_text += f"\n👨‍🔧 Механик: уровень {mechanic_level}/5, экономия {saved:,} ₽"
    if sto_income:
        success_text += f"\n💼 Инвесторы СТО получили: {sto_income:,} ₽"

    await safe_callback_answer(success_text)

    await show_garage_for_call(call, 0)


