@dp.callback_query(F.data.startswith("sell:"))
async def sell_car(call):

    car_id = int(
        call.data.split(":")[1]
    )

    user_id = call.from_user.id

    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute(
            "SELECT 1 FROM player_market_listings WHERE car_id = ? AND seller_id = ? AND status = 'active'",
            (car_id, user_id)
        )
        if await cursor.fetchone():
            await safe_callback_answer("❌ Сначала сними машину с рынка игроков.", show_alert=True)
            return

        cursor = await db.execute(
            """
            SELECT car_name,
                   buy_price,
                   repair_cost,
                   repaired,
                   history_multiplier,
                   paparazzi_multiplier,
                   paparazzi_until,
                   plate_id,
                   inspection_status,
                   inspection_valid_until, mileage, condition, engine_condition, gearbox_condition, suspension_condition,
                   brakes_condition, tires_condition, fluids_condition
            FROM garage g
            WHERE g.id = ?
            AND g.user_id = ?
            """,
            (car_id, user_id)
        )

        car = await cursor.fetchone()

    if not car:

        await safe_callback_answer(
            "❌ Автомобиль не найден!",
            show_alert=True
        )

        return

    name, buy, repair, repaired, history_multiplier, paparazzi_multiplier, paparazzi_until, plate_id, inspection_status, inspection_valid_until, mileage, condition, engine_condition, gearbox_condition, suspension_condition, brakes_condition, tires_condition, fluids_condition = car

    # Находим характеристики автомобиля.
    # Для автомобилей из старой БД используем резервные характеристики.
    template = get_car_template(name, buy, repair)

    if template is None:
        await safe_callback_answer(
            "❌ Не удалось загрузить автомобиль.",
            show_alert=True
        )
        return

    # Базовая рыночная цена
    market_price = random.randint(
        template["min"],
        template["max"]
    )

    # Скрытая история влияет на будущую цену продажи.
    market_price = int(market_price * history_multiplier)

    # Папарацци временно повышают спрос на редкую машину.
    if paparazzi_is_active(paparazzi_until):
        market_price = int(market_price * paparazzi_multiplier)

    lifecycle_factor = lifecycle_sale_multiplier(mileage, condition, repaired)
    market_price = int(market_price * lifecycle_factor)

    inspection_valid = bool(inspection_status == "passed" and inspection_valid_until and inspection_valid_until > datetime.now().isoformat())
    if not inspection_valid:
        market_price = int(market_price * 0.92)

    plate_bonus = 1.0
    if plate_id:
        async with aiosqlite.connect(DB) as db:
            cursor = await db.execute("SELECT plate_type FROM plates WHERE id = ?", (plate_id,))
            plate_row = await cursor.fetchone()
        if plate_row:
            plate_bonus = PLATE_TYPES.get(plate_row[0], PLATE_TYPES["region"])["multiplier"]
            market_price = int(market_price * plate_bonus)

    # Генерируем 3 случайных покупателей
    buyers = random.sample(
        BUYERS,
        min(3, len(BUYERS))
    )

    kb = InlineKeyboardBuilder()

    text = (
        "👥 <b>ПОКУПАТЕЛИ</b>\n\n"
        f"🚗 <b>{name}</b>\n"
        f"💵 Цена покупки: {buy:,} ₽\n"
        f"🔧 Ремонт: {repair:,} ₽\n"
        f"🛣 Пробег: {int(mileage or 0):,} км · {mileage_label(mileage)}\n"
        f"❤️ Состояние: {clamp_percent(condition)}% · {condition_label(condition)}\n"
    )

    if repaired:
        text += "✅ Состояние: отремонтирована\n"
    else:
        text += "🔧 Состояние: требует ремонта\n"
    if inspection_valid:
        text += "🔧 Техосмотр: ✅ действующий\n"
    else:
        text += "🔧 Техосмотр: ⚠️ отсутствует/истёк (−8% к предложению)\n"

    if paparazzi_is_active(paparazzi_until):
        text += (
            f"📸 <b>ПАПАРАЦЦИ АКТИВНЫ!</b> Рынок: <b>×{paparazzi_multiplier:.2f}</b>\n\n"
        )
    else:
        text += "\n"

    text += "💬 <b>Тебе поступили предложения:</b>\n\n"

    for index, buyer in enumerate(buyers):

        price = int(
            market_price *
            random.uniform(
                buyer["min"],
                buyer["max"]
            )
        )

        profit = (
            price
            - buy
            - (repair if repaired else 0)
        )

        if profit >= 0:
            profit_text = f"📈 +{profit:,} ₽"
        else:
            profit_text = f"📉 {profit:,} ₽"

        text += (
            f"{buyer['emoji']} <b>{buyer['name']}</b>\n"
            f"{buyer['role']}\n"
            f"💰 Предлагает: <b>{price:,} ₽</b>\n"
            f"{profit_text}\n\n"
        )

        kb.button(
            text=(
                f"{buyer['emoji']} "
                f"{buyer['name']} — {price:,} ₽"
            ),
            callback_data=(
                f"buyer:{car_id}:{price}:"
                f"{buyer['name']}"
            )
        )

    kb.button(
        text="🔄 Другие покупатели",
        callback_data=f"sell:{car_id}"
    )

    kb.button(
        text="🔙 Назад",
        callback_data=f"car:{car_id}"
    )

    kb.adjust(1)

    await edit_text_safe(call,
        text,
        parse_mode="HTML",
        reply_markup=kb.as_markup()
    )

    await safe_callback_answer()


