@dp.callback_query(F.data.startswith("buyer:"))
async def sell_to_buyer(call):

    data = call.data.split(":")

    car_id = int(data[1])
    sell_price = int(data[2])
    buyer_name = data[3]

    user_id = call.from_user.id

    async with aiosqlite.connect(DB) as db:

        # Проверяем автомобиль
        cursor = await db.execute(
            """
            SELECT car_name,
                   buy_price,
                   repair_cost,
                   repaired,
                   history_multiplier,
                   paparazzi_multiplier,
                   paparazzi_until,
                   plate_id,
                   inspection_status,
                   inspection_valid_until
            FROM garage g
            WHERE g.id = ?
            AND g.user_id = ?
            """,
            (car_id, user_id)
        )

        car = await cursor.fetchone()

        if not car:

            await safe_callback_answer(
                "❌ Автомобиль уже продан или не найден!",
                show_alert=True
            )

            return

        name, buy, repair, repaired, history_multiplier, paparazzi_multiplier, paparazzi_until, plate_id, inspection_status, inspection_valid_until = car

        # Считаем прибыль
        profit = (
            sell_price
            - buy
            - (repair if repaired else 0)
        )

        # XP за сделку
        xp_reward = 5

        # Начисляем деньги и XP
        await db.execute(
            """
            UPDATE players
            SET balance = balance + ?,
                xp = xp + ?
            WHERE user_id = ?
            """,
            (
                sell_price,
                xp_reward,
                user_id
            )
        )

        # Удаляем автомобиль из гаража
        if plate_id:
            await db.execute("DELETE FROM plates WHERE id = ? AND user_id = ?", (plate_id, user_id))

        await db.execute(
            """
            DELETE FROM garage
            WHERE id = ?
            AND user_id = ?
            """,
            (
                car_id,
                user_id
            )
        )

        await db.commit()

        # Проверяем уровень
        cursor = await db.execute(
            """
            SELECT xp, level
            FROM players
            WHERE user_id = ?
            """,
            (user_id,)
        )

        xp, level = await cursor.fetchone()

        new_level = max(
            1,
            xp // 1000 + 1
        )

        level_up = False

        if new_level > level:

            await db.execute(
                """
                UPDATE players
                SET level = ?
                WHERE user_id = ?
                """,
                (
                    new_level,
                    user_id
                )
            )

            await db.commit()

            level_up = True

    # Фиксируем чистый результат сделки в текущем месячном сезоне.
    await seasonal_add_stat(user_id, "profit", profit)

    # =====================================================
    # РЕЗУЛЬТАТ
    # =====================================================

    if profit >= 0:

        result = "📈 <b>ВЫГОДНАЯ СДЕЛКА!</b>"

    else:

        result = "📉 <b>УБЫТОК!</b>"

    text = (
        "🚗 <b>МАШИНА ПРОДАНА!</b>\n\n"
        f"🚘 {name}\n\n"
        f"👤 Покупатель: <b>{buyer_name}</b>\n"
        f"💰 Цена продажи: <b>{sell_price:,} ₽</b>\n\n"
        f"{result}\n"
        f"💵 Результат сделки: "
        f"<b>{profit:+,} ₽</b>\n\n"
        f"⭐ Получено XP: <b>+{xp_reward}</b>"
    )

    if level_up:

        text += (
            f"\n\n🎉 <b>НОВЫЙ УРОВЕНЬ!</b>\n"
            f"⭐ Теперь твой уровень: "
            f"<b>{new_level}</b>"
        )

    await edit_text_safe(call,
        text,
        parse_mode="HTML",
        reply_markup=menu()
    )

    await safe_callback_answer(
        "💰 Сделка завершена!"
    )



