DEALERSHIP_LEVELS = {
    1: {"cost": 0, "capacity": 5, "visitors": 10},
    2: {"cost": 1_000_000, "capacity": 8, "visitors": 20},
    3: {"cost": 3_000_000, "capacity": 12, "visitors": 35},
    4: {"cost": 8_000_000, "capacity": 20, "visitors": 60},
    5: {"cost": 20_000_000, "capacity": 30, "visitors": 100},
}

DEALERSHIP_COMMISSION = 5

DEALERSHIP_TRANSPORTER_LEVELS = {
    1: {"cost": 0, "capacity": 1, "transport": 45_000},
    2: {"cost": 1_500_000, "capacity": 3, "transport": 38_000},
    3: {"cost": 4_000_000, "capacity": 5, "transport": 30_000},
    4: {"cost": 10_000_000, "capacity": 10, "transport": 22_000},
    5: {"cost": 25_000_000, "capacity": 20, "transport": 15_000},
}


def transporter_capacity(level):
    return DEALERSHIP_TRANSPORTER_LEVELS.get(level, DEALERSHIP_TRANSPORTER_LEVELS[5])["capacity"]


def transporter_cost(current_level):
    nxt = current_level + 1
    return DEALERSHIP_TRANSPORTER_LEVELS.get(nxt, {}).get("cost")


def transporter_price(level):
    return DEALERSHIP_TRANSPORTER_LEVELS.get(level, DEALERSHIP_TRANSPORTER_LEVELS[1])["transport"]


async def ensure_transporter(user_id):
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT level FROM dealership_transporters WHERE owner_id = ?", (user_id,))
        row = await cur.fetchone()
        if row:
            return int(row[0])
        await db.execute("INSERT INTO dealership_transporters(owner_id, level) VALUES (?, 1)", (user_id,))
        await db.commit()
        return 1


async def get_transporter(user_id):
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT level, jobs_count, spent FROM dealership_transporters WHERE owner_id = ?", (user_id,))
        return await cur.fetchone() or (1, 0, 0)


async def dealership_period_stats(dealership_id, days):
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute(
            """SELECT COUNT(*), COALESCE(SUM(sale_price), 0), COALESCE(SUM(commission), 0)
               FROM dealership_sales
               WHERE dealership_id = ?
                 AND datetime(created_at) >= datetime('now', ?)""",
            (dealership_id, f"-{int(days)} days")
        )
        count, turnover, commission = await cur.fetchone()
        return int(count or 0), int(turnover or 0), int(commission or 0)


