async def build_dealership_stats_text(user_id):
    dealer = await get_dealership(user_id)
    if not dealer:
        return "❌ У тебя нет автосалона."
    dealership_id = dealer[0]
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT COUNT(*) FROM dealership_cars WHERE dealership_id = ?", (dealership_id,))
        remaining = int((await cur.fetchone())[0])
    lines = [
        f"📊 <b>СТАТИСТИКА — {dealer[2]}</b>\n",
        f"🚗 Осталось машин: <b>{remaining}/{dealership_capacity(dealer[3])}</b>",
        f"📈 Всего продано: <b>{dealer[5]}</b>",
        f"💰 Общий оборот: <b>{dealer[6]:,} ₽</b>",
        f"💵 Доход салона: <b>{dealer[8]:,} ₽</b>\n",
    ]
    for days, title in ((1, "Сегодня"), (7, "За неделю"), (30, "За месяц"), (365, "За год")):
        c, t, comm = await dealership_period_stats(dealership_id, days)
        lines.append(f"<b>{title}</b>: {c} машин • {t:,} ₽ оборота • {comm:,} ₽ дохода")
    return "\n".join(lines)


