@dp.callback_query(F.data.startswith("dealer_truck_upgrade:"))
async def dealer_truck_upgrade(call):
    _, target_text, cost_text = call.data.split(":")
    target, cost = int(target_text), int(cost_text)
    user_id = call.from_user.id
    current, _, _ = await get_transporter(user_id)
    if target != current + 1 or target not in DEALERSHIP_TRANSPORTER_LEVELS:
        await safe_callback_answer("❌ Некорректное улучшение.", show_alert=True)
        return
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT balance FROM players WHERE user_id = ?", (user_id,))
        row = await cur.fetchone()
        if not row or row[0] < cost:
            await safe_callback_answer("❌ Недостаточно денег.", show_alert=True)
            return
        await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (cost, user_id))
        await db.execute("UPDATE dealership_transporters SET level = ? WHERE owner_id = ?", (target, user_id))
        await db.commit()
    await show_dealer_truck(call)
    await safe_callback_answer("🚚 Автовоз улучшен!")


