async def show_dealer_transport_market(call, city, seed, index):
    dealer = await get_dealership(call.from_user.id)
    if not dealer:
        await safe_callback_answer("Сначала открой автосалон.", show_alert=True)
        return
    await ensure_transporter(call.from_user.id)
    level, _, _ = await get_transporter(call.from_user.id)
    index %= 12
    ad = get_market_ad(city, seed, index, include_limited=False)
    car = ad["car"]
    transport = transporter_price(level)
    transporter_worker_level = await get_worker_level(call.from_user.id, "transporter")
    if transporter_worker_level:
        transport = max(5_000, int(transport * (1 - 0.05 * transporter_worker_level)))
    total = int(ad["price"] + transport)
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT COUNT(*) FROM dealership_cars WHERE dealership_id = ?", (dealer[0],))
        stock = int((await cur.fetchone())[0])
    free = dealership_capacity(dealer[3]) - stock
    if free <= 0:
        await safe_callback_answer("❌ В салоне нет свободных мест.", show_alert=True)
        return
    text = (
        f"🚚 <b>ПОСТАВКА В АВТОСАЛОН</b>\n\n"
        f"🏙 Город: <b>{MARKET_CITIES[city]['name']}</b>\n"
        f"🚗 <b>{car['name']}</b>\n"
        f"💵 Цена рынка: <b>{ad['price']:,} ₽</b>\n"
        f"🚚 Автовоз: <b>{transport:,} ₽</b>\n"
        f"💰 Итого: <b>{total:,} ₽</b>\n"
        f"📦 Свободно в салоне: <b>{free}</b>\n\n"
        "После доставки автомобиль сразу появляется в продаже у твоего салона."
    )
