@dp.callback_query(F.data.startswith("dealer_transport_buy:"))
async def dealer_transport_buy(call):
    _, city, seed, index = call.data.split(":")
    user_id = call.from_user.id
    seed, index = int(seed), int(index)
    dealer = await get_dealership(user_id)
    if not dealer:
        await safe_callback_answer("Сначала открой автосалон.", show_alert=True)
        return
    await ensure_transporter(user_id)
    level, _, _ = await get_transporter(user_id)
    ad = get_market_ad(city, seed, index, include_limited=False)
    car = ad["car"]
    transport = transporter_price(level)
    transporter_worker_level = await get_worker_level(call.from_user.id, "transporter")
    if transporter_worker_level:
        transport = max(5_000, int(transport * (1 - 0.05 * transporter_worker_level)))
    total = int(ad["price"] + transport)
    async with aiosqlite.connect(DB) as db:
        await db.execute("BEGIN IMMEDIATE")
        cur = await db.execute("SELECT COUNT(*) FROM dealership_cars WHERE dealership_id = ?", (dealer[0],))
        stock = int((await cur.fetchone())[0])
        if stock >= dealership_capacity(dealer[3]):
            await db.rollback()
            await safe_callback_answer("❌ В салоне нет места.", show_alert=True)
            return
        cur = await db.execute("SELECT balance FROM players WHERE user_id = ?", (user_id,))
        bal = await cur.fetchone()
        if not bal or bal[0] < total:
            await db.rollback()
            await safe_callback_answer(f"❌ Нужно {total:,} ₽.", show_alert=True)
            return
        template = get_car_template(car["name"], ad["price"], car["repair"])
        market_min = template.get("min", ad["price"]) if template else ad["price"]
        market_max = template.get("max", ad["price"]) if template else ad["price"]
        sale_price = max(total + 1, int(((market_min + market_max) // 2) * float(ad.get("history_multiplier") or 1.0) * 1.08))
        manager_level = await get_worker_level(user_id, "manager")
        if manager_level:
            sale_price = int(sale_price * (1 + 0.03 * manager_level))
        await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (total, user_id))
        await db.execute(
            """INSERT INTO dealership_cars(dealership_id, owner_id, car_name, buy_price, sale_price, repair_cost, repaired, history_type, history_multiplier)\n               VALUES(?,?,?,?,?,?,?,?,?)""",
            (dealer[0], user_id, car["name"], total, sale_price, car["repair"], 1, ad["history_type"], ad["history_multiplier"])
        )
        await db.execute(
            """INSERT INTO dealership_transporters(owner_id, level, jobs_count, spent) VALUES(?, ?, 1, ?)\n               ON CONFLICT(owner_id) DO UPDATE SET jobs_count = jobs_count + 1, spent = spent + excluded.spent""",
            (user_id, level, transport)
        )
        await db.commit()
    await show_dealer_transport_market(call, city, seed, index)
    await safe_callback_answer(f"🚚 {car['name']} доставлен в салон!")


async def ensure_dealer_transporter_on_open(user_id):
    if await get_dealership(user_id):
        await ensure_transporter(user_id)


async def ensure_dealership(user_id, username=None):
    await create_player(user_id, username)

    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute(
            """
            SELECT id
            FROM dealerships
            WHERE owner_id = ?
            """,
            (user_id,)
        )
        row = await cursor.fetchone()

        if row:
            return row[0]

        balance_cursor = await db.execute(
            """
            SELECT balance
            FROM players
            WHERE user_id = ?
            """,
            (user_id,)
        )
        balance_row = await balance_cursor.fetchone()
        balance = balance_row[0] if balance_row else 0

        # Первый салон открывается за 5 млн ₽.
        if balance < 5_000_000:
            return None

        await db.execute(
            """
            UPDATE players
            SET balance = balance - 5000000
            WHERE user_id = ?
            """,
            (user_id,)
        )

        cursor = await db.execute(
            """
            INSERT INTO dealerships
            (owner_id, name)
            VALUES (?, ?)
            """,
            (user_id, "Автосалон")
        )
        dealership_id = cursor.lastrowid

        await db.commit()
        return dealership_id


async def get_dealership(user_id):
    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute(
            """
            SELECT id, owner_id, name, level, reputation,
                   sales_count, turnover, staff_count, business_income
            FROM dealerships
            WHERE owner_id = ?
            """,
            (user_id,)
        )
        return await cursor.fetchone()


def dealership_capacity(level):
    return DEALERSHIP_LEVELS.get(level, DEALERSHIP_LEVELS[5])["capacity"]


def dealership_level_cost(current_level):
    next_level = current_level + 1
    if next_level not in DEALERSHIP_LEVELS:
        return None
    return DEALERSHIP_LEVELS[next_level]["cost"]


async def build_dealership_home_text(user_id):
    dealership = await get_dealership(user_id)

    if not dealership:
        return (
            "🏢 <b>АВТОСАЛОН</b>\n\n"
            "Ты ещё не открыл свой автосалон.\n\n"
            "💰 Стоимость открытия: <b>5 000 000 ₽</b>\n"
            "🏪 После открытия другие игроки смогут покупать "
            "твои автомобили прямо в салоне."
        )

    (
        dealership_id,
        owner_id,
        name,
        level,
        reputation,
        sales_count,
        turnover,
        staff_count,
        business_income,
    ) = dealership

    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute(
            """
            SELECT COUNT(*)
            FROM dealership_cars
            WHERE dealership_id = ?
            """,
            (dealership_id,)
        )
        cars_count = (await cursor.fetchone())[0]

    capacity = dealership_capacity(level)
    next_cost = dealership_level_cost(level)

    text = (
        f"🏢 <b>{name}</b>\n\n"
        f"⭐ Уровень: <b>{level}</b>\n"
        f"🚗 Машин: <b>{cars_count}/{capacity}</b>\n"
        f"👨‍💼 Продавцов: <b>{staff_count}</b>\n"
        f"⭐ Репутация: <b>{reputation}/100</b>\n"
        f"📈 Продаж: <b>{sales_count}</b>\n"
        f"💰 Оборот: <b>{turnover:,} ₽</b>\n"
        f"💵 Доход салона: <b>{business_income:,} ₽</b>\n"
    )

    if next_cost:
        text += f"\n⬆️ Улучшение: <b>{next_cost:,} ₽</b>"
    else:
        text += "\n🏆 Максимальный уровень салона"

    return text


