@dp.callback_query(F.data == "dealer_open")
async def dealer_open(call):
    user_id = call.from_user.id

    async with aiosqlite.connect(DB) as db:
        cursor = await db.execute(
            """
            SELECT balance
            FROM players
            WHERE user_id = ?
            """,
            (user_id,)
        )
        row = await cursor.fetchone()
        balance = row[0] if row else 0

        if balance < 5_000_000:
            await safe_callback_answer(
                f"❌ Нужно 5 000 000 ₽.\n"
                f"Твой баланс: {balance:,} ₽",
                show_alert=True
            )
            return

        cursor = await db.execute(
            """
            SELECT id
            FROM dealerships
            WHERE owner_id = ?
            """,
            (user_id,)
        )
        if await cursor.fetchone():
            await safe_callback_answer("У тебя уже есть автосалон.")
            return

        await db.execute(
            """
            UPDATE players
            SET balance = balance - 5000000
            WHERE user_id = ?
            """,
            (user_id,)
        )

        await db.execute(
            """
            INSERT INTO dealerships (owner_id, name)
            VALUES (?, ?)
            """,
            (user_id, "Автосалон")
        )
        await db.execute("INSERT OR IGNORE INTO dealership_transporters(owner_id, level) VALUES (?, 1)", (user_id,))

        await db.commit()

    await show_dealership_home(call)
    await safe_callback_answer("🎉 Автосалон открыт!")


