@dp.callback_query(F.data.startswith("dealer_buy:"))
async def dealer_buy(call):
    dealer_car_id = int(call.data.split(":", 1)[1])
    buyer_id = call.from_user.id

    async with aiosqlite.connect(DB) as db:
        await db.execute("BEGIN IMMEDIATE")

        cursor = await db.execute(
            """
            SELECT
                dc.id,
                dc.dealership_id,
                dc.owner_id,
                dc.car_name,
                dc.buy_price,
                dc.sale_price,
                dc.repair_cost,
                dc.repaired,
                dc.history_type,
                dc.history_multiplier,
                d.name,
                d.reputation,
                d.sales_count,
                d.turnover
            FROM dealership_cars dc
            JOIN dealerships d
                ON d.id = dc.dealership_id
            WHERE dc.id = ?
            """,
            (dealer_car_id,)
        )

        car = await cursor.fetchone()

        if not car:
            await db.rollback()
            await safe_callback_answer(
                "❌ Эта машина уже продана.",
                show_alert=True
            )
            return

        (
            dc_id,
            dealership_id,
            seller_id,
            car_name,
            buy_price,
            sale_price,
            repair_cost,
            repaired,
            history_type,
            history_multiplier,
            dealership_name,
            reputation,
            sales_count,
            turnover,
        ) = car

        if seller_id == buyer_id:
            await db.rollback()
            await safe_callback_answer(
                "❌ Нельзя купить собственную машину.",
                show_alert=True
            )
            return

        cursor = await db.execute(
            """
            SELECT balance
            FROM players
            WHERE user_id = ?
            """,
            (buyer_id,)
        )
        buyer = await cursor.fetchone()

        if not buyer or buyer[0] < sale_price:
            await db.rollback()
            await safe_callback_answer(
                f"❌ Недостаточно денег.\n"
                f"Нужно: {sale_price:,} ₽",
                show_alert=True
            )
            return

        # 5% комиссия с продажи.
        commission = sale_price * DEALERSHIP_COMMISSION // 100
        seller_income = sale_price - commission

        # Списание денег у покупателя.
        updated = await db.execute(
            """
            UPDATE players
            SET balance = balance - ?
            WHERE user_id = ?
              AND balance >= ?
            """,
            (sale_price, buyer_id, sale_price)
        )

        if updated.rowcount != 1:
            await db.rollback()
            await safe_callback_answer(
                "❌ Не удалось провести оплату.",
                show_alert=True
            )
            return

        # Начисление продавцу.
        await db.execute(
            """
            UPDATE players
            SET balance = balance + ?
            WHERE user_id = ?
            """,
            (seller_income, seller_id)
        )

        # Автомобиль переходит покупателю в гараж.
        # Передаём полную историю проекта из карточки салона покупателю.
        dealer_meta = await db.execute(
            "SELECT COALESCE(owner_count,1), original_buy_price, original_purchased_at, vin, registered, registered_at, build_engine, build_gearbox, build_turbo, build_body FROM dealership_cars WHERE id = ?",
            (dealer_car_id,)
        )
        meta = await dealer_meta.fetchone()
        owner_count = int(meta[0] or 1) + 1 if meta else 2
        original_buy_price = meta[1] if meta and meta[1] is not None else buy_price
        original_purchased_at = meta[2] if meta else None
        vin = meta[3] if meta else None
        registered = int(meta[4] or 0) if meta else 0
        registered_at = meta[5] if meta else None
        build_engine = meta[6] if meta else None
        build_gearbox = meta[7] if meta else None
        build_turbo = int(meta[8] or 0) if meta else 0
        build_body = meta[9] if meta else None
        await db.execute(
            """
            INSERT INTO garage
            (user_id, car_name, buy_price, repair_cost, repaired, history_type, history_multiplier,
             purchased_at, original_buy_price, original_purchased_at, owner_count, vin, registered, registered_at,
             build_engine, build_gearbox, build_turbo, build_body)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                buyer_id, car_name, sale_price, repair_cost, repaired,
                history_type or "normal", history_multiplier or 1.0,
                datetime.now().isoformat(timespec="seconds"), original_buy_price, original_purchased_at, owner_count, vin, registered, registered_at,
                build_engine, build_gearbox, build_turbo, build_body,
            )
        )

        # Удаляем объявление, чтобы его нельзя было купить повторно.
        await db.execute(
            """
            DELETE FROM dealership_cars
            WHERE id = ?
            """,
            (dealer_car_id,)
        )

        # Обновляем статистику салона.
        await db.execute(
            """
            UPDATE dealerships
            SET sales_count = sales_count + 1,
                turnover = turnover + ?,
                business_income = business_income + ?,
                reputation = MIN(100, reputation + 1)
            WHERE id = ?
            """,
            (sale_price, commission, dealership_id)
        )

        await db.execute(
            """
            INSERT INTO dealership_sales
            (dealership_id, seller_id, buyer_id, dealership_car_id,
             car_name, sale_price, commission)
            VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            (
                dealership_id,
                seller_id,
                buyer_id,
                dealer_car_id,
                car_name,
                sale_price,
                commission,
            )
        )

        await db.commit()

    profit = sale_price - buy_price - (repair_cost if repaired else 0)
    seller_profit = seller_income - buy_price - (repair_cost if repaired else 0)
    await seasonal_add_stat(seller_id, "profit", seller_profit)
    await seasonal_add_stat(buyer_id, "collection", 1)

    await edit_text_safe(
        call,
        "✅ <b>АВТОМОБИЛЬ КУПЛЕН В АВТОСАЛОНЕ!</b>\n\n"
        f"🚗 <b>{car_name}</b>\n"
        f"🏢 Салон: <b>{dealership_name}</b>\n"
        f"💰 Цена: <b>{sale_price:,} ₽</b>\n"
        f"🧾 Комиссия салона: <b>{commission:,} ₽</b>\n\n"
        f"📈 Цена была выставлена владельцем.\n"
        f"🏠 Машина теперь в твоём гараже.",
        parse_mode="HTML",
        reply_markup=menu()
    )

    await safe_callback_answer("🎉 Покупка завершена!")

    # Уведомление владельцу, если возможно.
    try:
        await bot.send_message(
            seller_id,
            "🎉 <b>ПРОДАЖА В АВТОСАЛОНЕ!</b>\n\n"
            f"🚗 {car_name}\n"
            f"💰 Цена продажи: <b>{sale_price:,} ₽</b>\n"
            f"🧾 Комиссия 5%: <b>{commission:,} ₽</b>\n"
            f"💵 Тебе зачислено: <b>{seller_income:,} ₽</b>\n"
            f"📊 Результат сделки: <b>{seller_profit:+,} ₽</b>",
            parse_mode="HTML"
        )
    except Exception:
        pass


