# =========================================================
# 🎪 CAR FEST + 💎 СЕРВЕРНАЯ ЭКОНОМИКА РЕДКИХ АВТО
# =========================================================

SERVER_RARE_MODELS = [
    "Toyota Supra A80",
    "Nissan Skyline R33",
    "Nissan Silvia S15",
    "Subaru Impreza WRX",
    "Porsche 944",
    "Lancia Delta Integrale",
    "Maserati 3200 GT",
    "Alfa Romeo 156 GTA",
    "BMW E39 540i",
]

FESTIVAL_RACE_REWARDS = [1_000_000, 600_000, 300_000]


def festival_week_key():
    now = datetime.now()
    iso = now.isocalendar()
    return f"{iso.year}-W{iso.week:02d}"


def festival_number():
    iso = datetime.now().isocalendar()
    # Stable, human-readable sequential number within the calendar year.
    return int(iso.week)


def festival_ends_at():
    now = datetime.now()
    days_until_monday = 7 - now.weekday()
    end = (now + timedelta(days=days_until_monday)).replace(
        hour=0, minute=0, second=0, microsecond=0
    )
    return end.isoformat(timespec="seconds")


def festival_car_score(name, buy_price=0, repaired=0, history_type="normal"):
    template = get_car_template(name, buy_price, 0) or {}
    base = int((template.get("min", buy_price or 0) + template.get("max", buy_price or 0)) / 2)
    repaired_bonus = 140 if repaired else 0
    history_bonus = {"collector": 160, "rare": 220, "profit": 120, "accident": -80}.get(history_type, 0)
    rarity_bonus = 240 if name in SERVER_RARE_MODELS else 0
    return max(100, int(base / 10_000) + repaired_bonus + history_bonus + rarity_bonus + random.randint(0, 120))


def festival_keyboard():
    kb = InlineKeyboardBuilder()
    kb.button(text="🚘 Выставка", callback_data="fest_exhibition")
    kb.button(text="💎 Редкие машины", callback_data="rare_market")
