async def ensure_festival_week():
    week = festival_week_key()
    async with aiosqlite.connect(DB) as db:
        await db.execute(
            "INSERT OR IGNORE INTO car_festivals(week, festival_no) VALUES (?, ?)",
            (week, festival_number())
        )
        await db.commit()
    return week


async def finalize_previous_festival_race():
    current_week = festival_week_key()
    iso = datetime.now().isocalendar()
    prev_date = datetime.now() - timedelta(days=7)
    prev_iso = prev_date.isocalendar()
    previous_week = f"{prev_iso.year}-W{prev_iso.week:02d}"
    if previous_week == current_week:
        return
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute(
            "SELECT id, user_id, score FROM festival_race_entries WHERE week = ? AND reward_paid = 0 ORDER BY score DESC, id ASC LIMIT 3",
            (previous_week,)
        )
        winners = await cur.fetchall()
        for place, (entry_id, user_id, score) in enumerate(winners, 1):
            reward = FESTIVAL_RACE_REWARDS[place - 1]
            await db.execute(
                "UPDATE players SET balance = balance + ?, xp = xp + ? WHERE user_id = ?",
                (reward, 1000 - place * 100, user_id)
            )
            await db.execute("UPDATE festival_race_entries SET reward_paid = 1 WHERE id = ?", (entry_id,))
        await db.commit()


async def build_festival_text(user_id):
    week = await ensure_festival_week()
    await finalize_previous_festival_race()
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT COUNT(*) FROM festival_race_entries WHERE week = ?", (week,))
        racers = int((await cur.fetchone())[0])
        cur = await db.execute(
            "SELECT COUNT(*) FROM festival_auction_bids WHERE week = ?", (week,)
        )
        bids = int((await cur.fetchone())[0])
    return (
        f"🎪 <b>CAR FEST #{festival_number()}</b>\n\n"
        "🏁 Главное автомобильное событие недели!\n\n"
        "🚘 <b>Выставка</b> — покажи свою лучшую машину.\n"
        "👑 <b>Concours</b> — конкурс оригинальности и реставрации.\n"
        "🏎 <b>Гонки</b> — соревнуйся с игроками.\n"
        "🔨 <b>Аукцион</b> — редкий автомобиль недели.\n"
        "💎 <b>Редкие машины</b> — статистика всего сервера.\n\n"
        f"🏎 Участников гонки: <b>{racers}</b>\n"
        f"🔨 Сделано ставок: <b>{bids}</b>\n"
        f"📅 Фестиваль обновится в начале следующей недели."
    )


