async def build_festival_race(user_id):
    week = await ensure_festival_week()
    await finalize_previous_festival_race()
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            """SELECT e.user_id, e.car_id, e.car_name, e.score, p.username
               FROM festival_race_entries e
               LEFT JOIN players p ON p.user_id = e.user_id
               WHERE e.week = ?
               ORDER BY e.score DESC, e.id ASC LIMIT 20""",
            (week,)
        )
        rows = await cur.fetchall()
        cur = await db.execute(
            "SELECT 1 FROM festival_race_entries WHERE week = ? AND user_id = ?",
            (week, user_id)
        )
        mine = await cur.fetchone()
    text = f"🏎 <b>CAR FEST #{festival_number()} — ГОНКИ</b>\n\n"
    text += "Зарегистрируй одну машину. Результат рассчитывается по характеристикам проекта, редкости и состоянию.\n\n"
    if rows:
        for i, row in enumerate(rows, 1):
            medal = ["🥇", "🥈", "🥉"][i-1] if i <= 3 else f"{i}."
            uname = f"@{row['username']}" if row['username'] else "Игрок без username"
            text += f"{medal} <b>{row['car_name']}</b> — {uname} — 🏁 {row['score']}\n"
    else:
        text += "Пока никто не зарегистрировался.\n"
    text += "\n" + ("✅ Твоя машина уже участвует." if mine else "🚗 Выбери машину для участия.")
    return text, rows, bool(mine)


