@dp.callback_query(F.data.startswith("fest_race_submit:"))
async def fest_race_submit(call):
    car_id = int(call.data.split(":", 1)[1])
    week = await ensure_festival_week()
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute(
            "SELECT car_name, buy_price, repaired, history_type FROM garage WHERE id = ? AND user_id = ?",
            (car_id, call.from_user.id)
        )
        car = await cur.fetchone()
        if not car:
            await safe_callback_answer("❌ Машина не найдена.", show_alert=True)
            return
        cur = await db.execute("SELECT 1 FROM festival_race_entries WHERE week = ? AND user_id = ?", (week, call.from_user.id))
        if await cur.fetchone():
            await safe_callback_answer("❌ Ты уже участвуешь.", show_alert=True)
            return
        score = festival_car_score(*car)
        await db.execute(
            "INSERT INTO festival_race_entries(week, user_id, car_id, car_name, score) VALUES(?,?,?,?,?)",
            (week, call.from_user.id, car_id, car[0], score)
        )
        await db.commit()
    await seasonal_add_stat(call.from_user.id, "races", int(score))
    text, rows, mine = await build_festival_race(call.from_user.id)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=festival_race_keyboard(rows, call.from_user.id, mine))
    await safe_callback_answer(f"🏁 Твой результат: {score} очков!")


async def ensure_festival_auction():
    week = await ensure_festival_week()
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT week, car_name, start_price, current_bid, current_bidder, ends_at, finalized FROM festival_auctions WHERE week = ?", (week,))
        row = await cur.fetchone()
        if row:
            return row
        car_name = random.choice(SERVER_RARE_MODELS)
        template = get_car_template(car_name, 1_000_000, 0) or {}
        mid = int((template.get("min", 1_000_000) + template.get("max", 2_000_000)) / 2)
        start_price = max(750_000, int(mid * 0.70))
        ends_at = festival_ends_at()
        await db.execute(
            "INSERT INTO festival_auctions(week, car_name, start_price, ends_at) VALUES(?,?,?,?)",
            (week, car_name, start_price, ends_at)
        )
        await db.commit()
        return (week, car_name, start_price, 0, None, ends_at, 0)


async def finalize_festival_auction():
    row = await ensure_festival_auction()
    week, car_name, start_price, current_bid, bidder, ends_at, finalized = row
    try:
        expired = datetime.fromisoformat(ends_at) <= datetime.now()
    except ValueError:
        expired = False
    if not expired or finalized:
        return row
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT current_bid, current_bidder FROM festival_auctions WHERE week = ?", (week,))
        current = await cur.fetchone()
        if not current:
            return row
        bid, winner = current
        if winner and bid > 0:
            template = get_car_template(car_name, bid, 0) or {}
            repair = int(template.get("repair", 0))
            await db.execute(
                "INSERT INTO garage(user_id, car_name, buy_price, repair_cost, repaired, history_type, history_multiplier) VALUES(?,?,?,?,1, 'rare', 1.45)",
                (winner, car_name, bid, repair)
            )
        await db.execute("UPDATE festival_auctions SET finalized = 1 WHERE week = ?", (week,))
        await db.commit()
    return await ensure_festival_auction()


@dp.callback_query(F.data == "fest_auction")
async def fest_auction(call, back_to_auctions=False):
    row = await finalize_festival_auction()
    week, car_name, start_price, current_bid, bidder, ends_at, finalized = row
    kb = InlineKeyboardBuilder()
    if finalized:
        kb.button(text="🎪 CAR FEST", callback_data="car_fest") if not back_to_auctions else kb.button(text="🔨 Аукционы", callback_data="auctions")
    else:
        next_bid = max(start_price, int(current_bid or 0) + max(50_000, int((current_bid or start_price) * 0.05)))
        kb.button(text=f"🔨 Сделать ставку {next_bid:,} ₽", callback_data=f"fest_bid:{next_bid}")
        kb.button(text="🔄 Обновить", callback_data="fest_auction")
        kb.button(text="🎪 CAR FEST", callback_data="car_fest")
    kb.button(text="🔨 Аукционы", callback_data="auctions") if back_to_auctions else None
    kb.button(text="🔙 Меню", callback_data="menu")
    kb.adjust(1)
    status = "✅ Аукцион завершён" if finalized else f"⏳ До: <b>{ends_at}</b>"
    bid_text = f"{current_bid:,} ₽" if current_bid else f"старт {start_price:,} ₽"
    text = (
        f"🔨 <b>АУКЦИОН CAR FEST #{festival_number()}</b>\n\n"
        f"💎 Лот: <b>{car_name}</b>\n"
        f"💰 Текущая ставка: <b>{bid_text}</b>\n"
        f"{status}\n\n"
        "⚠️ При новой ставке предыдущая ставка полностью возвращается её владельцу.\n"
        "🏆 Победитель получит автомобиль в гараж после окончания аукциона."
    )
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer()


@dp.callback_query(F.data.startswith("fest_bid:"))
async def fest_bid(call):
    amount = int(call.data.split(":", 1)[1])
    row = await finalize_festival_auction()
    week, car_name, start_price, current_bid, current_bidder, ends_at, finalized = row
    if finalized:
        await safe_callback_answer("❌ Аукцион уже завершён.", show_alert=True)
        return
    try:
        if datetime.fromisoformat(ends_at) <= datetime.now():
            await finalize_festival_auction()
            await safe_callback_answer("❌ Время аукциона вышло.", show_alert=True)
            return
    except ValueError:
        pass
    async with aiosqlite.connect(DB) as db:
        await db.execute("BEGIN IMMEDIATE")
        cur = await db.execute("SELECT balance FROM players WHERE user_id = ?", (call.from_user.id,))
        player = await cur.fetchone()
        cur = await db.execute("SELECT current_bid, current_bidder FROM festival_auctions WHERE week = ?", (week,))
        auction = await cur.fetchone()
        if not player or not auction:
            await db.rollback()
            await safe_callback_answer("❌ Не удалось получить данные аукциона.", show_alert=True)
            return
        current, previous_bidder = auction
        current = int(current or 0)
        minimum = max(start_price, current + max(50_000, int((current or start_price) * 0.05)))
        if amount < minimum:
            await db.rollback()
            await safe_callback_answer(f"❌ Минимальная ставка: {minimum:,} ₽", show_alert=True)
            return
        if player[0] < amount:
            await db.rollback()
            await safe_callback_answer("❌ Недостаточно денег для ставки.", show_alert=True)
            return
        await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (amount, call.from_user.id))
        if previous_bidder and current > 0:
            await db.execute("UPDATE players SET balance = balance + ? WHERE user_id = ?", (current, previous_bidder))
        await db.execute("UPDATE festival_auctions SET current_bid = ?, current_bidder = ? WHERE week = ?", (amount, call.from_user.id, week))
        await db.execute("INSERT INTO festival_auction_bids(week, user_id, amount) VALUES(?,?,?)", (week, call.from_user.id, amount))
        await db.commit()
    await fest_auction(call)
    await safe_callback_answer(f"🔨 Ставка {amount:,} ₽ принята!")


async def get_server_rare_stats():
    stats = {}
    async with aiosqlite.connect(DB) as db:
        for model in SERVER_RARE_MODELS:
            owned = 0
            prices = []
            cur = await db.execute("SELECT COUNT(*), COALESCE(SUM(buy_price), 0) FROM garage WHERE car_name = ?", (model,))
            count, buy_sum = await cur.fetchone()
            owned += int(count or 0)
            if count:
                cur2 = await db.execute("SELECT buy_price FROM garage WHERE car_name = ?", (model,))
                prices.extend(int(r[0]) for r in await cur2.fetchall())
            cur = await db.execute("SELECT COUNT(*), COALESCE(SUM(buy_price), 0) FROM dealership_cars WHERE car_name = ?", (model,))
            count2, buy_sum2 = await cur.fetchone()
            owned += int(count2 or 0)
            if count2:
                cur2 = await db.execute("SELECT sale_price FROM dealership_cars WHERE car_name = ?", (model,))
                prices.extend(int(r[0]) for r in await cur2.fetchall())
            cur = await db.execute("SELECT COUNT(*), COALESCE(SUM(0), 0) FROM museum_cars WHERE car_name = ?", (model,))
            museum_count, _ = await cur.fetchone()
            owned += int(museum_count or 0)
            cur = await db.execute("""SELECT COUNT(*) FROM player_market_listings l JOIN garage g ON g.id = l.car_id WHERE g.car_name = ? AND l.status = 'active'""", (model,))
            active_player = int((await cur.fetchone())[0] or 0)
            cur = await db.execute("SELECT COUNT(*) FROM dealership_cars WHERE car_name = ?", (model,))
            active_dealer = int((await cur.fetchone())[0] or 0)
            stats[model] = {
                "total": owned,
                "active": active_player + active_dealer,
                "avg": int(sum(prices) / len(prices)) if prices else 0,
            }
    return stats


async def build_rare_market_text():
    stats = await get_server_rare_stats()
    lines = ["💎 <b>ЭКОНОМИКА РЕДКИХ АВТО</b>\n", "Статистика всего сервера по редким моделям.\n"]
    for model in SERVER_RARE_MODELS:
        d = stats[model]
        avg = f"{d['avg']:,} ₽" if d['avg'] else "нет данных"
        lines.append(
            f"💎 <b>{model}</b>\n"
            f"Всего на сервере: <b>{d['total']}</b>\n"
            f"Активно продаётся: <b>{d['active']}</b>\n"
            f"Средняя цена: <b>{avg}</b>\n"
        )
    return "\n".join(lines)


