async def constructor_text(car_id, user_id):
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM garage WHERE id = ? AND user_id = ?", (car_id, user_id))
        row = await cur.fetchone()
    if not row:
        return None
    engine = CONSTRUCTOR_ENGINES.get(row["build_engine"] or "stock", CONSTRUCTOR_ENGINES["stock"])
    gearbox = CONSTRUCTOR_GEARBOXES.get(row["build_gearbox"] or "stock", CONSTRUCTOR_GEARBOXES["stock"])
    turbo = bool(row["build_turbo"])
    power = 100 + engine["power"] + (CONSTRUCTOR_TURBO["power"] if turbo else 0)
    mult = engine["multiplier"] * gearbox["multiplier"] * (CONSTRUCTOR_TURBO["multiplier"] if turbo else 1.0)
    spent = engine["price"] + gearbox["price"] + (CONSTRUCTOR_TURBO["price"] if turbo else 0)
    return (
        f"🏗 <b>КОНСТРУКТОР — {row['car_name']}</b>\n\n"
        f"🚗 Кузов: <b>{row['build_body'] or row['car_name']}</b>\n"
        f"⚙️ Двигатель: <b>{engine['name']}</b>\n"
        f"🔩 КПП: <b>{gearbox['name']}</b>\n"
        f"💨 Турбо: <b>{'✅ установлено' if turbo else '❌ нет'}</b>\n"
        f"🧩 Обвес: <b>{'✅' if row['build_body'] else '❌'}</b> · Подвеска: <b>{'✅' if row['build_suspension'] else '❌'}</b>\n"
        f"🛋 Салон: <b>{'✅' if row['build_interior'] else '❌'}</b> · Покраска: <b>{'✅' if row['build_paint'] else '❌'}</b>\n\n"
        f"⚡ Расчётная мощность: <b>{power} л.с.</b>\n"
        f"📈 Коэффициент двигателя и КПП: <b>x{mult:.2f}</b>\n"
        f"💰 Вложено в силовой проект: <b>{spent:,} ₽</b>"
    )

