@dp.callback_query(F.data.startswith("constructor_extra:"))
async def constructor_extra_install(call):
    try:
        _, car_id_text, extra_key = call.data.split(":", 2)
        car_id = int(car_id_text)
    except (ValueError, TypeError):
        await safe_callback_answer(call, "Некорректное улучшение.", show_alert=True)
        return
    extra = CONSTRUCTOR_EXTRAS.get(extra_key)
    if not extra:
        await safe_callback_answer(call, "Улучшение не найдено.", show_alert=True)
        return
    uid = int(call.from_user.id)
    field = extra["field"]
    async with aiosqlite.connect(DB) as db:
        await db.execute("BEGIN IMMEDIATE")
        cur = await db.execute(f"SELECT {field} FROM garage WHERE id=? AND user_id=?", (car_id, uid))
        car = await cur.fetchone()
        if not car:
            await db.rollback()
            await safe_callback_answer(call, "Автомобиль не найден.", show_alert=True)
            return
        if car[0]:
            await db.rollback()
            await safe_callback_answer(call, "Это улучшение уже установлено.", show_alert=True)
            return
        cur = await db.execute("SELECT balance FROM players WHERE user_id=?", (uid,))
        player = await cur.fetchone()
        balance = int(player[0] or 0) if player else 0
        if balance < int(extra["price"]):
            await db.rollback()
            await safe_callback_answer(call, f"Нужно {int(extra['price']):,} ₽.", show_alert=True)
            return
        await db.execute("UPDATE players SET balance=balance-? WHERE user_id=?", (int(extra["price"]), uid))
        await db.execute(f"UPDATE garage SET {field}=? WHERE id=? AND user_id=?", (extra["value"], car_id, uid))
        await db.commit()
    await safe_callback_answer(call, f"✅ Установлено: {extra['name']}!")
    refreshed = await constructor_text(car_id, uid)
    await edit_text_safe(call, refreshed, parse_mode="HTML", reply_markup=constructor_menu_keyboard(car_id))


@dp.callback_query(F.data.startswith("register:"))
async def register_car(call):
    car_id = int(call.data.split(":", 1)[1]); user_id = call.from_user.id; cost = 25_000
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT id, car_name, registered, plate_id FROM garage WHERE id = ? AND user_id = ?", (car_id, user_id)); car = await cur.fetchone()
        if not car: await safe_callback_answer(call, "❌ Машина не найдена.", show_alert=True); return
        if car["registered"]: await safe_callback_answer("✅ Уже зарегистрирована."); return
        cur = await db.execute("SELECT balance FROM players WHERE user_id = ?", (user_id,)); bal = int((await cur.fetchone())[0])
        if bal < cost: await safe_callback_answer(f"❌ Нужно {cost:,} ₽.", show_alert=True); return
        plate_id = car["plate_id"]
        if not plate_id:
            number = await claim_unique_plate_number(db, "region", user_id)
            if not number:
                await db.rollback()
                await safe_callback_answer("❌ Не удалось найти свободный уникальный номер.", show_alert=True)
                return
            try:
                cur = await db.execute(
                    "INSERT INTO plates(user_id, number, plate_type, buy_price) VALUES(?,?,?,?)",
                    (user_id, number, "region", cost),
                )
                plate_id = cur.lastrowid
            except aiosqlite.IntegrityError:
                await db.rollback()
                await safe_callback_answer("❌ Этот номер уже занят. Попробуй зарегистрировать машину ещё раз.", show_alert=True)
                return
        await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (cost, user_id))
        await db.execute("UPDATE garage SET registered = 1, plate_id = ?, registered_at = ? WHERE id = ?", (plate_id, datetime.now().isoformat(timespec="seconds"), car_id)); await db.commit()
    await safe_callback_answer("🪪 Автомобиль зарегистрирован!")
    rows = await get_garage_rows(user_id)
    for i,row in enumerate(rows):
        if int(row["id"]) == car_id:
            obj=build_garage_car(row); await edit_text_safe(call, build_garage_caption(obj,i,len(rows)), parse_mode="HTML", reply_markup=build_garage_keyboard(obj,i,len(rows))); break

