# 👨‍🔧 СЕРВИСЫ ИГРОКОВ — СТО / МАЛЯРКА
# =========================================================

SERVICE_INFO = {
    "sto": {
        "title": "🔧 СТО",
        "service": "repair",
        "service_name": "Ремонт",
        "base_rate": 0.04,
        "min_price": 30_000,
        "max_price": 500_000,
        "specializations": ["Все марки", "BMW", "VAG", "JDM", "Премиум", "Классика"],
    },
    "paint": {
        "title": "🎨 Малярная мастерская",
        "service": "paint",
        "service_name": "Покраска",
        "base_rate": 0.025,
        "min_price": 20_000,
        "max_price": 300_000,
        "specializations": ["Все марки", "BMW", "VAG", "JDM", "Премиум", "Классика"],
    },
}


def service_price_for_car(service_key: str, buy_price: int) -> int:
    cfg = SERVICE_INFO[service_key]
    price = int(max(1, buy_price) * cfg["base_rate"])
    price = max(cfg["min_price"], min(cfg["max_price"], price))
    return int(round(price / 5000) * 5000)


def normalize_specialization(text: str) -> str:
    allowed = {"Все марки", "BMW", "VAG", "JDM", "Премиум", "Классика"}
    text = (text or "").strip()
    return text if text in allowed else "Все марки"


def service_stage_text(stage: str) -> str:
    return {
        "diagnostics": "🔎 Диагностика",
        "repair": "🔧 Ремонт",
        "painting": "🎨 Покраска",
        "ready": "✅ Готово к выдаче",
    }.get(stage or "diagnostics", "🔎 Диагностика")


def specialty_matches(car_name: str, specialization: str) -> bool:
    spec = normalize_specialization(specialization)
    name = (car_name or "").lower()
    if spec == "Все марки":
        return True
    if spec == "BMW":
        return "bmw" in name
    if spec == "VAG":
        return any(x in name for x in ("audi", "volkswagen", "skoda", "seat", "porsche"))
    if spec == "JDM":
        return any(x in name for x in ("toyota", "nissan", "honda", "mazda", "subaru", "mitsubishi", "lexus", "suzuki"))
    if spec == "Премиум":
        return any(x in name for x in ("mercedes", "bmw", "audi", "porsche", "lexus", "bentley", "ferrari", "lamborghini", "aston martin", "maserati", "rolls-royce"))
    if spec == "Классика":
        return any(x in name for x in ("lada", "volga", "жигул", "ваз", "moskvich", "москвич", "gaz", "ford mustang", "chevrolet camaro", "mercedes-benz w124"))
    return True


async def get_business_service_settings(owner_id: int, service_key: str):
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            "SELECT service_price, specialization, rating, review_count, level FROM player_business_properties WHERE owner_id=? AND business_key=?",
            (owner_id, service_key),
        )
        return await cur.fetchone()


async def effective_service_price(owner_id: int, service_key: str, buy_price: int) -> int:
    settings = await get_business_service_settings(owner_id, service_key)
    if settings and int(settings["service_price"] or 0) > 0:
        base = int(settings["service_price"])
    else:
        base = service_price_for_car(service_key, buy_price)
    return max(5_000, int(round(base / 5000) * 5000))


async def service_owners(service_key: str):
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            "SELECT p.owner_id, p.name, p.level, p.income_bonus "
            "FROM player_business_properties p "
            "WHERE p.business_key = ? ORDER BY p.level DESC, p.id ASC",
            (service_key,),
        )
        return await cur.fetchall()


async def get_service_orders(owner_id: int, statuses=("pending", "accepted")):
    marks = ",".join("?" for _ in statuses)
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            f"SELECT * FROM player_service_orders WHERE owner_id = ? AND status IN ({marks}) ORDER BY priority DESC, id ASC",
            (owner_id, *statuses),
        )
        return await cur.fetchall()


async def build_service_business_text(user_id: int, service_key: str):
    cfg = SERVICE_INFO[service_key]
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            "SELECT * FROM player_business_properties WHERE owner_id=? AND business_key=?",
            (user_id, service_key),
        )
        prop = await cur.fetchone()
    if not prop:
        return f"{cfg['title']}\n\n❌ У тебя нет этого бизнеса."
    orders = await get_service_orders(user_id)
    pending = sum(1 for r in orders if r["status"] == "pending")
    accepted = sum(1 for r in orders if r["status"] == "accepted")
    service_price = int(prop['service_price'] or 0)
    if service_price <= 0:
        service_price = cfg['min_price']
    return (
        f"{cfg['title']}\n\n"
        f"👑 Владелец: ты\n"
        f"⭐ Уровень: <b>{int(prop['level'])}/5</b>\n"
        f"📈 Бонус дохода: <b>+{int(prop['income_bonus'] or 0)}%</b>\n"
        f"⭐ Рейтинг: <b>{float(prop['rating'] or 5.0):.1f}/5</b> ({int(prop['review_count'] or 0)} отзывов)\n"
        f"💰 Цена работы: <b>{service_price:,} ₽</b>\n"
        f"🎯 Специализация: <b>{html.escape(str(prop['specialization'] or 'Все марки'))}</b>\n\n"
        f"👥 Новых заявок: <b>{pending}</b>\n"
        f"🔧 В работе: <b>{accepted}</b>\n\n"
        f"Клиенты могут отправлять тебе свои автомобили на {cfg['service_name'].lower()}."
    )


