@dp.callback_query(F.data.startswith("service_find:"))
async def service_find(call):
    service_key = call.data.split(":", 1)[1]
    cfg = SERVICE_INFO.get(service_key)
    if not cfg:
        await safe_callback_answer(call, "❌ Сервис не найден.", show_alert=True); return
    owners = await service_owners(service_key)
    text = f"{cfg['title']} игроков\n\n"
    kb = InlineKeyboardBuilder()
    if not owners:
        text += "Пока никто не открыл этот сервис."
    else:
        for row in owners[:20]:
            settings = await get_business_service_settings(int(row['owner_id']), service_key)
            rating = float(settings['rating'] or 5.0) if settings else 5.0
            reviews = int(settings['review_count'] or 0) if settings else 0
            spec = str(settings['specialization'] or 'Все марки') if settings else 'Все марки'
            price = int(settings['service_price'] or 0) if settings else 0
            price_text = f"от {price:,} ₽" if price > 0 else f"от {SERVICE_INFO[service_key]['min_price']:,} ₽"
            text += f"👤 <b>{html.escape(str(row['name']))}</b> · ⭐ {rating:.1f} ({reviews})\n🎯 {html.escape(spec)} · 💰 {price_text}\n"
            kb.button(text=f"🚗 Выбрать {row['name']}", callback_data=f"service_pick:{service_key}:{int(row['owner_id'])}")
        kb.adjust(1)
    kb.button(text="👨‍🔧 Сервисы игроков", callback_data="business_service_clients")
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer(call)


@dp.callback_query(F.data.startswith("service_pick:"))
async def service_pick(call):
    try:
        _, service_key, owner_id = call.data.split(":", 2)
        owner_id = int(owner_id)
    except ValueError:
        await safe_callback_answer(call, "❌ Некорректный сервис.", show_alert=True); return
    cfg = SERVICE_INFO.get(service_key)
    if not cfg or owner_id == call.from_user.id:
        await safe_callback_answer(call, "❌ Выбери мастерскую другого игрока.", show_alert=True); return
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT 1 FROM player_business_properties WHERE owner_id=? AND business_key=?", (owner_id, service_key))
        if not await cur.fetchone():
            await safe_callback_answer(call, "❌ Эта мастерская больше недоступна.", show_alert=True); return
        cur = await db.execute("SELECT id,car_name,buy_price FROM garage WHERE user_id=? ORDER BY id DESC", (call.from_user.id,))
        cars = await cur.fetchall()
    kb = InlineKeyboardBuilder()
    text = f"{cfg['title']}\n\nВыбери свою машину для {cfg['service_name'].lower()}:\n\n"
    if not cars:
        text += "❌ В гараже нет автомобилей."
    else:
        settings = await get_business_service_settings(owner_id, service_key)
        spec = str(settings['specialization'] or 'Все марки') if settings else 'Все марки'
        filtered = [car for car in cars if specialty_matches(str(car['car_name']), spec)]
        for car in filtered[:25]:
            price = await effective_service_price(owner_id, service_key, int(car['buy_price'] or 0))
            car_id = int(car['id'])
            kb.button(text=f"🚗 {car['car_name']} · {price:,} ₽", callback_data=f"service_request:{service_key}:{owner_id}:{car_id}:0")
            urgent_price = int(round((price * 1.25) / 5000) * 5000)
            kb.button(text=f"🔥 Срочно · {urgent_price:,} ₽", callback_data=f"service_request:{service_key}:{owner_id}:{car_id}:1")
        if not filtered:
            text += "❌ Твоя машина не подходит под специализацию этого сервиса.\n"
        kb.adjust(1)
    kb.button(text="🔙 Сервисы", callback_data="business_service_clients")
    await edit_text_safe(call, text.replace(',', ' '), parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer(call)


@dp.callback_query(F.data.startswith("service_request:"))
async def service_request(call):
    try:
        parts = call.data.split(":")
        _, service_key, owner_id, car_id = parts[:4]
        priority = int(parts[4]) if len(parts) > 4 else 0
        owner_id, car_id = int(owner_id), int(car_id)
    except ValueError:
        await safe_callback_answer(call, "❌ Некорректная заявка.", show_alert=True); return
    cfg = SERVICE_INFO.get(service_key)
    client_id = call.from_user.id
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT car_name,buy_price FROM garage WHERE id=? AND user_id=?", (car_id, client_id))
        car = await cur.fetchone()
        cur = await db.execute("SELECT name FROM player_business_properties WHERE owner_id=? AND business_key=?", (owner_id, service_key))
        owner = await cur.fetchone()
        if not car or not owner:
            await safe_callback_answer(call, "❌ Машина или мастерская не найдены.", show_alert=True); return
        price = await effective_service_price(owner_id, service_key, int(car['buy_price'] or 0))
        if priority:
            price = int(round((price * 1.25) / 5000) * 5000)
        cur = await db.execute("SELECT 1 FROM player_service_orders WHERE client_id=? AND car_id=? AND status IN ('pending','accepted')", (client_id, car_id))
        if await cur.fetchone():
            await safe_callback_answer(call, "❌ По этой машине уже есть активная заявка.", show_alert=True); return
        await db.execute(
            "INSERT INTO player_service_orders(client_id,owner_id,business_key,car_id,car_name,service_type,price,status,stage,priority) VALUES(?,?,?,?,?,?,?,'pending','diagnostics',?)",
            (client_id, owner_id, service_key, car_id, car['car_name'], cfg['service'], price, priority),
        )
        await db.commit()
    try:
        client_label = html.escape(await get_player_username_label(client_id))
        await bot.send_message(owner_id, f"📥 <b>Новая заявка в {cfg['title']}</b>\n\n🚗 {html.escape(car['car_name'])}\n💰 Работа: <b>{price:,} ₽</b>\n👤 Клиент: <b>{client_label}</b>", parse_mode="HTML")
    except Exception:
        pass
    await edit_text_safe(call, "✅ <b>Заявка отправлена владельцу!</b>\n\nОн должен принять автомобиль в работу. После завершения тебе придёт уведомление.", parse_mode="HTML", reply_markup=client_service_keyboard())
    await safe_callback_answer(call)


