@dp.callback_query(F.data.startswith("service_accept:"))
async def service_accept(call):
    try:
        order_id = int(call.data.split(":", 1)[1])
    except ValueError:
        await safe_callback_answer(call, "❌ Некорректный заказ.", show_alert=True); return
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM player_service_orders WHERE id=? AND owner_id=? AND status='pending'", (order_id, call.from_user.id))
        order = await cur.fetchone()
        if not order:
            await safe_callback_answer(call, "❌ Заказ уже обработан.", show_alert=True); return
        stage = 'painting' if order['service_type'] == 'paint' else 'repair'
        await db.execute("UPDATE player_service_orders SET status='accepted', stage=?, accepted_at=?, started_at=? WHERE id=?", (stage, datetime.now().isoformat(timespec='seconds'), datetime.now().isoformat(timespec='seconds'), order_id))
        await db.commit()
    try:
        await bot.send_message(order['client_id'], f"✅ <b>Мастерская приняла твою машину</b>\n\n🚗 {html.escape(order['car_name'])}\n💰 Цена: <b>{int(order['price']):,} ₽</b>", parse_mode='HTML')
    except Exception:
        pass
    await service_orders(call)


