@dp.callback_query(F.data.startswith("service_review:"))
async def service_review(call):
    try:
        _, order_id, rating = call.data.split(":")
        order_id, rating = int(order_id), max(1, min(5, int(rating)))
    except ValueError:
        await safe_callback_answer(call, "❌ Некорректная оценка.", show_alert=True); return
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM player_service_orders WHERE id=? AND client_id=? AND status='completed'", (order_id, call.from_user.id))
        order = await cur.fetchone()
        if not order:
            await safe_callback_answer(call, "❌ Заказ не найден.", show_alert=True); return
        cur = await db.execute("SELECT 1 FROM player_service_reviews WHERE order_id=?", (order_id,))
        if await cur.fetchone():
            await safe_callback_answer(call, "✅ Ты уже оставил отзыв.", show_alert=True); return
        await db.execute("INSERT INTO player_service_reviews(order_id,client_id,owner_id,business_key,rating) VALUES(?,?,?,?,?)", (order_id, call.from_user.id, order['owner_id'], order['business_key'], rating))
        cur = await db.execute("SELECT rating, review_count FROM player_business_properties WHERE owner_id=? AND business_key=?", (order['owner_id'], order['business_key']))
        prop = await cur.fetchone()
        old_rating = float(prop[0] or 5.0) if prop else 5.0
        old_count = int(prop[1] or 0) if prop else 0
        new_count = old_count + 1
        new_rating = ((old_rating * old_count) + rating) / new_count
        await db.execute("UPDATE player_business_properties SET rating=?, review_count=? WHERE owner_id=? AND business_key=?", (new_rating, new_count, order['owner_id'], order['business_key']))
        await db.commit()
    await edit_text_safe(call, f"✅ Спасибо! Оценка: {'⭐' * rating}\n\nРейтинг мастерской обновлён.", parse_mode='HTML', reply_markup=client_service_keyboard())
    await safe_callback_answer(call)


@dp.callback_query(F.data.startswith("service_complete:"))
async def service_complete(call):
    try:
        order_id = int(call.data.split(":", 1)[1])
    except ValueError:
        await safe_callback_answer(call, "❌ Некорректный заказ.", show_alert=True); return
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM player_service_orders WHERE id=? AND owner_id=? AND status='accepted'", (order_id, call.from_user.id))
        order = await cur.fetchone()
        if not order:
            await safe_callback_answer(call, "❌ Заказ уже завершён.", show_alert=True); return
        cur = await db.execute("SELECT balance FROM players WHERE user_id=?", (order['client_id'],))
        row = await cur.fetchone(); balance = int(row[0] or 0) if row else 0
        if balance < int(order['price']):
            await safe_callback_answer(call, "❌ У клиента недостаточно денег для оплаты.", show_alert=True); return
        await db.execute("UPDATE players SET balance=balance-? WHERE user_id=?", (order['price'], order['client_id']))
        owner_income = int(order['price'] * 0.90)
        await db.execute("UPDATE players SET balance=balance+? WHERE user_id=?", (owner_income, call.from_user.id))
        if order['service_type'] == 'repair':
            await db.execute("UPDATE garage SET repaired=1, repair_cost=0, repair_count=repair_count+1 WHERE id=? AND user_id=?", (order['car_id'], order['client_id']))
        else:
            await db.execute("UPDATE garage SET repaint_count=repaint_count+1 WHERE id=? AND user_id=?", (order['car_id'], order['client_id']))
        await db.execute("UPDATE player_service_orders SET status='completed', stage='ready', completed_at=? WHERE id=?", (datetime.now().isoformat(timespec='seconds'), order_id))
        await db.commit()
    try:
        review_kb = InlineKeyboardBuilder()
        for stars in range(1, 6):
            review_kb.button(text="⭐" * stars, callback_data=f"service_review:{order_id}:{stars}")
        review_kb.adjust(1)
        await bot.send_message(order['client_id'], f"✅ <b>Работа завершена!</b>\n\n🚗 {html.escape(order['car_name'])}\n🛠 {SERVICE_INFO[order['business_key']]['service_name']}\n💰 Списано: <b>{int(order['price']):,} ₽</b>\n🛡 Гарантия: <b>{int(order['guarantee_days'] or 0)} дней</b>\n\nОцени работу мастера:", parse_mode='HTML', reply_markup=review_kb.as_markup())
    except Exception:
        pass
    await service_orders(call)

