    await state.set_state(ServicePriceForm.waiting_price)
    await state.update_data(service_key=service_key)
    cfg = SERVICE_INFO[service_key]
    kb = InlineKeyboardBuilder(); kb.button(text="❌ Отмена", callback_data=f"service_business:{service_key}")
