@dp.message(ServicePriceForm.waiting_price)
async def service_price_enter(message: Message, state: FSMContext):
    try:
        price = int(str(message.text).replace(' ', '').replace(',', '').replace('₽',''))
    except ValueError:
        await message.answer("❌ Введи цену числом, например 120000")
        return
    data = await state.get_data(); service_key = data.get('service_key')
    cfg = SERVICE_INFO.get(service_key)
    if not cfg:
        await state.clear(); return
    price = max(cfg['min_price'], min(cfg['max_price'], price))
    async with aiosqlite.connect(DB) as db:
        await db.execute("UPDATE player_business_properties SET service_price=? WHERE owner_id=? AND business_key=?", (price, message.from_user.id, service_key))
        await db.commit()
    await state.clear()
    await message.answer(f"✅ Прайс установлен: <b>{price:,} ₽</b>", parse_mode='HTML')


