@dp.callback_query(F.data.startswith("property_buy:"))
async def property_buy(call):
    key = call.data.split(":",1)[1]
    user_id = call.from_user.id
    data = PROPERTY_TYPES.get(key)
    if not data:
        await safe_callback_answer(call, "❌ Объект не найден.", show_alert=True)
        return
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT property_key,price FROM player_properties WHERE owner_id=?", (user_id,))
        old = await cur.fetchone()
        cur = await db.execute("SELECT balance FROM players WHERE user_id=?", (user_id,))
        bal = int((await cur.fetchone())[0])
        if old and old[0] == key:
            await safe_callback_answer(call, "✅ У тебя уже есть этот объект.")
            return
        if bal < data["price"]:
            await safe_callback_answer(call, f"❌ Нужно {data['price']:,} ₽.", show_alert=True)
            return
        refund = int(old[1] * 0.60) if old else 0
        await db.execute("UPDATE players SET balance = balance - ? + ? WHERE user_id=?", (data["price"], refund, user_id))
        await db.execute(
            "INSERT INTO player_properties(owner_id,property_key,name,price,storage_bonus,level) VALUES(?,?,?,?,?,1) ON CONFLICT(owner_id) DO UPDATE SET property_key=excluded.property_key,name=excluded.name,price=excluded.price,storage_bonus=excluded.storage_bonus,level=1",
            (user_id,key,data["name"],data["price"],data["storage"]),
        )
        await db.commit()
    await show_property_home_message(call)
    await safe_callback_answer(call, f"🏡 {data['name']} приобретена!")

