# 🏚 АВТОМОБИЛЬНОЕ КЛАДБИЩЕ
# =========================================================

def graveyard_day():
    return datetime.now().strftime("%Y-%m-%d")


def graveyard_lots(day):
    pool = []
    for c in CARS:
        pool.append(c)
    for cars in IMPORT_CARS.values():
        pool.extend(cars)
    rng = random.Random(f"graveyard:{day}")
    rng.shuffle(pool)
    result = []
    for i, car in enumerate(pool[:10]):
        market = int((car.get("min", 0) + car.get("max", 0)) / 2)
        condition = rng.choice(["rust", "project", "stored", "parts"])
        multiplier = {"rust": 0.28, "project": 0.34, "stored": 0.42, "parts": 0.25}[condition]
        price = max(20_000, int(market * multiplier))
        result.append({**car, "price": price, "condition": condition, "index": i})
    return result


def graveyard_keyboard(day, index):
    kb = InlineKeyboardBuilder()
    lots = graveyard_lots(day)
    total = len(lots)
    kb.button(text="⬅️", callback_data=f"graveyard:{day}:{index-1}")
    kb.button(text=f"{index+1}/{total}", callback_data=f"graveyard:{day}:{index}")
    kb.button(text="➡️", callback_data=f"graveyard:{day}:{index+1}")
    lot = lots[index % total]
    kb.button(text=f"🛒 Забрать за {lot['price']:,} ₽", callback_data=f"grave_buy:{day}:{index}")
    kb.button(text="🗑 Свалка", callback_data="dump")
    kb.adjust(3, 1, 1)
    return kb.as_markup()


async def show_graveyard(target, day=None, index=0):
    day = day or graveyard_day()
    lots = graveyard_lots(day)
    index %= len(lots)
    lot = lots[index]
    condition_text = {
        "rust": "🟤 Кузов сильно повреждён ржавчиной.",
        "project": "🔧 Машина давно ждёт восстановления.",
        "stored": "📦 Долгое хранение, состояние неизвестно.",
        "parts": "🧩 Отличный кандидат на донора деталей.",
    }[lot["condition"]]
    text = (
        "🏚 <b>АВТОМОБИЛЬНОЕ КЛАДБИЩЕ</b>\n\n"
        f"🚗 <b>{lot['name']}</b>\n"
        f"📅 Год: <b>{lot.get('year','—')}</b>\n"
        f"{condition_text}\n\n"
        f"💰 Цена: <b>{lot['price']:,} ₽</b>\n"
        f"📈 Средняя рыночная стоимость: <b>{int((lot['min']+lot['max'])/2):,} ₽</b>\n"
        "💡 Можно использовать как проект или донора."
    )
    markup = graveyard_keyboard(day, index)
    if hasattr(target, "message"):
        await edit_text_safe(target, text, parse_mode="HTML", reply_markup=markup)
    else:
        await target.answer(text, parse_mode="HTML", reply_markup=markup)


# =========================================================
# 🏢 ЗАБРОШЕННЫЙ АВТОСАЛОН
# =========================================================

ABANDONED_DEALERSHIP_COST = 20_000_000


def abandoned_dealership_pool():
    pool = [dict(c) for c in CARS]
    for cars in IMPORT_CARS.values():
        pool.extend(dict(c) for c in cars)
    return pool


def abandoned_dealership_loot():
    rng = random.Random(f"abandoned_dealership:{datetime.now().strftime('%Y-%m-%d-%H')}")
    pool = abandoned_dealership_pool()
    rng.shuffle(pool)

    # Ровно 7 автомобилей, причём стараемся не дублировать модели.
    cars = []
    used = set()
    for car in pool:
        name = car.get("name")
        if name in used:
            continue
        used.add(name)
        cars.append(car)
        if len(cars) >= 7:
            break
    abandoned_limited_key = maybe_roll_limited_spawn_key(rng) if cars else None
    if abandoned_limited_key:
        limited_car = LIMITED_CARS_BY_KEY[abandoned_limited_key]
        slot = rng.randrange(len(cars))
        cars[slot] = {
            "name": limited_car["name"], "year": limited_car["year"],
            "min": int(limited_car["price"]), "max": int(limited_car["price"]),
            "repair": 0, "limited_key": abandoned_limited_key,
        }

    # Два редких номера: triple/gold/lucky.
    plate_types = ["gold", "triple", "lucky"]
    rng.shuffle(plate_types)
    plates = []
    used_numbers = set()
    for ptype in plate_types:
        for _ in range(30):
            number = generate_plate_number(ptype)
            if number not in used_numbers:
                used_numbers.add(number)
                base_price = int(PLATE_TYPES[ptype]["price"] * rng.uniform(1.4, 3.2))
                plates.append({"number": number, "plate_type": ptype, "price": base_price})
                break
        if len(plates) >= 2:
            break

    # Несколько случайных запчастей из уже существующего каталога.
    parts = []
    part_keys = list(PART_MARKET_CATALOG.keys())
    rng.shuffle(part_keys)
    for key in part_keys[:rng.randint(3, min(4, len(part_keys)))]:
        parts.append({
            "key": key,
            "name": PART_MARKET_CATALOG[key]["name"],
            "quantity": rng.randint(1, 3),
        })

    return cars, plates, parts


def abandoned_dealership_keyboard():
    kb = InlineKeyboardBuilder()
    kb.button(text=f"🏢 Купить салон за {ABANDONED_DEALERSHIP_COST:,} ₽", callback_data="abandoned_dealership_buy")
    kb.button(text="🔙 Свалка", callback_data="dump")
    kb.adjust(1)
    return kb.as_markup()


async def show_abandoned_dealership(target):
    cars, plates, parts = abandoned_dealership_loot()
    text = (
        "🏢 <b>ЗАБРОШЕННЫЙ АВТОСАЛОН</b>\n\n"
        "Старый салон закрыли много лет назад. Внутри всё осталось как есть.\n\n"
        "💰 <b>Стоимость покупки: 20 000 000 ₽</b>\n\n"
        "После покупки ты получишь случайный лут:\n"
        f"🚗 <b>{len(cars)} автомобилей</b>\n"
        f"🏷 <b>{len(plates)} редких номера</b>\n"
        f"🔧 <b>{sum(p['quantity'] for p in parts)} запчастей</b>\n\n"
        "⚠️ Машины случайные: среди обычных может попасться очень дорогая находка."
    )
    markup = abandoned_dealership_keyboard()
    if hasattr(target, "message"):
        await edit_text_safe(target, text, parse_mode="HTML", reply_markup=markup)
    else:
        await target.answer(text, parse_mode="HTML", reply_markup=markup)


@dp.callback_query(F.data == "abandoned_dealership")
async def abandoned_dealership_open(call):
    await show_abandoned_dealership(call)
    await safe_callback_answer()


@dp.callback_query(F.data == "abandoned_dealership_buy")
async def abandoned_dealership_buy(call):
    user_id = call.from_user.id
    cars, plates, parts = abandoned_dealership_loot()
    limited_awards = []

    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        await db.execute(
            "CREATE TABLE IF NOT EXISTS abandoned_dealership_history (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, cost INTEGER NOT NULL, created_at TEXT NOT NULL)"
        )
        cur = await db.execute("SELECT balance FROM players WHERE user_id = ?", (user_id,))
        row = await cur.fetchone()
        balance = int(row["balance"] if row else 0)
        if balance < ABANDONED_DEALERSHIP_COST:
            await safe_callback_answer(
                f"❌ Нужно {ABANDONED_DEALERSHIP_COST:,} ₽.",
                show_alert=True,
            )
            return

        now = datetime.now().isoformat(timespec="seconds")
        await db.execute(
            "UPDATE players SET balance = balance - ? WHERE user_id = ?",
            (ABANDONED_DEALERSHIP_COST, user_id),
        )

        # 7 машин сразу отправляются в гараж; редкий лимитированный слот выдаётся через общий реестр.
        for car in cars:
            if car.get("limited_key"):
                award = await issue_limited_vehicle_in_transaction(
                    db, user_id, car["limited_key"], source="abandoned_dealership",
                    paid_price=ABANDONED_DEALERSHIP_COST // 7,
                )
                if award:
                    limited_awards.append(award)
                    continue
                # Если экземпляр достался другому игроку до оплаты, этот слот становится обычным авто.
                car = dict(random.choice(CARS))
            await db.execute(
                """INSERT INTO garage(
                    user_id, car_name, buy_price, repair_cost, repaired, history_type,
                    history_multiplier, paparazzi_multiplier, paparazzi_until,
                    origin_country, current_country, current_city, repair_count, repaint_count,
                    restoration_stage, originality_score
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    user_id, car["name"],
                    max(1, int(car.get("min", 0) * 0.35)),
                    int(car.get("repair", 0)), 0,
                    "abandoned_dealership", 0.90, 1.0, None,
                    "Россия", "Россия", "Заброшенный автосалон",
                    0, 0, 0, 0,
                ),
            )

        # Номера получают постоянную запись в реестре до выдачи игроку.
        # Если предложенная комбинация уже занята/зарезервирована, выбираем новую.
        for plate in plates:
            number = await claim_unique_plate_number(
                db, plate["plate_type"], user_id, preferred_number=plate["number"]
            )
            if not number:
                continue
            try:
                await db.execute(
                    "INSERT INTO plates(user_id, number, plate_type, buy_price) VALUES(?,?,?,?)",
                    (user_id, number, plate["plate_type"], plate["price"]),
                )
                plate["number"] = number
            except aiosqlite.IntegrityError:
                # Если запись в инвентарь не прошла, освобождаем только что
                # созданную запись реестра в этой же транзакции.
                await db.execute(
                    "DELETE FROM plate_number_registry WHERE number = ? AND status = 'owned' AND reserved_by IS NULL",
                    (number,),
                )
                continue

        # Запчасти складываются в существующий инвентарь.
        for part in parts:
            pdata = PART_MARKET_CATALOG[part["key"]]
            await db.execute(
                """INSERT INTO player_parts(user_id, part_key, part_name, quantity, updated_at)
                   VALUES(?,?,?,?,?)
                   ON CONFLICT(user_id, part_key) DO UPDATE SET
                       quantity = quantity + excluded.quantity,
                       updated_at = excluded.updated_at""",
                (user_id, part["key"], pdata["name"], part["quantity"], now),
            )

        await db.execute(
            "INSERT INTO abandoned_dealership_history(user_id, cost, created_at) VALUES(?,?,?)",
            (user_id, ABANDONED_DEALERSHIP_COST, now),
        )
        await db.commit()

    if limited_awards:
        await refresh_limited_stock_cache()
    car_names = [c["name"] for c in cars]
    plate_lines = []
    for p in plates:
        pdata = PLATE_TYPES.get(p["plate_type"], PLATE_TYPES["region"])
        bonus_pct = round((float(pdata.get("multiplier", 1.0)) - 1.0) * 100)
        bonus_label = f"+{bonus_pct}%" if bonus_pct > 0 else "0%"
        plate_lines.append(
            f"🏷 <b>{p['number']}</b> — {p['price']:,} ₽\n"
            f"{pdata['name']} · коэффициент ×{pdata['multiplier']:.2f} ({bonus_label})\n"
            f"{pdata.get('feature', 'Коллекционный номер')}"
        )
    plate_text = "\n".join(plate_lines)
    part_text = "\n".join(f"🔧 {p['name']} ×{p['quantity']}" for p in parts)
    limited_text = "\n\n".join(limited_award_text(a, "💎 <b>ЭКСКЛЮЗИВ ИЗ ЗАБРОШЕННОГО САЛОНА!</b>") for a in limited_awards)
    text = (
        "🎉 <b>АВТОСАЛОН РАЗОБРАН!</b>\n\n"
        "Ты заплатил <b>20 000 000 ₽</b> и получил содержимое старого салона.\n\n"
        "🚗 <b>7 автомобилей:</b>\n" +
        "\n".join(f"• {name}" for name in car_names) +
        "\n\n🏷 <b>2 редких номера:</b>\n" + plate_text +
        "\n\n" + part_text +
        ("\n\n" + limited_text if limited_text else "") +
        "\n\n✅ Машины отправлены в гараж, номера — в коллекцию, запчасти — на склад."
    )
    kb = InlineKeyboardBuilder()
    kb.button(text="🚗 Гараж", callback_data="garage")
    kb.button(text="🏷 Мои номера", callback_data="plates_inventory")
    kb.button(text="🔧 Мои запчасти", callback_data="parts_inventory")
    kb.button(text="🔙 Свалка", callback_data="dump")
    kb.adjust(1)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer("🏢 Заброшенный автосалон куплен!")


