@dp.callback_query(F.data.startswith("grave_buy:"))
async def graveyard_buy(call):
    _, day, index = call.data.split(":")
    lots = graveyard_lots(day)
    lot = lots[int(index) % len(lots)]
    user_id = call.from_user.id
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT balance FROM players WHERE user_id = ?", (user_id,))
        player = await cur.fetchone()
        if not player or int(player[0]) < lot["price"]:
            await safe_callback_answer(f"❌ Нужно {lot['price']:,} ₽.", show_alert=True)
            return
        now = datetime.now().isoformat(timespec="seconds")
        cur = await db.execute(
            """INSERT INTO garage(user_id, car_name, buy_price, repair_cost, repaired, history_type, history_multiplier, paparazzi_multiplier, paparazzi_until, origin_country, current_country, current_city, repair_count, repaint_count, restoration_stage, originality_score)\n               VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (user_id, lot["name"], lot["price"], lot.get("repair", 0), 0, "salvage", 0.80, 1.0, None, "Россия", "Россия", "Автокладбище", 0, 0, 0, 0)
        )
        car_id = cur.lastrowid
        await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (lot["price"], user_id))
        await db.execute("INSERT INTO vehicle_locations(car_id,country,city,event_at,event_type) VALUES(?,?,?,?,?)", (car_id, "Россия", "Автокладбище", now, "salvage"))
        await db.execute("INSERT INTO vehicle_history(car_id,owner_id,event_type,event_at,amount,details) VALUES(?,?,?,?,?,?)", (car_id,user_id,"salvage_purchase",now,lot["price"],"Куплен на автомобильном кладбище"))
        await db.commit()
    await show_graveyard(call, day, int(index))
    await safe_callback_answer("🏚 Машина забрана с кладбища!")




# =========================================================
# 🏡 ПОИСК ЗАБРОШЕННЫХ АВТО ВО ДВОРАХ
# =========================================================

YARD_SEARCH_COOLDOWN = 30 * 60
YARD_POLICE_CHANCE = 0.18
YARD_SUCCESS_CHANCE = 0.42
YARD_DOCUMENT_COST = 75_000
YARD_MAX_ACTIVE = 1
yard_last_search = {}


def yard_day():
    return datetime.now().strftime("%Y-%m-%d")


def abandoned_condition_profile(rng, abandoned_years, water_level=0, vegetation_bonus=0):
    """Генерирует накопленные последствия длительного хранения автомобиля."""
    years = max(1, int(abandoned_years))
    water = max(0, int(water_level))
    return {
        "cobweb_level": min(100, max(0, 15 + years * 5 + rng.randint(-8, 8))),
        "vegetation_level": min(100, max(0, 4 + years * 6 + vegetation_bonus + rng.randint(-10, 10))),
        "mold_level": min(100, max(0, years * 3 + water + rng.randint(-8, 8))),
        "animal_damage": min(100, max(0, years * 2 + rng.randint(-6, 12))),
        "battery_charge": min(100, max(0, 88 - years * 9 + rng.randint(-8, 4))),
        "tire_condition": min(100, max(0, 96 - years * 6 + rng.randint(-8, 4))),
        "fluid_condition": min(100, max(0, 100 - years * 5 - water // 3 + rng.randint(-7, 4))),
    }


def condition_display(profile):
    battery = int(profile.get("battery_charge", 100))
    tires = int(profile.get("tire_condition", 100))
    fluids = int(profile.get("fluid_condition", 100))
    tire_text = "спущены" if tires <= 20 else f"состояние {tires}%"
    fluid_text = "требуют полной замены" if fluids <= 20 else f"состояние {fluids}%"
    return (
        f"🕸 Паутина: <b>{int(profile.get('cobweb_level', 0))}%</b>\n"
        f"🌿 Растительность: <b>{int(profile.get('vegetation_level', 0))}%</b>\n"
        f"🦠 Плесень: <b>{int(profile.get('mold_level', 0))}%</b>\n"
        f"🐀 Следы животных: <b>{int(profile.get('animal_damage', 0))}%</b>\n"
        f"🪫 Аккумулятор: <b>{battery}% заряда</b>\n"
        f"🛞 Колёса: <b>{tire_text}</b>\n"
        f"🛢 Жидкости: <b>{fluid_text}</b>"
    )


def condition_repair_multiplier(profile, flooded=False):
    mult = 1.0
    mult += int(profile.get("cobweb_level", 0)) / 100 * 0.02
    mult += int(profile.get("vegetation_level", 0)) / 100 * 0.06
    mult += int(profile.get("mold_level", 0)) / 100 * 0.22
    mult += int(profile.get("animal_damage", 0)) / 100 * 0.18
    mult += (100 - int(profile.get("battery_charge", 100))) / 100 * 0.06
    mult += (100 - int(profile.get("tire_condition", 100))) / 100 * 0.08
    mult += (100 - int(profile.get("fluid_condition", 100))) / 100 * 0.06
    if flooded:
        mult *= UNDERGROUND_FLOOD_REPAIR_MULTIPLIER
    return mult


def yard_lots(day, user_id):
    pool = []
    for c in CARS:
        pool.append(c)
    for cars in IMPORT_CARS.values():
        pool.extend(cars)
    rng = random.Random(f"yards:{day}:{user_id}")
    rng.shuffle(pool)
    result = []
    for i, car in enumerate(pool[:8]):
        market = int((car.get("min", 0) + car.get("max", 0)) / 2)
        condition = rng.choice(["abandoned", "rust", "nonrunner", "covered"])
        abandoned_years = rng.randint(2, 14)
        profile = abandoned_condition_profile(rng, abandoned_years)
        recovery_cost = max(25_000, int(market * rng.uniform(0.05, 0.14) * condition_repair_multiplier(profile)))
        result.append({
            **car,
            "index": i,
            "condition": condition,
            "abandoned_years": abandoned_years,
            **profile,
            "recovery_cost": recovery_cost,
            "market": market,
        })
    return result


def yard_keyboard(day, index, user_id):
    kb = InlineKeyboardBuilder()
    lots = yard_lots(day, user_id)
    total = len(lots)
    kb.button(text="⬅️", callback_data=f"yard:{day}:{index-1}")
    kb.button(text=f"{index+1}/{total}", callback_data=f"yard:{day}:{index}")
    kb.button(text="➡️", callback_data=f"yard:{day}:{index+1}")
    kb.button(text="🔎 Осмотреть", callback_data=f"yard_inspect:{day}:{index}")
    kb.button(text="🔙 Свалка", callback_data="dump")
    kb.adjust(3, 1, 1)
    return kb.as_markup()


def yard_condition_text(condition):
    return {
        "abandoned": "📦 Стоит во дворе без движения уже долгое время.",
        "rust": "🟤 На кузове заметна сильная коррозия.",
        "nonrunner": "🔧 Двигатель не запускается, требуется восстановление.",
        "covered": "🧹 Автомобиль накрыт и давно не используется.",
    }.get(condition, "❓ Состояние неизвестно.")


async def show_yard_search(target, day=None, index=0):
    user_id = target.from_user.id if hasattr(target, "from_user") else target.effective_user.id
    day = day or yard_day()
    lots = yard_lots(day, user_id)
    index %= len(lots)
    lot = lots[index]
    text = (
        "🏡 <b>ПОИСК ВО ДВОРАХ</b>\n\n"
        f"🚗 <b>{lot['name']}</b>\n"
        f"📅 Год: <b>{lot.get('year','—')}</b>\n"
        f"{yard_condition_text(lot['condition'])}\n"
        f"🏚 Простой: <b>{lot['abandoned_years']} лет</b>\n"
        f"{condition_display(lot)}\n\n"
        f"💎 Потенциал после восстановления: <b>≈ {lot['market']:,} ₽</b>\n"
        f"🔧 Ориентировочные расходы на восстановление: <b>{lot['recovery_cost']:,} ₽</b>\n\n"
        "⚠️ При попытке забрать автомобиль есть риск встретить полицию.\n"
        "✅ При удачном исходе автомобиль можно принять в гараж как восстановительный проект и оформить новые игровые документы."
    )
    markup = yard_keyboard(day, index, user_id)
    if hasattr(target, "message"):
        await edit_text_safe(target, text, parse_mode="HTML", reply_markup=markup)
    else:
        await target.answer(text, parse_mode="HTML", reply_markup=markup)


@dp.callback_query(F.data == "yard_search")
async def yard_search_open(call):
    await show_yard_search(call)
    await safe_callback_answer()


@dp.callback_query(F.data.startswith("yard:"))
async def yard_page(call):
    _, day, index = call.data.split(":")
    await show_yard_search(call, day, int(index))
    await safe_callback_answer()


@dp.callback_query(F.data.startswith("yard_inspect:"))
async def yard_inspect(call):
    _, day, index = call.data.split(":")
    user_id = call.from_user.id
    lots = yard_lots(day, user_id)
    lot = lots[int(index) % len(lots)]
    now_ts = datetime.now().timestamp()
    last = yard_last_search.get(user_id, 0)
    if now_ts - last < YARD_SEARCH_COOLDOWN:
        remaining = int(YARD_SEARCH_COOLDOWN - (now_ts - last))
        mins = max(1, remaining // 60)
        await safe_callback_answer(f"⏳ Следующий поиск через {mins} мин.", show_alert=True)
        return
    yard_last_search[user_id] = now_ts

    roll = random.random()
    if roll < YARD_POLICE_CHANCE:
        fine = random.randint(20_000, 80_000)
        async with aiosqlite.connect(DB) as db:
            await db.execute("UPDATE players SET balance = MAX(0, balance - ?) WHERE user_id = ?", (fine, user_id))
            await db.commit()
        await safe_callback_answer(f"🚔 Патруль заметил подозрительную активность. Штраф: {fine:,} ₽.", show_alert=True)
        return

    if roll < YARD_POLICE_CHANCE + YARD_SUCCESS_CHANCE:
        async with aiosqlite.connect(DB) as db:
            cur = await db.execute("SELECT balance FROM players WHERE user_id = ?", (user_id,))
            player = await cur.fetchone()
            balance = int(player[0]) if player else 0
            if balance < YARD_DOCUMENT_COST:
                await safe_callback_answer(f"❌ Для оформления документов нужно {YARD_DOCUMENT_COST:,} ₽.", show_alert=True)
                return
            now = datetime.now().isoformat(timespec="seconds")
            cur = await db.execute(
                """INSERT INTO garage(
                    user_id, car_name, buy_price, repair_cost, repaired, history_type, history_multiplier,
                    paparazzi_multiplier, paparazzi_until, origin_country, current_country, current_city,
                    repair_count, repaint_count, restoration_stage, originality_score, registered, registered_at,
                    abandoned_years, storage_condition, dust_level, recovery_method, water_level,
                    cobweb_level, vegetation_level, mold_level, animal_damage, battery_charge, tire_condition, fluid_condition
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    user_id, lot["name"], YARD_DOCUMENT_COST, lot.get("recovery_cost", 0), 0,
                    "yard_recovery", 0.88, 1.0, None, "Россия", "Россия", "Двор",
                    0, 0, 0, 0, 1, now,
                    lot["abandoned_years"], yard_condition_text(lot["condition"]), 0, "самостоятельно", 0,
                    lot["cobweb_level"], lot["vegetation_level"], lot["mold_level"], lot["animal_damage"],
                    lot["battery_charge"], lot["tire_condition"], lot["fluid_condition"]
                ),
            )
            car_id = cur.lastrowid
            await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (YARD_DOCUMENT_COST, user_id))
            await db.execute(
                "INSERT INTO vehicle_locations(car_id,country,city,event_at,event_type) VALUES(?,?,?,?,?)",
                (car_id, "Россия", "Двор", now, "yard_recovery"),
            )
            await db.execute(
                "INSERT INTO vehicle_history(car_id,owner_id,event_type,event_at,amount,details) VALUES(?,?,?,?,?,?)",
                (car_id, user_id, "yard_recovery", now, YARD_DOCUMENT_COST, "Найден как заброшенный автомобиль во дворе; оформлен в игровой системе новыми документами"),
            )
            await db.commit()
        await edit_text_safe(
            call,
            "✅ <b>МАШИНА НАЙДЕНА!</b>\n\n"
            f"🚗 <b>{lot['name']}</b>\n"
            f"💰 Оформление: <b>{YARD_DOCUMENT_COST:,} ₽</b>\n"
            "📄 Машина добавлена в гараж как восстановительный проект.\n"
            "🪪 Внутри игры ей оформлены новые документы, поэтому она не числится в угоне.\n\n"
            f"🔧 Восстановление: около <b>{lot.get('recovery_cost',0):,} ₽</b>\n\n"
            f"{condition_display(lot)}",
            parse_mode="HTML", reply_markup=InlineKeyboardBuilder().button(text="🏠 Гараж", callback_data="garage").as_markup()
        )
        await safe_callback_answer("🚗 Машина успешно забрана!")
        return

    await safe_callback_answer("❌ Во дворе ничего подходящего не найдено. Попробуй поискать в другом месте.", show_alert=True)


# =========================================================
# 🅿️ ПОИСК ЗАБРОШЕННЫХ АВТО НА ПОДЗЕМНЫХ ПАРКОВКАХ
# =========================================================

UNDERGROUND_SEARCH_COOLDOWN = 45 * 60
UNDERGROUND_FIND_CHANCE = 0.46
UNDERGROUND_SELF_DRIVE_POLICE = 0.34
UNDERGROUND_TOW_POLICE = 0.12
UNDERGROUND_TOW_COST = 55_000
UNDERGROUND_DOC_COST = 90_000
UNDERGROUND_FLOOD_FIND_CHANCE = 0.22
UNDERGROUND_FLOOD_REPAIR_MULTIPLIER = 2.40
UNDERGROUND_FLOOD_VALUE_MULTIPLIER = 0.72
UNDERGROUND_FLOOD_WATER_MIN = 18
UNDERGROUND_FLOOD_WATER_MAX = 95
underground_last_search = {}


def underground_day():
    return datetime.now().strftime("%Y-%m-%d")


def underground_lots(day, user_id):
    pool = []
    for c in CARS:
        pool.append(c)
    for cars in IMPORT_CARS.values():
        pool.extend(cars)
    rng = random.Random(f"underground:{day}:{user_id}")
    rng.shuffle(pool)
    result = []
    conditions = [
        ("dusty", "Покрыта толстым слоем пыли"),
        ("forgotten", "Стоит без движения много лет"),
        ("damp", "Сырой паркинг, следы длительного хранения"),
        ("covered", "Накрыта старым чехлом, кузов почти не видно"),
    ]
    for i, car in enumerate(pool[:8]):
        market = int((car.get("min", 0) + car.get("max", 0)) / 2)
        abandoned_years = rng.randint(2, 17)
        flooded = rng.random() < UNDERGROUND_FLOOD_FIND_CHANCE
        if flooded:
            condition_key = "flooded"
            condition_text = rng.choice([
                "Нижний этаж частично затоплен",
                "Машина стояла в воде после аварии дренажной системы",
                "На полу следы многолетней сырости и подтопления",
            ])
            water_level = rng.randint(UNDERGROUND_FLOOD_WATER_MIN, UNDERGROUND_FLOOD_WATER_MAX)
            dust = min(99, 35 + abandoned_years * 2 + rng.randint(-8, 8))
            repair_multiplier = UNDERGROUND_FLOOD_REPAIR_MULTIPLIER
            value_multiplier = UNDERGROUND_FLOOD_VALUE_MULTIPLIER
        else:
            condition_key, condition_text = rng.choice(conditions)
            water_level = rng.randint(0, 8) if condition_key != "damp" else rng.randint(8, 25)
            dust = min(99, 45 + abandoned_years * 3 + rng.randint(-8, 8))
            repair_multiplier = 1.0
            value_multiplier = 1.0
        profile = abandoned_condition_profile(rng, abandoned_years, water_level, vegetation_bonus=8 if abandoned_years >= 9 else 0)
        base_recovery_cost = max(35_000, int(market * rng.uniform(0.07, 0.18)))
        recovery_cost = max(35_000, int(base_recovery_cost * condition_repair_multiplier(profile, flooded=flooded)))
        market_after_storage = max(1, int(market * value_multiplier))
        result.append({
            **car,
            "index": i,
            "condition_key": condition_key,
            "condition_text": condition_text,
            "abandoned_years": abandoned_years,
            "dust_level": dust,
            "water_level": water_level,
            "flooded": flooded,
            **profile,
            "recovery_cost": recovery_cost,
            "market": market,
            "market_after_storage": market_after_storage,
        })
    return result


def underground_keyboard(day, index, user_id):
    lots = underground_lots(day, user_id)
    total = len(lots)
    index %= total
    kb = InlineKeyboardBuilder()
    kb.button(text="⬅️", callback_data=f"underground:{day}:{index-1}")
    kb.button(text=f"{index+1}/{total}", callback_data=f"underground:{day}:{index}")
    kb.button(text="➡️", callback_data=f"underground:{day}:{index+1}")
    kb.button(text="🔎 Осмотреть", callback_data=f"underground_inspect:{day}:{index}")
    kb.button(text="🔙 Свалка", callback_data="dump")
    kb.adjust(3, 1, 1)
    return kb.as_markup()


async def show_underground_search(target, day=None, index=0):
    user_id = target.from_user.id if hasattr(target, "from_user") else target.effective_user.id
    day = day or underground_day()
    lots = underground_lots(day, user_id)
    index %= len(lots)
    lot = lots[index]
    text = (
        "🅿️ <b>ПОДЗЕМНАЯ ПАРКОВКА</b>\n\n"
        f"🚗 <b>{lot['name']}</b>\n"
        f"📅 Год выпуска: <b>{lot.get('year', '—')}</b>\n"
        f"🏚 Заброшена: <b>{lot['abandoned_years']} лет</b>\n"
        f"{lot['condition_text']}.\n"
        f"🌫 Пыль: <b>{lot['dust_level']}%</b>\n"
        f"💧 Вода: <b>{lot['water_level']}%</b>\n"
        f"{condition_display(lot)}\n"
        + ("⚠️ <b>ЗАТОПЛЕННЫЙ ЭТАЖ</b> — ремонт значительно дороже.\n" if lot.get('flooded') else "")
        + "\n"
        f"💎 Потенциал после восстановления: <b>≈ {lot['market_after_storage']:,} ₽</b>\n"
        f"🔧 Ориентировочный ремонт: <b>{lot['recovery_cost']:,} ₽</b>\n\n"
        "🚚 Можно вызвать эвакуатор и аккуратно доставить машину в гараж.\n"
        "🚗 Либо попытаться забрать её самостоятельно — риск встречи с полицией выше."
    )
    markup = underground_keyboard(day, index, user_id)
    if hasattr(target, "message"):
        await edit_text_safe(target, text, parse_mode="HTML", reply_markup=markup)
    else:
        await target.answer(text, parse_mode="HTML", reply_markup=markup)


@dp.callback_query(F.data == "underground_search")
async def underground_search_open(call):
    await show_underground_search(call)
    await safe_callback_answer()


@dp.callback_query(F.data.startswith("underground:"))
async def underground_page(call):
    _, day, index = call.data.split(":")
    await show_underground_search(call, day, int(index))
    await safe_callback_answer()


@dp.callback_query(F.data.startswith("underground_inspect:"))
async def underground_inspect(call):
    _, day, index = call.data.split(":")
    user_id = call.from_user.id
    lots = underground_lots(day, user_id)
    lot = lots[int(index) % len(lots)]
    now_ts = datetime.now().timestamp()
    last = underground_last_search.get(user_id, 0)
    if now_ts - last < UNDERGROUND_SEARCH_COOLDOWN:
        remaining = int(UNDERGROUND_SEARCH_COOLDOWN - (now_ts - last))
        mins = max(1, remaining // 60)
        await safe_callback_answer(f"⏳ Следующий поиск через {mins} мин.", show_alert=True)
        return
    underground_last_search[user_id] = now_ts

    if random.random() > UNDERGROUND_FIND_CHANCE:
        await safe_callback_answer("🔦 Проверил паркинг — подходящего автомобиля найти не удалось.", show_alert=True)
        return

    kb = InlineKeyboardBuilder()
    kb.button(text=f"🚚 Эвакуатор — {UNDERGROUND_TOW_COST:,} ₽", callback_data=f"underground_recover:{day}:{index}:tow")
    kb.button(text="🚗 Забрать самостоятельно", callback_data=f"underground_recover:{day}:{index}:self")
    kb.button(text="🔙 Назад", callback_data=f"underground:{day}:{index}")
