                "underground_recovery", 0.95, 1.0, None, "Россия", "Россия", "Подземный паркинг",
                0, 0, 0, 0, 1, registered_at,
                lot["abandoned_years"], storage_label, lot["dust_level"], recovery_label, lot.get("water_level", 0),
                lot["cobweb_level"], lot["vegetation_level"], lot["mold_level"], lot["animal_damage"],
                lot["battery_charge"], lot["tire_condition"], lot["fluid_condition"],
