# =========================================================
# 🏡 ЗАБРОШЕННЫЕ ДАЧНЫЕ ГАРАЖИ
# =========================================================

DACHA_SEARCH_COOLDOWN = 45 * 60
DACHA_FIND_CHANCE = 0.58
DACHA_POLICE_CHANCE = 0.20
DACHA_SERIOUS_CHECK_CHANCE = 0.10
DACHA_TOW_COST = 65_000
DACHA_DOC_COST = 95_000
DACHA_MAX_ACTIVE = 1
dacha_last_search = {}
dacha_recovery_lock = {}


def dacha_day():
    return datetime.now().strftime("%Y-%m-%d")


def dacha_lots(day, user_id):
    pool = list(CARS)
    for cars in IMPORT_CARS.values():
        pool.extend(cars)
    rng = random.Random(f"dacha:{day}:{user_id}")
    rng.shuffle(pool)
    result = []
    locations = [
        "Старый дачный кооператив",
        "Заброшенная дача у леса",
        "Садовое товарищество",
        "Старая дачная улица",
        "Закрытый гаражный ряд",
    ]
    garage_states = [
        ("ржавый замок", 0.90),
        ("старые распашные ворота", 1.00),
        ("заросший въезд", 1.08),
        ("частично разрушенные ворота", 1.15),
        ("старый металлический бокс", 1.04),
    ]
    for i, car in enumerate(pool[:7]):
        market = int((car.get("min", 0) + car.get("max", 0)) / 2)
        abandoned_years = rng.randint(4, 21)
        water = rng.randint(0, 18) if rng.random() < 0.25 else 0
        profile = abandoned_condition_profile(rng, abandoned_years, water, vegetation_bonus=10 if abandoned_years >= 12 else 0)
        state_text, state_mult = rng.choice(garage_states)
        rarity_roll = rng.random()
        if rarity_roll < 0.05:
            value_mult = 1.35
            history_type = "dacha_rare"
        elif rarity_roll < 0.18:
            value_mult = 1.12
            history_type = "dacha_history"
        else:
            value_mult = 0.95
            history_type = "dacha"
        recovery_cost = max(
            35_000,
            int(market * rng.uniform(0.08, 0.20) * state_mult * condition_repair_multiplier(profile, bool(water)))
        )
        access_difficulty = rng.randint(1, 5)
        result.append({
            **car,
            "index": i,
            "location": rng.choice(locations),
            "garage_state": state_text,
            "access_difficulty": access_difficulty,
            "abandoned_years": abandoned_years,
            "water_level": water,
            "history_type": history_type,
            "market": int(market * value_mult),
            "recovery_cost": recovery_cost,
            **profile,
        })
    return result


def dacha_keyboard(day, index, user_id):
    lots = dacha_lots(day, user_id)
    kb = InlineKeyboardBuilder()
    kb.button(text="⬅️", callback_data=f"dacha:{day}:{index-1}")
    kb.button(text=f"{index+1}/{len(lots)}", callback_data=f"dacha:{day}:{index}")
    kb.button(text="➡️", callback_data=f"dacha:{day}:{index+1}")
    kb.button(text="🔎 Осмотреть гараж", callback_data=f"dacha_inspect:{day}:{index}")
    kb.button(text="🔙 Свалка", callback_data="dump")
    kb.adjust(3, 1, 1)
    return kb.as_markup()


async def show_dacha_garages(target, day=None, index=0):
    user_id = target.from_user.id if hasattr(target, "from_user") else target.effective_user.id
    day = day or dacha_day()
    lots = dacha_lots(day, user_id)
    index %= len(lots)
    lot = lots[index]
    text = (
        "🏡 <b>ЗАБРОШЕННЫЕ ДАЧНЫЕ ГАРАЖИ</b>\n\n"
        f"📍 {lot['location']}\n"
        f"🚪 Ворота: <b>{lot['garage_state']}</b>\n"
        f"🚗 <b>{lot['name']}</b>\n"
        f"📅 Год: <b>{lot.get('year', '—')}</b>\n"
        f"🏚 Заброшена: <b>{lot['abandoned_years']} лет</b>\n"
        f"{condition_display(lot)}\n"
        + (f"💧 Вода: <b>{lot['water_level']}%</b> — есть риск дополнительной коррозии.\n" if lot['water_level'] else "")
        + f"🔧 Восстановление: <b>{lot['recovery_cost']:,} ₽</b>\n"
        + f"💎 Потенциал после восстановления: <b>≈ {lot['market']:,} ₽</b>\n\n"
        "🔎 Нажми «Осмотреть гараж», чтобы проверить автомобиль.\n"
        "⚠️ При вывозе возможна проверка полиции и проверка документов."
    )
    if hasattr(target, "message"):
        await edit_text_safe(target, text, parse_mode="HTML", reply_markup=dacha_keyboard(day, index, user_id))
    else:
        await target.answer(text, parse_mode="HTML", reply_markup=dacha_keyboard(day, index, user_id))


@dp.callback_query(F.data == "dacha_garages")
async def dacha_garages_open(call):
    await show_dacha_garages(call)
    await safe_callback_answer()


@dp.callback_query(F.data.startswith("dacha:"))
async def dacha_page(call):
    _, day, index = call.data.split(":")
    await show_dacha_garages(call, day, int(index))
    await safe_callback_answer()


@dp.callback_query(F.data.startswith("dacha_inspect:"))
async def dacha_inspect(call):
    _, day, index = call.data.split(":")
    user_id = call.from_user.id
    now_ts = datetime.now().timestamp()
    last = dacha_last_search.get(user_id, 0)
    if now_ts - last < DACHA_SEARCH_COOLDOWN:
        remaining = int(DACHA_SEARCH_COOLDOWN - (now_ts - last))
        await safe_callback_answer(f"⏳ Следующий выезд через {max(1, remaining // 60)} мин.", show_alert=True)
        return
    dacha_last_search[user_id] = now_ts
    lots = dacha_lots(day, user_id)
    lot = lots[int(index) % len(lots)]
    if random.random() > DACHA_FIND_CHANCE:
        await safe_callback_answer("🔦 Осмотрел гараж — машина слишком сильно повреждена и для игры не пригодна.", show_alert=True)
        return
    kb = InlineKeyboardBuilder()
    kb.button(text=f"🚚 Эвакуатор — {DACHA_TOW_COST:,} ₽", callback_data=f"dacha_recover:{day}:{index}:tow")
    kb.button(text=f"🚗 Забрать самому — {DACHA_DOC_COST:,} ₽", callback_data=f"dacha_recover:{day}:{index}:self")
    kb.button(text="🔙 Назад", callback_data=f"dacha:{day}:{index}")
    kb.adjust(1)
    text = (
        "✅ <b>МАШИНА НАЙДЕНА В ГАРАЖЕ!</b>\n\n"
        f"🚗 <b>{lot['name']}</b>\n"
        f"📍 {lot['location']}\n"
        f"🚪 Доступ: <b>сложность {lot['access_difficulty']}/5</b>\n"
        f"🏚 Простой: <b>{lot['abandoned_years']} лет</b>\n"
        f"{condition_display(lot)}\n"
        + (f"💧 Вода: <b>{lot['water_level']}%</b>\n" if lot['water_level'] else "")
        + f"🔧 Восстановление: <b>{lot['recovery_cost']:,} ₽</b>\n\n"
        "Как организовать вывоз?\n"
        "🚚 Эвакуатор — безопаснее и дороже.\n"
        "🚗 Самостоятельный вывоз — дешевле, но выше шанс проверки полиции."
    )
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer("🔎 Найден заброшенный дачный гараж!")


@dp.callback_query(F.data.startswith("dacha_recover:"))
async def dacha_recover(call):
    _, day, index, method = call.data.split(":")
    user_id = call.from_user.id
    lots = dacha_lots(day, user_id)
    lot = lots[int(index) % len(lots)]
    now_ts = datetime.now().timestamp()
    locked_until = dacha_recovery_lock.get(user_id, 0)
    if locked_until > now_ts:
        minutes = max(1, int((locked_until - now_ts) // 60))
        await safe_callback_answer(f"🚔 После недавней проверки нельзя снова выезжать пока что. Ещё {minutes} мин.", show_alert=True)
        return

    police_chance = DACHA_POLICE_CHANCE + (0.12 if method == "self" else -0.05)
    police_chance += lot["access_difficulty"] * 0.015
    police_chance = max(0.05, min(0.55, police_chance))
    roll = random.random()

    if roll < police_chance:
        fine = random.randint(25_000, 110_000)
        serious = random.random() < DACHA_SERIOUS_CHECK_CHANCE
        async with aiosqlite.connect(DB) as db:
            await db.execute("UPDATE players SET balance = MAX(0, balance - ?) WHERE user_id = ?", (fine, user_id))
            await db.commit()
        dacha_recovery_lock[user_id] = now_ts + (2 * 60 * 60 if serious else 45 * 60)
        result = (
            "🚔 <b>ПОЛИЦИЯ ОСТАНОВИЛА ВЫВОЗ</b>\n\n"
            f"📄 Сотрудники попросили предъявить документы на автомобиль.\n"
            f"💸 Штраф: <b>{fine:,} ₽</b>\n"
            + ("🔎 Проведена расширенная проверка. Следующая поездка временно недоступна.\n" if serious else "")
            + "🚗 Автомобиль остался в гараже."
        )
        await edit_text_safe(call, result, parse_mode="HTML", reply_markup=InlineKeyboardBuilder().button(text="🔙 Свалка", callback_data="dump").as_markup())
        await safe_callback_answer("🚔 Проверка полиции завершена.", show_alert=True)
        return

    tow_cost = DACHA_TOW_COST if method == "tow" else 0
    total_cost = DACHA_DOC_COST + tow_cost
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT balance FROM players WHERE user_id = ?", (user_id,))
        player = await cur.fetchone()
        balance = int(player[0]) if player else 0
        if balance < total_cost:
            await safe_callback_answer(f"❌ Нужно {total_cost:,} ₽ для оформления и вывоза автомобиля.", show_alert=True)
            return
        now = datetime.now().isoformat(timespec="seconds")
        recovery_label = "эвакуатор" if method == "tow" else "самостоятельно"
        storage_label = f"Заброшенный дачный гараж; {lot['garage_state']}"
        cur = await db.execute(
            """INSERT INTO garage(
                user_id, car_name, buy_price, repair_cost, repaired, history_type, history_multiplier,
                paparazzi_multiplier, paparazzi_until, origin_country, current_country, current_city,
                repair_count, repaint_count, restoration_stage, originality_score, registered, registered_at,
                abandoned_years, storage_condition, dust_level, recovery_method, water_level,
                cobweb_level, vegetation_level, mold_level, animal_damage, battery_charge, tire_condition, fluid_condition
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                user_id, lot["name"], total_cost, lot["recovery_cost"], 0, lot["history_type"], 0.93, 1.0, None,
                "Россия", "Россия", "Дачный кооператив", 0, 0, 0, 0, 1, now,
                lot["abandoned_years"], storage_label, min(100, 55 + lot["abandoned_years"] * 2), recovery_label, lot["water_level"],
                lot["cobweb_level"], lot["vegetation_level"], lot["mold_level"], lot["animal_damage"],
                lot["battery_charge"], lot["tire_condition"], lot["fluid_condition"],
            )
        )
        car_id = cur.lastrowid
        await db.execute("UPDATE players SET balance = balance - ? WHERE user_id = ?", (total_cost, user_id))
        await db.execute("INSERT INTO vehicle_locations(car_id,country,city,event_at,event_type) VALUES(?,?,?,?,?)", (car_id, "Россия", "Дачный кооператив", now, "dacha_recovery"))
        await db.execute(
            "INSERT INTO vehicle_history(car_id,owner_id,event_type,event_at,amount,details) VALUES(?,?,?,?,?,?)",
            (
                car_id, user_id, "dacha_recovery", now, total_cost,
                f"Найден в заброшенном дачном гараже; простой {lot['abandoned_years']} лет; {lot['garage_state']}; вывоз: {recovery_label}; оформлены новые игровые документы",
            ),
        )
        await db.commit()

    await edit_text_safe(
        call,
        "✅ <b>МАШИНА ДОСТАВЛЕНА В ГАРАЖ!</b>\n\n"
        f"🚗 <b>{lot['name']}</b>\n"
        f"🏚 Простой: <b>{lot['abandoned_years']} лет</b>\n"
        f"{condition_display(lot)}\n"
        f"🚚 Способ вывоза: <b>{'эвакуатор' if method == 'tow' else 'самостоятельно'}</b>\n"
        f"💰 Оформление и вывоз: <b>{total_cost:,} ₽</b>\n"
        f"🔧 Восстановление: около <b>{lot['recovery_cost']:,} ₽</b>\n\n"
        "🪪 Машина получила новые игровые документы и теперь доступна для восстановления и дальнейшей продажи.",
        parse_mode="HTML",
        reply_markup=InlineKeyboardBuilder().button(text="🏠 Гараж", callback_data="garage").as_markup(),
    )
    await safe_callback_answer("🏡 Машина успешно забрана из дачного гаража!")


