@dp.callback_query(F.data.startswith("rare_part:"))
async def rare_part_search(call):
    car_id = int(call.data.split(":", 1)[1])
    row = await get_car_pts(car_id, call.from_user.id)
    if not row:
        await safe_callback_answer("❌ Автомобиль не найден.", show_alert=True); return
    rng = random.Random(f"rarepart:{call.from_user.id}:{car_id}:{datetime.now().strftime('%Y%m%d')}")
    if rng.random() > 0.28:
        await safe_callback_answer("🔎 Сегодня редкую деталь найти не удалось.", show_alert=True); return
    name, ptype, value = rng.choice(RARE_PART_POOL)
    async with aiosqlite.connect(DB) as db:
        await db.execute("INSERT INTO rare_parts(user_id,car_id,part_name,part_type,value,origin_country,discovered_at) VALUES(?,?,?,?,?,?,?)", (call.from_user.id,car_id,name,ptype,value,row["origin_country"],datetime.now().isoformat(timespec="seconds")))
        await db.execute("UPDATE garage SET originality_score = MIN(100, originality_score + 10) WHERE id = ?", (car_id,))
        await db.execute("INSERT INTO vehicle_history(car_id,owner_id,event_type,event_at,amount,details) VALUES(?,?,?,?,?,?)", (car_id,call.from_user.id,"rare_part",datetime.now().isoformat(timespec="seconds"),0,name))
        await db.commit()
    await safe_callback_answer(f"💎 Найдена редкая деталь: {name}!", show_alert=True)
    await restoration_menu(call)


