def concours_day():
    return datetime.now().strftime("%Y-%m-%d")


async def concours_text(day):
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("""SELECT e.id,e.user_id,e.car_id,e.originality,e.votes,g.car_name,p.username\n                               FROM concours_entries e\n                               JOIN garage g ON g.id=e.car_id\n                               LEFT JOIN players p ON p.user_id=e.user_id\n                               WHERE e.day=? ORDER BY e.votes DESC,e.originality DESC,e.id LIMIT 10""", (day,))
        rows = await cur.fetchall()
    text = "👑 <b>CONCOURS D'ELEGANCE</b>\n\n🏆 Конкурс оригинальности и качества реставрации.\n\n"
    if not rows:
        text += "Пока никто не выставился.\n"
    else:
        for i,r in enumerate(rows,1):
            text += f"{i}. 🚗 <b>{r['car_name']}</b> — ❤️ {r['votes']} | ⭐ {r['originality']}%\n"
    return text


