@dp.callback_query(F.data.startswith("concours_vote:"))
async def concours_vote(call):
    entry_id=int(call.data.split(":",1)[1]); day=concours_day(); voter=call.from_user.id
    async with aiosqlite.connect(DB) as db:
        cur=await db.execute("SELECT 1 FROM concours_votes WHERE day=? AND voter_id=?",(day,voter))
