@dp.callback_query(F.data.startswith("seasonal_rank:"))
async def seasonal_rank_category(call):
    metric = call.data.split(":", 1)[1]
    if metric not in SEASONAL_METRICS:
        return await safe_callback_answer(call, "Неизвестная категория рейтинга.", show_alert=True)
    text = await build_seasonal_rating_text(metric)
    # Личная статистика участника показывается отдельно, даже если его нет в топ-10.
    season_key = current_season_key()
    column = SEASONAL_METRICS[metric]["column"]
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute(
            f"SELECT COALESCE({column},0) FROM seasonal_player_stats WHERE season_key=? AND user_id=?",
            (season_key, call.from_user.id),
        )
        mine = await cur.fetchone()
        mine_score = int(mine[0] or 0) if mine else 0
        cur = await db.execute(
            f"SELECT COUNT(*) FROM seasonal_player_stats WHERE season_key=? AND {column} > ?",
            (season_key, mine_score),
        )
        rank = int((await cur.fetchone())[0] or 0) + 1
    unit = SEASONAL_METRICS[metric]["unit"]
    formatted = f"{mine_score:+,} ₽" if metric == "profit" else f"{mine_score:,} {unit}"
    text += f"\n\n👤 <b>Твой результат:</b> {formatted}\n📍 <b>Место:</b> {rank}"
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=seasonal_rating_keyboard(metric))
    await safe_callback_answer(call)


