async def announcements_text(limit=10):
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            "SELECT message, created_at FROM announcements ORDER BY id DESC LIMIT ?",
            (limit,),
        )
        rows = await cur.fetchall()

    if not rows:
        return "📢 <b>ОБЪЯВЛЕНИЯ</b>\n\nПока объявлений нет."

    parts = ["📢 <b>ОБЪЯВЛЕНИЯ</b>", ""]
    for row in rows:
        created = str(row["created_at"] or "")
        try:
            dt = datetime.fromisoformat(created)
            created = dt.strftime("%d.%m.%Y %H:%M")
        except Exception:
            pass
        ann_type = row["announcement_type"] or "news"
        if ann_type == "maintenance":
            title = "🛠 <b>ТЕХНИЧЕСКИЕ РАБОТЫ</b>"
        else:
            title = "📢 <b>ОБЪЯВЛЕНИЕ АДМИНИСТРАЦИИ</b>"
        parts.append(f"{title}\n🕒 <b>{html.escape(created)}</b>\n{html.escape(row['message'] or '')}\n")
    return "\n".join(parts).strip()


