class AnnouncementForm(StatesGroup):
    text = State()


def is_admin(user_id: int) -> bool:
    return int(user_id) in ADMIN_IDS


class BlockedUserMiddleware(BaseMiddleware):
    async def __call__(self, handler, event: TelegramObject, data: dict):
        user = getattr(event, "from_user", None)
        if not user:
            return await handler(event, data)
        if is_admin(user.id):
            return await handler(event, data)
        try:
            async with aiosqlite.connect(DB) as db:
                db.row_factory = aiosqlite.Row
                cur = await db.execute("SELECT blocked, blocked_until FROM players WHERE user_id = ?", (user.id,))
                row = await cur.fetchone()
            if row and row["blocked"]:
                until = row["blocked_until"]
                if until:
                    try:
                        expires = datetime.fromisoformat(until)
                        if datetime.now() >= expires:
                            async with aiosqlite.connect(DB) as db:
                                await db.execute("UPDATE players SET blocked = 0, blocked_until = NULL WHERE user_id = ?", (user.id,))
                                await db.commit()
                        else:
                            await event.answer("🚫 Ты заблокирован в боте до " + expires.strftime("%d.%m.%Y %H:%M"))
                            return
                    except Exception:
                        await event.answer("🚫 Ты заблокирован в боте.")
                        return
                else:
                    await event.answer("🚫 Ты заблокирован в боте.")
                    return
        except Exception:
            pass
        return await handler(event, data)


# Проверяем блокировку до обычных обработчиков.
dp.message.outer_middleware(BlockedUserMiddleware())
dp.callback_query.outer_middleware(BlockedUserMiddleware())


