async def admin_target_text(user_id: int):
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM players WHERE user_id = ?", (user_id,))
        player = await cur.fetchone()
        if not player:
            return "❌ Игрок с таким username не найден."
        cur = await db.execute("SELECT COUNT(*) FROM garage WHERE user_id = ?", (user_id,))
        cars = int((await cur.fetchone())[0] or 0)
        cur = await db.execute("SELECT COUNT(*) FROM player_deals WHERE seller_id = ? OR buyer_id = ?", (user_id, user_id))
        deals = int((await cur.fetchone())[0] or 0)
        cur = await db.execute("SELECT COUNT(*) FROM seller_reviews WHERE seller_id = ?", (user_id,))
        reviews = int((await cur.fetchone())[0] or 0)
        cur = await db.execute("SELECT AVG(rating) FROM seller_reviews WHERE seller_id = ?", (user_id,))
        rating = float((await cur.fetchone())[0] or 0)
    status = "🚫 ЗАБЛОКИРОВАН" if player["blocked"] else "✅ Активен"
    until = ""
    if player["blocked_until"]:
        until = f"\n⏰ До: <b>{player['blocked_until']}</b>"
    username = f"@{html.escape(player['username'])}" if player["username"] else "Без username"
    return (
        f"👤 <b>ИГРОК</b>\n\n"
        f"👤 Username: <b>{username}</b>\n"
        f"💰 Баланс: <b>{int(player['balance'] or 0):,} ₽</b>\n"
        f"🪙 Коины: <b>{int(player['coins'] or 0):,}</b>\n"
        f"⭐ Уровень: <b>{player['level']}</b>\n"
        f"✨ XP: <b>{player['xp']}</b>\n"
        f"🚗 Машин в гараже: <b>{cars}</b>\n"
        f"🤝 Сделок: <b>{deals}</b>\n"
        f"⭐ Репутация: <b>{rating:.1f}/5</b> ({reviews})\n"
        f"📌 Статус: <b>{status}</b>{until}"
    )


