@dp.message(AdminForm.username)
async def admin_user_enter(message: Message, state: FSMContext):
    if not is_admin(message.from_user.id): return
    username = str(message.text or "").strip().lstrip("@").strip()
    if not username or username.isdigit():
        await message.answer("❌ Введи корректный username в формате @username.")
        return
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT user_id FROM players WHERE lower(username)=lower(?) LIMIT 1", (username,))
        row = await cur.fetchone()
    if not row:
        await message.answer("❌ Игрок с таким username не найден. Пусть он запустит бота, чтобы профиль обновился.", reply_markup=admin_keyboard())
        await state.clear()
        return
    user_id = int(row[0])  # Внутренний ключ БД; пользователю он не показывается.
    await state.clear()
    text = await admin_target_text(user_id)
    await message.answer(text, parse_mode="HTML", reply_markup=admin_target_keyboard(user_id) if "не найден" not in text else admin_keyboard())


