@dp.message(AdminForm.amount)
async def admin_amount_enter(message: Message, state: FSMContext):
    if not is_admin(message.from_user.id): return
    try:
        amount = int(message.text.replace(" ", "").replace(",", ""))
        if amount <= 0: raise ValueError
    except ValueError:
        await message.answer("❌ Введи положительное число.")
        return
    data = await state.get_data()
    target = int(data["target_user_id"])
    action = data["action"]
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT user_id, balance FROM players WHERE user_id = ?", (target,))
        row = await cur.fetchone()
        if not row:
            await state.clear(); await message.answer("❌ Игрок не найден."); return
        if action == "give":
            await db.execute("UPDATE players SET balance = balance + ? WHERE user_id = ?", (amount, target))
            action_text = "выдал"
        else:
            await db.execute("UPDATE players SET balance = MAX(0, balance - ?) WHERE user_id = ?", (amount, target))
            action_text = "забрал"
        await db.commit()
    await admin_log(message.from_user.id, action, target, amount)
    await state.clear()
    target_label = html.escape(await get_player_username_label(target))
    await message.answer(f"✅ Админ {action_text} <b>{amount:,} ₽</b> у/игроку <b>{target_label}</b>.", parse_mode="HTML", reply_markup=admin_target_keyboard(target))


