@dp.message(AdminForm.block_days)
async def admin_block_enter(message: Message, state: FSMContext):
    if not is_admin(message.from_user.id): return
    try:
        days = int(message.text.strip())
        if days < 0: raise ValueError
    except ValueError:
        await message.answer("❌ Введи целое число от 0.")
        return
    data = await state.get_data(); target = int(data["target_user_id"])
    until = None if days == 0 else (datetime.now() + timedelta(days=days)).isoformat(timespec="seconds")
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT user_id FROM players WHERE user_id = ?", (target,))
        if not await cur.fetchone():
            await state.clear(); await message.answer("❌ Игрок не найден."); return
        await db.execute("UPDATE players SET blocked = 1, blocked_until = ? WHERE user_id = ?", (until, target))
        await db.commit()
    await admin_log(message.from_user.id, "block", target, details=f"days={days}")
    await state.clear()
    target_label = html.escape(await get_player_username_label(target))
    await message.answer(f"🚫 Игрок <b>{target_label}</b> заблокирован " + ("навсегда." if days == 0 else f"на {days} дн."), parse_mode="HTML", reply_markup=admin_target_keyboard(target))


