@dp.callback_query(F.data == "admin_stats")
async def admin_stats(call):
    if not is_admin(call.from_user.id):
        await safe_callback_answer("⛔", show_alert=True); return
    async with aiosqlite.connect(DB) as db:
        async def q1(sql, params=()):
            cur = await db.execute(sql, params); return (await cur.fetchone())[0] or 0
        players = await q1("SELECT COUNT(*) FROM players")
        cars = await q1("SELECT COUNT(*) FROM garage")
        value = await q1("SELECT COALESCE(SUM(buy_price + repair_cost),0) FROM garage")
        blocked = await q1("SELECT COUNT(*) FROM players WHERE blocked = 1")
        deals = await q1("SELECT COUNT(*) FROM player_deals")
        sales = await q1("SELECT COUNT(*) FROM player_deals WHERE deal_type = 'sale'")
        trades = await q1("SELECT COUNT(*) FROM player_deals WHERE deal_type = 'trade'")
        turnover = await q1("SELECT COALESCE(SUM(amount),0) FROM player_deals WHERE deal_type = 'sale'")
        listings = await q1("SELECT COUNT(*) FROM player_market_listings WHERE status='active'")
        reviews = await q1("SELECT COUNT(*) FROM seller_reviews")
        balance = await q1("SELECT COALESCE(SUM(balance),0) FROM players")
    text = (
        "📊 <b>СТАТИСТИКА БОТА</b>\n\n"
        f"👥 Игроков: <b>{players:,}</b>\n"
        f"🚫 Заблокировано: <b>{blocked:,}</b>\n"
        f"🚗 Машин в гаражах: <b>{cars:,}</b>\n"
        f"💎 Стоимость текущего автопарка: <b>{int(value):,} ₽</b>\n"
        f"💰 Денег на балансах: <b>{int(balance):,} ₽</b>\n\n"
        f"💵 Продаж между игроками: <b>{sales:,}</b>\n"
        f"🤝 Обменов: <b>{trades:,}</b>\n"
        f"📦 Всего сделок: <b>{deals:,}</b>\n"
        f"📈 Оборот P2P-продаж: <b>{int(turnover):,} ₽</b>\n"
        f"📣 Активных объявлений: <b>{listings:,}</b>\n"
        f"⭐ Отзывов: <b>{reviews:,}</b>"
    )
    kb = InlineKeyboardBuilder(); kb.button(text="🔄 Обновить", callback_data="admin_stats"); kb.button(text="🔙 Панель", callback_data="admin_home"); kb.adjust(1)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup()); await safe_callback_answer()


