@dp.message(AnnouncementForm.text)
async def admin_announce_send(message: Message, state: FSMContext):
    if not is_admin(message.from_user.id):
        return

    announcement = (message.text or "").strip()
    if not announcement:
        await message.answer("❌ Сообщение не может быть пустым. Напиши текст ещё раз.")
        return
    if len(announcement) > 4000:
        await message.answer("❌ Слишком длинно. Максимум 4000 символов.")
        return

    data = await state.get_data()
    announcement_type = data.get("announcement_type", "news")

    # Сохраняем объявление до рассылки, чтобы оно осталось в ленте даже при частичных ошибках.
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute(
            "INSERT INTO announcements(admin_id, message, announcement_type) VALUES(?, ?, ?)",
            (message.from_user.id, announcement, announcement_type),
        )
        announcement_id = cur.lastrowid
        cur = await db.execute("SELECT user_id FROM players ORDER BY user_id")
        recipients = [int(row[0]) for row in await cur.fetchall()]

    delivered = 0
    failed = 0
    for user_id in recipients:
        try:
            if announcement_type == "maintenance":
                title = "🛠 <b>ТЕХНИЧЕСКИЕ РАБОТЫ</b>"
                body = (
                    f"{title}\n\n"
                    f"{html.escape(announcement)}\n\n"
                    "Спасибо за понимание!"
                )
            else:
                body = (
                    "📢 <b>ОБЪЯВЛЕНИЕ АДМИНИСТРАЦИИ</b>\n\n"
                    + html.escape(announcement)
                )
            await bot.send_message(
                chat_id=user_id,
                text=body,
                parse_mode="HTML",
            )
            delivered += 1
            await asyncio.sleep(0.05)
        except Exception:
            failed += 1

    async with aiosqlite.connect(DB) as db:
        await db.execute(
            "UPDATE announcements SET delivered = ?, failed = ? WHERE id = ?",
            (delivered, failed, announcement_id),
        )
        await db.commit()

    await admin_log(
        message.from_user.id,
        "maintenance" if announcement_type == "maintenance" else "announcement",
        amount=delivered,
        details=f"id={announcement_id}; failed={failed}; chars={len(announcement)}",
    )
    await state.clear()
    result_title = "🛠 <b>Технические работы отправлены!</b>" if announcement_type == "maintenance" else "✅ <b>Объявление отправлено!</b>"
    await message.answer(
        result_title + "\n\n"
        f"👥 Получили: <b>{delivered}</b>\n"
        f"❌ Не доставлено: <b>{failed}</b>\n"
        f"🆔 Сообщение: <code>#{announcement_id}</code>",
        parse_mode="HTML",
        reply_markup=admin_keyboard(),
    )


@dp.callback_query(F.data == "admin_announcements")
async def admin_announcements(call):
    if not is_admin(call.from_user.id):
        await safe_callback_answer("⛔", show_alert=True)
        return
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            "SELECT a.id, a.admin_id, p.username AS admin_username, a.message, a.announcement_type, a.delivered, a.failed, a.created_at "
            "FROM announcements a LEFT JOIN players p ON p.user_id = a.admin_id ORDER BY a.id DESC LIMIT 15"
        )
        rows = await cur.fetchall()

    text = "📜 <b>ИСТОРИЯ ОБЪЯВЛЕНИЙ</b>\n\n"
    if not rows:
        text += "Объявлений пока нет."
    else:
        for row in rows:
            msg = html.escape((row["message"] or "").replace("\n", " "))
            if len(msg) > 90:
                msg = msg[:90] + "…"
            kind = "🛠 Техработы" if row["announcement_type"] == "maintenance" else "📢 Объявление"
            admin_label = "@" + str(row["admin_username"]) if row["admin_username"] else "Админ без username"
            text += (
                f"<code>#{row['id']}</code> · {kind} · {row['created_at']}\n"
                f"👤 Админ: <b>{html.escape(admin_label)}</b>\n"
                f"📨 {row['delivered']} · ❌ {row['failed']}\n"
                f"📝 {msg}\n\n"
            )

    kb = InlineKeyboardBuilder()
    kb.button(text="📢 Новое объявление", callback_data="admin_announce")
    kb.button(text="🔙 Панель", callback_data="admin_home")
    kb.adjust(1)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer()


@dp.callback_query(F.data == "admin_logs")
async def admin_logs(call):
    if not is_admin(call.from_user.id):
        await safe_callback_answer("⛔", show_alert=True); return
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            "SELECT l.admin_id, ap.username AS admin_username, l.action, l.target_user_id, "
            "tp.username AS target_username, l.amount, l.details, l.created_at "
            "FROM admin_logs l "
            "LEFT JOIN players ap ON ap.user_id = l.admin_id "
            "LEFT JOIN players tp ON tp.user_id = l.target_user_id "
            "ORDER BY l.id DESC LIMIT 25"
        )
        rows = await cur.fetchall()
    text = "📝 <b>ЛОГИ АДМИНОВ</b>\n\n"
    for row in rows:
        extra = f" — {row['amount']:,} ₽" if row['amount'] else ""
        admin_label = "@" + str(row["admin_username"]) if row["admin_username"] else "Админ без username"
        target_label = (" → @" + str(row["target_username"])) if row["target_user_id"] and row["target_username"] else (" → игрок без username" if row["target_user_id"] else "")
        text += f"{html.escape(str(row['created_at']))} | {html.escape(admin_label)} | {html.escape(str(row['action']))}{html.escape(target_label)}{extra}\n"
    if not rows: text += "Логов пока нет."
    kb = InlineKeyboardBuilder(); kb.button(text="🔙 Панель", callback_data="admin_home")
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup()); await safe_callback_answer()



