def _insurance_market_value(template):
    return max(100_000, int((template.get("min", 0) + template.get("max", 0)) / 2))


async def _ensure_car_design(car_id, user_id):
    now = datetime.now().isoformat(timespec="seconds")
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT * FROM garage WHERE id=? AND user_id=?", (car_id, user_id))
        row = await cur.fetchone()
        if not row:
            return None
        await db.execute("""
            INSERT OR IGNORE INTO car_designs(car_id,user_id,updated_at)
            VALUES(?,?,?)
        """, (car_id, user_id, now))
        await db.commit()
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM car_designs WHERE car_id=? AND user_id=?", (car_id, user_id))
        return await cur.fetchone()


