@dp.callback_query(F.data.startswith("insurance:"))
async def insurance_view(call, car_id_override=None):
    if car_id_override is not None:
        car_id = int(car_id_override)
    else:
        parts = call.data.split(":")
        car_id = int(parts[1])
    uid = call.from_user.id
    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM garage WHERE id=? AND user_id=?", (car_id, uid)); car = await cur.fetchone()
        if not car:
            return await safe_callback_answer(call, "❌ Автомобиль не найден.", show_alert=True)
        cur = await db.execute("SELECT * FROM car_insurance WHERE car_id=? AND user_id=?", (car_id, uid)); policy = await cur.fetchone()

    template = get_car_template(car["car_name"], car["buy_price"], car["repair_cost"]) or {}
    market_value = _insurance_market_value(template)

    if policy and int(policy["active"] or 0) and str(policy["expires_at"] or "") >= datetime.now().isoformat():
        info = INSURANCE_POLICIES.get(policy["policy_type"], INSURANCE_POLICIES["osago"])
        text = (
            "🛡 <b>СТРАХОВКА</b>\n\n"
            f"🚗 <b>{html.escape(str(car['car_name']))}</b>\n"
            f"Полис: <b>{info['emoji']} {info['name']}</b>\n"
            f"💳 Премия: <b>{int(policy['monthly_cost']):,} ₽ / 30 дней</b>\n"
            f"💰 Покрытие: <b>{int(policy['coverage']):,} ₽</b>\n"
            f"📅 До: <b>{str(policy['expires_at'])[:10]}</b>\n"
            f"🚨 Страховых случаев: <b>{int(policy['claim_count'] or 0)}</b>\n"
            f"⚠️ Индекс риска: <b>{int(policy['fraud_score'] or 0)}</b>\n\n"
            f"{html.escape(info['desc'])}"
        )
        kb = InlineKeyboardBuilder()
        kb.button(text="📜 Страховая история", callback_data=f"insurance_history:{car_id}")
        kb.button(text="❌ Отменить полис", callback_data=f"insurance_cancel:{car_id}")
        kb.button(text="🔙 К машине", callback_data=f"car:{car_id}")
        kb.adjust(1)
    else:
        text = (
            "🛡 <b>ОФОРМЛЕНИЕ СТРАХОВКИ</b>\n\n"
            f"🚗 <b>{html.escape(str(car['car_name']))}</b>\n"
            f"📊 Расчётная стоимость автомобиля: <b>{market_value:,} ₽</b>\n\n"
            "Выбери полис на 30 дней:\n\n"
        )
        kb = InlineKeyboardBuilder()
        for key, info in INSURANCE_POLICIES.items():
            monthly = max(5_000, int(market_value * info["rate"]))
            coverage = int(market_value * info["coverage"])
            text += f"{info['emoji']} <b>{info['name']}</b> — {monthly:,} ₽ · покрытие {coverage:,} ₽\n{info['desc']}\n\n"
            kb.button(text=f"Оформить {info['name']}", callback_data=f"insurance_buy:{car_id}:{key}")
        kb.button(text="🔙 К машине", callback_data=f"car:{car_id}")
        kb.adjust(1)

    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer(call)


@dp.callback_query(F.data.startswith("insurance_buy:"))
async def insurance_buy(call):
    _, car_id_raw, policy_key = call.data.split(":", 2)
    car_id = int(car_id_raw); uid = call.from_user.id
    info = INSURANCE_POLICIES.get(policy_key)
    if not info:
        return await safe_callback_answer(call, "❌ Такой полис недоступен.", show_alert=True)

    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute("SELECT * FROM garage WHERE id=? AND user_id=?", (car_id, uid)); car = await cur.fetchone()
        if not car:
            return await safe_callback_answer(call, "❌ Автомобиль не найден.", show_alert=True)
        template = get_car_template(car["car_name"], car["buy_price"], car["repair_cost"]) or {}
        market_value = _insurance_market_value(template)
        cost = max(5_000, int(market_value * info["rate"]))
        coverage = int(market_value * info["coverage"])
        cur = await db.execute("SELECT balance FROM players WHERE user_id=?", (uid,)); row = await cur.fetchone()
        balance = int(row[0] or 0) if row else 0
        if balance < cost:
            return await safe_callback_answer(call, f"❌ Нужно {cost:,} ₽.", show_alert=True)

        now = datetime.now()
        expires = now + timedelta(days=30)
        await db.execute("UPDATE car_insurance SET active=0, cancelled_at=? WHERE car_id=? AND user_id=?", (now.isoformat(timespec="seconds"), car_id, uid))
        await db.execute("""
            INSERT INTO car_insurance(car_id,user_id,policy_type,monthly_cost,coverage,started_at,expires_at,claim_count,fraud_score,active)
            VALUES(?,?,?,?,?,?,?,?,?,1)
            ON CONFLICT(car_id) DO UPDATE SET
                user_id=excluded.user_id,
                policy_type=excluded.policy_type,
                monthly_cost=excluded.monthly_cost,
                coverage=excluded.coverage,
                started_at=excluded.started_at,
                expires_at=excluded.expires_at,
                claim_count=0,
                fraud_score=0,
                active=1,
                cancelled_at=NULL
        """, (car_id, uid, policy_key, cost, coverage, now.isoformat(timespec="seconds"), expires.isoformat(timespec="seconds"), 0, 0))
        await db.execute("UPDATE garage SET insurance_active=1 WHERE id=? AND user_id=?", (car_id, uid))
        await db.execute("UPDATE players SET balance=balance-? WHERE user_id=?", (cost, uid))
        await db.execute("""
            INSERT INTO vehicle_history(car_id,owner_id,event_type,event_at,amount,details)
            VALUES(?,?,?,?,?,?)
        """, (car_id, uid, "Страховка", now.isoformat(timespec="seconds"), cost, f"Оформлен полис {info['name']}, покрытие {coverage:,} ₽"))
        await db.commit()

    await safe_callback_answer(call, f"✅ Полис {info['name']} оформлен")
    await insurance_view(call, car_id)


@dp.callback_query(F.data.startswith("insurance_cancel:"))
async def insurance_cancel(call):
    car_id = int(call.data.split(":", 1)[1]); uid = call.from_user.id
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("UPDATE car_insurance SET active=0,cancelled_at=? WHERE car_id=? AND user_id=? AND active=1", (datetime.now().isoformat(timespec="seconds"), car_id, uid))
        await db.execute("UPDATE garage SET insurance_active=0 WHERE id=? AND user_id=?", (car_id, uid))
        await db.commit()
    await safe_callback_answer(call, "❌ Полис отменён")
    await insurance_view(call, car_id)


