def battle_pass_level(xp: int) -> int:
    return min(BP_MAX_LEVEL, max(1, int(xp or 0) // BP_XP_PER_LEVEL + 1))


def battle_pass_level_xp(xp: int) -> int:
    if battle_pass_level(xp) >= BP_MAX_LEVEL:
        return BP_XP_PER_LEVEL
    return int(xp or 0) % BP_XP_PER_LEVEL


def battle_pass_reward_text(rewards):
    parts = []
    for reward in rewards:
        rtype = reward.get("type")
        amount = int(reward.get("amount", 1))
        if rtype == "rub":
            parts.append(f"💰 {amount:,} ₽")
        elif rtype == "currency":
            parts.append(f"🎟 {amount} валюты БП")
        elif rtype == "part":
            parts.append(f"{BP_PARTS.get(reward.get('key'), '🔩 Запчасть')} ×{amount}")
        elif rtype == "event_case":
            parts.append(f"📦 Кейс запчастей Battle Pass ×{amount}")
        elif rtype == "rare_car":
            parts.append(f"🏎 Редкая машина — {BP_RARE_CAR['name']}")
    return " + ".join(parts)


async def bp_ensure_user(user_id):
    async with aiosqlite.connect(DB) as db:
        await db.execute(
            "INSERT OR IGNORE INTO battle_pass_users(user_id, season, xp, currency) VALUES(?,?,0,0)",
            (user_id, BP_SEASON),
        )
        await db.commit()


async def bp_get_user(user_id):
    await bp_ensure_user(user_id)
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute(
            "SELECT xp, currency, premium FROM battle_pass_users WHERE user_id=? AND season=?",
            (user_id, BP_SEASON),
        )
        row = await cur.fetchone()
    xp = int(row[0] or 0) if row else 0
    currency = int(row[1] or 0) if row else 0
    premium = bool(int(row[2] or 0)) if row else False
    return {"xp": xp, "currency": currency, "premium": premium, "level": battle_pass_level(xp)}


async def bp_task_metrics(user_id):
    async with aiosqlite.connect(DB) as db:
        queries = {
            "jobs": ("SELECT COALESCE(jobs_count,0) FROM vehicle_services WHERE user_id=?", (user_id,)),
            "garage": ("SELECT COUNT(*) FROM garage WHERE user_id=?", (user_id,)),
            "repairs": ("SELECT COUNT(*) FROM maintenance_history WHERE user_id=?", (user_id,)),
            "parts": ("SELECT COALESCE(SUM(quantity),0) FROM player_parts WHERE user_id=?", (user_id,)),
            "inspections": ("SELECT COUNT(*) FROM inspections WHERE user_id=?", (user_id,)),
            "plates": ("SELECT COUNT(*) FROM plates WHERE user_id=?", (user_id,)),
            "museum_visits": ("SELECT COUNT(*) FROM museum_visits WHERE visitor_id=?", (user_id,)),
            "exhibitions": ("SELECT COUNT(*) FROM exhibition_entries WHERE user_id=?", (user_id,)),
            "market_listings": ("SELECT COUNT(*) FROM player_market_listings WHERE seller_id=?", (user_id,)),
            "deals": ("SELECT COUNT(*) FROM player_deals WHERE seller_id=? OR buyer_id=?", (user_id, user_id)),
            "garage_value": ("SELECT COALESCE(SUM(COALESCE(buy_price,0)),0) FROM garage WHERE user_id=?", (user_id,)),
            "registered": ("SELECT COUNT(*) FROM garage WHERE user_id=? AND registered=1", (user_id,)),
        }
        result = {}
        for key, (query, params) in queries.items():
            cur = await db.execute(query, params)
            row = await cur.fetchone()
            result[key] = int(row[0] or 0) if row else 0
    return result


async def bp_sync_tasks(user_id, notify=True):
    await bp_ensure_user(user_id)
    metrics = await bp_task_metrics(user_id)
    completed_now = []
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute(
            "SELECT task_key FROM battle_pass_task_claims WHERE user_id=? AND season=?",
            (user_id, BP_SEASON),
        )
        already = {str(row[0]) for row in await cur.fetchall()}
        total_xp = 0
        for task in BATTLE_PASS_TASKS:
            if int(metrics.get(task["metric"], 0)) >= int(task["target"]) and task["key"] not in already:
                await db.execute(
                    "INSERT INTO battle_pass_task_claims(user_id,season,task_key) VALUES(?,?,?)",
                    (user_id, BP_SEASON, task["key"]),
                )
                total_xp += int(task["xp"])
                completed_now.append(task)
        if total_xp:
            await db.execute(
                "UPDATE battle_pass_users SET xp=xp+?, updated_at=CURRENT_TIMESTAMP WHERE user_id=? AND season=?",
                (total_xp, user_id, BP_SEASON),
            )
        await db.commit()

    if notify and completed_now:
        names = "\n".join(f"✅ {task['title']} — +{task['xp']} XP" for task in completed_now)
        try:
            await bot.send_message(
                user_id,
                f"🎫 <b>BATTLE PASS</b>\n\n{names}\n\n✨ Опыт БП автоматически начислен.",
                parse_mode="HTML",
            )
        except Exception:
            pass
    return completed_now


async def bp_claim_level(user_id, level, track="free"):
    rewards_map = BATTLE_PASS_REWARDS if track == "free" else BATTLE_PASS_PREMIUM_REWARDS
    if not isinstance(level, int) or level not in rewards_map:
        return False, "❌ Награда не найдена."

    bp = await bp_get_user(user_id)
    if bp["level"] < level:
        return False, "🔒 Этот уровень ещё не открыт."
    if track == "premium" and not bp["premium"]:
        return False, f"👑 Premium БП не активирован. Купи его за {BP_PREMIUM_PRICE_STARS} ⭐."

    claim_table = "battle_pass_claims" if track == "free" else "battle_pass_premium_claims"
    async with aiosqlite.connect(DB) as db:
        await db.execute("BEGIN IMMEDIATE")
        cur = await db.execute(
            f"INSERT OR IGNORE INTO {claim_table}(user_id,season,level) VALUES(?,?,?)",
            (user_id, BP_SEASON, level),
        )
        if cur.rowcount == 0:
            await db.rollback()
            return False, "ℹ️ Эта награда уже получена."

        granted = []
        for reward in rewards_map[level]:
            rtype = reward.get("type")
            amount = int(reward.get("amount", 1))
            if rtype == "rub":
                await db.execute("UPDATE players SET balance=balance+? WHERE user_id=?", (amount, user_id))
                granted.append(f"💰 +{amount:,} ₽")
            elif rtype == "currency":
                await db.execute(
                    "UPDATE battle_pass_users SET currency=currency+?, updated_at=CURRENT_TIMESTAMP WHERE user_id=? AND season=?",
                    (amount, user_id, BP_SEASON),
                )
                granted.append(f"🎟 +{amount} валюты БП")
            elif rtype == "part":
                key = reward["key"]
                await db.execute(
                    """
                    INSERT INTO player_parts(user_id,part_key,part_name,quantity)
                    VALUES(?,?,?,?)
                    ON CONFLICT(user_id,part_key)
                    DO UPDATE SET quantity=quantity+excluded.quantity, updated_at=CURRENT_TIMESTAMP
                    """,
                    (user_id, key, BP_PARTS[key], amount),
                )
                granted.append(f"{BP_PARTS[key]} ×{amount}")
            elif rtype == "event_case":
                await db.execute(
                    """
                    INSERT INTO battle_pass_inventory(user_id,item_key,quantity)
                    VALUES(?,?,?)
                    ON CONFLICT(user_id,item_key)
                    DO UPDATE SET quantity=quantity+excluded.quantity, updated_at=CURRENT_TIMESTAMP
                    """,
                    (user_id, "bp_parts_case", amount),
                )
                granted.append(f"📦 Кейс запчастей Battle Pass ×{amount}")
            elif rtype == "rare_car":
                car = BP_RARE_CAR
                await db.execute(
                    """
                    INSERT INTO garage(
                        user_id,car_name,buy_price,repair_cost,repaired,
                        history_type,history_multiplier,original_buy_price,owner_count,
                        origin_country,current_country,current_city,purchased_at,original_purchased_at
                    ) VALUES(?,?,?,?,0,?,?,?,?,?,?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
                    """,
                    (user_id, car["name"], car["price"], car["repair"], "battle_pass_premium",
                     car["history_multiplier"], car["price"], 1, car["origin_country"],
                     car["current_country"], car["current_city"]),
                )
                granted.append(f"🏎 {car['name']}")

        await db.commit()
    return True, " + ".join(granted) if granted else "✅ Награда получена."


async def bp_is_premium(user_id):
    bp = await bp_get_user(user_id)
    return bool(bp.get("premium"))


async def bp_create_premium_invoice(user_id):
    await bp_ensure_user(user_id)
    bp = await bp_get_user(user_id)
    if bp["premium"]:
        return False, "👑 Premium БП уже активирован в этом сезоне."

    payload = f"bp_premium:{BP_SEASON}:{user_id}"
    await bot.send_invoice(
        chat_id=user_id,
        title="👑 Premium Battle Pass",
        description=f"Открывает премиум-трек наград сезона «{BP_SEASON_NAME}». Цена: {BP_PREMIUM_PRICE_STARS} Stars.",
        payload=payload,
        currency="XTR",
        prices=[LabeledPrice(label="Premium Battle Pass", amount=BP_PREMIUM_PRICE_STARS)],
        provider_token="",
    )
    return True, f"👑 Счёт на {BP_PREMIUM_PRICE_STARS} ⭐ отправлен."


async def bp_activate_premium_from_payment(user_id, payment):
    payload = str(payment.invoice_payload or "")
    parts = payload.split(":")
    if len(parts) != 3 or parts[0] != "bp_premium" or parts[1] != BP_SEASON:
        return False, "❌ Неверный платёжный payload.", False
    try:
        payload_user_id = int(parts[2])
    except ValueError:
        return False, "❌ Неверный пользователь в payload.", False
    if payload_user_id != user_id:
        return False, "❌ Платёж принадлежит другому пользователю.", False
    if str(payment.currency) != "XTR":
        return False, "❌ Ожидались Telegram Stars.", False
    if int(payment.total_amount or 0) != BP_PREMIUM_PRICE_STARS:
        return False, "❌ Неверная сумма платежа.", False

    charge_id = str(payment.telegram_payment_charge_id or "")
    if not charge_id:
        return False, "❌ Не найден ID платежа.", False

    async with aiosqlite.connect(DB) as db:
        cur = await db.execute(
            "SELECT 1 FROM battle_pass_payments WHERE telegram_payment_charge_id=?",
            (charge_id,),
        )
        if await cur.fetchone():
            return True, "✅ Этот платёж уже обработан.", False

        cur = await db.execute(
            "SELECT premium FROM battle_pass_users WHERE user_id=? AND season=?",
            (user_id, BP_SEASON),
        )
        row = await cur.fetchone()
        already_premium = bool(row and int(row[0] or 0))

        await db.execute(
            """
            INSERT INTO battle_pass_payments(telegram_payment_charge_id,user_id,season,stars_amount,payload)
            VALUES(?,?,?,?,?)
            """,
            (charge_id, user_id, BP_SEASON, int(payment.total_amount), payload),
        )

        if not already_premium:
            await db.execute(
                """
                UPDATE battle_pass_users
                SET premium=1,
                    premium_purchased_at=CURRENT_TIMESTAMP,
                    premium_charge_id=?,
                    updated_at=CURRENT_TIMESTAMP
                WHERE user_id=? AND season=?
                """,
                (charge_id, user_id, BP_SEASON),
            )

        await db.commit()

    if already_premium:
        try:
            await bot.refund_star_payment(
                user_id=user_id,
                telegram_payment_charge_id=charge_id,
            )
        except Exception as exc:
            print(f"⚠️ Не удалось автоматически вернуть повторную оплату Premium БП: {exc}")
        return True, "ℹ️ Premium уже был активирован. Повторная оплата возвращена.", True

    return True, "👑 Premium Battle Pass активирован! Теперь доступны премиум-награды всех достигнутых уровней.", False


async def bp_shop_purchase(user_id, item_key):
    """Безопасная покупка товара сезонного магазина за валюту БП."""
    item = BATTLE_PASS_SHOP.get(item_key)
    if not item:
        return False, "❌ Товар не найден. Обнови каталог магазина."

    await bp_ensure_user(user_id)
    price = int(item["price"])
    amount = int(item.get("amount", 1))
    kind = item.get("kind")

    async with aiosqlite.connect(DB) as db:
        db.row_factory = aiosqlite.Row
        await db.execute("BEGIN IMMEDIATE")
        cur = await db.execute(
            "SELECT currency, xp FROM battle_pass_users WHERE user_id=? AND season=?",
            (user_id, BP_SEASON),
        )
        user_row = await cur.fetchone()
        if not user_row:
            await db.rollback()
            return False, "❌ Не удалось загрузить профиль Battle Pass. Попробуй ещё раз."

        currency = int(user_row["currency"] or 0)
        xp = int(user_row["xp"] or 0)
        cur = await db.execute(
            "SELECT quantity FROM battle_pass_shop_purchases WHERE user_id=? AND season=? AND item_key=?",
            (user_id, BP_SEASON, item_key),
        )
        bought_row = await cur.fetchone()
        bought = int(bought_row["quantity"] or 0) if bought_row else 0
        limit = item.get("max_per_season")

        if limit is not None and bought >= int(limit):
            await db.rollback()
            return False, f"✅ Лимит достигнут: этот товар можно купить не более {int(limit)} раз за сезон."
        if kind == "bp_xp" and battle_pass_level(xp) >= BP_MAX_LEVEL:
            await db.rollback()
            return False, "🏆 Ты уже достиг максимального уровня. Буст XP сейчас не нужен."
        if currency < price:
            await db.rollback()
            return False, f"❌ Не хватает {price - currency} 🎟 валюты БП. Сейчас у тебя {currency} 🎟."

        await db.execute(
            "UPDATE battle_pass_users SET currency=currency-?, updated_at=CURRENT_TIMESTAMP WHERE user_id=? AND season=?",
            (price, user_id, BP_SEASON),
        )

        if kind == "part":
            part_key = item["part_key"]
            await db.execute(
                """
                INSERT INTO player_parts(user_id,part_key,part_name,quantity)
                VALUES(?,?,?,?)
                ON CONFLICT(user_id,part_key)
                DO UPDATE SET quantity=quantity+excluded.quantity, updated_at=CURRENT_TIMESTAMP
                """,
                (user_id, part_key, BP_PARTS[part_key], amount),
            )
        elif kind == "mixed_parts":
            received = []
            for _ in range(amount):
                part_key = random.choice(list(BP_PARTS.keys()))
                received.append(BP_PARTS[part_key])
                await db.execute(
                    """
                    INSERT INTO player_parts(user_id,part_key,part_name,quantity)
                    VALUES(?,?,?,1)
                    ON CONFLICT(user_id,part_key)
                    DO UPDATE SET quantity=quantity+1, updated_at=CURRENT_TIMESTAMP
                    """,
                    (user_id, part_key, BP_PARTS[part_key]),
                )
        elif kind == "rub":
            await db.execute("UPDATE players SET balance=balance+? WHERE user_id=?", (amount, user_id))
        elif kind == "event_case":
            await db.execute(
                """
                INSERT INTO battle_pass_inventory(user_id,item_key,quantity)
                VALUES(?,?,?)
                ON CONFLICT(user_id,item_key)
                DO UPDATE SET quantity=quantity+excluded.quantity, updated_at=CURRENT_TIMESTAMP
                """,
                (user_id, "bp_parts_case", amount),
            )
        elif kind == "rare_car":
            car = BP_RARE_CAR
            await db.execute(
                """
                INSERT INTO garage(
                    user_id,car_name,buy_price,repair_cost,repaired,
                    history_type,history_multiplier,original_buy_price,owner_count,
                    origin_country,current_country,current_city,purchased_at,original_purchased_at
                ) VALUES(?,?,?,?,0,?,?,?,?,?,?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
                """,
                (user_id, car["name"], car["price"], car["repair"], "battle_pass_shop",
                 car["history_multiplier"], car["price"], 1, car["origin_country"],
                 car["current_country"], car["current_city"]),
            )
        elif kind == "bp_xp":
            await db.execute(
                "UPDATE battle_pass_users SET xp=xp+?, updated_at=CURRENT_TIMESTAMP WHERE user_id=? AND season=?",
                (amount, user_id, BP_SEASON),
            )
        else:
            await db.rollback()
            return False, "❌ Этот тип товара пока не поддерживается. Валюта не списана."

        await db.execute(
            """
            INSERT INTO battle_pass_shop_purchases(user_id,season,item_key,quantity)
            VALUES(?,?,?,1)
            ON CONFLICT(user_id,season,item_key)
            DO UPDATE SET quantity=quantity+1, updated_at=CURRENT_TIMESTAMP
            """,
            (user_id, BP_SEASON, item_key),
        )
        await db.commit()

    if kind == "rare_car":
        return True, f"🏎 Получен автомобиль <b>{html.escape(BP_RARE_CAR['name'])}</b>! Он уже в твоём гараже."
    if kind == "bp_xp":
        return True, f"⚡ Начислено +{amount:,} XP Battle Pass."
    if kind == "rub":
        return True, f"💰 На баланс начислено {amount:,} ₽."
    if kind == "event_case":
        return True, f"📦 В инвентарь добавлено кейсов: {amount}."
    if kind == "mixed_parts":
        return True, f"🔩 Получено {amount} случайных запчасти. Проверь инвентарь запчастей."
    return True, f"✅ Куплено: {html.escape(item['name'])}."


async def bp_claimed_levels(user_id, track="free"):
    table = "battle_pass_claims" if track == "free" else "battle_pass_premium_claims"
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute(
            f"SELECT level FROM {table} WHERE user_id=? AND season=?",
            (user_id, BP_SEASON),
        )
        return {int(row[0]) for row in await cur.fetchall()}


async def bp_inventory_snapshot(user_id):
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute(
            "SELECT item_key, quantity FROM battle_pass_inventory WHERE user_id=? AND quantity>0 ORDER BY item_key",
            (user_id,),
        )
        inventory = {str(row[0]): int(row[1] or 0) for row in await cur.fetchall()}
    # Legacy case rewards from earlier builds remain usable after upgrading.
    legacy_count = inventory.pop("future_event_parts_case", 0)
    if legacy_count:
        inventory["bp_parts_case"] = inventory.get("bp_parts_case", 0) + legacy_count
    return inventory



def bp_progress_bar(current: int, total: int, length: int = 12) -> str:
    total = max(1, int(total))
    current = max(0, min(int(current), total))
    filled = round((current / total) * length)
    return "🟩" * filled + "⬜" * (length - filled)


def bp_level_status(level: int, current_level: int, claimed: set[int]) -> str:
    if level in claimed:
        return "✅"
    if level < current_level:
        return "🎁"
    if level == current_level:
        return "⭐"
    return "🔒"


def bp_next_reward_line(rewards, premium=False):
    prefix = "👑" if premium else "🆓"
    return f"{prefix} {battle_pass_reward_text(rewards)}"


