def bp_rewards_keyboard(page, bp_level, claimed_free, claimed_premium, premium):
    page_size = 3
    pages = max(1, (BP_MAX_LEVEL + page_size - 1) // page_size)
    page = max(0, min(page, pages - 1))
    start = page * page_size + 1
    end = min(BP_MAX_LEVEL, start + page_size - 1)

    kb = InlineKeyboardBuilder()
    for level in range(start, end + 1):
        free_claimed = level in claimed_free
        free_locked = level > bp_level
        premium_claimed = level in claimed_premium
        if free_claimed and (not premium or premium_claimed):
            icon = "✅"
        elif free_locked:
            icon = "🔒"
        elif level == bp_level:
            icon = "⭐"
        else:
            icon = "🎁"
        kb.button(text=f"{icon} 🖼 Уровень {level:02d}", callback_data=f"bp_view:{level}")

    if page > 0:
        kb.button(text="◀️ Назад", callback_data=f"bp_rewards:{page-1}")
    kb.button(text=f"📄 {page+1}/{pages}", callback_data="bp_home")
    if page < pages - 1:
        kb.button(text="Вперёд ▶️", callback_data=f"bp_rewards:{page+1}")

    kb.button(text="🎁 Забрать доступные", callback_data="bp_claim_all")
    kb.button(text="📊 Список уровней", callback_data="bp_levels:0")
    kb.button(text="📋 Задания", callback_data="bp_tasks:0")
    kb.button(text="🛍 Магазин", callback_data="bp_shop")
    kb.button(text="🏠 Battle Pass", callback_data="bp_home")
    kb.adjust(1, 1, 1, 3, 1, 2, 1, 1)
    return kb.as_markup()


