def bp_shop_items(category="featured"):
    """Каталог товаров в стабильном порядке, без обращения к БД."""
    if category not in BP_SHOP_CATEGORIES:
        category = "featured"
    entries = []
    for key, item in BATTLE_PASS_SHOP.items():
        if category == "featured":
            if item.get("featured"):
                entries.append((key, item))
        elif item.get("category") == category:
            entries.append((key, item))
    return entries


def bp_shop_keyboard(category="featured", page=0):
    if category not in BP_SHOP_CATEGORIES:
        category = "featured"
    items = bp_shop_items(category)
    pages = max(1, (len(items) + BP_SHOP_PAGE_SIZE - 1) // BP_SHOP_PAGE_SIZE)
    page = max(0, min(int(page), pages - 1))
    start = page * BP_SHOP_PAGE_SIZE
    visible = items[start:start + BP_SHOP_PAGE_SIZE]

    kb = InlineKeyboardBuilder()
    for key, label in [
        ("featured", "🔥 Главное"), ("parts", "🔧 Запчасти"),
        ("money", "💰 Деньги"), ("cases", "📦 Кейсы"),
        ("cars", "🏎 Авто"), ("boosts", "⚡ Бустеры"),
    ]:
        prefix = "• " if category == key else ""
        kb.button(text=f"{prefix}{label}", callback_data=f"bp_shop_cat:{key}")

    for key, item in visible:
        kb.button(
            text=f"{item.get('emoji', '🎁')} {item['short_name']} · {item['price']} 🎟",
            callback_data=f"bp_shop_item:{key}",
        )

    if page > 0:
        kb.button(text="◀️ Назад", callback_data=f"bp_shop_cat:{category}:{page-1}")
    kb.button(text=f"📄 {page+1}/{pages}", callback_data=f"bp_shop_cat:{category}:{page}")
    if page < pages - 1:
        kb.button(text="Вперёд ▶️", callback_data=f"bp_shop_cat:{category}:{page+1}")
    kb.button(text="🎒 Инвентарь", callback_data="bp_inventory")
    kb.button(text="🎫 Battle Pass", callback_data="bp_home")
    kb.button(text="🏠 Главное меню", callback_data="menu")
    kb.adjust(2, 2, 2, 1, 1, 1, 1, 2, 2)
    return kb.as_markup()


async def bp_shop_item_text(user_id, item_key):
    item = BATTLE_PASS_SHOP.get(item_key)
    if not item:
        return "❌ Товар не найден. Открой каталог магазина заново."
    bp = await bp_get_user(user_id)
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute(
            "SELECT quantity FROM battle_pass_shop_purchases WHERE user_id=? AND season=? AND item_key=?",
            (user_id, BP_SEASON, item_key),
        )
        row = await cur.fetchone()
    bought = int(row[0] or 0) if row else 0
    limit = item.get("max_per_season")
    stock_line = f"Покупок за сезон: <b>{bought}/{int(limit)}</b>" if limit is not None else f"Покупок за сезон: <b>{bought}</b> · без ограничения"
    if limit is not None and bought >= int(limit):
        availability = "✅ <b>Лимит покупок исчерпан</b>"
    elif item.get("kind") == "bp_xp" and bp["level"] >= BP_MAX_LEVEL:
        availability = "🏆 <b>Максимальный уровень уже получен</b>"
    elif bp["currency"] >= int(item["price"]):
        availability = "🟢 <b>Можно купить</b>"
    else:
        availability = f"🔒 Не хватает <b>{int(item['price']) - bp['currency']} 🎟</b>"

    return (
        f"🛍 <b>МАГАЗИН BATTLE PASS</b>\n"
        f"━━━━━━━━━━━━━━━━━━\n\n"
        f"{item.get('emoji', '🎁')} <b>{html.escape(item['name'])}</b>\n\n"
        f"{html.escape(item['description'])}\n\n"
        f"💳 Стоимость: <b>{int(item['price'])} 🎟</b>\n"
        f"👛 Твой баланс: <b>{bp['currency']} 🎟</b>\n"
        f"{stock_line}\n\n"
        f"{availability}\n\n"
        "Нажми «Купить» для обмена валюты Battle Pass. До списания ты всегда видишь цену, баланс и лимит."
    )


def bp_shop_item_keyboard(item_key, purchased_count=0, level=1):
    item = BATTLE_PASS_SHOP.get(item_key)
