async def clan_home_text(user_id: int):
    await clan_resolve_expired_wars()
    clan = await clan_get_info(user_id)
    if not clan:
        async with aiosqlite.connect(DB) as db:
            cur = await db.execute("SELECT COUNT(*) FROM clans")
            clan_count = int((await cur.fetchone())[0] or 0)
        return (
            "🛡 <b>КЛАНЫ АВТОПЕРЕКУПА</b>\n"
            "━━━━━━━━━━━━━━━━━━\n\n"
            "Объединяйся с игроками, выполняй общие задания, пополняй казну "
            "и открывай клановые кейсы. Вызывай другие кланы на войну за "
            "супер-эксклюзивные автомобили.\n\n"
            f"👥 Создано кланов: <b>{clan_count}</b>\n"
            f"💳 Создание клана: <b>{CLAN_CREATE_COST:,} ₽</b>\n"
            + f"👤 Максимум участников: <b>{CLAN_MAX_MEMBERS}</b>\n"
            "⚔️ Длительность войны: <b>30 минут</b>\n"
            "🎁 Клановый кейс оплачивается из общей казны."
        )

    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT COUNT(*) FROM clan_members WHERE clan_id = ?", (clan["id"],))
        members = int((await cur.fetchone())[0] or 0)
        cur = await db.execute("SELECT COUNT(*) FROM clan_tasks WHERE clan_id=? AND task_date=? AND progress>=target AND claimed=0", (clan["id"], utcnow_naive().strftime("%Y-%m-%d")))
        ready_tasks = int((await cur.fetchone())[0] or 0)
        cur = await db.execute("SELECT COUNT(*) FROM clan_wars WHERE status IN ('pending','active') AND (challenger_clan_id=? OR opponent_clan_id=?)", (clan["id"], clan["id"]))
        wars = int((await cur.fetchone())[0] or 0)
    role_text = "👑 Глава" if clan["role"] == "leader" else "👤 Участник"
    level = clan["xp"] // 1000 + 1
    return (
        f"🛡 <b>КЛАН [{html.escape(clan['tag'])}] {html.escape(clan['name'])}</b>\n"
        "━━━━━━━━━━━━━━━━━━\n\n"
        f"{role_text}\n"
        f"👥 Участники: <b>{members}/{CLAN_MAX_MEMBERS}</b>\n"
        f"💰 Казна: <b>{clan['treasury']:,} ₽</b>\n"
        + f"⭐ Уровень клана: <b>{level}</b> · XP: <b>{clan['xp']:,}</b>\n"
        + f"📋 Заданий готово к награде: <b>{ready_tasks}</b>\n"
        + f"⚔️ Активных вызовов/войн: <b>{wars}</b>\n\n"
        + f"🎁 Клановый кейс стоит <b>{CLAN_CASE_COST:,} ₽</b> из казны.\n"
        + "🏁 Войны длятся 30 минут. Победивший клан получает супер-эксклюзивный автомобиль одному из бойцов, участвовавших в войне."
    )


