@dp.message(ClanCreateForm.waiting_name)
async def clan_create_name(message: Message, state: FSMContext):
    name = " ".join((message.text or "").split()).strip()
    if not 3 <= len(name) <= 24:
        await message.answer("❌ Название должно содержать от 3 до 24 символов. Попробуй ещё раз.")
        return
    if any(ord(ch) < 32 for ch in name):
        await message.answer("❌ В названии есть недопустимые символы. Попробуй ещё раз.")
        return

    user_id = int(message.from_user.id)
    await create_player(user_id, message.from_user.username)
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT clan_id FROM clan_members WHERE user_id=?", (user_id,))
        if await cur.fetchone():
            await state.clear()
            await message.answer("❌ Ты уже состоишь в клане.")
            return
        cur = await db.execute("SELECT balance FROM players WHERE user_id=?", (user_id,))
        player = await cur.fetchone()
        if not player or int(player[0] or 0) < CLAN_CREATE_COST:
            await state.clear()
            await message.answer(f"❌ Нужно {CLAN_CREATE_COST:,} ₽ для создания клана.")
            return
        cur = await db.execute("SELECT 1 FROM clans WHERE name=? COLLATE NOCASE", (name,))
        if await cur.fetchone():
            await message.answer("❌ Клан с таким названием уже существует. Придумай другое.")
            return
        cur = await db.execute("UPDATE players SET balance=balance-? WHERE user_id=? AND balance>=?", (CLAN_CREATE_COST, user_id, CLAN_CREATE_COST))
        if cur.rowcount != 1:
            await state.clear()
            await message.answer("❌ Не удалось списать деньги. Проверь баланс и попробуй снова.")
            return
        await db.execute("INSERT INTO clans(name, tag, leader_id, treasury, xp) VALUES(?, 'TEMP', ?, 0, 0)", (name, user_id))
        clan_id = int((await (await db.execute("SELECT last_insert_rowid()")).fetchone())[0])
        tag = f"CL{clan_id:04d}"
        await db.execute("UPDATE clans SET tag=? WHERE id=?", (tag, clan_id))
        await db.execute("INSERT INTO clan_members(user_id, clan_id, role) VALUES(?, ?, 'leader')", (user_id, clan_id))
        await clan_ensure_daily_tasks(db, clan_id)
        await db.commit()
    await state.clear()
    await message.answer(
        f"✅ Клан <b>[{html.escape(tag)}] {html.escape(name)}</b> создан!\n"
        f"💸 Потрачено: <b>{CLAN_CREATE_COST:,} ₽</b>\n"
        "Приглашай игроков, выполняй задания и копи казну на клановые кейсы.",
        parse_mode="HTML", reply_markup=clan_main_keyboard(),
    )


@dp.callback_query(F.data == "clan_join_list")
async def clan_join_list(call):
    await create_player(call.from_user.id, call.from_user.username)
    if await clan_get_info(call.from_user.id):
        await safe_callback_answer(call, "Ты уже состоишь в клане.", show_alert=True)
        return
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("""
            SELECT c.id, c.name, c.tag, c.xp, COUNT(m.user_id)
            FROM clans c LEFT JOIN clan_members m ON m.clan_id=c.id
            GROUP BY c.id ORDER BY c.xp DESC, c.id DESC LIMIT 30
        """)
        rows = await cur.fetchall()
    kb = InlineKeyboardBuilder()
    for clan_id, name, tag, xp, members in rows:
        if int(members or 0) >= CLAN_MAX_MEMBERS:
            continue
        label = f"[{tag}] {name} · {members}/{CLAN_MAX_MEMBERS}"
        kb.button(text=label[:60], callback_data=f"clan_join:{int(clan_id)}")
    kb.button(text="🔙 Назад", callback_data="clan_home")
    kb.adjust(1)
    text = "🔎 <b>СПИСОК КЛАНОВ</b>\n\nВыбери клан, в который хочешь вступить."
    if not rows:
        text += "\n\nПока нет ни одного клана — создай первый!"
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer(call)


