async def clan_tasks_screen(user_id: int):
    clan = await clan_get_info(user_id)
    if not clan:
        return None, []
    async with aiosqlite.connect(DB) as db:
        await clan_ensure_daily_tasks(db, clan["id"])
        await db.commit()
        cur = await db.execute("""
            SELECT id, task_key, title, description, target, progress,
                   reward_money, reward_xp, claimed
            FROM clan_tasks WHERE clan_id=? AND task_date=? ORDER BY id
        """, (clan["id"], utcnow_naive().strftime("%Y-%m-%d")))
        rows = await cur.fetchall()
    lines = ["📋 <b>ЕЖЕДНЕВНЫЕ КЛАНОВЫЕ ЗАДАНИЯ</b>", ""]
    for task_id, key, title, description, target, progress, reward_money, reward_xp, claimed in rows:
        target = int(target or 0)
        progress = min(target, int(progress or 0))
        bar_count = 10 if not target else min(10, int(progress / target * 10))
        bar = "🟩" * bar_count + "⬜" * (10 - bar_count)
        if claimed:
            status = "✅ Награда получена"
        elif progress >= target:
            status = "🎁 Можно забрать награду"
        else:
            status = "⏳ Выполняется"
        lines.append(
            f"<b>{html.escape(title)}</b>\n{html.escape(description)}\n"
            f"{bar} <b>{progress:,}/{target:,}</b>\n"
            + f"🎁 Награда: {int(reward_money):,} ₽ и {int(reward_xp)} XP\n"
            + f"{status}\n"
        )
    lines.append("\nПрогресс общий для всех участников. Задания обновляются ежедневно по UTC.")
    return "\n".join(lines), rows


def clan_tasks_keyboard(rows):
    kb = InlineKeyboardBuilder()
    for row in rows:
        task_id, key, title, description, target, progress, reward_money, reward_xp, claimed = row
        if not int(claimed or 0) and int(progress or 0) >= int(target or 0):
            kb.button(text=f"🎁 Забрать награду #{task_id}", callback_data=f"clan_task_claim:{int(task_id)}")
    kb.button(text="🔙 В клан", callback_data="clan_home")
    kb.adjust(1)
    return kb.as_markup()


