        value = pmarket_market_price(
            car["car_name"], car["buy_price"], car["repair_cost"], car["repaired"], car["history_multiplier"],
            car["build_engine"], car["build_gearbox"], car["build_turbo"], car["mileage"], car["condition"],
            car["build_body"], car["build_suspension"], car["build_interior"], car["build_paint"], 1,
        )
        vehicle_snapshot = json.dumps(dict(car), ensure_ascii=False, default=str)
        cur = await db.execute("SELECT username FROM players WHERE user_id=?", (uid,))
