@dp.callback_query(F.data == "clan_leave")
async def clan_leave_callback(call):
    user_id = int(call.from_user.id)
    clan = await clan_get_info(user_id)
    if not clan:
        await safe_callback_answer(call, "Ты не состоишь в клане.", show_alert=True)
        return
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT user_id, role, joined_at FROM clan_members WHERE clan_id=? ORDER BY joined_at", (clan["id"],))
        members = await cur.fetchall()
        others = [row for row in members if int(row[0]) != user_id]
        if clan["role"] == "leader" and others:
            new_leader = int(others[0][0])
            await db.execute("UPDATE clan_members SET role='member' WHERE user_id=?", (new_leader,))
            await db.execute("UPDATE clan_members SET role='leader' WHERE user_id=?", (new_leader,))
            await db.execute("UPDATE clans SET leader_id=? WHERE id=?", (new_leader, clan["id"]))
        await db.execute("DELETE FROM clan_members WHERE user_id=?", (user_id,))
        if not others:
            await db.execute("DELETE FROM clan_tasks WHERE clan_id=?", (clan["id"],))
            await db.execute("DELETE FROM clan_war_participants WHERE clan_id=?", (clan["id"],))
            await db.execute("UPDATE clan_wars SET status='cancelled', finished_at=CURRENT_TIMESTAMP WHERE status IN ('pending','active') AND (challenger_clan_id=? OR opponent_clan_id=?)", (clan["id"], clan["id"]))
            await db.execute("DELETE FROM clans WHERE id=?", (clan["id"],))
        await db.commit()
    await edit_text_safe(call, "✅ Ты покинул клан.", reply_markup=clan_lobby_keyboard())
    await safe_callback_answer(call)


async def clan_resolve_expired_wars():
    """Завершает истёкшие войны и выдаёт машину одному из участвовавших бойцов победителя."""
    now = utcnow_naive().strftime("%Y-%m-%d %H:%M:%S")
    async with aiosqlite.connect(DB) as db:
        await db.execute("UPDATE clan_wars SET status='expired', finished_at=? WHERE status='pending' AND created_at <= datetime('now', '-15 minutes')", (now,))
        cur = await db.execute("""
            SELECT id, challenger_clan_id, opponent_clan_id, prize_car
            FROM clan_wars WHERE status='active' AND ends_at IS NOT NULL AND ends_at<=?
        """, (now,))
        wars = await cur.fetchall()
        for war_id, left_id, right_id, prize_car in wars:
            cur = await db.execute("SELECT COALESCE(SUM(power),0) FROM clan_war_participants WHERE war_id=? AND clan_id=?", (war_id, left_id))
            left_power = int((await cur.fetchone())[0] or 0)
            cur = await db.execute("SELECT COALESCE(SUM(power),0) FROM clan_war_participants WHERE war_id=? AND clan_id=?", (war_id, right_id))
            right_power = int((await cur.fetchone())[0] or 0)
            if left_power == right_power:
                cur = await db.execute("UPDATE clan_wars SET status='draw', finished_at=? WHERE id=? AND status='active'", (now, war_id))
                continue
            winner_clan_id = int(left_id if left_power > right_power else right_id)
            cur = await db.execute("SELECT user_id FROM clan_war_participants WHERE war_id=? AND clan_id=?", (war_id, winner_clan_id))
            candidates = [int(row[0]) for row in await cur.fetchall()]
            if not candidates:
                cur = await db.execute("UPDATE clan_wars SET status='draw', finished_at=? WHERE id=? AND status='active'", (now, war_id))
                continue
            winner_user_id = random.choice(candidates)
            cur = await db.execute("""
                UPDATE clan_wars SET status='finished', winner_clan_id=?, winner_user_id=?, finished_at=?
                WHERE id=? AND status='active'
            """, (winner_clan_id, winner_user_id, now, war_id))
            if cur.rowcount != 1:
                continue
            car_data = next((item for item in CLAN_SUPER_CARS if item["name"] == prize_car), None)
            car_value = int(car_data["value"] if car_data else 250_000_000)
            await clan_insert_car(db, winner_user_id, prize_car, car_value, "super_exclusive")
            await db.execute("UPDATE clans SET xp=xp+500 WHERE id=?", (winner_clan_id,))
            await clan_add_task_progress(db, winner_clan_id, "war_win", 1)
        await db.commit()


def clan_wars_keyboard(wars, clan_id):
    kb = InlineKeyboardBuilder()
    kb.button(text="⚔️ Вызвать другой клан", callback_data="clan_challenge_list")
    for row in wars:
        war_id, challenger_id, opponent_id, status, prize_car, winner_id, ends_at, left_name, left_tag, right_name, right_tag = row
        if status == "active":
            kb.button(text=f"🔥 Открыть войну #{war_id}", callback_data=f"clan_war_view:{war_id}")
        elif status == "pending" and int(opponent_id) == int(clan_id):
            kb.button(text=f"✅ Принять вызов #{war_id}", callback_data=f"clan_war_accept:{war_id}")
            kb.button(text=f"❌ Отклонить #{war_id}", callback_data=f"clan_war_decline:{war_id}")
        elif status == "pending" and int(challenger_id) == int(clan_id):
            kb.button(text=f"⏳ Вызов отправлен · #{war_id}", callback_data=f"clan_war_view:{war_id}")
        elif status in ("finished", "draw", "expired", "cancelled"):
            kb.button(text=f"📜 Итоги войны #{war_id}", callback_data=f"clan_war_view:{war_id}")
    kb.button(text="🔙 В клан", callback_data="clan_home")
    kb.adjust(1)
    return kb.as_markup()


@dp.callback_query(F.data == "clan_wars")
async def clan_wars_callback(call):
    clan = await clan_get_info(call.from_user.id)
    if not clan:
        await safe_callback_answer(call, "Сначала вступи в клан.", show_alert=True)
        return
    await clan_resolve_expired_wars()
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("""
            SELECT w.id, w.challenger_clan_id, w.opponent_clan_id, w.status, w.prize_car,
                   w.winner_clan_id, w.ends_at, c1.name, c1.tag, c2.name, c2.tag
            FROM clan_wars w
            LEFT JOIN clans c1 ON c1.id=w.challenger_clan_id
            LEFT JOIN clans c2 ON c2.id=w.opponent_clan_id
            WHERE w.challenger_clan_id=? OR w.opponent_clan_id=?
            ORDER BY CASE w.status WHEN 'active' THEN 0 WHEN 'pending' THEN 1 ELSE 2 END, w.id DESC
            LIMIT 10
        """, (clan["id"], clan["id"]))
        wars = await cur.fetchall()
    lines = ["⚔️ <b>КЛАНОВЫЕ ВОЙНЫ</b>", "", "Награда победителю — супер-эксклюзивный автомобиль. Война длится 30 минут; каждый участник может внести вклад один раз за 100 000 ₽.", ""]
    if not wars:
        lines.append("Пока войн нет. Вызови другой клан на сражение!")
    for row in wars:
        war_id, left_id, right_id, status, prize_car, winner_id, ends_at, left_name, left_tag, right_name, right_tag = row
        left = f"[{left_tag}] {left_name}" if left_name else f"Клан #{left_id}"
        right = f"[{right_tag}] {right_name}" if right_name else f"Клан #{right_id}"
        if status == "pending":
            state = "⏳ Ожидает ответа"
        elif status == "active":
            state = f"🔥 Идёт бой до {str(ends_at or '')[11:16]} UTC"
        elif status == "finished":
            state = f"🏆 Победитель: {left if int(winner_id or 0)==int(left_id) else right}"
        elif status == "draw":
            state = "🤝 Ничья — автомобиль не разыгран"
        elif status == "expired":
            state = "⌛ Вызов истёк без ответа"
        else:
            state = "Отменена"
        lines.append(f"<b>Война #{war_id}</b>\n{html.escape(left)} ⚔️ {html.escape(right)}\n🎁 Приз: <b>{html.escape(prize_car)}</b>\n{state}")
    await edit_text_safe(call, "\n\n".join(lines), parse_mode="HTML", reply_markup=clan_wars_keyboard(wars, clan["id"]))
    await safe_callback_answer(call)


