@dp.callback_query(F.data.startswith("clan_challenge:"))
async def clan_challenge_callback(call):
    try:
        target_id = int(call.data.split(":", 1)[1])
    except (ValueError, IndexError):
        await safe_callback_answer(call, "Некорректный соперник.", show_alert=True)
        return
    clan = await clan_get_info(call.from_user.id)
    if not clan or clan["role"] != "leader":
        await safe_callback_answer(call, "Вызовить другой клан может только глава своего клана.", show_alert=True)
        return
    if target_id == clan["id"]:
        await safe_callback_answer(call, "Нельзя вызвать свой клан.", show_alert=True)
        return
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT name, tag, leader_id FROM clans WHERE id=?", (target_id,))
        target = await cur.fetchone()
        if not target:
            await safe_callback_answer(call, "Этот клан не найден.", show_alert=True)
            return
        cur = await db.execute("""
            SELECT 1 FROM clan_wars
            WHERE status IN ('pending','active') AND
            (challenger_clan_id IN (?,?) OR opponent_clan_id IN (?,?)) LIMIT 1
        """, (clan["id"], target_id, clan["id"], target_id))
        if await cur.fetchone():
            await safe_callback_answer(call, "Один из кланов уже участвует в вызове или войне.", show_alert=True)
            return
        prize = random.choice(CLAN_SUPER_CARS)["name"]
        await db.execute("INSERT INTO clan_wars(challenger_clan_id,opponent_clan_id,status,prize_car) VALUES(?,?,'pending',?)", (clan["id"], target_id, prize))
        await db.commit()
    try:
        await bot.send_message(
            int(target[2]),
            f"⚔️ Клан <b>[{html.escape(clan['tag'])}] {html.escape(clan['name'])}</b> вызывает вас на войну!\n"
            f"🎁 Супер-приз: <b>{html.escape(prize)}</b>\n\nОткрой раздел «🛡 Кланы» и прими или отклони вызов в течение 15 минут.",
            parse_mode="HTML",
        )
    except Exception:
        pass
    await edit_text_safe(
        call,
        f"✅ Вызов клану <b>[{html.escape(target[1])}] {html.escape(target[0])}</b> отправлен.\n"
        f"🎁 На кону: <b>{html.escape(prize)}</b>\n\nСоперник должен принять вызов в течение 15 минут.",
        parse_mode="HTML", reply_markup=clan_back_keyboard("clan_wars"),
    )
    await safe_callback_answer(call)


