@dp.callback_query(F.data.startswith("clan_war_view:"))
async def clan_war_view_callback(call):
    try:
        war_id = int(call.data.split(":", 1)[1])
    except (ValueError, IndexError):
        await safe_callback_answer(call, "Некорректная война.", show_alert=True)
        return
    await clan_resolve_expired_wars()
    clan = await clan_get_info(call.from_user.id)
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("""
            SELECT w.challenger_clan_id, w.opponent_clan_id, w.status, w.prize_car,
                   w.winner_clan_id, w.winner_user_id, w.ends_at,
                   c1.name, c1.tag, c2.name, c2.tag
            FROM clan_wars w LEFT JOIN clans c1 ON c1.id=w.challenger_clan_id
            LEFT JOIN clans c2 ON c2.id=w.opponent_clan_id WHERE w.id=?
        """, (war_id,))
        war = await cur.fetchone()
        if not war:
            await safe_callback_answer(call, "Война не найдена.", show_alert=True)
            return
        if not clan or clan["id"] not in (int(war[0]), int(war[1])):
            await safe_callback_answer(call, "Ты не участник этих кланов.", show_alert=True)
            return
        cur = await db.execute("SELECT COALESCE(SUM(power),0) FROM clan_war_participants WHERE war_id=? AND clan_id=?", (war_id, int(war[0])))
        left_power = int((await cur.fetchone())[0] or 0)
        cur = await db.execute("SELECT COALESCE(SUM(power),0) FROM clan_war_participants WHERE war_id=? AND clan_id=?", (war_id, int(war[1])))
        right_power = int((await cur.fetchone())[0] or 0)
        cur = await db.execute("SELECT power FROM clan_war_participants WHERE war_id=? AND user_id=?", (war_id, call.from_user.id))
        joined = await cur.fetchone()
    left_name = f"[{war[8]}] {war[7]}" if war[7] else f"Клан #{war[0]}"
    right_name = f"[{war[10]}] {war[9]}" if war[9] else f"Клан #{war[1]}"
    status = str(war[2])
    if status == "active":
        state_text = f"⏱ До завершения: {html.escape(str(war[6] or '')[11:16])} UTC\n"
    elif status == "finished":
        winner_name = left_name if int(war[4] or 0) == int(war[0]) else right_name
        state_text = f"🏆 Победитель: <b>{html.escape(winner_name)}</b>\n🚘 Автомобиль передан участнику-победителю.\n"
    elif status == "draw":
        state_text = "🤝 Ничья: силы равны, машина осталась неразыгранной.\n"
    else:
        state_text = f"Статус: <b>{html.escape(status)}</b>\n"
    text = (
        f"⚔️ <b>КЛАНОВАЯ ВОЙНА #{war_id}</b>\n\n"
        f"🔴 {html.escape(left_name)} — <b>{left_power} силы</b>\n"
        f"🔵 {html.escape(right_name)} — <b>{right_power} силы</b>\n\n"
        f"🎁 Приз: <b>{html.escape(war[3])}</b>\n"
        + state_text
    )
    kb = InlineKeyboardBuilder()
    if status == "active" and not joined:
        kb.button(text=f"🛡 Усилить клан · {CLAN_WAR_FEE:,} ₽", callback_data=f"clan_war_join:{war_id}")
    kb.button(text="🔄 Обновить войну", callback_data=f"clan_war_view:{war_id}")
    kb.button(text="🔙 К войнам", callback_data="clan_wars")
    kb.adjust(1)
    await edit_text_safe(call, text, parse_mode="HTML", reply_markup=kb.as_markup())
    await safe_callback_answer(call)


@dp.callback_query(F.data.startswith("clan_war_join:"))
async def clan_war_join_callback(call):
    try:
        war_id = int(call.data.split(":", 1)[1])
    except (ValueError, IndexError):
        await safe_callback_answer(call, "Некорректная война.", show_alert=True)
        return
    clan = await clan_get_info(call.from_user.id)
    if not clan:
        await safe_callback_answer(call, "Ты не состоишь в клане.", show_alert=True)
        return
    player = await get_player(call.from_user.id)
    if not player:
        await safe_callback_answer(call, "Профиль игрока не найден.", show_alert=True)
        return
    strength = random.randint(70, 130) + max(0, int(player[2]) - 1) * 5
    now = utcnow_naive().strftime("%Y-%m-%d %H:%M:%S")
    async with aiosqlite.connect(DB) as db:
        cur = await db.execute("SELECT challenger_clan_id, opponent_clan_id, status, ends_at FROM clan_wars WHERE id=?", (war_id,))
        war = await cur.fetchone()
        if not war or int(clan["id"]) not in (int(war[0]), int(war[1])) or war[2] != "active" or not war[3] or war[3] <= now:
            await safe_callback_answer(call, "Эта война уже завершена или недоступна.", show_alert=True)
            return
        cur = await db.execute("INSERT OR IGNORE INTO clan_war_participants(war_id,user_id,clan_id,power,paid) VALUES(?,?,?,?,?)", (war_id, call.from_user.id, clan["id"], strength, CLAN_WAR_FEE))
        if cur.rowcount != 1:
            await safe_callback_answer(call, "Ты уже участвовал в этой войне.", show_alert=True)
            return
        cur = await db.execute("UPDATE players SET balance=balance-? WHERE user_id=? AND balance>=?", (CLAN_WAR_FEE, call.from_user.id, CLAN_WAR_FEE))
        if cur.rowcount != 1:
            await db.execute("DELETE FROM clan_war_participants WHERE war_id=? AND user_id=?", (war_id, call.from_user.id))
            await db.commit()
            await safe_callback_answer(call, "Недостаточно денег для участия в войне.", show_alert=True)
            return
        await db.commit()
    # Показываем обновлённый счёт войны в том же сообщении; обработчик сам ответит на callback.
    await clan_war_view_callback(call)


