# ЗАПУСК
# =========================================================

async def main():
    if not TOKEN or TOKEN == "PASTE_NEW_BOT_TOKEN_HERE":
        raise RuntimeError(
            "Не задан токен бота. Сначала установи переменную окружения BOT_TOKEN "
            "со свежим токеном, созданным через BotFather."
        )

    await init_db()
    await init_clan_tables()
    await seed_phone_news()
    phone_task = asyncio.create_task(phone_npc_loop())
    phone_alert_task = asyncio.create_task(phone_price_alert_loop())
    battle_pass_task = asyncio.create_task(bp_task_loop())
    gov_auction_task = asyncio.create_task(gov_auction_settlement_loop())

    print("🚗 Автоперекуп запущен!")

    try:
        await dp.start_polling(bot)
    finally:
        phone_task.cancel()
        phone_alert_task.cancel()
        battle_pass_task.cancel()
        gov_auction_task.cancel()
        for task in (phone_task, phone_alert_task, battle_pass_task, gov_auction_task):
            try:
                await task
            except asyncio.CancelledError:
                pass


if __name__ == "__main__":
    asyncio.run(main())
